window.ATLAS_I18N_LOR={"01IO012":["Disciplinas gemelas","Concede a un aliado +3|+0 o +0|+3 esta ronda.","","''Nunca temas el cambio. Te pondrá a prueba y te mostrará tus límites. El cambio es el mejor maestro''. - Karma","Hechizo",[],["Jonia"],"COMÚN"],"01IO015":["Yasuo","Cuando aturdes o usas Retirada sobre un enemigo, le inflijo 2 de daño.","Has aturdido o retirado 5 unidades o más.","''La muerte es como el viento...\".","Unidad",[],["Jonia"],"Campeón"],"01IO020":["Protector de las máscaras","Cuando se me invoca, se concede al resto de aliados +1|+0 esta ronda.","","''Hoy, tu rostro será reflejo de disciplina, entrenamiento, humildad y equilibrio. Hoy, eres un kinkou''.","Unidad",[],["Jonia"],"COMÚN"],"01IO045":["Heraldo de la primavera","Apoyo: Concede Robo de vida al aliado al que apoye esta ronda.","","''Durante el reinado del invierno, escuchamos las pisadas\nsobre el suelo cubierto de nieve. \nA su paso, crecían tallos y hojas que adornaban el bosque.\nHabía llegado un nuevo heraldo estacional''.\n- Poema de Shon-Xan","Unidad",[],["Jonia"],"COMÚN"],"01IO008":["Hada blandefilos","Cuando aturdes o retiras a una unidad, consigo +2|+0.","","''Ah, ¡¿que te parezco peludita y adorable?! ¡A ver si esto también te parece adorable!''.","Unidad",["YORDLE"],["Jonia"],"RARA"],"01IO040":["Espadachín kinkou","","","''Hace tiempo, nuestros hogares, templos y escuelas se encontraban aquí. Ahora vagamos por unas ruinas cubiertas por las sombras. La Orden de Zed ha corrompido el legado de este lugar sagrado... Me aseguraré de que lo lamenten''.","Unidad",[],["Jonia"],"COMÚN"],"01IO041":["Karma","Fin de ronda: Crea en la mano un hechizo aleatorio de una de tus regiones.","Tienes Iluminación.","\"Al reflexionar, centramos la mente y trazamos caminos para superar cualquier obstáculo\".","Unidad",[],["Jonia"],"Campeón"],"01IO011":["Retirada","Retira a un aliado.","","Un guerrero ilustre ha de saber cuándo está perdida la batalla. Una retirada a tiempo puede significar una futura victoria. ","Hechizo",[],["Jonia"],"COMÚN"],"01IO009":["Zed","Atacar: Invoca 1 Sombra viviente en ataque con mis estadísticas.","He visto como mis Sombras vivientes aliadas o yo hemos golpeado dos veces el nexo enemigo.","''El equilibrio es el maestro del necio. Las sombras me han enseñado lo que es el auténtico poder''.","Unidad",[],["Jonia"],"Campeón"],"01IO014":["Anciano de Greenglade","Cuando se me invoca, concede +1|+1 a los aliados de la mano.","","Hay retazos de la sabiduría jonia que se conservan en escritos, pero la mayor parte vive en los relatos y las enseñanzas de los ancianos venerados de esa tierra, que renuevan sin cesar los textos del pasado.","Unidad",[],["Jonia"],"COMÚN"],"01IO005":["Poro ágil","","","''Sé que suena un poco absurdo, pero lo último que recuerdo son... cosquillas''. - Forajido de Navori","Unidad",["PORO"],["Jonia"],"COMÚN"],"01IO044":["Conspirador de Navori","Para jugar esta carta, retira a un aliado.","","''¡Venga, tenemos que salir de aquí! ¿Que quién soy? Te lo explicaré de camino, lo prometo...''.","Unidad",[],["Jonia"],"COMÚN"],"01IO023":["Protectora rubí","Jugar: Otorga +3|+3 a un aliado de la mano.","","''En época de conflicto, los aldeanos buscaron la ayuda de la antigua protectora del Valle otoñal. Aquellos que llegaron hasta su corazón, recibieron su bendición y cambiaron las tornas de la batalla''.\n- Epopeya de Las Tierras Primigenias","Unidad",[],["Jonia"],"RARA"],"01IO029":["Siembra de semillas","Otorga +1|+0 a los aliados de la mano.","","''No solo semillas, jóvenes. El legado de la mismísima tierra, promesas de un futuro próspero''. - Karma","Hechizo",[],["Jonia"],"RARA"],"01IO003":["Marca de la muerte","Elimina el efecto Endeble de un aliado y se lo otorga a un enemigo.","","''Soy la hoja en la oscuridad''. - Zed\n\n","Hechizo",[],["Jonia"],"RARA"],"01IO047":["Fulgor sombrío","Otorga Endeble a todos los adeptos en combate.","","Cuando las corrientes de magia se desequilibran, abandonan el mundo espiritual y penetran en el reino mortal... Muchas veces los resultados son sorprendentes.","Hechizo",[],["Jonia"],"ÉPICA"],"01IO026":["Mentor ejemplar","Jugar: Otorga +1|+0 a un aliado de la mano.","","''¡Me ha llevado años conseguir este físico de muerte! ¡Días inagotables de avistar aves, describir nubes y de llevar bandejas llenas de bollos! ¡Mi constancia es admirable!''.","Unidad",[],["Jonia"],"COMÚN"],"01IO024":["Alba y ocaso","Invoca 2 copias exactas de un aliado con Endeble.","","''Shen es un hombre atrapado entre los peligros de dos mundos a los que terminará fallando. Yo solo me consagro a Jonia''. - Zed","Hechizo",[],["Jonia"],"RARA"],"01IO028":["Dinosaurio escamado","Jugar: Consigo +3|+0 o +0|+3.","","Uno de los habitantes más viejos de Greenglade. Ha resistido el paso del tiempo gracias a una adaptación constante.","Unidad",["REPTIL"],["Jonia"],"COMÚN"],"01IO057":["Asesina de las sombras","Cuando se me invoca, se roba 1.","","Grácilmente, se desliza.\nPasos silenciosos en las sombras.\nSus garras son la única huella.","Unidad",[],["Jonia"],"COMÚN"],"01IO032":["Shen","Apoyo: Concede Barrera esta ronda al aliado al que apoye.","He visto a aliados obtener Barrera en 5 ocasiones.","''Como una mano que estrecha a otra, el reino mortal y el espiritual están entrelazados''. ","Unidad",[],["Jonia"],"Campeón"],"01IO013":["Sombra malvada","","","''¿Qué precio estamos dispuestos a pagar por el poder? Un juramento sellado sobre la piel da comienzo a la transformación...''. - Zed","Unidad",[],["Jonia"],"COMÚN"],"01IO018":["Impulso","Concede +1|+0 y Ataque rápido a un aliado esta ronda.","","El combate no es más que una carrera para acabar con la vida del enemigo antes de que él te arrebate la tuya.","Hechizo",[],["Jonia"],"COMÚN"],"01IO056":["Yone, el Cazavientos","Jugar: Aturde a 2 enemigos.","","''De pequeño, le pregunté a mi hermano: '¿el viento huye o persigue?' Antes me seguía en busca de orientación. Ahora yo lo persigo para hacer justicia''.\n","Unidad",[],["Jonia"],"RARA"],"01IO016":["Céfiro sabio","Jugar: Crea una copia exacta de una carta en la mano, excepto Céfiro sabio.","","''El guerrero lloraba su pérdida mientras el anciano lo consolaba y decía: 'Busca al sabio de los cielos, pues solo él es capaz de devolvernos lo que se ha perdido en vida pero permanece en el recuerdo'''.\n- Epopeya de las Tierras Primigenias","Unidad",["AVE"],["Jonia"],"RARA"],"01IO036":["Centinela de Greenglade","Golpear: Reduce en 1 el coste de la unidad más cara que tengas en la mano.","","''¡Patrulla, una... no...! ¡Dos criaturas enormes y peludas se dirigen hacia nosotros! Pedid ref... Eh. Un momento... El catalejo estaba al revés...''.","Unidad",["YORDLE"],["Jonia"],"COMÚN"],"01IO033":["Minah Piesveloces","Jugar: Retira a 3 enemigos.","","''Ahí estábamos, cruzando el prado, cuando de repente aparece una cría de la nada y PAM, PAM, PAM... ¡Reventados!''. - Forajido de Navori","Unidad",[],["Jonia"],"ÉPICA"],"01IO001":["Ritual de renovación","Cura a un aliado o a tu nexo 4 de vida. Roba una carta.","","''Solo al elevar nuestra mente sentiremos que nuestro cuerpo está completo''. - Karma","Hechizo",[],["Jonia"],"RARA"],"01IO010":["Mantenerse unidos","Intercambia a dos aliados y les concede Barrera esta ronda.","","''Avanzo respetando el equilibrio''. - Shen\n","Hechizo",[],["Jonia"],"RARA"],"01IO022":["Fantasma","Concede Elusión a un aliado esta ronda.","","''Vete, escóndete y no vuelvas hasta que estén todos muertos''. - Zed","Hechizo",[],["Jonia"],"COMÚN"],"01IO021":["Rapaz planeadora","Cuando se me invoca, se concede al resto de aliados +2|+2 esta ronda.","","''La primavera llega primero a los acantilados de Jonia, donde el batido de las nuevas alas baña la tierra a merced de la suave brisa estacional''.\n- Epopeya de Las Tierras Primigenias","Unidad",[],["Jonia"],"ÉPICA"],"01IO054":["Visión del tiempo","Crea otro hechizo aleatorio de una de tus regiones en la mano.\nIluminación: Crea 2.","","''Cuando tu esperanza vacile, recuerda que no estás solo. El pasado está siempre a nuestro lado. Ha conocido infinitos mañanas y la esperanza que ellos traen''. - Karma","Hechizo",[],["Jonia"],"RARA"],"01IO027":["Vidente taciturna de las sombras","Golpe al nexo: Crea una copia de mí en la mano.","","''En la carne no se puede confiar. Es frágil. Tan delicada como la línea que separa luz y oscuridad''.","Unidad",[],["Jonia"],"ÉPICA"],"01IO031":["Surcanubes","Los hechizos de Ráfaga y de Concentración cuestan 1 menos.","","Sus canciones se oían desde las aldeas: ondas sonoras largas y graves que resonaban entre el cielo y la ladera. Extrañas, sin forma, como las nubes del atardecer.","Unidad",[],["Jonia"],"RARA"],"01IO002":["Voluntad de Jonia","Retira a una unidad.","","Cuando los invasores llegaron por vez primera a Jonia, descubrieron que no bastaría con conquistar a sus habitantes.","Hechizo",[],["Jonia"],"COMÚN"],"01IO017":["Cuchillaveloz de Navori","Cuando se me invoca, consigo Elusión esta ronda.","","''Descuida, le quitaré hasta los dientes. Sácame de aquí y te prometo que nos repartimos el botín. ¡Me dirás que no es un buen trato!''.","Unidad",["YORDLE"],["Jonia"],"COMÚN"],"01IO042":["Estudiante peleón","Cuando invocas a otro aliado, consigo +1|+1 esta ronda.","","''¿Qué sentido tiene luchar cuando nadie supervisa tus movimientos?''.","Unidad",[],["Jonia"],"COMÚN"],"01IO006":["Dúo de Greenglade","Cuando invocas a otro aliado, consigo +1|+0 esta ronda.","","''¡Oye, cuidado con esas rama! ¡A la izquierda! ¡Izquierda!''. \n''Cuando me lleves tú a mí, bola de pelo, iremos a donde tú quieras. ¡Pero ahora mando yo!''.","Unidad",[],["Jonia"],"RARA"],"01IO050":["Buscavías kinkou","Alianza: Invoca a un aliado de coste 1 de tu mazo.","","Vaya a donde vaya, se asegura de que el resto pueda seguirla.","Unidad",[],["Jonia"],"RARA"],"01IO048":["Yusari","","","''Tu orden nos ha expulsado de nuestras tierras. Has demostrado tu poder, maestro Zed. Ahora yo te demostraré que soy digno de ser tu pupilo''.","Unidad",[],["Jonia"],"RARA"],"01IO007":["Ren Filosombrío","Golpear: Crea 1 Sombra malvada en la mano.","","''Correr, huir, buscar refugio. Nada importa, pues las sombras han venido a por vosotros''.","Unidad",[],["Jonia"],"ÉPICA"],"01IO053":["Evocador esmeralda","Iluminación: Tengo +4|+4.","","''La guerra se alimenta de nuestros instintos más básicos... Pero los instintos no tienen ningún control sobre nuestras mayores virtudes: confianza, paciencia y contemplación''.","Unidad",[],["Jonia"],"COMÚN"],"01IO004":["Poción de vida","Cura a un aliado o a tu nexo 3 de vida.","","Cada generación, región y familia tiene su remedio casero, aunque algunos son más efectivos que otros.","Hechizo",[],["Jonia"],"COMÚN"],"01IO049":["Rechazar","Detengo un hechizo veloz, uno lento o una habilidad.","","No.","Hechizo",[],["Jonia"],"RARA"],"01IO052":["Bandolero de Navori","Cuando se me invoca, se invoca 1 Forajido de Navori con mis estadísticas.","","''Yo era un músico ambulante famoso en todas partes, de aquí al Placidium... Hasta que llegaron los noxianos. Ahora sobrevivo a base de monedas robadas. Mi madre tenía razón, debería haberme hecho curandero...''.","Unidad",[],["Jonia"],"COMÚN"],"01IO030":["El Empíreo","","","''El propio cielo se levantó con remolinos de nubes y fuertes vientos que azotaban nuestra brigada. Intentamos estar a la altura, pero ¿quién puede alcanzar el viento?''. - General de la Legión","Unidad",["DRAGÓN"],["Jonia"],"ÉPICA"],"01IO019":["Vigía de Greenglade","Cuando un aliado obtiene Barrera, consigo +2|+0.","","''Greenglade protege a los suyos, pero tú... Tú no eres de aquí''.","Unidad",[],["Jonia"],"COMÚN"],"01IO046":["Tempestad de acero","Aturde a un enemigo en ataque.","","\"¡Hasagi!\". - Yasuo","Hechizo",["ELEMENTAL"],["Jonia"],"RARA"],"01IO037":["Refugio espiritual","Concede Barrera y Robo de vida a un aliado esta ronda.","","''Esta espada era de mi padre. Ojalá te dé la fuerza que a mí me faltó en el pasado''. - Shen","Hechizo",[],["Jonia"],"COMÚN"],"01IO043":["Moldeador de ríos","Golpear: Roba un hechizo.","","''Somos los orgullosos hijos de las Tierras Primigenias. Ríos de magia fluyen por nuestra sangre vastaya como lo hacen por nuestro reino''.","Unidad",[],["Jonia"],"RARA"],"01IO038":["Sacerdotisa solitaria","Jugar: Retira a todos los demás aliados.","","''La meditación y el instinto son los únicos compañeros que deseo tener''.","Unidad",[],["Jonia"],"RARA"],"01IO039":["Alteración sombría","Retira a un aliado para invocar 1 Sombra viviente en su lugar.","","¿De verdad te enfrentas al enemigo que crees ver? ¿O es un engaño de las sombras?","Hechizo",[],["Jonia"],"COMÚN"],"01IO055":["Protector de ki","Concede Barrera a un aliado de la mano.\nRoba 1 carta.","","''Los que mantienen el equilibrio conocerán la protección de los kinkou''. - Shen\n","Hechizo",[],["Jonia"],"COMÚN"],"01NX020":["Draven","Cuando se me invoca o al golpear: Crea 1 Hacha giratoria en la mano.","He golpeado con 2 o más Hachas giratorias en total.","\"¿Que quieres un autógrafo? Pues a la cola\".","Unidad",[],["Noxus"],"Campeón"],"01NX006":["Vladimir","Jugar: Inflige 1 de daño a cualquier número de aliados para infligirle esa cantidad de daño a un enemigo.","Has conseguido que 5 o más aliados sobrevivan al daño.","Despiadado. Frío. Cruel. Enigmático. Perspicaz. Encantador.\nIrresistible...","Unidad",[],["Noxus"],"Campeón"],"01NX004":["Golpe selectivo","Mata a una unidad con 3 o menos de poder.","","Todos morimos, pero los débiles mueren antes.","Hechizo",[],["Noxus"],"RARA"],"01NX048":["Conservador carmesí","Cuando sobrevivo al daño, se crea una unidad Carmesí aleatoria en la mano.","","''¡Mis queridos compañeros!''. ''Eh... ¿Sí? Recibí la invitación''. ''... tontorrón, al baile del tontorrón''. ''¡Ah, vamos! Presentaré a mi familia''. ''Sigamos los pasos, querida. Kye, ¿vendrás?''.","Unidad",[],["Noxus"],"COMÚN"],"01NX038":["Darius","","Veo que el nexo enemigo tiene la mitad de la vida inicial o menos.","''Una voluntad de hierro y la fuerza de un titán. No hay mejor general para encabezar a la Legión Trifariana''. - Swain\n","Unidad",[],["Noxus"],"Campeón"],"01NX023":["Huésped aracnoide","Cuando se me invoca, otorga a otros aliados arácnidos +2|+0.","","Con una mirada, caes en su red. Con un mordisco, caes en las de ellas.","Unidad",["ARAÑA"],["Noxus"],"RARA"],"01NX013":["Maniobra decisiva","Aturde a un enemigo. Concede +2|+0 a todos los aliados esta ronda.","","''Cualquier necio puede lanzar todas sus tropas contra el enemigo. El verdadero talento está en saber esconderlas hasta el momento adecuado''. - Swain","Hechizo",[],["Noxus"],"RARA"],"01NX046":["Centinela aracnoide","Jugar: Aturde a un enemigo.","","''¡Ah! Me enamora... Esas piernas eternas, esa voz de una dulzura paralizante, esos ojos rojos como una rosa. ¡Y pensar que ha accedido a cenar conmigo esta noche!''. - Aristócrata desafortunado","Unidad",["ARAÑA"],["Noxus"],"COMÚN"],"01NX047":["Transfusión","Inflige 1 de daño a un aliado y concede +2|+2 a otro esta ronda.","","\"Hay que dar y recibir... Tú das y yo recibo\". - Vladimir","Hechizo",[],["Noxus"],"COMÚN"],"01NX040":["Saboteadora de la Legión","Atacar: Inflige 1 de daño al nexo enemigo.","","''Nuestros rompescudos pueden partir a un hombre en dos, pero, cuando es necesario obrar con más discreción, la legión dispone de una amplia variedad de talentos''. - Swain","Unidad",[],["Noxus"],"COMÚN"],"01NX025":["Vínculo fraternal","Otorga +2|+0 a 2 aliados.","","''Los lazos creados en la guerra son tan firmes como los de la sangre, pues esta se comparte en ambos''. - Veterano de la Legión","Hechizo",[],["Noxus"],"COMÚN"],"01NX055":["Araña sepulcral","Cuando se me invoca, se invoca 1 Cría de araña.","","''A mis arañas les encanta la compañía. Una pena que ese sentimiento no suela ser recíproco''. - Elise","Unidad",["ARAÑA"],["Noxus"],"COMÚN"],"01NX030":["Discípula carmesí","Cuando sobrevivo al daño, inflige 1 de daño al nexo enemigo.","","''¡Uh, Edvin! Aquí estás, guapetón. ¡Estaba pensando en ti!''. ''Entonces ya podemos irnos''. ''Acompáñame, nos lo pasaremos bien''. ''O nada...''.","Unidad",[],["Noxus"],"RARA"],"01NX007":["Comentarista de la arena","Atacar: Concede +1|+0 al resto de aliados en ataque esta ronda.","","Rugió con júbilo. Durante un instante, el corazón de la arena y el suyo fueron uno solo. Alzó el puño en un gesto triunfante y provocó el entusiasmo de las masas.","Unidad",[],["Noxus"],"RARA"],"01NX021":["Saqueador de la Legión","Atacar: Otorga +1|+1 a los Saqueadores de la Legión aliados estén donde estén.","","La Legión Trifariana está repleta de forajidos oportunistas que se aprovechan de los débiles y de los heridos con los que se topan.","Unidad",[],["Noxus"],"COMÚN"],"01NX009":["Favorito del público","Cuando se me invoca, consigo +1|+1 por cada aliado que tengas.","","Algunos justicieros son admirados por su carisma; otros, por su técnica y agilidad. Vessid no posee ninguna de estas virtudes, pero nadie desmiembra a sus rivales con más gracia que él.","Unidad",[],["Noxus"],"RARA"],"01NX011":["Espiral de muerte","Un aliado en combate golpea a un enemigo en combate.","","\"Me encanta mi trabajo\". - Draven","Hechizo",[],["Noxus"],"COMÚN"],"01NX053":["Ajuste de cuentas","Si tienes un aliado con 5 o más de poder, mata a todas las unidades con 4 o menos de poder.","","''¡EEEES LA HORA DE LA VERDAAAAAD!''. - Comentarista de la arena","Hechizo",[],["Noxus"],"ÉPICA"],"01NX054":["Rugido intimidante","Aturde a todos los enemigos con 4 o menos de poder.","","''Está respirando hondo; quizá nos deleite con... ¡Ahí está, señores y señoras! ¡El infame grito de guerra de Thunder! ¡Nos tiene a todos temblando como un trueno!''.\n- Comentarista de la arena","Hechizo",[],["Noxus"],"RARA"],"01NX029":["Veterano de la Legión","Cuando otro aliado sobrevive al daño, le otorga +1|+0.","","Volvió de la guerra al borde de la muerte, y solo las caricias de su marido y los bálsamos del boticario pudieron hacerlo sanar. Noxus ha invertido mucho para contar con su sabiduría y consejo, incluso muchos años después de su último combate.","Unidad",[],["Noxus"],"ÉPICA"],"01NX014":["Shiraza, la Hoja","Inflijo el doble de daño al nexo.","","''¿Que ha dicho qué? ¡Menudo cabeza hueca! Aunque va bien de espalda...''.","Unidad",[],["Noxus"],"ÉPICA"],"01NX042":["Katarina","Cuando se me invoca, crea 1 Filo de la cuchilla Fugaz en la mano.","He golpeado una vez. Cuando subo de nivel, me retiro.","\"No hay nada mejor que un objetivo demaciano para practicar la puntería\".","Unidad",[],["Noxus"],"Campeón"],"01NX051":["Capitán Farron","Cuando se me invoca, se crean 2 Diezmar en la mano.","","En las profundidades del Sumidero de Zaun, Benn Farron era considerado una amenaza. Era inestable e inaceptable. En el ejército noxiano halló la oportunidad de convertirse en un aliado admirado e imparable.","Unidad",[],["Noxus"],"ÉPICA"],"01NX012":["Retaguardia de la Legión","","","En Noxus, donde los soldados son venerados por su audacia en el campo de batalla, servir en la retaguardia es una especie de castigo.","Unidad",[],["Noxus"],"COMÚN"],"01NX043":["Filo de la cuchilla","Inflige 1 de daño a cualquier unidad o al nexo.","","''En las manos adecuadas, una cuchilla puede atravesarlo todo... y cuando digo todo es todo''. - Katarina","Hechizo",[],["Noxus"],"COMÚN"],"01NX037":["Granadero de la Legión","Último aliento: Inflige 1 de daño al nexo enemigo.","","Todos los noxianos aprenden que una vida al servicio del imperio es una buena vida, pero pocos viven tan bien como los Granaderos de la Legión.","Unidad",[],["Noxus"],"COMÚN"],"01NX010":["General de la Legión","Cuando se me invoca, consigo +1|+1 por cada unidad que has aturdido o retirado esta partida.","","Todo noxiano conoce los tres pilares de la fuerza. Los soldados, si desean destacar y ascender, deben también aprender a dominarlos.","Unidad",[],["Noxus"],"COMÚN"],"01NX017":["Tamborilera de la Legión","Apoyo: Concede Ataque rápido al aliado al que apoye esta ronda.","","La Legión expandió el imperio al ritmo de sus tambores. Nada podía pararlos, y nada lo consiguió.","Unidad",[],["Noxus"],"COMÚN"],"01NX003":["Corredor de apuestas","Comienzo de ronda: Descarta la carta de menor coste para robar 1.","","''Apuestas por Shiraza como única superviviente, pero ese crío jonio... Sí, le falta un brazo, pero no está muerto. Eso lo hace un superviviente, ¿no? Claro, siempre podrías doblar tu apuesta...''.","Unidad",["YORDLE"],["Noxus"],"RARA"],"01NX039":["Visión","Al jugarse o descartarse, otorga +1|+0 a los aliados.","","''Aquellos que no pueden ver el futuro no encuentran lugar en él''. - Jericho Swain","Hechizo",[],["Noxus"],"RARA"],"01NX041":["Rompescudos trifariano","","","''No tengo paciencia para preparar un asedio. Traedme a los rompescudos''. - Darius","Unidad",[],["Noxus"],"COMÚN"],"01NX036":["Minotauro justiciero","Comienzo de ronda: Aturde al enemigo más débil.","","''No me importa quién te haya hecho daño ni cómo. Tienes que hacérselo pagar en el foso, y aquí se paga por adelantado. No hay descuentos por pasados trágicos''.","Unidad",[],["Noxus"],"RARA"],"01NX044":["Ariete","Atacar: Consigo +4|+0.","","''Se niegan a abrir las puertas. Exigen hablar con Darius, pero está a dos días de aquí. ¿Enviamos jinetes a buscarlo?''.\n''No, no hace falta''.","Unidad",[],["Noxus"],"ÉPICA"],"01NX005":["Aristócrata carmesí","Jugar: Inflige 1 de daño a un aliado y le otorga +1|+0 y Abrumar.","","''Raro... ¿Tú también vas al baile del...?''. ''¿Lo podré soportar?''. ''Respeto tu propuesta, querida, pero mi padre me desheredaría... Quizá deberíamos llevar vestidos a juego''.","Unidad",[],["Noxus"],"COMÚN"],"01NX016":["Candidato trifariano","Cuando se me invoca, consigo +2|+0 si tienes otro aliado de Noxus.","","''Conseguirás tu título cuando tu hacha esté desafilada de cortar cabezas y tus botas estén caladas de sangre''.\n- Veterano de la Legión","Unidad",[],["Noxus"],"COMÚN"],"01NX019":["Fortaleza","Concede +3|+0 y Abrumar a un aliado esta ronda.","","''Cuando digo que la sutileza está sobrevalorada, no digo que no sea útil. Pero está sobrevalorada''. - Darius","Hechizo",[],["Noxus"],"COMÚN"],"01NX015":["Mascota adorada","","","Las quiere mucho a todas, pero a esta, a la que más.","Unidad",["ARAÑA"],["Noxus"],"COMÚN"],"01NX050":["Loto mortal","Inflige 1 de daño a todas las unidades en combate.","","''Baila conmigo''. - Katarina","Hechizo",[],["Noxus"],"RARA"],"01NX056":["Velocidad del rayo","Inflige 2 de daño a un enemigo y, después, prepara el ataque.","","Cuando avistas la cuchilla, ya es demasiado tarde.","Hechizo",[],["Noxus"],"COMÚN"],"01NX033":["Asesora trifariana","Cuando se me invoca, roba 1 por cada aliado con 5 o más de poder que tengas.","","''Se necesita una percepción implacable para decidir quiénes son merecedores de formar parte de la Legión Trifariana, pero ella es capaz de distinguir quién vale y quién no con una sola mirada''. - General de la Legión","Unidad",[],["Noxus"],"RARA"],"01NX052":["Sangre por sangre","Inflige 1 de daño a un adepto aliado. Si sobrevive, crea una copia del mismo en la mano.","","La primera clase de hemomancia lo deja todo pringado.","Hechizo",[],["Noxus"],"COMÚN"],"01NX045":["Justiciero despiadado","","","''¡Y ahora el Garras! La última batalla contra los Cinco Psicópatas fue de lo más encarnizada. Ahora es el turno de los Tres Psicópatas... ¡Bueno, venga! ¡Hora de apostar por la carnaza de hoy! ¡Cuatro a una, señores!''. - Karl, corredor de apuestas","Unidad",[],["Noxus"],"RARA"],"01NX031":["Trifariana buscagloria","","","A la mayoría le sirve con ganarse un puesto en la Legión Trifariana. Pero no a todos.","Unidad",[],["Noxus"],"RARA"],"01NX002":["Diezmar","Inflige 4 de daño al nexo enemigo.","","''A veces hace falta ingenio táctico para entrar en una fortaleza. Otras, solo tienes que bombardearla''. - Darius","Hechizo",[],["Noxus"],"RARA"],"01NX008":["Jinete de basiliscos","Alianza: Consigo +1|+1 y Abrumar.","","Esta unidad en concreto utiliza caballos, pero no los monta. A las bestias les parecen deliciosos.","Unidad",[],["Noxus"],"RARA"],"01NX034":["Poro cariñoso","","","''En Noxus no hay sitio para los... los débi... ¡Que alguien me quite este bicho de encima!''. - Darius.","Unidad",["PORO"],["Noxus"],"COMÚN"],"01NX035":["Fan número uno de Draven","Cuando se me invoca, Draven se coloca en la parte de arriba del mazo si no lo tienes ya en la mano o en juego.","","''¿Que quieres un autógrafo? Pues a la cola''.","Unidad",[],["Noxus"],"COMÚN"],"01NX026":["Trifariano imprudente","","","''La imprudencia es un defecto, pero la legión puede transformarla en una herramienta''. - Swain","Unidad",[],["Noxus"],"COMÚN"],"01NX027":["Elixir de cólera","Concede a un aliado +3|+0 esta ronda.","","''Cuando no aceptan tu mano, siempre queda el puño''.\n- Axioma noxiano","Hechizo",[],["Noxus"],"COMÚN"],"01NX022":["Guillotina noxiana","Mata a una unidad dañada para crear 1 Guillotina noxiana Fugaz en la mano.","","Para Darius, la clemencia está en los golpes certeros.","Hechizo",[],["Noxus"],"RARA"],"01NX032":["Evocador carmesí","Cuando se me invoca, inflige 1 de daño a todos los demás aliados.","","''¿Acaso importa? Vas a seguir insistiendo... Así que vale''.","Unidad",[],["Noxus"],"RARA"],"01NX024":["Kato, el Brazo","Apoyo: Concede +3|+0 y Abrumar al aliado al que apoye esta ronda.","","''Shiraza es una gran novi... digo, amiga. Que no es que estemos saliendo, para nada. Pero si lo estuviéramos, que no lo estamos, me gustaría decirle que feliz aniversario. Y eso es todo. Nada de preguntas''.","Unidad",[],["Noxus"],"ÉPICA"],"01NX049":["Astucia","Aturde a un enemigo.","","\"Deja que tus enemigos se pongan la soga al cuello y te ahorrarás el esfuerzo''. - LeBlanc","Hechizo",[],["Noxus"],"COMÚN"],"01DE031":["Oradores del alba","Fin de ronda: Otorga al resto de aliados +1|+1 si un aliado muere esta ronda.","","''Puede que el mal haya ganado una batalla, pero no ganará la guerra. Recordemos a los caídos, ¡y que su memoria nos sirva de coraza!''.","Unidad",[],["Demacia"],"ÉPICA"],"01DE022":["Lucian","","He visto morir a 4 aliados o más o a una Senna aliada.","\"Si te tengo a mi lado, todo irá bien, Senna\".","Unidad",[],["Demacia"],"Campeón"],"01DE019":["En marcha","Reduce en 1 el coste de los aliados que tengas en la mano.","","\"Cambiar la hoz por la espada en cuestión de días. Es lo que se espera de cualquier ciudadano de Demacia que esté en condiciones de luchar''. - Garen","Hechizo",[],["Demacia"],"RARA"],"01DE042":["Lux","","Te he visto jugar 6 o más de maná de hechizos. Cuando subo de nivel, crea 1 Chispa final en la mano.","''Siempre he sabido que en mí hay algo diferente... una luz que nace en el interior. No tengo claro lo que es, ¡pero tendré que averiguarlo!''. ","Unidad",[],["Demacia"],"Campeón"],"01DE010":["Lancero raudo","Último aliento: Crea una unidad Élite aleatoria en la mano.","","''Hay que tener agallas para poner una vida en manos de un alargéntea y enzarzarse en la batalla lejos de tierra firme. Agallas y mucho aguante''. - Garen","Unidad",["ÉLITE","AVE"],["Demacia"],"RARA"],"01DE020":["Defensora de la Vanguardia","","","''No sabíamos quién o qué eran esas criaturas, pero conocíamos los rostros de quienes luchaban a nuestro lado, y eso era todo lo que necesitábamos''.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE034":["Herrero de batalla","Cuando invocas a una unidad Élite, consigue +1|+1.","","Las guerras se deciden en la forja.","Unidad",[],["Demacia"],"RARA"],"01DE002":["Tianna Crownguard","Cuando se me invoca, prepara el ataque.","","''Nuestra casa ha sangrado por el reino. No permitiré que manches el honor de la familia por unos trucos con luz''.","Unidad",[],["Demacia"],"ÉPICA"],"01DE012":["Garen","Cuando se me invoca, concede +1|+1 a otros aliados esta ronda.","He golpeado dos veces.","El entrenamiento y la resistencia forjan el alma del soldado. Incluso ante las circunstancias más extremas, no desfalleceremos.","Unidad",["ÉLITE"],["Demacia"],"Campeón"],"01DE017":["Entereza","Si tienes un solo aliado, le otorgas +3|+3.","","Cuando los demás fracasan, hallar el camino hacia la victoria queda en manos de un auténtico héroe.","Hechizo",[],["Demacia"],"RARA"],"01DE045":["Fiora","","He matado a 2 enemigos.","''En exhibiciones y torneos, en la práctica y en el campo de batalla, busco un digno oponente. No descansaré hasta ser la mejor''.","Unidad",[],["Demacia"],"Campeón"],"01DE052":["Formación de acero radiante","Cuando se me invoca o al atacar: Concede a los aliados Barrera esta ronda.","","''Esta formación es la base de nuestra táctica. Todos los soldados deben tener fe en su escudo y en el de sus compañeros para que surta efecto. Mientras ellos no caigan, tampoco lo hará el reino''. - Garen\n","Unidad",[],["Demacia"],"ÉPICA"],"01DE021":["Persecución implacable","Prepara el ataque.",""," ''Hay que plantarle cara al miedo. Qué suerte que esté yo aquí''. - Lucian\n","Hechizo",[],["Demacia"],"COMÚN"],"01DE025":["Arresto","Un aliado captura a una unidad.","","\"Entrégate, pues somos la ley que debes obedecer. Eso es todo''. - Persuasor de los Cazadores de Magos","Hechizo",[],["Demacia"],"COMÚN"],"01DE007":["Juicio","Un aliado en combate golpea a todos los enemigos en combate.","","La justicia nunca deja las cosas a medias.","Hechizo",[],["Demacia"],"ÉPICA"],"01DE055":["Duelista Laurent","Jugar: Otorga Contendiente a un aliado de la mano.","","''Parecía un petimetre engreído con una espada costosa en la mano, ¡pero resulta que sabía lo que se hacía! Me gustaría pedirle la revancha, pero con ese ridículo acento que tenía me fue imposible quedarme con su nombre''. - Alférez demaciano","Unidad",[],["Demacia"],"COMÚN"],"01DE048":["Instigador de los Cazadores de Magos","Consigo +2|+2 cuando hayas lanzado un hechizo de coste 6 o más esta partida.","","''Hace mucho tiempo, la magia indómita de las Guerras Rúnicas sometió a toda Runaterra. La orden se creó en consecuencia para proteger el reino y librarlo de toda magia, tanto interna como externa''. - Manual del cazador de magos","Unidad",[],["Demacia"],"RARA"],"01DE001":["Abanderado de vanguardia","Alianza: Otorga +1|+1 a todos los demás aliados.","","''Es esencial comprender el peso de nuestro estandarte. Ondea por nuestro rey, nuestras casas, nuestro pueblo. Simboliza nuestra inquebrantable fe en Demacia. Alzadlo con firmeza. Que contemplen nuestro orgullo''. - Tianna Crownguard ","Unidad",["ÉLITE"],["Demacia"],"RARA"],"01DE043":["Chefs de guerra","Apoyo: Concede +1|+1 al aliado al que apoye esta ronda.","","No se debe tratar a la ligera a ningún miembro del ejército de Demacia.","Unidad",[],["Demacia"],"COMÚN"],"01DE049":["Poro intrépido","","","''El nuevo recluta tiene la entereza y el valor propios de los mejores soldados. ¿Llegará a servir algún día en la Vanguardia? Es... más pequeño que el resto. Veamos cómo acontecen los hechos''. - Sargento de la Vanguardia","Unidad",["PORO"],["Demacia"],"COMÚN"],"01DE053":["Caballero Laurent","Golpear: Crea otro adepto aleatorio con Contendiente de una de tus regiones en la mano.","","''... Santo cielo''. - Fiora","Unidad",[],["Demacia"],"ÉPICA"],"01DE033":["Conmemoración","Cuesto 1 menos por cada aliado que haya muerto en esta ronda. Invoca a un adepto aleatorio de Demacia de coste 5.","","''Hoy nos alzamos para enmendar las injusticias que acabaron con los que vinieron antes que nosotros. Sus sacrificios no fueron en vano''. - Guardiana radiante","Hechizo",[],["Demacia"],"RARA"],"01DE044":["Valor duplicado","Cura toda la vida a un aliado y después duplica su poder y su vida.","","En nuestro caso es cierto: un soldado demaciano vale por dos enemigos.","Hechizo",[],["Demacia"],"RARA"],"01DE024":["Procurador de los Cazadores de Magos","Último aliento: Crea un hechizo aleatorio en la mano de 6 de coste o más de una facción que no sea Demacia.","","''Es innegable que los artículos arcanos suscitan un gran interés, pero estos poderosos artilugios han de quedar en manos de nuestros diestros expertos y no mezclarse con la ignorancia bienintencionada de nuestros ciudadanos''.\n- Manual del cazador de magos","Unidad",[],["Demacia"],"COMÚN"],"01DE004":["Vanguardia alargéntea","Jugar: Invoca una copia exacta de mí.","","Cayeron del cielo como flechas de plata y rayos que avanzan hacia su objetivo con firmeza y agilidad. Y, entonces, desaparecieron sin dejar rastro. ","Unidad",["ÉLITE","AVE"],["Demacia"],"COMÚN"],"01DE011":["Pupilo Laurent","","","''¡¿Que ha hecho qué?! ¡Pero si le confié el sable de equilibrio dual de Pierre de Guillard, de un valor inestimable! ¡Me prometió que solo lo usaría para practicar!''. - Guardafilos Laurent","Unidad",[],["Demacia"],"COMÚN"],"01DE047":["Sucesión","Invoca Vanguardia Impertérrita.","","Las vestimentas de la Vanguardia Impertérrita se transmiten de un soldado a otro, de modo que los nuevos reclutas puedan sentir el peso y el orgullo de sus responsabilidades.","Hechizo",[],["Demacia"],"COMÚN"],"01DE046":["Centinela de la Vanguardia","","","Que todo esté en calma no significa que sea seguro.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE050":["Purificar","Silencia a un adepto.","","''La grismarca de petricita es tu principal protección contra la magia, el símbolo de nuestras responsabilidades y un recordatorio de nuestra autoridad. Hónrala por encima de todas las cosas''.\n- Manual del cazador de magos","Hechizo",[],["Demacia"],"COMÚN"],"01DE040":["Persuasor de los Cazadores de Magos","Consigo +1|+1 y Contendiente cuando hayas lanzado un hechizo de coste 6 o más esta partida.","","''Ciudadanos de Demacia, manteneros a salvo es un honor. Para ello, precisamos de vuestro apoyo incondicional, pues, a pesar de nuestras altas murallas, hay magos ocultos entre nosotros''.\n","Unidad",[],["Demacia"],"RARA"],"01DE036":["Escudera de la Vanguardia","Cuando invocas a una unidad Élite, mi coste se reduce en 1.","","''Cada lugar y cada persona que he conocido me ha aportado algo nuevo. Sin embargo, cuanto más crezco y más me fortalezco, me doy más cuenta de lo mucho que me queda por aprender''. - Cithria, escudera de la Vanguardia\n","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE037":["Réplica","Concede +3|+0 y Barrera a un aliado esta ronda.","","''Como era de esperar, luchas como un poro''. - Fiora","Hechizo",[],["Demacia"],"RARA"],"01DE014":["Refuerzos","Invoca 2 Vanguardias Impertérritas y otorga +1|+1 a los aliados Élite.","","''Nuestro enemigo sabe que, si ataca a uno de nosotros, todos responderemos al ataque''.\n- Código de la Vanguardia\n","Hechizo",[],["Demacia"],"RARA"],"01DE015":["Guardiana radiante","Cuando se me invoca, consigo Robo de vida y Aguante si un aliado ha muerto esta ronda.","","''Mareas de manos frías de no muertos arrastraban a sus compañeros hacia abajo. Solo ella se resistía; un baluarte de luz y justicia que parecía trazar los nombres de los caídos con cada giro de su espada''. - Alférez demaciano","Unidad",[],["Demacia"],"RARA"],"01DE003":["Guardafilos Laurent","Jugar: Otorga +2|+2 a un aliado.","","''Sí, puedo ver su belleza. No obstante, como con cualquier otro artilugio, su verdadera hermosura solo se revela en manos de quien logra su dominio''. ","Unidad",[],["Demacia"],"RARA"],"01DE026":["Combate único","Un aliado y un enemigo se golpean el uno al otro.","","''Que hablen las espadas''. - Fiora","Hechizo",[],["Demacia"],"COMÚN"],"01DE032":["Barrera prismática","Concede Barrera a un aliado esta ronda.","","''Si eres diferente, puede que el mundo te dé la espalda. Dicen que en la diferencia está la debilidad, pero lo que se oculta en ella en realidad es fortaleza y compasión. ¡Te protegeré incluso en los momentos de mayor oscuridad!''. - Lux","Hechizo",[],["Demacia"],"COMÚN"],"01DE027":["¡En guardia!","Concede a los aliados Contendiente esta ronda.","","''No existe demaciano que contemple rechazar la lección de un Laurent sobre el dominio de la espada. Tampoco que haya sobrevivido a ella''. - Fiora","Hechizo",[],["Demacia"],"RARA"],"01DE006":["Sargento de la Vanguardia","Cuando se me invoca, se crea 1 ¡Por Demacia! en la mano.","","''Entrena con nosotros de sol a sol, y siempre es el primero en adentrarse en el campo de batalla. Más duro que el acero y más firme que la roca, no podríamos haber dado con un líder mejor''. - Alférez demaciano","Unidad",["ÉLITE"],["Demacia"],"RARA"],"01DE038":["Senna, Centinela de la Luz","La primera vez que un Lucian aliado muera, consigo +1|+1 y Ataque doble.","","''Nuestros Centinelas son la primera línea de defensa entre la marea incesante de no muertos y los reinos de los mortales. Golpeamos los primeros, sin piedad y sin mirar atrás, pues las vidas de nuestros compañeros están en juego''.","Unidad",[],["Demacia"],"RARA"],"01DE041":["Espalda con espalda","Concede a dos aliados +3|+3 esta ronda.","","''¡Cúbreme las espaldas, que voy!''.\n''Vaya, justo te iba a pedir yo lo mismo''.\n- Lorn y Dax, batallón del este","Hechizo",[],["Demacia"],"RARA"],"01DE035":["¡Por Demacia!","Concede a los aliados +3|+3 esta ronda.","","''Es nuestro hogar, familia y compañeros en batalla. Es nuestro orgullo, honor y fortaleza. Hoy luchamos por defenderla y por eso gritamos con orgullo: ¡Demacia!''.\n- Sargento de la Vanguardia","Hechizo",[],["Demacia"],"RARA"],"01DE018":["Golpe radiante","Concede a un aliado +1|+1 esta ronda.","","''Los no muertos luchan como si para ellos no hubiera mañana. Nuestro trabajo es asegurar que así sea''. - Lucian\n\n","Hechizo",[],["Demacia"],"COMÚN"],"01DE009":["Guarda de acero radiante","Jugar: Concede Barrera a un aliado esta ronda.","","''El secreto de nuestra prosperidad como nación es que, si el precio de la victoria son las vidas de nuestros soldados, jamás lo pagaremos de buena gana''. - Rey Jarvan III","Unidad",[],["Demacia"],"COMÚN"],"01DE039":["Cithria de Cloudfield","","","''Antes de irme a dormir, mi madre me contaba historias de los grandes héroes de Demacia mientras afilaba su espada. Mis sueños estaban repletos de aventuras, y hoy comienzo a escribir la mía''.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE056":["Noblespada de la Vanguardia","Atacar: Consigo +2|+2.","","Suena el grito de batalla y mis pies ya han puesto marcha. Solo necesito la orden de mi comandante para conocer mi destino y promulgar su voluntad.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE029":["Rastreador plumaveloz","Cuando invocas a un aliado, consigo Contendiente.","","Estos parientes de los picuchillos alargénteas comparten su instinto depredador, que coexiste con una falta de consciencia en lo que respecta a su relativo tamaño reducido.","Unidad",["AVE"],["Demacia"],"COMÚN"],"01DE028":["Caballería de la Vanguardia","","","La Vanguardia no precisa de tambores que marquen el ritmo de su avance; el eco de los cascos sobre el campo de batalla es más que suficiente.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE013":["Chaleco de cadenas","Otorga Aguante a un aliado.","","El acero demaciano es mundialmente conocido por su solidez. Para forjarlo se necesitan a los mejores herreros.","Hechizo",[],["Demacia"],"COMÚN"],"01DE023":["Investigadora de los Cazadores de Magos","Crea 1 Arresto en la mano cuando hayas lanzado un hechizo de coste 6 o más esta partida.","","''Perdone la intrusión, pero necesitamos que coopere con nosotros. Se nos ha alertado acerca de unos... sucesos inusuales''.","Unidad",[],["Demacia"],"COMÚN"],"01DE051":["Cithria, la Audaz","Atacar: Concede +1|+1 y Temible al resto de aliados en ataque esta ronda.","","''Las historias y las leyendas siempre fueron más que simple ficción para mí. La aventura me llama. Dejé Cloudfield atrás para descubrir mi propia aventura y me he dado cuenta de que tendré incontables. Y esto solo acaba de empezar''.\n","Unidad",["ÉLITE"],["Demacia"],"ÉPICA"],"01DE054":["Redentora de la Vanguardia","Cuando se me invoca, se roba una unidad si un aliado ha muerto esta ronda.","","\"¡Nuestros caídos serán recordados en cada grito de batalla, en cada espadazo, en cada golpe que resistan nuestros escudos! ¡Hoy la victoria será nuestra!''.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"01DE030":["Avanzadilla alargéntea","","","Una infinita lluvia de flechas se precipitaba desde las murallas de la fortaleza, pero ninguna de ellas conseguía siquiera rozar el resplandor plateado que atravesaba el cielo. ","Unidad",["AVE"],["Demacia"],"COMÚN"],"01PZ040":["Jinx","","Veo que tu mano está vacía.","\"¿Qué te pasa, Espinas?\".\n\"¡Me tienes preocupada, Jinx! Cada vez que te aburres, quieres...\".\n\"... volar algo por los aires. ¡Qué gran idea, gracias!\".","Unidad",[],["Piltover y Zaun"],"Campeón"],"01PZ008":["Teemo","Golpe al nexo: Coloca 5 Boletus venenosos en cartas aleatorias en el mazo enemigo.","Has colocado 15 o más Boletus venenosos.","\"Regla n.º 154 del explorador de Bandle: ¡no temas a lo desconocido! Regla n.º 276: ¡los habitantes del bosque son nuestros amigos! Regla n.º 354: ¡si es peludo, se puede tocar pero no comer! Regla n.º 417...''.","Unidad",["YORDLE"],["Ciudad de Bandle","Piltover y Zaun"],"Campeón"],"01PZ056":["Heimerdinger","Cuando lanzas un hechizo, crea una torreta con Fugaz de coste equivalente en la mano. Cuesta 0.","Te he visto invocar aliados tecnológicos cuya suma de poder es igual o superior a 12.","''¿Científico loco? ¡Pfff! ¡Perdona, querrás decir científico altamente estable, aunque ligeramente desordenado y ecléctico! ¡Gracias!''.","Unidad",["YORDLE"],["Ciudad de Bandle","Piltover y Zaun"],"Campeón"],"01PZ013":["Experimentador mejorado","Jugar: Descarta tu mano. Roba 3. Inflige 3 de daño a un enemigo.","","Sus sueños le costaron sus manos, pero no desistió. Nada se interpondrá en su camino.","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"01PZ007":["Robot del desfile","Apoyo: Crea 4 copias del aliado al que apoye en tu mazo.","","El sonido de los cañones fue guiando hacia la plaza a las multitudes que querían disfrutar del espectáculo. Pasarían semanas hasta que consiguieran quitarse todo el confeti del pelo.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ018":["Prodigio de la academia","","","¿Cómo apunta? Muy buena pregunta.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ019":["Aprendiz entusiasta","Cuando se me invoca, recuperas 2 de maná de hechizos.","","No todo el mundo está hecho para traer el progreso a Piltover. Hay gente que necesita un poco de orientación... Por ejemplo, la gente con un punto de vista equivocado.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ025":["Vendedor ambulante de boletus","Cuando juegas un hechizo, coloca 3 Boletus venenosos en el mazo enemigo.","","''¿Son de calidad?''.\n''¡Hombre, pues claro! ¡De primera categoría! ¡Me lo han dicho ellos mismos!''.\n''A ver, dámelos... ¿Qué?''.\n''¡Ajá! ¡Este va a casarse!''.\n''¿Cuántos te has comido?''.\n''... ¡como una lapa!''.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ048":["Corina Veraza","Jugar: Destruye las 5 cartas de más arriba del mazo para infligir 1 de daño por cada hechizo destruido a todos los enemigos y al nexo enemigo.","","''Los piltovanos son cortos de miras y no ven más allá de los engranajes y la chatarra; son incapaces de valorar el delicado arte de cada tallo, cada pétalo, cada célula de mi cultivario. Elaboraré una sentencia con la gracia que no merecen''.","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"01PZ028":["Invención improvisada","Al lanzarse o descartarse, invoca 1 Escurridizo de chatarra.","","Con un puñado de chatarra y muy poco tiempo, la joven inventora recordó una peculiar fuente de inspiración: una criatura que una vez vio escapar por los ríos de una jungla muy lejana.","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"01PZ050":["Fuerza de hechizo naciente","Concede a un aliado +4|+0 y Ataque rápido esta ronda.","","''Da como cosquillas cuando empieza a brillar. Es normal..., ¿no?''. - Ezreal","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"01PZ054":["Novato de los Bum","Atacar: Inflige 2 de daño al nexo enemigo.","","''¿Seguro que es buena idea?''.\n''Nop''.\n''Deberías responder que sí''.\n''Pues casi mejor que no preguntes''.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ030":["Personaje sospechoso","Jugar: Elige un adepto. Me transformo en una copia exacta de él.","","''¡Hola, compañeros barones químicos!''.","Unidad",["YORDLE"],["Piltover y Zaun"],"RARA"],"01PZ017":["Vendedor de barriles usados","Cuando se me invoca, se invoca 2 Barriles cáusticos.","","''¿Te envía Ziel? Ya le dije que 'santa Rita, Rita, lo que se da no se quita'. No puedo devolverle el dinero de algo que ni siquiera he visto. En cualquier caso, he recibido otra tanda de barriles de primera que no me importaría repartir...''.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ038":["Dragador del Sumidero","Jugar: Descarta una carta para robar 1.","","En el Sumidero no se desperdicia nada.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ036":["Ezreal","Golpe al nexo: Crea 1 Disparo místico Fugaz en la mano.","Has seleccionado como objetivo a enemigos 8 veces o más.","\"¿Gafas? Listas. ¿Bufanda? Lista. ¿Guantelete guay con poderes mágicos que entiendo a la perfección? ¡Listo, listo y listo!\".","Unidad",[],["Piltover y Zaun"],"Campeón"],"01PZ035":["Jae Medarda","Cuando se me selecciona como objetivo, se roba 1.","","Heredero del prestigioso clan Medarda de Piltover, Jae siempre ha preferido salir en busca de antiguos artefactos que ocuparse del negocio familiar... para disgusto de su padre.","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"01PZ010":["Nube de setas","Coloca 5 Boletus venenosos en el mazo enemigo.","","Primero, un golpe seco cuando explota el champiñón. Luego, un dolor punzante y extenuante. Por último, el lejano eco de las risas...","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"01PZ045":["Mocosa zaunita","Jugar: Descarta una carta para robar 1.","","''Apuesto a que crees que las ratas del Sumidero cuidan de los suyos''.\n''Lo único que hacen es mirarse el ombligo, primo''.\n''Una pena... Eh, ¿has visto mi cartera?''.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ002":["Tabernero del callejón","Cuando se me invoca, se crea una carta aleatoria en la mano por cada copia de Tabernero del callejón que hayas invocado en esta partida.","","''Eso es, amigo mío; es un trago ligero de la misma manera que el Sumidero tiene un aroma ligero. El cubo está donde el tocadiscos''.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ004":["Andanada certera","Inflige 3 de daño a un enemigo o al nexo enemigo, 2 a otro y 1 a otro más.","","''Cuando uno tiene talento, la suerte no existe''. - Ezreal","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"01PZ020":["Poro atrevido","","","Su primer lanzamiento fue pura casualidad: se cayó en un cañón del Día del Progreso mientras se pavoneaba. Ahora se ha convertido en la estrella de Piltover: surca los cielos y emociona al público a su paso.","Unidad",["PORO"],["Piltover y Zaun"],"COMÚN"],"01PZ046":["Copias falsificadas","Escoge una carta de la mano. Crea en tu mazo 4 copias exactas de esa carta.","","La imitación es la forma más sincera de hurto.","Hechizo",[],["Piltover y Zaun"],"RARA"],"01PZ052":["Disparo místico","Inflige 2 de daño a cualquier unidad o al nexo.","","''Nunca fallo. Aunque alguna vez que otra he realizado un disparo de advertencia...''. - Ezreal","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"01PZ033":["Búsqueda de la perfección","Si has jugado 20 cartas nuevas esta partida, invoca 1 Gatástrofe.","","''Todos los que hicimos posible la visión de Von Yipp fuimos engañados. No sabíamos lo que habíamos creado, el terrible poder que liberaríamos''. - Ingeniero de proyecto piltovano","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"01PZ005":["Transmodulador hextech","Transforma un adepto en una copia idéntica de otro adepto.","","''¡NO PARABAS DE DECIR QUE QUERÍAS PERDER PESO!''.\n''¿Y VAS Y ME CONVIERTES EN YORDLE?''.\n''¡HAS PERDIDO PESO!''.\n''¡¡PERO AHORA SOY UN YORDLE!!''.","Hechizo",[],["Piltover y Zaun"],"RARA"],"01PZ021":["Secuaces de Midenstokke","Golpe al nexo: Invoca una copia exacta de mí.","","''Señor Berz, lo encontramos dormido dentro de la caja fuerte, cubierto en oro y aferrado a la puerta''.\n''No era yo, sería un tipo que se parecía a mí''.\n''Aún no ha soltado la puerta''.\n''Demostradlo''.","Unidad",[],["Piltover y Zaun"],"RARA"],"01PZ031":["Impacto de Statikk","Inflige 1 de daño a un enemigo o al nexo enemigo y 1 a otro.\nRoba 1.","","\"¡Y así descubrimos el arco voltaico! Claro que mi predecesor ya planteó la hipótesis de tal evento, pero subestimó el alcance del arco. Pobre hombre\". - Heimerdinger","Hechizo",[],["Piltover y Zaun"],"RARA"],"01PZ059":["Machacabot dorado","","","MATAR. APLASTAR. DESTRUIR. REPETIR.","Unidad",["TECNOLOGÍA"],["Piltover y Zaun"],"COMÚN"],"01PZ001":["Chatarra","Para jugar esta carta, descarta hasta 2 cartas. Roba 1 por cada carta que hayas descartado.","","''Aaaaaaanda. ¡¿CINCO POLIS Y UN GÓLEM?! ¡Quieto parao! ¡Tengo justo lo que necesito! A ver si lo encuentro...''.\n- Jinx","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"01PZ057":["Chatarra montada","Invoca 2 Escurridizos de chatarra.","","Dos gentiles criaturas a las que una vez separó una obstáculo infranqueable de terreno se reúnen de una vez por todas en las tibias aguas del Sumidero.","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"01PZ027":["Rayo termogénico","Gasta todo el maná para jugar esta carta. Inflige esa cantidad de daño a una unidad.","","''Hemos agotado el tiempo y los fondos. A pesar de que el rayo funciona, no hemos logrado regular su consumo de energía''. - Investigadora zaunita","Hechizo",[],["Piltover y Zaun"],"RARA"],"01PZ055":["Académica astuta","Cuando robas una carta, consigo +1|+0 esta ronda.","","La imaginación es la chispa de una gran invención, pero hace falta investigar con diligencia para que esa chispa se convierta en una explosión.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ014":["Innovación no autorizada","Invoca 1 Artilugio ilegal.","","''Presenta fallos e incidentes para todos los gustos: temblores de explosiones lejanas, gases pútridos de las fisuras. Pronto uno de esos idiotas acabará destrozando la ciudad''.\n- Filántropo piltovano","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"01PZ034":["Chatarrero del Sumidero","Alianza: Crea 1 Mapa del Sumidero en la mano. Cuesta 0 esta ronda.","","Enseguida, los niños zaunitas comenzaron a explorar los viejos túneles de la mina y los niveles más profundos de las Calles. Descubrieron un mundo diferente, lleno de nuevos amigos.","Unidad",[],["Piltover y Zaun"],"RARA"],"01PZ003":["Robot de ensamblaje","Cuando lanzas un hechizo, consigo +1|+1.","","''Cualquier descerebrado puede construir una máquina, ¡pero hace falta una destreza extraordinaria para inculcarle la idea de verdadero progreso a una mente mecánica! Esos burócratas de poca monta pronto volverán a suplicarme...''.\n - Klas Henwick","Unidad",[],["Piltover y Zaun"],"RARA"],"01PZ044":["Quematrastes punki","Jugar: Inflige 1 de daño a todos los enemigos.","","''... su solo desemboca en una escala menor armónica, justo antes de arpegiar —sí, esa palabra existe— hacia la transposición del puente. Seguramente no logres entender su obra jamás''. - Max Bliff, cancerbero","Unidad",[],["Piltover y Zaun"],"RARA"],"01PZ029":["Benefactor eminente","Jugar: Manifiesta una carta épica de una de tus regiones.","","''Siempre fui un hombre consumido por el rencor. Aplastaba a la competencia mientras amasaba mi propia fortuna. Ahora me dedico a realizar labores altruistas y confío en que el penitente invierno me absuelva de mis pecados''.","Unidad",[],["Piltover y Zaun"],"RARA"],"01PZ051":["Forjadora temeraria","Todos tus hechizos y habilidades infligen 1 de daño adicional.","","''¿Me dices que quieres un extra de explosiones? ¡Pues has venido al lugar adecuado!''.","Unidad",[],["Piltover y Zaun"],"RARA"],"01PZ023":["Profesor Von Yipp","Cuando invocas un aliado de coste 1, le otorgas +2|+2.","","''Hoy tengo el honor de presentar ante el comité mi nuevo invento, como ha demostrado mi querido compañero...''.","Unidad",["GATO"],["Piltover y Zaun"],"RARA"],"01PZ024":["Volticiano inestable","Consigo +4|+0 y Ataque rápido cuando hayas lanzado un hechizo de coste 6 o más esta partida.","","Nombre: Klas Henwick. Edad: 51. Tipo de permiso: Condicional de clase 2. Estado: Denegado. Comentarios: Ignoró las continuas advertencias sobre la reducción de explosiones en el laboratorio. (Caso 13X764NM). PROHIBIDA LA ENTRADA.","Unidad",[],["Piltover y Zaun"],"RARA"],"01PZ049":["¡Día del Progreso!","Roba 3 y después reduce en 1 su coste.","","¡DÍA DEL PROGRESO!\n¡Ven a celebrarlo en la PLAZA DE LAS PUERTAS DEL SOL!\n¡Descubre MARAVILLAS HEXTECH!\n¡Contempla al PORO ATREVIDO!\n¡Escucha HOY al HOMBRE DEL MAÑANA!\n¡Entrada GRATUITA! \n¡Los niños piltovanos son bienvenidos!","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"01PZ006":["Guardia de la plaza","Cuesto 1 menos por cada hechizo que hayas lanzado en esta partida.","","Tienes veinte segundos para seguir las órdenes.","Unidad",[],["Piltover y Zaun"],"RARA"],"01PZ053":["Panda de roedores","Cuando se me invoca, se crea 1 Nube de setas en la mano.","","''¡Como lo oyes! ¡Van escondidos por ahí en amasijo! Parece que están locos, pero es porque no los entiendes como yo. ¡Tienen grandes planes! Grandes panes. Pan con queso... ¿Qué estaba diciendo?''. - Vendedor ambulante de boletus","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ012":["¡Mascafuegos!","Descártame para invocarme.","","''¡A por ellos, Mascafueguitos!''. - Jinx","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ039":["¡A tope!","Para jugar esta carta, descarta 1.\nInflige 3 de daño a cualquier unidad o al nexo.","","''¡FUEGO Y TODA LA PESCA!''. - Jinx","Hechizo",[],["Piltover y Zaun"],"RARA"],"01PZ016":["Destello de lucidez","Crea un hechizo aleatorio de coste 6 o más de una de tus regiones en la mano.\nRecarga el maná de hechizos.","","Solo hace falta una epifanía para poner en marcha el legado.","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"01PZ058":["Roedor bobalicón","Cuando se me invoca, se crean 2 Nubes de setas en la mano.","","''¿Has visto una grande, eh? Es tan descomunal como un caballo y tan taimada como un krug. No la pierdas de vista, hazme caso. ¡Ese bombón se ha ganado el título de reina por algo!''. - Vendedor ambulante de boletus","Unidad",["YORDLE"],["Piltover y Zaun"],"RARA"],"01PZ009":["Aeronauta aficionado","","","''¿Máquinas voladoras personales? ¡Eso son quimeras! Es más, acabo de pedirle a mi aprendiz que tire el último prototipo. ¿Dónde se habrá metido?''. - Ingeniero piltovano","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01PZ042":["Marinera intrépida","Apoyo: Concede Elusión al aliado al que apoye esta ronda.","","Para muchos piltovanos, la ciencia y la invención son la única forma de explorar lo inexplorado desde la comodidad de su Ciudad del Progreso. Solo unos pocos se aventuran más allá del horizonte para descubrir mucho más: el mundo.","Unidad",[],["Piltover y Zaun"],"RARA"],"01PZ026":["Mapa del Sumidero","Otorga Elusión a un aliado.","","''¡Los piltis creen que lo saben todo, pero sus mapas solo señalan los lugares que les hemos indicado nosotros! No conocen el terreno, pero tú puedes conocerlo... por un módico precio''. - Ajuna Lem, carroñero del Sumidero","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"01PZ043":["Carterista punki","Golpe al nexo: Crea en la mano una copia exacta de un hechizo aleatorio del mazo del rival.","","Esperaban que los desterrados bajo la superficie de la Ciudad del Progreso se volviesen los unos contra los otros.  En su lugar, decidieron unirse y trabajar juntos para construir un nuevo hogar. No era gran cosa, pero era su hogar: Zaun.","Unidad",[],["Piltover y Zaun"],"RARA"],"01PZ047":["Barril cáustico","Último aliento: Inflige 1 de daño a ambos nexos.","","''Te diría que te pusieras traje, pero, con el calor que hace, vas a acabar más sudado que el sobaco de un camionero... Pero guantes sí, ¿me oyes? Ah, y si te cae algo de esa porquería encima, reza por que no sea grave''. - Ziel, capataz zaunita","Unidad",[],["Piltover y Zaun"],"COMÚN"],"01FR024":["Anivia","Atacar: Inflijo 1 de daño a todos los enemigos y al nexo enemigo.\nÚltimo aliento: Revivo como Huevonivia.","Tienes Iluminación.","''Nací en esta tierra severa y es mi deber protegerla. Ni el tiempo, la guerra o la mismísima muerte perturbarán mi vigía''.","Unidad",["AVE"],["Freljord"],"Campeón"],"01FR039":["Tryndamere","","En lugar de morir, subo de nivel.","''No mueras por la causa, vive por ella''.","Unidad",[],["Freljord"],"Campeón"],"01FR006":["Legado de los Hijos del Hielo","Concede +2|+2 a un aliado y a todas sus copias estén donde estén.","","''Somos los Hijos del Hielo. La magia de Freljord corre por nuestras venas. En el pasado, nuestros ancestros sellaron una maldad ancestral; ahora nosotros somos la última línea de defensa que impide su regreso''. - Gregor el Guardián","Hechizo",[],["Freljord"],"COMÚN"],"01FR022":["Halcón de mal agüero","Cuando se me invoca, otorga +1|+1 a los dos aliados de arriba del mazo.","","''Nuestros asaltantes han llegado en tres ocasiones hasta puertas avarosanas, pero siempre se han encontrado arcos tensados. ¿Cómo sabían que atacaríamos?''. - Steffen, thane de cicatrices","Unidad",["AVE"],["Freljord"],"COMÚN"],"01FR042":["Vientos helados","Aplica Escarchar a 2 enemigos.","","''¿Osas desafiarme en mi propio territorio? Esta batalla te queda grande''. - Anivia","Hechizo",["ELEMENTAL"],["Freljord"],"RARA"],"01FR009":["Braum","La primera vez que sobrevivo a daño, invoca 1 Poro fuerte.","He sobrevivido a 10 o más de daño en total.","\"¡Papá, cuenta la de Braum y la puerta!\".\n\"¡O cuando chocó contra una montaña y la partió en dos!\".\n\"¡Ah! ¡O la vez que salvó la taberna del temible yeti!\".","Unidad",[],["Freljord"],"Campeón"],"01FR018":["Lobo dientehielo","Golpear: Cuando golpeo a una unidad con 0 de poder, muere.","","Los depredadores de los páramos del norte han aprendido que las presas más fáciles son las víctimas del invierno.","Unidad",["PERRO"],["Freljord"],"RARA"],"01FR036":["Tirador avarosano","Jugar: Inflige 1 de daño a un enemigo.","","En Freljord, o se caza o se muere de hambre.","Unidad",[],["Freljord"],"COMÚN"],"01FR045":["Steffen, thane de cicatrices","Cuando sobrevivo al daño, consigo +3|+0.","","''Mi destino quedó entrelazado con el de la Garra Invernal cuando Sejuani me hizo mi primera cicatriz. Desde entonces, todas las demás me las he ganado a su servicio''.","Unidad",[],["Freljord"],"COMÚN"],"01FR008":["Poro solitario","Cuando se me invoca, se crea otro poro de coste 1 aleatorio en la mano.","","''Llevo toda mi vida en Freljord y te digo que no hay nada más escalofriante que ver a este pequeñín triste''. - Pastor de poros","Unidad",["PORO"],["Freljord"],"COMÚN"],"01FR055":["Fragmentación","Inflige 4 de daño a un enemigo si tiene 0 de poder. Si no, le aplica Escarchar.","","''El invierno avanza sobre estas tierras y trae consigo humildad para los fuertes y destrucción para los débiles''.\n- Steffen, thane de cicatrices","Hechizo",["ELEMENTAL"],["Freljord"],"COMÚN"],"01FR038":["Ashe","Atacar: Aplica Escarchar al enemigo más fuerte.","Has reducido el poder de 5 enemigos o más a 0. Cuando subo de nivel, crea 1 Flecha de cristal en la parte superior del mazo.","\"Cuando miro a mi hogar, veo lo que es y lo que podría llegar a ser. Un lugar próspero, de abundancia; un hogar tanto para mi gente como para todos aquellos que busquen la paz. Freljord, unido\".","Unidad",[],["Freljord"],"Campeón"],"01FR029":["Toque de alarma","Roba un campeón.","","''¡Asaltantes a la vista! Dad el aviso y encended las antorchas. Necesitaremos toda la ayuda que podamos conseguir''.\n- Centinela avarosano","Hechizo",[],["Freljord"],"RARA"],"01FR035":["Saqueadora sin cicatrices","Cuando sobrevivo al daño, consigo +3|+0.","","''La juventud avarosana crece débil, blanda y nada preparada para el fragor de la batalla. Nuestros jóvenes se forjan en el fragor del combate''. - Madretriz Vrynna\n","Unidad",[],["Freljord"],"COMÚN"],"01FR020":["Avalancha","Inflige 2 de daño a TODAS las unidades.","","El alma de toda avalancha es una simple piedra que decide cambiar de lugar.","Hechizo",["ELEMENTAL"],["Freljord"],"RARA"],"01FR014":["Yeti bebé","Último aliento: Crea 2 Yetis enfurecidos en tu mazo.","","''¡Era tan pequeño y tranquilito! El tiempo pasa volando y se ha convertido en un... Bueno, en un yeti''. - Trampero avarosano","Unidad",["YETI"],["Freljord"],"COMÚN"],"01FR049":["Lobo acechante","Cuando se me invoca, tu rival invoca 1 Liebre ártica.","","''Un conejo jamás podrá aprender a ser lobo''.\n- Refrán de la Garra Invernal","Unidad",["PERRO"],["Freljord"],"COMÚN"],"01FR037":["Batidores avarosanos","Alianza: Otorga +3|+3 y Abrumar al aliado de más arriba del mazo.","","A medida que los refuerzos alcanzaban la cima de la colina, los batidores se arrodillaron ante la Comandante, puesto que ella, la reina Ashe, Avarosa reencarnada, prometía la paz en su discurso.","Unidad",[],["Freljord"],"RARA"],"01FR026":["Garrasalvaje alfa","","","La fuerza de un caballo de batalla y la ferocidad inconsciente de un felino.","Unidad",["GATO"],["Freljord"],"COMÚN"],"01FR030":["Acero quebradizo","Aplica Escarchar a un enemigo con 3 o menos de vida.","","''¿Frío? ¡Ja! ¡Esperemos que tu moral sea más robusta que tu acero!''. - Braum","Hechizo",["ELEMENTAL"],["Freljord"],"COMÚN"],"01FR013":["Madretriz Vrynna","Cuando sobrevivo al daño, consigo +3|+0.","","''Prefiero morir congelada en la intemperie antes que compartir un hogar con los piltrafas de Ashe. Si calor es lo que buscan, yo se lo daré''.","Unidad",[],["Freljord"],"ÉPICA"],"01FR019":["Aliento invernal","Mata a todos los enemigos con 0 de poder y aplica Escarchar a todos los enemigos.","","La Comandante Invierno es la primera y última enemiga a la que deben hacer frente los invasores de Freljord. Sus progenieros son las despiadadas ventiscas y la escarcha.","Hechizo",["ELEMENTAL"],["Freljord"],"ÉPICA"],"01FR041":["Guardia del hogar avarosano ","Cuando se me invoca, se otorga +1|+1 a los aliados del mazo.","","\"¡Muchas tribus bajo un mismo estandarte! Quizá algún día toda Freljord luche unida''.","Unidad",[],["Freljord"],"ÉPICA"],"01FR025":["Pastor de poros","Cuando se me invoca, roba un poro si hay un poro visible.","","Los pastores solo necesitamos dos cosas: amor y compañía. Lo demás solo son peludismos.\n","Unidad",[],["Freljord"],"RARA"],"01FR054":["Saqueadora damatriz","","","''Los fuertes cosechan lo que los débiles siembran. ¡Que aprendan esos avarosanos cuál es su sitio!''.","Unidad",[],["Freljord"],"RARA"],"01FR021":["Tarkaz el Sin Tribu","Atacar: Inflige 1 de daño a todas las unidades en combate.","","''Tarkaz luchó más y mejor que la mayoría. Asumió su derrota con elegancia. Bueno, más o menos...''. - Tryndamere","Unidad",[],["Freljord"],"ÉPICA"],"01FR043":["Amor de poro","Jugar: Combina tus adeptos poros para formar 1 Montón de poros y le otorga sus estadísticas y palabras clave positivas.","","''Venga, una historia más, pero solo si estáis en silencio, ¡que va a venir madre!''.\n''Tiempo atrás, los saqueadores atacaron el pueblo de Avarosa. Sus defensas no fueron suficientes y la batalla parecía perdida. Entonces apareció un poro que le ofreció ayuda a Avarosa...''.","Unidad",["PORO"],["Freljord"],"RARA"],"01FR033":["Piedras wyrdia","Comienzo de ronda: Obtienes una gema de maná adicional esta ronda.","","''Estos monumentos ancestrales nos recuerdan que no somos la única tribu que ha desafiado estas indómitas tierras''. - Ashe","Unidad",[],["Freljord"],"COMÚN"],"01FR011":["Arquero glacial","Jugar: Aplica Escarchar a un enemigo.","","Los avarosanos se enorgullecen de sus duras estaciones y sus gélidas tierras. Sus sagaces defensores van más allá. ","Unidad",[],["Freljord"],"COMÚN"],"01FR050":["Tabernero bonachón","Jugar: Cura a un aliado o a tu nexo 3 de vida.","","''¡En el Búho Achispado todos sois bienvenidos! Tenemos potajes y brebajes de todo tipo para combatir el frío de estas tierras. ¡Adelante!''.","Unidad",[],["Freljord"],"COMÚN"],"01FR052":["La caminante","Jugar: Destruye a todas las unidades con 4 o menos de poder en juego y en ambas manos.","","''Me alcé de entre los escombros para toparme con una cicatriz que atravesaba el terreno circundante. Donde antes aguardaban mis compañeros, ahora solo quedaban cenizas candentes y una figura distante avanzaba en el horizonte...''.\n- Bjerg el Errante","Unidad",[],["Freljord"],"ÉPICA"],"01FR016":["Snack para poros","Otorga +1|+1 a los poros aliados estén donde estén.","","''Se los zampan de un bocado y se te quedan mirando, con la lengua fuera, más contentos que unas pascuas, como pidiendo más. ¡A ver quién les dice que no!''. - Repostero avarosano","Hechizo",[],["Freljord"],"COMÚN"],"01FR005":["Furia de batalla","Otorga +8|+4 a un aliado.","","''Dicen que me enciendo con facilidad''. - Tryndamere","Hechizo",[],["Freljord"],"RARA"],"01FR023":["Llamada de la comandante","Invoca al aliado de más arriba del mazo ahora y en cada comienzo de ronda.","","Llegará el día en que una llamada inconfundible resuene en todo Freljord. Todos se alzarán para responder, pues anunciará el regreso de nuestros antiguos enemigos.","Hechizo",[],["Freljord"],"ÉPICA"],"01FR047":["Místico salvaje","Iluminación: Tengo +4|+4.","","''Los que rugen para entenderse con las bestias no tardan en olvidar su lengua materna''. - Anivia","Unidad",[],["Freljord"],"COMÚN"],"01FR056":["Yeti de hielo","Cuando se me invoca, se aplica Escarchar a los enemigos con 3 o menos de vida.","","''¡Aaaaaaaaaaaaaaaah!''. - Bjerg el Errante","Unidad",["YETI"],["Freljord"],"RARA"],"01FR027":["Elnuk fornido","","","Las historias del pueblo avarosano hablan del ''Tío elnuk'', un cascarrabias cabezota que solo quería un pequeño terreno y meter las narices en alguna que otra discusión. ","Unidad",["ELNUK"],["Freljord"],"COMÚN"],"01FR057":["En manada","Concede +2|+2 a los aliados y Abrumar esta ronda.","","Un aullido solitario perforó el silencio de la noche. Entonces, otro le siguió, y otro poco después. En unos instantes, la manada aullaba como si se tratara de un solo ser: un coro frenético entonando su sed de sangre.","Hechizo",[],["Freljord"],"RARA"],"01FR004":["Elixir de hierro","Concede a un aliado +0|+2 esta ronda.","","\"Frío, ¿eh? No pasa nada, en el Búho servimos algo tan fuerte que hace que los bebés tengan barba y el frío salga pitando de tu cuerpo\". - Tabernero bonachón","Hechizo",[],["Freljord"],"COMÚN"],"01FR048":["Trampero avarosano","Cuando se me invoca, se crea 1 Yeti enfurecido entre las 3 cartas de arriba de tu mazo.","","''¡No he cazado nada en toda la semana! O esas bestias me ven venir, o algo anda espantándolas...''.","Unidad",[],["Freljord"],"COMÚN"],"01FR017":["Batallón de elnuks","Jugar: Invoca a todos los elnuks de las 6 cartas de arriba de tu mazo y coloca al resto en tu mazo.","","''Los avarosanos son como los elnuks: herbívoros insípidos, víctimas de los sin cicatrices. Si han sobrevivido hasta ahora es porque son muchos''. - Madretriz Vrynna","Unidad",["ELNUK"],["Freljord"],"COMÚN"],"01FR046":["Ten coraje","Otorga a un aliado herido +3|+3.","","''A pesar de estar gravemente herido, Braum dejó escapar una sentida carcajada... Sabía que los héroes se forjan en los peores momentos''.\n- La leyenda de Braum","Hechizo",[],["Freljord"],"RARA"],"01FR012":["Catalizador de eones","Obtienes una gema de maná vacía y tu nexo se cura 3 de vida.","","Ni el rubí ni el zafiro superan el encanto de la roca eón, una brillante gema con legendarias propiedades curativas.","Hechizo",[],["Freljord"],"COMÚN"],"01FR040":["Chamana colmillo escarcha","Comienzo de ronda: Aplica Escarchar al enemigo más fuerte.","","''Para fundirse con lo salvaje, hemos de aprender no a refugiarnos del frío, sino a deleitarnos con su brutalidad''.","Unidad",[],["Freljord"],"RARA"],"01FR031":["Yeti ancestral","Fin de ronda: Mi coste se reduce en 1.","","''¿Qué ha sido eso? Parecía un estornudo. ¿Los glaciares... estornudan?''. - Bjerg el Errante\n","Unidad",["YETI"],["Freljord"],"RARA"],"01FR053":["Poro fuerte","","","''Cuernos largos perdió un ojo defendiendo al mismísimo Rey Poro del ataque de un garrasalvaje iracundo. Al fin y al cabo, lo que importa no es el tamaño del arma, sino el del corazón''.\n- Pastor de poros\n","Unidad",["PORO"],["Freljord"],"COMÚN"],"01FR010":["Promesa de progeniero","Otorga +0|+3 a 2 aliados.","","''Seré la antorcha que guíe tu corazón, el escudo que te acompañe. Deja que reúna la fuerza que nos proteja. Que nuestras vidas fluyan en armonía cuando la sangre selle mi promesa''. - Tryndamere","Hechizo",[],["Freljord"],"RARA"],"01FR001":["Congelación instantánea","Aplica Escarchar a un enemigo.","","El frío llega y arrasa con todo sin previo aviso, incluso con los mejores guerreros.","Hechizo",["ELEMENTAL"],["Freljord"],"RARA"],"01FR032":["Vidente iluminado","Cuando lanzas un hechizo, se otorga +1|+1 al aliado de más arriba del mazo.","","''Otórgales buen oído para escuchar el viento, pies ligeros para cruzar las nieves y vista aguda para vislumbrar más allá del velo invernal''.","Unidad",[],["Freljord"],"RARA"],"01FR051":["Grandes aventuras","Si tienes un yeti, se invoca 1 Yeti enfurecido. Si no, se crea en la parte superior de tu mazo.","","''Este tenía unas fauces repletas de dientes como cuchillos, puños enormes y unos ojos que daban miedo. Cuando rugía, ¡hacía temblar hasta a los árboles! Me lo dijo el tío Bjerg''.\n- Ingvar, la Joven","Hechizo",[],["Freljord"],"COMÚN"],"01FR034":["Los resilientes","Cuando se me invoca, consigo +1|+1 por cada aliado que haya muerto.","","''La vida no se lo ha puesto fácil al viejo Bjerg. Perdió a sus compañeros en el norte; volvió meses después, pálido y diciendo sandeces. Que si bestias gigantes por aquí, que si garras enormes por allá... Pobre hombre''. - Tabernero bonachón","Unidad",[],["Freljord"],"RARA"],"01FR007":["Bjerg balbuceante","Cuando se me invoca, se roba una unidad con 5 o más de poder.","","''¡Ti... Tienes que creerme! ¡Era enorme, te lo juro! ¡ENORME!''.","Unidad",[],["Freljord"],"COMÚN"],"01FR003":["Centinela avarosano","Último aliento: Roba 1 carta.","","''En el pasado, busqué mi lugar en campos de batalla lejanos. Ahora sé que mi lugar está junto a los míos, en nuestro hogar. Mis ojos están a su servicio, y su seguridad, en mis manos''.","Unidad",[],["Freljord"],"COMÚN"],"01SI038":["Bromista espectral","Cuando muere otro aliado, inflige 1 de daño al nexo enemigo.","","Su engaño más cruel no fue masacrar a los soldados que confiaron en el llanto de una niña, sino sembrar la duda en los supervivientes que volvieron a casa e ignoraron las súplicas de sus hijas.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI049":["Vestigio del más allá","Mata a un aliado para robar 2 cartas.","","''Me equivoqué. Nunca debimos mirar a través del pálido velo. No importa qué revelación se encontrase más allá, el precio que debíamos pagar era demasiado alto''. - Arie Wrence, vengador impertérrito","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI053":["Elise","Atacar: Invoca 1 Cría de araña en ataque.","Comienzo de ronda: Tienes otras 3 o más arañas.","Antaño fue la matriarca de una poderosa familia noxiana. La oscura unión con las Islas de la Sombra le otorgó una juventud y belleza antinaturales a cambio del sacrificio de un par de almas. Una decisión muy sencilla.","Unidad",["ARAÑA"],["Islas de la Sombra"],"Campeón"],"01SI057":["Crocolito ancestral","Para jugar esta carta, mata a 2 aliados.","","''Mételos en la jaula, pim, pam, pum...\nLlévate todas las almas, una por una...\n¡No dejes que escapen! ¡No, señor!\nO sus espíritus se rebelarán...''.","Unidad",["REPTIL"],["Islas de la Sombra"],"RARA"],"01SI023":["Pastora de almas","Cuando invocas a un aliado con Endeble, obtiene +1|+1.","","Solo los caídos eran capaces de ver que no iba sola, pues solo ellos podían apreciar la infinita hilera de siluetas que la seguían hasta el más allá.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI010":["Envite de sombras","Invoca 2 Jinetes espectrales.","","Ahora viven como murieron en aquel entonces: leales hasta el fin de los tiempos.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI042":["Hecarim","Atacar: Invoca 2 Jinetes espectrales en ataque.","Has atacado con 7 o más aliados con Endeble.","Eso no son truenos. Es la Sombra de la Guerra que se cierne sobre el horizonte.","Unidad",[],["Islas de la Sombra"],"Campeón"],"01SI027":["Ofrendas recientes","Si han muerto 3 o más aliados esta ronda, invoca a Vilemaw.","","''Arrodíllate ante tu dios de dientes afilados. O mejor, muere por él''. - Elise","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI048":["Guardián maldito","Último aliento: Invoca 1 Abominación prófuga.","","Locura y tiempo. Nunca ha habido un dúo más destructivo.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI018":["Escriba del pesar","Cuando se me invoca, crea en la mano una copia de un aliado que haya muerto esta partida.","","''Nuestro escritor no tenía ni idea de que, pronto, la Ru... la Rui... ¡No, no, mal! Se ha vuelto a correr la tinta. Nuestro escritor no tenía... ¡Que no!''.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI030":["Kalista","","He visto morir a 3 o más aliados.","En vida, era una general, una defensora, una heroína. Cuando la carne perdió la batalla, no le quedó más que el fuego ardiente de la retribución, y se convirtió en un espíritu eterno cargado de venganza.","Unidad",[],["Islas de la Sombra"],"Campeón"],"01SI035":["Rhasa, el Desgarrador","Jugar: Mata a los 2 enemigos más debiles si un aliado ha muerto esta ronda.","","''Nos dijeron que sería... un viaje legendario. Íbamos a... por el futuro de Demacia. Zarpamos con esperanza. Pero todas esas vidas... ¿Y para qué?\". - Arie Wrence, soldado demaciano","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"01SI005":["Escurridizo del más allá","Cuesto 1 menos por cada aliado que haya muerto en esta partida.","","En otros tiempos, fue un animal de carga en un reino ya olvidado. Ahora este monstruo recorre viejos campos de batalla en busca de chatarra para su coraza y almas para alimentar su esencia.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI037":["Poro siniestro","","","A ver, hay formas peores de morir.","Unidad",["PORO"],["Islas de la Sombra"],"COMÚN"],"01SI052":["Thresh","","He visto morir a 6 o más unidades.","''Clinc, clanc... hacen las cadenas. Alguien viene a por ti...\nClinc, clanc... El Carcelero está detrás de ti...''.","Unidad",[],["Islas de la Sombra"],"Campeón"],"01SI033":["Comandante Ledros","Jugar: Inflige una cantidad de daño al nexo enemigo equivalente a la mitad de su vida redondeada hacia arriba.\nÚltimo aliento: Regreso a la mano.","","La mayoría de espíritus se pierden cuando el paso de los años difumina sus recuerdos, pero la angustia de Ledros lo ancló a su pasado. Hay cosas que el tiempo no puede borrar.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"01SI003":["Harrowing","Revive a los 6 aliados más fuertes que hayan muerto en esta partida y les otorga Endeble.","","Algunas noches, la marea de espíritus hambrientos se deja llevar por la Niebla Negra. Esta los arrastra a través de los mares para que se deleiten con los mortales y alimenten la oscuridad creciente con nuevos espíritus corruptos.","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"01SI041":["El imperecedero","Último aliento: Revivo al comienzo de la siguiente ronda y consigo +1|+1 por cada vez que he muerto.","","El viejo mártir recordaba cómo condujo a sus camaradas hasta su perdición, pero ha pasado mucho tiempo y ha olvidado el motivo...","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"01SI045":["Absorbealmas","Drena 4 de vida de un aliado.","","''Lo que te mata me hace más fuerte''. - Thresh","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI036":["Sensación de hormigueo","Si un aliado muere esta ronda, invoca 2 Crías de araña.","","La sensación insidiosa que notas en la piel no es tan preocupante como la que sientes debajo de ella.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI051":["Prodigio torturado","Cuando otro aliado muere o se activa Último aliento: Recarga el maná de hechizos.","","Trabajaba día y noche para perfeccionar su obra. Fue entonces cuando una oscura ráfaga silenciosa lo atravesó. Muchos gritaron y trataron de huir; él no notó nada.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI012":["Isleño despistado","Jugar: Otorga a un aliado de la mano Endeble y reduce su coste en 1.","","Vaya, pobre chaval...","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI031":["Heraldo del hierro","Atacar: Consigo +1|+0 por cada aliado con Endeble que tengas.","","Tanto en la vida como en la muerte, imparte sus despiadadas órdenes con un bramido. Y, tanto en la vida como en la muerte, los leales caballeros de Hecarim las acatan y lo siguen a la matanza.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI034":["Lanza negra","Si un aliado muere esta ronda, inflige 4 de daño a una unidad.","","''Nuestra lanza canta por los caídos''. - Kalista","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI043":["Aristócrata desafortunado","Último aliento: Invoca 1 Cría de araña.","","''¿La... Lady Elise? ¿Adónde habéis ido?...''.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI009":["Espíritus agitados","Apoyo: Otorga +2|+0 y Endeble al aliado al que apoye.","","Algunos miran a la Ruina y solo ven destrucción y miseria. Otros prefieren ver el vaso medio lleno.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI007":["Reliquia embrujada","Invoca 3 Espíritus desatados.","","Este tipo de artilugios antiguos son de un valor incalculable tanto para los vivos, que anhelan hacerse con ellos, como para los muertos, que los protegen con desesperación.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI056":["Arácnido furibundo","Cuando se me invoca, concedo +1|+0 al resto de arañas aliadas y -1|-0 a los enemigos esta ronda.","","''Pueden tejer una red del tamaño de un hombre en menos de un minuto... ¿Quieres que te hagan una demostración?''.\n- Elise","Unidad",["ARAÑA"],["Islas de la Sombra"],"RARA"],"01SI001":["Venganza","Mata a una unidad.","","Con su último aliento, los traicionados invocan a Kalista con la esperanza de que su lanza les conceda al fin la venganza.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI019":["La caja","Inflige 3 de daño a cada enemigo invocado esta ronda.","","''Nadie puede escapar''. - Thresh","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI011":["Carnicero voraz","Para jugar esta carta, mata a un aliado.","","Somos lo que comemos.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI014":["Espectro de la niebla","Cuando se me invoca, otorga +1|+0 a todos los Espectros de la niebla aliados estén donde estén.","","Los espectros de las Islas abandonaron sus identidades hace tiempo, y ahora se han convertido en amalgamas de un hambre visceral e insaciable.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI022":["Marca de las Islas","Otorga +2|+2 y Endeble a un aliado.","","Poder, sí, pero ¿a qué precio?","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI006":["Posesión","Roba un adepto enemigo esta ronda (no se puede jugar si ya tienes 6 aliados o hitos).","","Se despertó con las manos teñidas de rojo y el campamento tan silencioso como un cementerio. ","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI028":["Esquirla del alma","Invoca una copia exacta de un aliado con Endeble y 1|1.","","''Levanté el cadáver de las aguas para ver si reconocía al pobre incauto. Cuando posé la mano sobre su hombro, se giró lentamente y vi su rostro... Era yo''. - Arie Wrence, soldado demaciano","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI025":["Atrocidad","Mata a un aliado para infligir a cualquier unidad o al nexo una cantidad de daño equivalente a su poder.","","Para los que no pueden morir, matar no significada nada.","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI046":["Llamada de la Niebla","Revive a un aliado aleatorio que haya muerto esta ronda.","","''La Niebla separa el espíritu de la carne y deja atrás una parodia obscena de la vida. La he visto corromper mi tierra. Ahora me dirijo a esas islas malditas para poner fin a su yugo''. - Arie Wrence, vengador impertérrito","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI050":["Despertar de las crías","Invoca 3 Crías de araña y otorga +1|+0 a los aliados arácnidos.","","Están aún más hambrientas cuando nacen.","Hechizo",[],["Islas de la Sombra"],"RARA"],"01SI016":["Susurraespectros","Alianza: Invoca 1 Espectro de la niebla.","","Aparece sin hacer un solo ruido, pero los horrores que la siguen no saben de sigilo.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI021":["Cuadriga de tiburones","Último aliento: La próxima vez que un aliado con Endeble ataque, revivo y ataco.","","''¿Que ha visto qué? Vaya, entiendo. La locura es una amante cruel, boticario. Al menos el resto aún dice cosas con cierto sentido''. - Cirujano demaciano","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI032":["Cronista de La Ruina","Jugar: Mata a un aliado y después lo revive.","","Hubo una época en la que se sentaba junto a su padre, un conservador, mientras este estudiaba tomos y volúmenes llenos de polvo. Esperaba que un día su pequeña lo sucediese, pero no así...","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI058":["Emisor etéreo","Jugar: Mata a un aliado para invocar a un adepto aleatorio que cueste 2 más.","","¡Espíritus, prestadme vuestras voces! Juntos invocaremos una oscuridad eterna.","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI054":["Garras del inmortal","Drena 3 de vida a una unidad.","","Los muertos solo quieren silenciar el vibrante e incansable latido de los vivos.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI044":["Matrona espectral","Jugar: Elige a un aliado de la mano e invoca una copia exacta de él con Endeble.","","La Ruina corrompió todo a su paso. Los más gentiles se volvieron despiadados, los más valientes se volvieron perversos. La razón se convirtió en rencor.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"01SI039":["Terror aracnoide","","","Algunos espíritus malignos toman la apariencia de la fauna local y transforman lo conocido en una pesadilla.","Unidad",["ARAÑA"],["Islas de la Sombra"],"COMÚN"],"01SI020":["Portador de la llama","Cuando se me invoca, revive al campeón aliado más fuerte que haya muerto.","","¿Para qué sirve una vela a punto de extinguirse, si no para hacer arder a la siguiente?","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI029":["Lamento marchito","Inflige 1 de daño a todos los enemigos. Tu nexo se cura 3 de vida.","","Aquello que nos mata los fortalece.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI004":["Azote de aguas oscuras","","","Algunos trataron de escapar de la Ruina sumergiéndose bajo las olas, pensando que la corrupción no repararía en ellos si se hundían en las profundidades. Craso error.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI026":["Presa del carcelero","Último aliento: Crea otro adepto aleatorio con Último aliento que cueste 3 de maná o menos.","","Aguantó la respiración cuanto pudo, rezando que el carcelero pasara de largo. Lo que no sabía es que esta búsqueda era parte del eterno tormento que Thresh tenía planeado.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"01SI040":["Festín infame","Drena 1 de vida a una unidad para invocar 1 Cría de araña.","","''¡Mi... Mi señora! ¡No sabía que os gustaban tanto las... arañas! ¿Podríais decirles que se marchen? ¿La... Lady Elise? Os lo suplico...''. - Lord Sassen, aristócrata desafortunado","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"01SI015":["La Ruina","Mata a todas las unidades.","","Y pensar que algo tan puro como el amor podría dar lugar a algo tan cruel e ineludible. ","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"01SI055":["Engullealmas","","","''Mientras los barcos se acercan a las tierras malditas, pienso: ¿esas creaciones infernales nacieron en estas tierras perversas? ¿Alguna vez han tenido vida?\". - Arie Wrence, soldado demaciano","Unidad",[],["Islas de la Sombra"],"RARA"],"01SI047":["Recuerdos desvanecidos","Elige un adepto y crea una copia de él con Endeble en la mano.","","Por un segundo, pareció recordar. Los rayos de sol que bailaban sobre su piel, las suculentas zarzamoras que tanto disfrutaba, la frágil melodía que los árboles entonaban a la brisa. Entonces... desapareció.","Hechizo",[],["Islas de la Sombra"],"RARA"],"02PZ001":["Subfelino","Cuando se me invoca, roba 1 carta.\nSi has jugado al menos 10 cartas nuevas esta partida, consigo +4|+0.","","Nada podría impedir que escapara de esos humanos atontados. Ni siquiera un poco de agua...","Unidad",["GATO"],["Piltover y Zaun"],"ÉPICA"],"02PZ010":["Investigador veterano","Cuando se me invoca, ambos jugadores roban una carta.","","Hay agentes que confían en su instinto para resolver casos. Otros se hacen valer de sus contactos. El punto fuerte del agente J. S. Harknor, en cambio, es la diligencia y el papeleo. Muchísimo papeleo.","Unidad",["YORDLE"],["Piltover y Zaun"],"COMÚN"],"02PZ006":["¡Te tengo!","Al robarme, cuesto 2 menos esta ronda.\nInflige 3 de daño a una unidad.","","\"¿Le importaría probarse estas esposas, señor Berz?\".\n\"¿Y yo qué me llevo?\".\n\"Te las puedes quedar\".\n\"Trato hecho\".\n\"Quedas arrestado. ¡Lleváoslo!\".","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"02PZ004":["Rompemuros","Concede +2|+0 a un aliado esta ronda.\nCrea 1 Rompemuros Fugaz en la mano.","","\"Dejo que mis puños hablen por mí\". - Vi","Hechizo",[],["Piltover y Zaun"],"RARA"],"02PZ007":["Investigadora perspicaz","Cuando juegas una carta de coste 2, roba 1 carta y le otorga Fugaz.","","\"Todos los detectives reaccionan, pero los buenos anticipan y los mejores previenen\". - Manual del guardián","Unidad",[],["Piltover y Zaun"],"RARA"],"02PZ002":["Jefa mecanicista Zevi","Cuando robas una carta, obtiene Fugaz y crea una copia exacta de ella en la mano.","","A los cinco años, construyó el primer cuchillo sónico multifrecuencia. Aunque no resultaba demasiado práctico (solo lo usaba para hacer bocadillos), crearlo fue el primer paso que la conduciría al departamento de armas de élite de los guardianes.","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"02PZ008":["Vi","Si esta carta está en juego o en la mano, obtiene +1|+0 cuando juegas otra carta (máx. de +8|+0).","He golpeado con 10 o más de daño en un solo golpe.","\"¡Agente Vi, por favor! ¡Piensa en la gente, en los daños colaterales! ¡En todo el papeleo por los daños causados!\".\n- Investigadora perspicaz","Unidad",[],["Piltover y Zaun"],"Campeón"],"02PZ009":["Rastros de pruebas","Crea en la mano una carta aleatoria de coste 2 de una de tus regiones. En esta ronda cuesta 2 menos.","","\"Ergo\", expuso el agente Harknor, \"el rastro nos conduce hasta...\".","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"02PZ003":["¡Prepárate!","Al robarme, cuesto 2 menos esta ronda.\nHace que un aliado pase a tener 4|4.","","\"¡Hay problemas en el muelle! ¡Llévate esto y saluda de mi parte!\". - Jefa mecanicista Zevi","Hechizo",[],["Piltover y Zaun"],"RARA"],"02PZ005":["Patrulleros","Al robarme, cuesto 1 menos esta ronda.","","Los agentes se reían de la técnica de carrera de la guardiana Mir. El guardián Kepple nunca llegó a pillarlo.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"02BW040":["Nortuga","","","\"JESTIONAR A LA PLEVE ES MI PUNTO FUERTE, PERO LA HORTOGRAFIA TAMVIEN SE ME DA DE MARABILLA\".\n- Nota escrita en la arena","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW057":["Surfeacrestas","","","\"Estos ojos han visto las cosas más extrañas en los arrecifes. Pero ¿qué le ha puesto ese tarugo a las naranjas? Eso sí que es un misterio...\". - Suboficial","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW041":["La bestia oculta","","","\"No temáis al mal conocido,\npues es también sobrevivido.\nPero ¿qué hay de aquellos perdidos en lo más profundo?\n¿Y de sus almas vagando sin rumbo?\". - Escrito en la viga de una taberna de Aguas Estancadas","Unidad",["MONSTRUO MARINO"],["Aguas Estancadas"],"COMÚN"],"02BW013":["Degüello acechante","","","\"... y el muy idiota dijo que tenía unas caderas de espectáculo. Le contesté que se dejara de halagos o le iba cortar la lengua\".","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW034":["Ídolo mono","Comienzo de ronda: Recibo 2 de daño e invoca 1 Mono de la pólvora.","","\"Eso es un... recuerdo. La tripulación se lo mangó a un antiguo rival mío que estaba mal de la cabeza. Resulta que lo que decía sobre poderes misteriosos ancestrales no era del todo locura...\". - Miss Fortune","Unidad",[],["Aguas Estancadas"],"RARA"],"02BW056":["Devorador de las profundidades","Jugar: Destruye a un enemigo que tenga menos vida que yo.","","\"Navegaba yo la otra mañana,\nsin ver que de Aguas Estancadas me alejaba.\nSalió a darme la bienvenida\ndel mar profundo la Dama hundida...\". - \"La balada de la Dama hundida\"","Unidad",["MONSTRUO MARINO"],["Aguas Estancadas"],"ÉPICA"],"02BW060":["Corsaria tiradora","Cuando los aliados atacan, inflige 1 de daño al nexo enemigo.","","\"Aunque no lo creas, ser bajita da mucha ventaja en el combate. A nadie se le ocurre nunca mirar hacia abajo\".","Unidad",["YORDLE"],["Aguas Estancadas"],"COMÚN"],"02BW011":["Yordle estafador","Alianza: Birla 1 y crea 1 Disparo de advertencia en la mano.","","\"Ya sabes, a los amigos les encanta ayudarse entre ellos. ¿Y a ti? Me encanta cómo te brilla la mirada. Y esa espada que llevas... es muy bonita, la verdad\".","Unidad",["YORDLE"],["Aguas Estancadas"],"RARA"],"02BW030":["Coleccionista de tesoros","Cuando se me invoca, desecha 2 cartas y crea 2 Tesoros en tu mazo.","","\"A día de hoy, hay más riquezas bajo las olas que en la superficie, estoy seguro. Si no fuera por ella, nos haríamos ricos\". - Carnicero abrupto","Unidad",["MONSTRUO MARINO"],["Aguas Estancadas"],"ÉPICA"],"02BW019":["Burbujoso","","","Los arrecifes de las Islas de las Serpientes cuentan con corrientes de poderosa magia que alimentan a sus extraordinarios habitantes.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW007":["Corredora de apuestas","Para jugar esta carta, descarta 2.\nAtacar: Roba 2 cartas y les otorga Fugaz.","","\"No suele tener nada de especial. Las mesas están repletas de necios demasiado ocupados cantando a pleno pulmón como para concentrarse en la partida. Que no es que a mí me importe, ¿eh? Si el dinero va a ser para alguien, mejor que sea para mí\".","Unidad",[],["Aguas Estancadas"],"RARA"],"02BW014":["Criaturas de coral","Cuando se me invoca, se crea en la mano un hechizo aleatorio de coste 1 de una de tus regiones.","","Las aguas poco profundas suelen estar repletas de vida marina de todo tipo y condición, pero no hay lugar comparable a la Ruta Cerúlea. Es un lugar mágico, de otro mundo, repleto de maravillas.","Unidad",[],["Aguas Estancadas"],"RARA"],"02BW055":["Matarife","Asalto: Otorga +1|+0 a los aliados de coste 1 estén donde estén.","","Cuando dispara, hay que ser rápidos con los ganchos. La sangre en el agua siempre atrae a visitantes indeseados.","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"02BW017":["Repartidor de cítricos","Asalto: Cura 3 de vida a los aliados y al nexo y, después, prepara el ataque.","","\"Todos los marineros se creen tan duros... Que si 'arrr' esto, 'grr' lo de más allá. Pues vale, ¡pero sin naranjas no sois nada! Son buenas para la piel, para los dientes y para el humor. O se come o se nada, y punto\".","Unidad",[],["Aguas Estancadas"],"RARA"],"02BW038":["Manta veloz","Cuando se me invoca, roba un hechizo de coste 3 o menos de tu mazo.","","Una vez, Relámpago consiguió completar el circuito de la Ruta Cerúlea en menos de tres minutos. Hacia el final, tuvo que apañárselas para esquivar el casco destrozado de Jilldaw. ¡Las corrientes ese día eran espectaculares!","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"02BW021":["Cazaaletas","Jugar: Otorga a un enemigo Vulnerable.","","\"He oído que nada kilómetros hasta encontrar a su presa y nunca ha fallado ni un solo tiro. No sé si es hombre o pez, pero está claro que conoce las aguas mejor que ninguno de nosotros\". - Carnicero abrupto","Unidad",[],["Aguas Estancadas"],"RARA"],"02BW035":["Sheriff Lariette Rose","Cuando se me invoca, otorga Vulnerable a todos los enemigos.","","Aguas Estancadas es una ciudad sin ley, pero hay algunos valientes que se dedican a impartir lo que ellos consideran justicia.","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"02BW058":["Carnicero abrupto","Asalto: Consigo +1|+1.","","Entrar en los Garfios Dentados es una ardua y sangrienta tarea. Los marineros deben demostrar que saben navegar, pelear y descuartizar. Los candidatos más detestables superan las tres pruebas en una única matanza.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW028":["Rex Aguas revueltas","Asalto: Lanza Andanada de cañón 7 veces contra enemigos seleccionados aleatoriamente.","","\"Navega más allá de marineros, más allá de los restos del naufragio.\nLa batalla ya ha terminado.\nYa no queda humo; el capitán se ha enfrentado a Rex\ny su barco no es más que un montón de astillas\". - \"En casa contigo, Sally\"","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"02BW037":["Ojo abisal","Golpe al nexo: Roba 1.","","\"Sí, sí, lloraron y buscaron salida\nen Nashramae, movidos por la fe.\nPero la naturaleza, furiosa, se llevó muchas vidas.\nY el resto siguieron al ojo que todo lo ve\". - \"El ojo que todo lo ve\"","Unidad",["MONSTRUO MARINO"],["Aguas Estancadas"],"RARA"],"02BW008":["Suboficial","Jugar: Invoca a 1 Barril de pólvora o a un adepto aleatorio de coste 1.","","Pronto aprendió que no había mejor forma de motivar a los marineros que con la ayuda de una espoleta ardiendo.","Unidad",["YORDLE"],["Aguas Estancadas"],"RARA"],"02BW047":["Buscarresiduos","Cuando se me invoca, desecha 3.","","Hay que ser especial para conseguir convertir basura en equipamiento de primera. Pero si hay algo que se les dé bien, eso es. Eso y nada más.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW004":["Grumete del Heraldo","Cuando se me invoca, se invoca 1 Barril de pólvora.","","\"Sí, podríamos luchar contra ellos al amanecer, cuando esté despierta la tripulación y tengan los cañones listos. Pero también podríamos dejarles un regalito en la oscuridad de la noche...\".","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW002":["Heraldo de la muerte","Cuando se me invoca, roba a Gangplank.\nDuplica todo el daño infligido por tus hechizos, habilidades y aliados.","","\"¡Ah, despedíos y levad anclas,\npues el Heraldo de la muerte está al caer!\n¡Hacia las profundidades, donde aguardan los cadáveres,\npues el Heraldo de la muerte está al caer!\". - \"El Heraldo de la muerte está al caer\"","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"02BW016":["Robot tragaperras","Cuando se me invoca o al comienzo de ronda: Consigo +0|+1 por cada carta que hayas robado en la última ronda. Después, baraja mis estadísticas.","","Un prototipo explotó después de lanzar tres bombas. Dicha \"característica\" se ha eliminado de los modelos más recientes.","Unidad",[],["Aguas Estancadas"],"RARA"],"02BW027":["Flota de caza","Cuando se me invoca, tu rival invoca 1 Narval dorado.","","El oro que brilla bajo las olas no es ni de moneda ni de lingote, sino del cuerno lustroso del adversario que plantó cara al capitán de la Flota del Matadero.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW050":["Solista sutil","Asalto: Reduce en 2 el coste de los aliados de la mano y del mazo.","","\"¡Uníos a nosotros en una aventura musical! ¡Disfrutad de melodías de toda Runaterra! Pero recordad: para entrar hay que pagar, y se agradecen las propinas...\". - Promotor del espectáculo","Unidad",[],["Aguas Estancadas"],"RARA"],"02BW015":["La Sirena","Cuando se me invoca, roba a Miss Fortune.\nMientras estoy atacando, todos tus hechizos y habilidades infligen 1 más de daño.","","La Sirena es inconfundible. Sus anchas velas perladas y la madera pulida de su cubierta le otorgan una belleza a la altura de la de la capitana que la navega.","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"02BW010":["Poro asaltante","Asalto: Consigo dos palabras clave aleatorias.","","\"Su cara lleva más tiempo que ninguna otra en el tablón de recompensas. Es un demonio avaricioso e inclemente que no deja que nada ni nadie se interponga en su camino. Y lo peor de todo es que es una monada\". - Gangplank","Unidad",["PORO"],["Aguas Estancadas"],"COMÚN"],"02BW009":["As del billar","Cuando se me invoca, roba 1 carta en el siguiente comienzo de ronda y le otorga Fugaz.","","\"No lo entiendo, la verdad. Lo estaba clavando, pero esa última... No hubo manera. Supongo que hoy no es mi día\".\n- Corredora de apuestas","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW005":["Cazarrecompensas","Cuando se me invoca, otorga Vulnerable al enemigo más fuerte.","","\"¿Estas pintas traes? Uf, sabía que no eras de buen ver, pero esto... Más vale que esa cabeza merezca la pena\".","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW039":["Navío cazamonstruos","Cuando se me invoca, se crea un Monstruo marino aleatorio en la mano.","","Tripulación tras tripulación decide aventurarse más allá de las aguas poco profundas en busca de fortuna. Esos pobres desgraciados no tardan en descubrir lo terrorífico que puede resultar el océano, y por qué muchos nunca vuelven...","Unidad",[],["Aguas Estancadas"],"RARA"],"02BW006":["Mago misterioso","Jugar: Transforma a un aliado en un adepto aleatorio de coste 5.","","\"¿Marvolio? ¿Y... y mis manos?\".\n\"¡Ahora mismo las hago aparecer! ¡Tachán! Ejem. ¡Tacháaaaan!\".\n\"¡¿DÓNDE ESTÁN MIS MANOS?!\".\n\"¡BUENO, HORA DE IRSE! ¡MUCHAS GRACIAS A TODOS!\".","Unidad",[],["Aguas Estancadas"],"RARA"],"02BW036":["Narval dorado","","","Cuenta la leyenda que una ballena pálida y cornuda le robó algo a la Dama Barbuda hace mucho tiempo. La Dama la castigó cubriéndola de oro para que fuera siempre víctima de la avaricia ajena.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"02BW033":["Comerciante del mercado negro","Cuando robas una carta enemiga, su coste se reduce en 1.\nAsalto: Birla 1.","","\"¡Tengo todo lo que buscas! Incluso mercancías 'especiales'... Pero si te preguntan, yo no he sido\".","Unidad",[],["Aguas Estancadas"],"RARA"],"02BW032":["Gangplank","Cuando se me invoca, se invoca 1 Barril de pólvora.","Has infligido daño al nexo enemigo en 5 o más rondas diferentes.","\"No te quedes mirando fijamente o se dará cuenta. Y no hables mal de él, pues no hay susurro en Aguas Estancadas que se le escape. Aquí viene. Encógete de hombros. Baja la mirada\". - Grumete del Heraldo","Unidad",[],["Aguas Estancadas"],"Campeón"],"02BW022":["Miss Fortune","Cuando los aliados atacan, inflige 1 de daño a todos los enemigos en combate y al nexo enemigo.","Te he visto atacar 4 veces.","\"¿Miss Fortune? Aquí todos me llaman Capitana\".","Unidad",[],["Aguas Estancadas"],"Campeón"],"02BW046":["Fizz","Cuando juegas un hechizo, dejo de ser objetivo de cualquier habilidad o hechizo enemigos y consigo Elusión esta ronda.","Has jugado 6 hechizos o más.","De todas las leyendas de Aguas Estancadas, Fizz es la más volátil. Los hay que lo maldicen y lo culpan de los brutales naufragios que adornan la costa...","Unidad",["YORDLE"],["Ciudad de Bandle","Aguas Estancadas"],"Campeón"],"02BW026":["Twisted Fate","Jugar: Juega una Carta del destino.","Te he visto robar 9 cartas.","\"Ahora céntrate en las manos, cuenta las cartas y no te quedes atrás. Y recuerda...\".","Unidad",[],["Aguas Estancadas"],"Campeón"],"02BW053":["Nautilus","","Cuando estás En apuros. Cuando subo de nivel, se añaden a tu mazo copias de los aliados desechados que cuesten 4 o más.","\"Lo que rompió el Rencor fue un ancla. Arrastró a Finn y todo. Ahora solo quedamos unos pocos, pero se acerca la noche... Y con ella, el frío. Lo siento, mamá. Tenías razón. El Titán sigue con vida\". - Nota recuperada","Unidad",[],["Aguas Estancadas"],"Campeón"],"02BW061":["Ases en la manga","Al robarme, cuesto 1 menos esta ronda.\nOtorga +2|+1 a un aliado.","","\"Nada como una buena racha para hacerte rico\". - Twisted Fate","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"02BW024":["Dúo dinámico","Invoca a 2 adeptos aleatorios de coste 1.","","\"Oye, Gav, ¿ese no es el tipo que buscamos? Parece que ha hecho amigos\".\n\"¿Eso... eso es un hombre tiburón, Baz?\".\n\"Sí, y también un montón de oro. Andando...\". - Baz y Gav, cazarrecompensas en potencia","Hechizo",[],["Aguas Estancadas"],"RARA"],"02BW003":["Toma de rehenes","Asalto: Retira a cualquier adepto a tu mano.","","\"¡Ahora trabajas para nosotros!\". - Suboficial","Hechizo",[],["Aguas Estancadas"],"RARA"],"02BW025":["Carnaza para tiburones","Concede Vulnerable a un enemigo e invoca 1 Dientes largos.","","\"¡Tiburón!\". - Fizz","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"02BW012":["¡Más pólvora!","Invoca 2 Barriles de pólvora.","","\"¡Barril!\". - Gangplank","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"02BW018":["Parrrlamento","Inflige 1 de daño a cualquier unidad o al nexo.\nSi resulta letal, inflige 1 de daño al nexo enemigo.","","La estrategia de meditación de Gangplank suele ser breve y sangrienta.","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"02BW048":["A la fuga","Invoca a un adepto aleatorio de coste 1.","","\"¿Qué opinas, Baz? A mí no me intimida\".\n\"¿Seguro, Gav? Se ha escapado de la cárcel...\".\n\"Por astuto, no por fuerte. Anda, ¡vamos!\". - Baz y Gav, cazarrecompensas en potencia","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"02BW043":["Escoge una carta","Para jugar esta carta, coloca una carta de la mano en el mazo.\nRoba 2 cartas en el siguiente comienzo de ronda y les otorga Fugaz.","","\"Escribo mi propia fortuna\". - Twisted Fate","Hechizo",[],["Aguas Estancadas"],"RARA"],"02BW051":["Gamberro juguetón","Elimina a un aliado en ataque del combate y prepara el ataque.","","\"¡Estoy un salto por delante!\". - Fizz","Hechizo",[],["Aguas Estancadas"],"RARA"],"02BW054":["Aguas revueltas","Aturde a un enemigo.\nColoca esa unidad en el mazo del rival si tienes a Nautilus.","","\"Hundidlos\". - Nautilus","Hechizo",[],["Aguas Estancadas"],"RARA"],"02BW042":["Tanteo","Esta ronda, aumenta el poder y la vida de los aliados al número de hechizos que hayas jugado en esta partida.","","Los marineros de Aguas Estancadas temen a las corrientes que rodean la ciudad por su violencia y su inestabilidad, pero ninguno se imagina lo que yace bajo las aguas.","Hechizo",[],["Aguas Estancadas"],"ÉPICA"],"02BW059":["Disparo devastador","Desecha 3 cartas.\nInflige 7 de daño a una unidad.","","\"Si los hunde en el mar, ha merecido la pena\". - Refrán de Aguas Estancadas","Hechizo",[],["Aguas Estancadas"],"RARA"],"02BW023":["La marea despierta","Reduce el coste de los Monstruos marinos en 1 estén donde estén.\nRoba un Monstruo marino.","","Los marineros ahogan susurros sobre la oscuridad venidera; una era en la que los mares hervirán y horrores inconcebibles se alzarán desde las profundidades.","Hechizo",[],["Aguas Estancadas"],"RARA"],"02BW031":["Redoble","Inflige 2 de daño a un enemigo.\nSi resulta letal, inflige 4 de daño al nexo enemigo.","","\"Yo siempre disparo primero\". - Miss Fortune","Hechizo",[],["Aguas Estancadas"],"RARA"],"02BW029":["Salvamento","Desecha 2 cartas.\nRoba 2.","","Los restos de un naufragio no se mantienen mucho tiempo a flote. Cualquier marinero que se precie tiene que ser capaz de distinguir la mercancía de valor de entre lo inservible...","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"02BW049":["Mercancía robada","Birla 1.\nAsalto: Birla 1 más.","","Lo mío es mío, y lo tuyo... mío también.","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"02BW001":["El que avisa no es traidor","Concede Vulnerable a un enemigo esta ronda. Si muere esta ronda, roba 1.","","\"¡Mantén la cabeza bien alta y no pierdas el ánimo, chaval! Si el capitán te ve cabizbajo, te abrirá en canal y te dará de comer a las gaviotas. ¡Venga, andando!\". - Grumete del Heraldo","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"02BW063":["Juego de manos","Asalto: Roba una carta al azar (no campeón) de la mano del rival.","","\"Que las cartas estén de tu parte no es cuestión de suerte, sino de psicología. Haz que el otro dude de sí mismo, y ya has ganado\". - Twisted Fate","Hechizo",[],["Aguas Estancadas"],"RARA"],"02BW045":["Que llueva","Inflige 1 de daño a tres enemigos aleatorios distintos o al nexo enemigo.","","\"¡Armas al rojo vivo!\". - Miss Fortune","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"02BW020":["Disparo de advertencia","Inflige 1 de daño al nexo enemigo.","","\"¡Tienes que disparar cuando los demás, chaval! ¡En eso consisten los bombardeos!\". - Suboficial","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"02BW044":["Explora las profundidades","Desecha 4.","","\"Si no vale su peso en oro, se va por la borda. Y eso también se aplica a vosotros. ¡A trabajar!\". - Suboficial","Hechizo",[],["Aguas Estancadas"],"RARA"],"02BW062":["Navegante isleña","Cuando se me invoca, invoca a un adepto aleatorio de coste 1 que recibe Vigía.","","\"Asciende la luz de la Madre Serpiente.\nSube a los cielos, desde la corriente.\nEl cielo con ojos grises sosiega el alma.\nEl reflejo de su mirada en calma.\nSonríe, está en paz...\".\n- Oración a Nagakabouros","Unidad",[],["Aguas Estancadas"],"RARA"],"02FR009":["Domalobos","Asalto: Obtienes una gema de maná vacía.","","Los jóvenes invasores de la Garra Invernal reciben un cachorro de lobo el día en el que son capaces de alzar un arma. Se les educa únicamente en la batalla. Entrenan a los lobos en las artes de la masacre, y a los niños en las del saqueo y el robo.","Unidad",[],["Freljord"],"COMÚN"],"02FR004":["Congelación","Concede Escarchar y Vulnerable a un enemigo esta ronda.","","\"Estos sangrecaliente no durarían ni un solo día en Freljord\".\n- Sejuani","Hechizo",["ELEMENTAL"],["Freljord"],"RARA"],"02FR002":["Sejuani","Jugar: Concede Escarchar y Vulnerable a un enemigo esta ronda.","Has infligido daño al nexo enemigo en 5 o más rondas diferentes.","Aunque su mayal de Hielo Puro es formidable, Sejuani es la verdadera arma; un arma forjada por los vientos gélidos de Freljord y puesta a prueba en condiciones extremas.","Unidad",[],["Freljord"],"Campeón"],"02FR001":["Dama incendiaria","Comienzo de ronda: Inflige 1 de daño a todo.","","\"Se esmerarán con sus cultivos,\nsembrarán los campos sin cesar,\ny luego haremos que todo arda,\npues la Garra Invernal cumple su voluntad\". - Canción infantil de la Garra Invernal","Unidad",[],["Freljord"],"RARA"],"02FR005":["Ursine caminante espiritual","Asalto: Me transformo en Ursine garratormenta.","","Los ursine comienzan siendo humanos, pero abandonan sus características mortales para entregarse al poder salvaje que otorga el espíritu de Volibear.","Unidad",[],["Freljord"],"COMÚN"],"02FR010":["Botín compartido","Otorga +1|+1 a las 3 unidades de más arriba del mazo.\nAsalto: Roba una de ellas.","","\"Compartir y repartir por igual\". - Invasora implacable","Hechizo",[],["Freljord"],"RARA"],"02FR008":["Capitana de asalto","Cuando se me invoca, roba a Sejuani.\nAsalto: Duplica el poder y la vida de los aliados de tu mazo.","","\"Cuando la primavera es lo suficientemente cálida como para que podamos sembrar los campos, trae consigo barcos... y pronto comienza a escasear el grano\". - Guardia del hogar avarosano","Unidad",[],["Freljord"],"ÉPICA"],"02FR007":["Furia del norte","Concede +3|+4 a un aliado esta ronda.","","\"¡Dejaos llevar por la bestia que mora en vuestro interior!\".\n- Sejuani","Hechizo",[],["Freljord"],"COMÚN"],"02FR006":["Invasora implacable","","","La Garra Invernal no tiene igual en Freljord, y todos conocen la inclemencia de sus saqueadores. Una vez que su sed de sangre toma el control, la única esperanza para sus víctimas es una muerte rápida.","Unidad",[],["Freljord"],"COMÚN"],"02FR003":["Aurora poreal","Crea 2 poros aleatorios y 2 Snack para poros en la mano.","","\"Si le pides un deseo a un poro\ny contemplas la noche estrellada,\nverás el aperitivo en el firmamento\ny sentirás un brillo en tu mirada\". - Ingvar, la Joven","Hechizo",[],["Freljord"],"ÉPICA"],"02NX001":["Leviatán","Cuando se me invoca, roba a Swain.\nComienzo de ronda: Inflige 1 de daño al nexo enemigo dos veces.","","Cuando los habitantes de Jonia lo vieron en el horizonte, pensaron que se trataba de un monstruo. No estaban muy equivocados. La nave de guerra de acero es aterradora, el mayor logro de la ingeniería naval noxiana hasta la fecha.","Unidad",[],["Noxus"],"ÉPICA"],"02NX007":["Swain","Golpe al nexo: Inflige 3 de daño al nexo enemigo.","Has infligido 14 o más de daño fuera de combate.","\"Un poder más allá de la comprensión de los mortales me dio la oportunidad de ver lo que muchos apenas imaginan. Veo a través de la oscuridad que otros temen\".","Unidad",[],["Noxus"],"Campeón"],"02NX006":["Rompeciudades","Comienzo de ronda: Inflige 1 de daño al nexo enemigo.","","La voz del anciano era sorprendentemente calmada. \"¿Qué sentido tiene recoger piedras para elevar las murallas si los noxianos siempre encuentran el modo de derrumbarlas?\", preguntó.","Unidad",[],["Noxus"],"RARA"],"02NX002":["Aurok Cuernoafilado ","Atacar: Aturde a todos los enemigos dañados.","","\"Durante generaciones, hemos estado subyugados. No entendimos lo que significaba la libertad hasta que Noxus comenzó a invadir nuestras tierras. Por esa razón lucho por el imperio\".","Unidad",[],["Noxus"],"ÉPICA"],"02NX009":["Bandada de cuervos","Inflige 4 de daño a una unidad si ha recibido daño o está aturdida.","","Escuchad. ¿Lo oís? Es el estruendo de miles de alas agitándose con fuerza.","Hechizo",[],["Noxus"],"RARA"],"02NX004":["Zapadora imperial","Jugar: Inflige 1 de daño a un aliado para infligir 2 al nexo enemigo.","","\"Rápida y silenciosa hasta que explota\".","Unidad",[],["Noxus"],"COMÚN"],"02NX003":["Fervor noxiano","Inflige 3 de daño a un aliado para infligir 3 a cualquier unidad o al nexo.","","\"Los sacrificios son necesarios\". - Jericho Swain","Hechizo",[],["Noxus"],"COMÚN"],"02NX010":["Colmillo acorazado","Todos los enemigos con 4 o menos de poder no pueden hacerme daño.","","\"Una vez que se pone en marcha, nada frena a una bestia de guerra. Lo mejor es apartarse de su camino\". - Jinete de basiliscos","Unidad",[],["Noxus"],"RARA"],"02NX008":["La mano de la muerte","Inflige 2 de daño a un enemigo y 1 al nexo enemigo.","","\"Intenta morir con dignidad\". - Swain","Hechizo",[],["Noxus"],"COMÚN"],"02NX005":["Balista de hierro","","","\"Asediar es fácil con las herramientas adecuadas. Los arietes los sacan y las balistas los matan\". - Ingeniero de asedio","Unidad",[],["Noxus"],"COMÚN"],"02DE003":["Oso tejón leal","","","Es cierto eso que dicen de que las mascotas son como sus dueños.","Unidad",[],["Demacia"],"COMÚN"],"02DE008":["Cuernolargo","","","Un recluta de los guardabosques pasa meses en el bosque, aprendiendo a predecir cada movimiento de su compañero. Ha de ser paciente, pues, una vez que se haya establecido un vínculo entre ellos, nada podrá destruirlo.","Unidad",[],["Demacia"],"COMÚN"],"02DE004":["Guardabosques","","","\"Juro proteger este bosque y a todo aquel que busque refugio en él\".","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"02DE006":["Quinn","Cuando se me invoca, invoca 1 Valor.","Te he visto atacar 4 veces.","\"Nuestra querida Quinn siempre ha sido una cazadora audaz, y con Valor a su lado sobrevolando el terreno, se vuelven un dúo imparable\". - Genevieve Corazón de Olmo, montaraz","Unidad",[],["Demacia"],"Campeón"],"02DE009":["Guardabosques veterano","Último aliento: Invoca 1 Oso tejón leal.","","Betrand se inició en los vigías de Bandle. Consiguió todas las insignias habidas y por haber, excepto la de \"disposición dicharachera\".","Unidad",["YORDLE"],["Demacia"],"RARA"],"02DE005":["Espíritu indomable","Otorga a un aliado \"No puedo recibir daño ni morir\".","","Haciendo caso omiso a la pierna herida, la guardabosques volvió a ponerse en pie, espada en mano. La determinación que le impedía desfallecer no era únicamente la suya propia, sino la de Demacia entera.","Hechizo",[],["Demacia"],"ÉPICA"],"02DE002":["Asalto cegador","Invoca 1 Valor.","","\"¡Lo tengo en el pelo! ¡Lo tengo en el pelo!\". - Saqueador de la Legión","Hechizo",[],["Demacia"],"RARA"],"02DE010":["Genevieve Corazón de Olmo","Cuando se me invoca, concede +1|+1 a otros aliados esta ronda.","","Ver a los guardabosques de Demacia en combate resulta verdaderamente inspirador. Luchan como si fueran uno: humano y animal, codo con codo, movidos por una determinación feroz e inseparables en todo momento.","Unidad",[],["Demacia"],"ÉPICA"],"02DE007":["Valor salvaje","Concede a los aliados Aguante esta ronda.","","\"Cuando el enemigo se acerque, no os dejéis llevar por el miedo, pues los árboles nos protegerán\". - Guardabosques","Hechizo",[],["Demacia"],"RARA"],"02DE001":["Golpe concentrado","Elige a un enemigo y dos aliados le golpean uno detrás de otro.","","\"¡Conmigo, todos juntos!\". - Guardabosques","Hechizo",[],["Demacia"],"COMÚN"],"02SI005":["Absorción de magia","Desecha 3.\nCura 3 de vida a los aliados.","","\"Las Islas serán purificadas\". - Maokai","Hechizo",[],["Islas de la Sombra"],"RARA"],"02SI010":["Guarda de la arboleda","Cuando se me invoca, desecha 3 cartas.","","\"El gran treant no ha dejado de... criaturas. Esta... florece la vida por donde pasa... es increíble algo tan... aquí. ¡Normal que se llamen las Islas Bendecidas!\". - Diario encontrado","Unidad",[],["Islas de la Sombra"],"COMÚN"],"02SI008":["Maokai","En cada ronda, la primera vez que invocas a otro aliado, desecha 2 cartas e invoca 1 Pimpollo.","Han muerto 25 o más unidades aliadas o se han desechado 25 o más de tus cartas.","Estas tierras malditas no acabarían con Maokai. El compromiso del treant era tan fuerte, y su ira tan feroz, que nada podría detenerlo.","Unidad",[],["Islas de la Sombra"],"Campeón"],"02SI007":["Sapo espinoso","Último aliento: Desecha 2 cartas y tu nexo se cura 2 de vida.","","\"... una especie asombrosa… la misma criatura que me encontré de niño... ¡no ha envejecido! Me pregunto si… próximo poblado. ¡Quizás estas ricuras vivan eternamente!\".\n- Diario encontrado","Unidad",[],["Islas de la Sombra"],"COMÚN"],"02SI003":["Terror de las mareas","Los Monstruos marinos aliados tienen Temible.\nAtacar: Concede a los enemigos -2|-0 esta ronda.","","Se percataron del peligro cuando ya era demasiado tarde. La titánica bestia abrió sus enormes fauces y fue a por ellos. Los cazadores no pudieron sino aguardar la muerte que les sobrevenía a medida que el barco crujía entre infinitos dientes.","Unidad",["MONSTRUO MARINO"],["Islas de la Sombra"],"ÉPICA"],"02SI001":["Recolector del yermo","Cuando muere otro aliado, drena 1 de vida al nexo enemigo.","","\"Conocí al tal Niven... ¡el nuevo barquero! Nos condujo hasta... ¡Canta genial! Antes... deberíamos invitarlo a cenar un día de estos\". - Diario encontrado","Unidad",[],["Islas de la Sombra"],"RARA"],"02SI002":["Crujivid marchita","Cuando juegas un adepto, este muere para invocar 1 Crujivid marchita.","","\"Hoy es otro día asombroso... salió a la superficie... los niños estaban aterrados. Pero... no era una amenaza. Me acariciaba... qué criatura más confiada. ¡Buscaré más bayas!\".\n- Diario encontrado","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"02SI004":["Vigía maldita","Jugar: Mata a un aliado para invocar 2 Pimpollos.","","\"Todo corazón es un jardín en el que pueden crecer raíces\".","Unidad",[],["Islas de la Sombra"],"RARA"],"02SI006":["Bestia de la maleza","La primera vez que un aliado muere, consigo +2|+2.","","Hace mucho tiempo que las criaturas de las Islas de la Sombra no tienen sentimientos. Deben alimentar su hambre.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"02SI009":["Lanzamiento de pimpollo","Invoca 1 Pimpollo en el siguiente comienzo de ronda.","","\"¡Wiiiiiiiii!\". - Pimpollo","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"02IO008":["Onda sónica","Concede Contendiente a un aliado esta ronda.\nCrea 1 Golpe resonante Fugaz en la mano.","","\"Domínate a ti mismo...\". - Lee Sin","Hechizo",[],["Jonia"],"COMÚN"],"02IO002":["Escamas del dragón","Cuando se me invoca, se crea 1 Protección del dragón en la mano.","","\"El alumno debe actuar con compasión, pues fue la generosidad del dragón lo que alimentó las Tierras Primigenias y las llenó de vida y calidez\". - Enseñanzas del dragón","Unidad",[],["Jonia"],"COMÚN"],"02IO006":["Lee Sin","Cuando lanzas un hechizo, consigo Contendiente esta ronda.\nCuando lanzas otro, consigo Barrera esta ronda.","Has jugado 8 hechizos o más.","\"El dragón ayuda a los dignos. Revitaliza a los exhaustos. Reconforta a los enfermos. Ilumina a los perdidos. Equilibra a los desorientados...\".","Unidad",[],["Jonia"],"Campeón"],"02IO004":["Cuernos del dragón","","","\"El alumno debe esforzarse hasta el límite, pues fue el poder del dragón el que rescató a la tierra de entre las olas y nos dio un hogar\". - Enseñanzas del dragón","Unidad",[],["Jonia"],"COMÚN"],"02IO003":["Ojo del dragón","Comienzo de ronda: Fluir: Invoca 1 Cría de dragón.","","\"El alumno debe pensar con claridad, pues es la fuerza del dragón la que arrastra al sol por el firmamento y nos revela el mundo que nos rodea\".\n- Enseñanzas del dragón","Unidad",[],["Jonia"],"ÉPICA"],"02IO001":["Garras del dragón","Cuando estoy en la mano, juega 2 hechizos en la misma ronda para invocarme.","","\"El alumno debe escuchar con atención, pues fue el rugido del dragón el que trajo los primeros sonidos y bendijo nuestros jóvenes espíritus con el don de la magia\". - Enseñanzas del dragón","Unidad",[],["Jonia"],"COMÚN"],"02IO005":["Palma conmocionante","Aturde a un enemigo para invocar 1 Cola del dragón.","","\"No me has visto irme y no me verás regresar\". - Cola del dragón","Hechizo",[],["Jonia"],"RARA"],"02IO010":["Repliegue","Retira a un aliado para crear 1 Volver Fugaz en la mano.","","Los primeros noxianos en poner pie en las playas de Jonia se encontraron con un enemigo débil, con la guardia baja. Masacraron a miles, pero unos pocos consiguieron escapar...","Hechizo",[],["Jonia"],"RARA"],"02IO007":["Ira del dragón","Un aliado lanza a un enemigo contra el nexo enemigo, lo que golpea al enemigo y después al nexo enemigo.\nSi el enemigo sobrevive, se retira.","","\"Si no libero al dragón, acabará por consumirme\". - Lee Sin","Hechizo",[],["Jonia"],"ÉPICA"],"02IO009":["Meditación profunda","Fluir: Cuesto 2 menos.\nRoba otros 2 hechizos.","","La meditación es una travesía sin destino; un camino que solo puede encontrarse cuando uno se da por perdido.","Hechizo",[],["Jonia"],"RARA"],"03NX019":["Dad caza a los débiles","Tu oponente descarta al adepto más débil de su mano.","","\"Este mundo no es lugar para los débiles. Cada día les supone un nuevo tormento, un nuevo golpe. Yo no otorgo muerte, sino clemencia\". - Arrel la Rastreadora","Hechizo",[],["Noxus"],"RARA"],"03NX022":["Garras salvajes","Un aliado golpea a un enemigo. Si cuenta con Abrumar, el daño extra lo recibe el nexo enemigo.","","\"¡Oooh! ¡Hoy Garras está más salvaje que de costumbre! ¡Mucho ojito con esas garras, amigos!\". - Comentarista de la arena","Hechizo",[],["Noxus"],"ÉPICA"],"03NX007":["Riven","Cuando se me invoca, si tienes la ficha de ataque o cuando consigas la ficha de ataque, activa Reforjar.","Has creado Hoja del exilio.","\"No huiré de lo que fui. Prometí que arreglaría todo lo que destruí...\".","Unidad",[],["Noxus"],"Campeón"],"03NX006":["Empuñadura del arma","Concede +2|+0 a un aliado esta ronda. Activa Reforjar.","","\"Para conocer al enemigo, primero hay que conocer su arma. Te revelará cómo se mueve, cómo piensa, cuándo planea golpear. El arma es la expresión más pura de su portador\".\n- Arrel la Rastreadora","Hechizo",[],["Noxus"],"COMÚN"],"03NX002":["Arrel la Rastreadora","Fin de ronda: Si me has lanzado un hechizo este turno, golpeo al enemigo más débil.","","\"Escóndete y te encontraremos.\nRespira y te oiremos.\nCorre y te mataremos\".","Unidad",[],["Noxus"],"ÉPICA"],"03NX018":["Atrapar","Aturde a un enemigo.\nSi tienes a Darius, prepara el ataque.","","''Yo me encargaré de esto''. - Darius","Hechizo",[],["Noxus"],"RARA"],"03NX009":["Jinete colérica","","","\"No hay nada como dar caza a soldados. Para seguirles la pista, has de pensar como ellos. Para atraparlos, has de temerlos como ellos te temen a ti. Es un vínculo que pocos podrán experimentar, pero que yo disfruto más que ningún otro\".","Unidad",[],["Noxus"],"COMÚN"],"03NX017":["Basilisco sediento de sangre","Jugar: Inflige 1 de daño a un aliado y a un enemigo 4 veces.","","Los domadores de basiliscos limitan la comida que reciben las bestias en los días previos a la contienda. Cuando sueltan a las criaturas, estas no son capaces de distinguir aliados de enemigos y se vuelven ferozmente indomables.","Unidad",["REPTIL"],["Noxus"],"ÉPICA"],"03NX015":["Recursos de supervivencia","La vida de los aliados no puede bajar de 1 esta ronda.\nCuando se descarta, la vida de tu aliado más fuerte no puede bajar de 1 esta ronda.","","\"Los perrodracos reconocen su olor. Darán con ella y pondremos fin a esto. No hay otra opción\". - Arrel la Rastreadora","Hechizo",[],["Noxus"],"RARA"],"03NX014":["Determinación inquebrantable","Concede a un aliado +3|+2 esta ronda.","","\"Sí, os arreglaré las armas, cuidaré de vuestras monturas y os haré la comida. Total, no sirvo para nada más, ¿verdad?\".\n- Erath, escudero","Hechizo",[],["Noxus"],"COMÚN"],"03NX003":["Escudero","Último aliento: Activa Reforjar.","","\"Ya habéis oído a las cazadoras: cien días y cien noches. Cien llagas en los pies, cien bichos en el desayuno, cien 'que si la espada' y 'que si la venganza'... Y un sinfín de miradas fulminantes e insultos abrasadores por parte de esas tres\". ","Unidad",[],["Noxus"],"COMÚN"],"03NX001":["Tejedora de runas","Cuando se me invoca, se activa Reforjar.","","\"La mayoría de las armas son herramientas rudas que dependen de la destreza de su portador. Sin embargo, las armas infundidas con magia rúnica son mucho más que simple acero\".","Unidad",[],["Noxus"],"COMÚN"],"03NX005":["Cazadora despiadada","Cuando se me invoca, consigo Ataque rápido esta ronda.","","\"Ahí estás. ¡Sabíamos que no vendrías con nosotras sin resistirte! O eso esperábamos\".","Unidad",[],["Noxus"],"RARA"],"03BW006":["Jack el Ganador","Comienzo de ronda: Crea 1 Durmiendo entre peces en la mano.","","Tras años en el ring, Jack ha aprendido unas cuantas lecciones. Ahora sabe que todo el que sangra es capaz de sentir miedo. Conoce el poder de una intimidante mirada silenciosa. Domina el arte de la violencia sin control.","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"03BW010":["Bocado del pantano","Un aliado captura a otro aliado y obtiene las estadísticas del aliado capturado.","","\"Pasa, camarada, y todos tus deseos te serán concedidos eternamente\". - Tahm Kench","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"03BW005":["Costo hundido","Coloca una unidad o hito en su mazo.","","\"Te he dado exactamente lo que querías, camarada. Pero nunca dije que fuera a durar para siempre\". - Tahm Kench","Hechizo",[],["Aguas Estancadas"],"RARA"],"03BW004":["Tahm Kench","Cuando se me invoca o al comienzo de ronda: Crea 1 Paladar peculiar en la mano.","He capturado a 3 o más unidades. Cuando subo de nivel, destruyo a los enemigos que haya capturado y mis aliados quedan libres.","\"Conozco esa cara. Sientes que las cartas que tienes no son las que te mereces. Posees un gusto refinado, ¿a que sí? Tal vez yo te pueda ayudar a saborear todo lo que siempre has deseado; déjame satisfacer esa ansia. Solo necesito tu nombre. Escríbelo en este papel... y tendrás todo lo que quieras\".","Unidad",[],["Aguas Estancadas"],"Campeón"],"03BW002":["Lagarto al sol","Comienzo de ronda: Recibo 2 de daño.","","\"¡La gente es tonta! Les das algo frío para beber y un sitio cálido donde sentarse y sueltan todo tipo de secretos a un rostro amable. ¿Y quién podría superar al joven Leonard en eso, eh?\". - Corvina de la fortuna","Unidad",[],["Aguas Estancadas"],"COMÚN"],"03BW014":["Asunto explosivo","Invoca 1 Mono de la pólvora.\nAsalto: Invoca otro para el próximo comienzo de ronda.","","''Ay... ¿Creéis que son cucos o qué? Porque no lo son. Se meten en todo, lo dejan todo hecho un desastre y no se callan ni debajo del agua. Nada de monos en el barco. Punto final''.\n- Suboficial","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"03BW007":["Pulpaquete","Jugar: Recibo 3 de daño.","","\"Desde luego, Pablo puede ser un hueso duro de roer... je je, y, bueno, también se ha llevado sus puñetazos... pero no conozco a nadie más que pueda lograr asesinatos óctuples, chaval\". - Alevín sabio","Unidad",[],["Aguas Estancadas"],"COMÚN"],"03BW016":["Barco explosivo","Inflige 1 de daño a una unidad.\nInvoca una cantidad de Barriles de pólvora equivalente al daño infligido.","","\"El joven Gerent dio la voz de alarma justo antes de que explotara el primero. El casco comenzó a sacudirse y las velas estallaron en llamas, pero el Jilldaw aguantó a flote. Pensé que lo peor ya había pasado, pero entonces seguí la mirada de Gerent, que estaba fija en mar abierto, y vi los botes de remos cargados de pólvora que se dirigían hacia nosotros\".\n- Superviviente del Jilldaw","Hechizo",[],["Aguas Estancadas"],"RARA"],"03BW001":["Muelles del Matadero","Comienzo de ronda: Desecha 1 carta. Si estás En apuros, muero para invocar un Monstruo marino aleatorio.","","Cada día, son muchos los que se acercan a los Muelles del Matadero para contemplar las monstruosidades que los cazadores de Aguas Estancadas sacan de las profundidades. Normalmente son bestias muertas. Pero no siempre.","Hito",[],["Aguas Estancadas"],"ÉPICA"],"03BW015":["Viejo gruñón","Jugar: Recibo 2 de daño.","","\"TOCA LA CAMPANA, ¿QUIERES? VOY A ENSEÑARLE A ESE MOJÓN RESPINGÓN LA RAZÓN DE TODOS MIS APODOS. SE VA A ENTERAR. ¡'PABLO OCHO PUÑOS', 'EL CRACK DEL KRAKEN', 'TENTÁCULOS ASESINOS'! ¡TE VAN A LLORAR HASTA LAS PÚAS CUANDO HAYA ACABADO CONTIGO!\". - Pulpaquete","Unidad",[],["Aguas Estancadas"],"COMÚN"],"03BW003":["Alevín sabio","Jugar: Inflige 1 de daño a todos los demás aliados y consigo +1|+0 por cada uno de ellos.","","El proceso que implica alcanzar el poder suele ser violento... pero no es habitual que sea tan chapucero.","Unidad",[],["Aguas Estancadas"],"RARA"],"03BW017":["Pez burbuja","Cuesto 1 menos por cada hechizo que hayas lanzado en esta partida. Cuando se me invoca, crea en la mano un hechizo aleatorio de coste 1 de una de tus regiones.","","\"¡Firme, grumete! Tu misión es infiltrarte tras las filas enemigas, colocar tantas burbujas como puedas ¡y contarnos todo lo que veas! ¡Todo, ¿eh?! ¡¿Entendido?!\". - Almirante Shelly, Nortuga","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"03BW008":["Corvina de la fortuna","Jugar: Inflige 1 de daño a mí y a un aliado para robar 1.","","\"La vieja Babs ha tenido sus más y sus menos. Mató a algunas personas de por aquí en su época, pero supongo que eso le confiere un aire de autenticidad\". - Lagarto al sol","Unidad",[],["Aguas Estancadas"],"COMÚN"],"03BW020":["Pandemonio de pólvora","Invoca 1 Mono de la pólvora por cada vez que hayas activado Asalto durante esta partida.","","''Oh, esas pequeñas bolas de hollín no son tan malas. Un consejo: les encantan los fuegos artificiales. Solo tenéis que haceros con las reservas de pólvora de vuestros enemigos y esos diablillos se encargarán del resto''. - Miss Fortune","Hechizo",[],["Aguas Estancadas"],"ÉPICA"],"03BW009":["Chantaje","Inflige 2 de daño a un aliado para otorgar Vulnerable a 2 enemigos.","","\"Dime ahora mismo de dónde has sacado esos barriles de más que tienes, Slim. ¿Eh? Si no quieres, podemos empezar un tira y afloja entre tu lengua y el brazo de Jimbo. Y, colega..., por ti no pienso apostar\". - Alevín sabio","Hechizo",[],["Aguas Estancadas"],"RARA"],"03DE010":["La gran plaza","Cuando se invoca a un aliado, le concede +1|+1 y Contendiente esta ronda.","","Tianna alzó la vista por encima de la asamblea para evaluar las filas allí reunidas. El único ruido de la plaza era el chasquido del estandarte provocado por la brisa. Inclinó la cabeza con un gesto seco en señal de aprobación y, a continuación, levantó el estandarte dando un grito. \"¿Estáis listos para luchar por Demacia?\". La respuesta del ejército allí congregado hizo retumbar las mismas montañas. ","Hito",[],["Demacia"],"ÉPICA"],"03FR009":["El Abismo de los Lamentos","Comienzo de ronda: Crea en la mano un campeón de nivel 2 aleatorio que no tengas en la mano, en el mazo o en el tablero.","","Al puente acuden muchos héroes atraídos por algo perteneciente al mundo de lo desconocido. Hacen frente al frío gélido y a la plataforma que se desmorona a su paso para comprobar qué les aguarda más allá: la victoria o la muerte.","Hito",[],["Freljord"],"ÉPICA"],"03MT005":["Sendas divergentes","Roba un hito o destruye un hito.","","Targon es un enclave caprichoso, donde lo irrompible se puede romper y lo roto se recompone.","Hechizo",[],["Targon"],"COMÚN"],"03SI009":["Criptas de Helia","Comienzo de ronda: Si es posible, mata a tu aliado de mayor coste para invocar a un aliado de tu mazo que cueste 1 más.","","¿Qué mejor que la promesa de una vida eterna y riquezas infinitas para atraer a las almas a un lugar desdichado como este?","Hito",[],["Islas de la Sombra"],"ÉPICA"],"03IO006":["Monasterio de Hirana","Comienzo de ronda: Crea 1 Santuario en la mano.","","Las montañas de Jonia ocultan varios santuarios para aquellos que busquen centrarse y descansar.","Hito",[],["Jonia"],"ÉPICA"],"03NX013":["Tierra Abrasada","Mata a una unidad dañada o destruye un hito.","","\"Los perrodracos reconocen su olor. Darán con ella y pondremos fin a esto. No hay otra opción\". - Arrel la Rastreadora","Hechizo",[],["Noxus"],"COMÚN"],"03NX004":["Arena de Noxkraya","Fin de ronda: Tu aliado más fuerte y el enemigo más débil se golpean el uno al otro.","","\"¿Cómo va eso, justicieros y justicieras? ¡¿Estáis preparados para una abrasadora noche en el CAMPO DE FUEGO?! Oh, oh. Parece que el pequeño Trik lleva hoy las de perder. ¡Va a enfrentarse al portentoso, al peleoso, GRANAAAAK el Enorme! ¡Que los médicos no se vayan muy lejos, esto va a ser un asalto rápido!\". - Comentarista de la arena","Hito",[],["Noxus"],"ÉPICA"],"03DE004":["Capitana Arrika","Jugar: Captura a una unidad o un hito.","","De pequeña, Arrika presenció de primera mano los devastadores efectos de la conquista noxiana cuando el imperio destruyó su hogar. Cuando se alistó en el ejército, juró que jamás dejaría que una bandera de Noxus se izara en territorio demaciano ni permitiría que ningún otro muchacho se quedara huérfano.","Unidad",["ÉLITE"],["Demacia"],"RARA"],"03IO005":["Vuelta a casa","Retira una unidad o un hito aliado para retirar una unidad o un hito enemigo.","","\"Trevooooooorrrr, vuelveeeee...\". - La casa de Trevor","Hechizo",[],["Jonia"],"COMÚN"],"03MT052":["Manantial estelar","Fin de ronda: Cura 1 de vida a los aliados dañados. Después, si te he visto curar 22 de daño o más a aliados, ganas la partida.","","\"Arriba en la sagrada corriente descendente,\nEn lo hondo de los charcos, mana la sanación,\nLa luz brillante, el agua resplandeciente,\nHay que escuchar de los ríos la canción,\nEn lo más alto de la montaña de cristal\".\n- Estrofa Ottrani","Hito",[],["Targon"],"ÉPICA"],"03MT064":["La cima de Targon","Comienzo de ronda: Reduce el coste de una carta aleatoria de la mano de todos los jugadores a 0 esta ronda.","","A las puertas del reino celestial se alza el guardián cristalino de Targon. Ante su presencia, todo se desvanece: la esperanza, el miedo, las dudas. Sus pruebas desintegran toda preocupación mortal y desnudan el alma de aquellos que asciendan el Monte. Y, entonces, este juez definitivo imparte su sentencia. ","Hito",[],["Targon"],"ÉPICA"],"03SI008":["Derrumbe","Mata a un aliado para matar a una unidad o destruye un hito.","","Nada permanece en estas islas malditas. Todo se acaba.","Hechizo",[],["Islas de la Sombra"],"RARA"],"03PZ001":["La Universidad de Piltover","Comienzo de ronda: Descarta tu mano. Crea 3 cartas aleatorias en la mano y les otorga Fugaz.","","Los inventos del profesor Cecil B. Heimerdinger lo hicieron famoso, pero fueron sus animadas clases y la evidente impredecibilidad de los experimentos que realizaba en el aula lo que hizo mella en las mentes más brillantes de Piltover imposible de borrar.","Hito",[],["Piltover y Zaun"],"ÉPICA"],"03FR003":["Observador impasible","Jugar: Destruye todos los hitos o inflige 3 de daño a todas las demás unidades.","","\"No tuvimos tiempo para recoger nuestras cosas ni avisar a los demás. Solo pudimos correr hacia el bosque y contemplar como aplastaba nuestros hogares\". - Guardia del hogar avarosano","Unidad",[],["Freljord"],"RARA"],"03MT026":["Rahvun, Lanza del Mediodía","Amanecer: Crea una carta con Amanecer en la mano.\nPara nosotros siempre es de día.","","''¡Manteneos fieles, Ra-Horak, y nuestra luz brillará siempre con fuerza!''.","Unidad",[],["Targon"],"RARA"],"03MT067":["Íbice de cristal","Jugar: Otorga Abrumar a un aliado.","","A quienes busquen escalar Targon les vendría bien hacerse amigos de la fauna local. No existen criaturas más familiarizadas con los peligros de Targon, ni que puedan viajar con más soltura por su gélido terreno.","Unidad",[],["Targon"],"COMÚN"],"03MT084":["Moldeando estrellas","Convoca una carta celestial de 7 o más de coste, y después cura 5 de vida a un aliado o a tu nexo.","","\"Mira a las estrellas. Si tienes suerte, te devolveré la mirada\".\n- Aurelion Sol","Hechizo",[],["Targon"],"COMÚN"],"03MT221":["Colmillos","Jugar: Convoca una carta celestial de coste 3 o inferior.","","\"Madre Luna, muéstrame el camino.\nDesgarra el firmamento,\ndeseo ver más allá\".\n- Plegaria lunari","Unidad",[],["Targon"],"ÉPICA"],"03MT093":["Pádel estelar","Inflige 5 de daño a un enemigo que haya atacado esta ronda o que esté Aturdido.","","\"¡Catapuuumsis!\". - Zoe","Hechizo",[],["Targon"],"COMÚN"],"03MT073":["Portaocaso lunari","Cuando se me invoca, crea 1 Polvo de pétalo del atardecer en la mano.","","''Los pétalos del atardecer florecen cuando cae la noche, y solo bajo la luna llena. Es un emblema que nos llena de orgullo a los lunari. Hemos empleado su polvo desde hace siglos, pues somos los únicos que sabemos cómo cosecharlos de forma segura''.","Unidad",[],["Targon"],"COMÚN"],"03MT002":["Se hunden los cielos","Cuesto 2 menos por cada aliado celestial o dragón que tengas. Inflige 15 de daño a todos los enemigos.","","''Cuando llegue el momento, castigaré a Runaterra. Quizá decida arrastrar lo que quede de ella conmigo durante la eternidad. Como un juguete... Un juguete inerte e inútil. No sé, la verdad es que no me lo he planteado en serio''.\n- Aurelion Sol","Hechizo",[],["Targon"],"ÉPICA"],"03MT217":["Aphelios","Anochecer: Elige un arma lunar que crear en la mano.\nCada ronda, la primera vez que juegues otras 2 cartas: Crea el arma lunar en fase en la mano si no tienes ya una.","Has usado 4 armas lunares o más.","\"Cada conflicto sirve para demostrarles a los solari que nos merecemos respeto. Les hemos hecho ver que la luz de la luna está a la altura de la de su sol, les hemos enseñado a no menospreciar lo que no conocían. Y las lecciones que todavía deben aprender...\". - Orador menguante lunari","Unidad",[],["Targon"],"Campeón"],"03MT044":["Guardián del Sol","Amanecer o cuando activas otra carta con Amanecer: Consigo +1|+1.","","''Guardián resplandeciente, tu ira arde como el sol de mediodía. Ven y castiga a aquellos que osen adentrarse en este lugar sagrado''. - Inscripción del guardián del Sol","Unidad",[],["Targon"],"ÉPICA"],"03MT056":["Diana","Anochecer o cuando activas otra carta con Anochecer: Consigo Contendiente esta ronda.","Has activado Anochecer 4 o más veces.","Se erguía entre ellos preparándose para la batalla, resplandeciente, ataviada de plateado y azul, con ojos como estrellas del firmamento. La luna se alzó y la bañó de luz, y los lunari se agruparon en torno a ella con los ojos cerrados. Llenos de gratitud, rezaron en silencio por su seguridad.","Unidad",[],["Targon"],"Campeón"],"03MT020":["Cosmicornio resplandeciente","Jugar: Cura a un aliado y a tu nexo 3 de vida.","","''¿Ves esa estrella que se mueve por el cielo? Es un cosmicornio adulto. Los jóvenes comparten su magia curativa con nosotros hasta que pueden regresar al cielo, pero los adultos emplean su poder sin ayuda. Ver uno y ser capaz de reconocerlo es un augurio de buena suerte. Cuidar de uno supone una bendición aún mayor''. - Lidari, vigilante de las estrellas","Unidad",[],["Targon"],"COMÚN"],"03MT091":["Mapa celeste superguay","Convoca una carta celestial de coste 3 o inferior.","","\"Y a estas tres estrellas brillosas y especiales las llamaré.... ¡'La comba celestial'! O igual es más bien una carita sonriente del revés, no sé\". - Zoe","Hechizo",[],["Targon"],"RARA"],"03MT047":["Cygnus el Nocturno","Anochecer: Concede Elusión a un aliado esta ronda.","","Los lunari aguardaron a la caída de la noche para refugiarse en ella. El camino frente a ellos parecía desierto, pero Cygnus sabía que el campamento solari estaba poco más allá. Hizo un gesto y los demás se pusieron en fila tras él.","Unidad",[],["Targon"],"ÉPICA"],"03MT094":["Acechasombras lunari","Anochecer: Consigo Elusión.","","\"Permitidnos dirigir nuestros ojos a los cielos, al sol, al abrazo de nuestra da... Un momento... ¿Qué...? ¿Qué es eso?...\".\n- Sacerdote solari","Unidad",[],["Targon"],"COMÚN"],"03MT036":["Bendición de Targon","Otorga +3|+3 a un aliado.","","\"Un regalito de Targon\". - Taric","Hechizo",[],["Targon"],"RARA"],"03MT092":["Cabra montesa","Golpear: Crea 1 Gema en la mano.","","Las cabras del Monte Targon son incluso más peligrosas que sus primas cotidianas, pues las gemas que componen sus cuernos incrustan añicos hirientes cuando golpean. ","Unidad",[],["Targon"],"RARA"],"03MT060":["Protector fornido","Comienzo de ronda: Cura 3 de vida a tu nexo. Me inflige daño equivalente a la curación realizada.","","''Nadie conoce los caminos de Targon como yo, por eso me quedo enganchado con algunos de los, em, cosmicornios obstinados esos. ¡Qué bien que quieran que cuide de ellos!''. ","Unidad",[],["Targon"],"ÉPICA"],"03MT001":["Bichejillos furtivos","Jugar: Aturde a todos los enemigos con 2 o menos de poder.","","El silencio cristalino de la ladera de la montaña trajo el tintineo del deshielo y, mucho más por encima, lo que los viajeros habrían jurado que eran... carcajadas.","Unidad",[],["Targon"],"COMÚN"],"03MT055":["Soraka","Apoyo: Me cura 4 de vida a mí y al aliado al que apoyo.","Has curado a aliados dañados 4 o más veces.","\"La curación es, por naturaleza, altruista. No es que tú obtengas el poder de otros; es que te lo entregan con gusto. Trata a los demás con compasión y verás como brillan\".","Unidad",[],["Targon"],"Campeón"],"03MT048":["Obsequiadora","Cuando se me invoca, crea 1 Gema en la mano.","","''Dicen que el Protector ha bendecido estas gemas. Llevadlas con vosotros y os acompañará en espíritu''.","Unidad",[],["Targon"],"COMÚN"],"03MT082":["Luz del alba","Concede +1|+1 a los aliados esta ronda.\nActiva el efecto Amanecer de un aliado.","","''¡Nos alzamos con el amanecer! ¡Marchamos con la luz!''.\n- Leona","Hechizo",[],["Targon"],"RARA"],"03MT058":["Taric","Apoyo: El aliado al que apoyo y yo conseguimos Aguante esta ronda. Copia el último hechizo que me hayas lanzado únicamente a mí esta ronda y se aplica a ese aliado (no se puede volver a copiar).","Te he visto seleccionar como objetivo o apoyar a aliados 7 o más veces.","''La gentileza de Taric inspira a todo aquel que lo conoce, los impulsa a buscar la calidez interior capaz de alentarlos incluso en las noches más frías''. - Adivino de la montaña","Unidad",[],["Targon"],"Campeón"],"03MT062":["Chispóloga atolondrada","Jugar: Si una carta celestial es visible, concede +1|+1 y Escudo de hechizos a un aliado.","","\"... y una brilliposa es como polvo estelar que ha caído al suelo y alza de nuevo el vuelo. Son superbonitas; vi una anoche que era preciosa y qué hambre tengo y echó a volar hacia las estrellas y entonces...\".","Unidad",[],["Targon"],"RARA"],"03MT040":["Brilliposa","","","\"La esperanza es un ser delicado que vuela cada vez más alto y al que nadie debe dar caza\". - Sacerdotisa lunari","Unidad",[],["Targon"],"COMÚN"],"03MT086":["Artista ensimismada","Jugar: Descarta 1 para convocar una carta celestial de coste 3 o inferior.","","''¡Esta es mi preferida! La llamo 'Identidad metafísica de la psique consciente'. A no ser que inclines la cabeza así... Entonces parecen como dos cucharas''.","Unidad",[],["Targon"],"RARA"],"03MT016":["Aplastador sobresaltado","","","''Aaay, el aplastador gigante no quiere cruzar el portalcito, ¿eh? No pasa nada, podemos... ¡Ja, ja, ja, ja! ¡Era broma! ¡Ahí vas!''. - Zoe","Unidad",[],["Targon"],"COMÚN"],"03MT054":["Leona","Amanecer: Aturde al enemigo más fuerte.","Has activado Amanecer 5 o más veces.","Se alzaba entre ellos preparándose para la batalla, irradiando luz, envuelta en resplandores de color dorado y carmesí, con los ojos como ascuas. El sol se alzó y la coronó con su luz, y todos los solari presentes bajaron la mirada... No por vergüenza, sino en señal de respeto.","Unidad",[],["Targon"],"Campeón"],"03MT220":["La senda hendida","Anochecer: Aturde a un enemigo. Si es un adepto, lo vuelve a aturdir en el siguiente comienzo de ronda.","","\"Ya se ha hecho de noche, Madre Luna.\nDanos fuerza para detener a quienes pretendan herirnos,\ny que lamenten su fortuna\".\n- Plegaria lunari","Unidad",[],["Targon"],"RARA"],"03MT021":["Mentedoble infinito","Jugar: Elige 2 enemigos.\nComienzo de ronda: Los aturdes.","","Los viajeros cuyas miradas se cruzan con la de la criatura reciben un conocimiento tan profundo, una percepción tan asombrosa, que sus mentes se desmoronan en ese instante.","Unidad",["DRAGÓN"],["Targon"],"ÉPICA"],"03MT006":["Inviolus Vox","Cada ronda, cuando un aliado con Furia mata a un enemigo por primera vez, crea un adepto Dragón aleatorio en la mano.","","''¡Mira a los cielos y verás lo que yo veo! Primero, la señal que brilla en la noche estrellada. Después, días y días de furia en los que todo arde. ¡Ya verás! ¡Todos lo veremos!''. - Heraldo de dragones","Unidad",["DRAGÓN"],["Targon"],"ÉPICA"],"03MT015":["Contemplad el infinito","Convocar.","","Los cielos cuelgan sobre ti como un oscuro tapiz de estrellas parpadeantes. Frente a su eternidad, eres insignificante, sin brillo. ¿Adónde dirigirás antes la mirada?","Hechizo",[],["Targon"],"COMÚN"],"03MT013":["Ceguera lunar","Silencia a 2 unidades enemigas esta ronda.\nAnochecer: No pueden bloquear esta ronda.","","\"Aquellos que no estén acostumbrados a la luna deberán aprender a aprovechar su luz o se quedarán ciegos\". - Diana","Hechizo",[],["Targon"],"COMÚN"],"03MT009":["Zoe","Golpe al nexo: Crea 1 Mapa celeste superguay en la mano o, si ya tienes una copia, su coste se reduce en 1.","Te he visto jugar 10 cartas con diferentes nombres.","\"¡Andaaaa, holaaaa! ¿Qué haces? ¿Es un juego de cartas? ¿¿Puedo jugar?? ¡¿Qué?! ¿Que ya estoy en la partida? ¡Ja! Qué locura de dimensión...\".","Unidad",[],["Targon"],"Campeón"],"03MT087":["Aurelion Sol","Jugar: Convoca una carta celestial de 7 o más de coste.\nComienzo de ronda: Crea una carta celestial aleatoria en la mano.","Fin de ronda: Tus aliados tienen 20 o más de poder en total.","''¡Me es indiferente lo que escribas sobre mí, criatura mediocre! Pero asegúrate de especificar lo apuesto que soy. Y lo magnífico. Y que soy muy pero que muy inteligente. ¿Sabes escribirlo o te lo deletreo?''.","Unidad",["DRAGÓN"],["Targon"],"Campeón"],"03MT019":["Bastión","Otorga +1|+1 y Escudo de hechizos a un aliado.","","''En honor a la montaña''. - Taric","Hechizo",[],["Targon"],"COMÚN"],"03MT214":["El Vuelo","Golpe al nexo: Roba 1 y coloca esta carta entre las 3 cartas de arriba del mazo.","","''Madre luna, dame confianza,\nlléname de la convicción del Vuelo,\nguíame en mi camino''.\n- Plegaria lunari","Unidad",["AVE"],["Targon"],"RARA"],"03MT071":["Tyari el Viajero","Apoyo: Otorga +0|+2 al aliado al que apoye.","","Cuando viajas, debes estar abierto a la travesía, que te trasformará inevitablemente. Cuando viajas, siempre recibes algo nuevo que te nutre... y siempre dejas algo de tu antiguo yo atrás. ","Unidad",[],["Targon"],"COMÚN"],"03MT008":["Plegaria","Cura por completo a aliados dañados.","","\"¡Por la vida!\". - Soraka","Hechizo",[],["Targon"],"RARA"],"03MT023":["Estallido solar","Inflige 6 de daño a una unidad.\nAmanecer: En lugar de eso, la silencias esta ronda y le infliges 6 de daño.","","Hay pocos que sobrevivan a una mirada tan intensa como la del sol.","Hechizo",[],["Targon"],"RARA"],"03MT045":["Protección astral","Cura 4 de vida a un aliado y le otorga +0|+4.","","\"¿Te has creído que nos habías vencido? ¡Ja! Esto solo acaba de empezar\". - Protector fornido","Hechizo",[],["Targon"],"COMÚN"],"03MT080":["Guarda del manantial","Cuando se me invoca, crea 1 Dones termales en la mano.","","\"Principalmente, me ocupo de los manantiales, pero la responsabilidad de un pastor es, ante todo, con su rebaño. Parece que las prioridades chocan\".","Unidad",[],["Targon"],"COMÚN"],"03MT042":["Ladrona de hechizos","Manifiesta un hechizo enemigo jugado esta partida.","","\"¡Guau, eso ha sido geniaaaal! Pero sería mucho mejor si lo hiciera yo, ¿eh? ¡Bueno, gracias, hastalueguiii!\". - Zoe","Hechizo",[],["Targon"],"RARA"],"03MT057":["Forjador de soles solari","Amanecer: Consigo Robo de vida esta ronda.","","El Forjador de soles alzó su lupa bajo la luz que inundaba la habitación. El artilugio de los solari absorbió los resplandecientes rayos de sol para crear un potente encantamiento para su arma.","Unidad",[],["Targon"],"COMÚN"],"03MT041":["Mentor de las gemas","Apoyo: Otorga +2|+2 al aliado al que apoye.\nÚltimo aliento: Crea 3 Gemas en la mano.","","\"¿Has pillado algo de lo que ha dicho?\".\n\"Ni una sola palabra. Sonaba bien, eso sí\".\n- Emir y Haley, exploradores de la montaña","Unidad",["YORDLE"],["Targon"],"ÉPICA"],"03MT027":["Hoja del cénit","Otorga +1|+2 a un aliado y le concede Abrumar esta ronda.\nAmanecer: Roba 1 Hoja del cénit.","","''¡Que el sol os infunda con su fuerza!''. - Sacerdotisa solari","Hechizo",[],["Targon"],"COMÚN"],"03MT096":["Sacerdotisa solari","Amanecer: Convoca una carta celestial de 4, 5 o 6 de coste.","","Los solari miran a las estrellas para guiarse como cualquier targoriano, siendo la estrella más importante de su fe el Sol.","Unidad",[],["Targon"],"RARA"],"03MT028":["Portaescudo solari","Amanecer: Consigo +0|+4 esta ronda.","","\"No te amparas en el abrigo de la noche. Qué gran necedad\". La portaescudo se enderezó. \"Suelta tus armas y entrégate\".\nLa lunari se agachó en silencio y preparó de nuevo sus hojas curvas.\nQue así sea.\nEn respuesta, la solari se preparó para el combate y alzó el escudo para reflejar los rayos del sol naciente.","Unidad",[],["Targon"],"COMÚN"],"03MT089":["Guarda de la medialuna","Anochecer: Consigo +2|+0.","","''Guarda estoico, que el amable tacto de la luna llena te devuelva la fuerza. Despierta y protégenos de los que osen traspasar este lugar sagrado''. - Inscripción del guarda de la medialuna","Unidad",[],["Targon"],"RARA"],"03MT051":["Toque divino","Cura a un aliado o a tu nexo 2 de vida. Roba una carta.","","Cuando más brillan los cosmicornios es cuando están felices.","Hechizo",[],["Targon"],"COMÚN"],"03MT003":["Nido de dragón","Roba 2 dragones diferentes u otorga +1|+1 y Abrumar a todos los dragones aliados.","","''Sus llantos recuerdan a los ásperos maullidos de un gato. Si los escuchas alguna vez, date la vuelta y busca al guardia más cercano. Donde hay huevos de dragón, hay dragones, ¿entendido?''. - Recolectora de Targon","Hechizo",[],["Targon"],"RARA"],"03MT098":["Vigor solar","Otorga +0|+2 a un aliado.","","''¡Nuestro escudo es nuestra convicción, determinación y confianza en la luz!''. - Portaescudo solari","Hechizo",[],["Targon"],"COMÚN"],"03MT215":["Regalos del más allá","Elige un arma lunar que crear en la mano.","","''A tu alcance, Aphelios...''. - Alune","Hechizo",[],["Targon"],"COMÚN"],"03MT063":["Sueñalunas","Jugar: Convocar.\nAnochecer: Reduce el coste de esa carta en 1.","","''¡Pero mira cuántos amigos tenemos hoy en el firmamento! ¿Ves esa estrella tan brillante? ¡Es el Mensajero, que no nos quita ojo de encima! ¿Y esa constelación tan tenue de ahí? ¡Es el Gamberro, que se oculta tras las nubes! Y la de encima... ¡¡Shh, Kulun!! ¡Esas no puedes bajarlas a zarpazos!...''.","Unidad",[],["Targon"],"COMÚN"],"03MT100":["Dragón del eclipse","Amanecer: La siguiente unidad celestial o dragón que juegues cuesta 2 menos.\nAnochecer: Crea un adepto dragón y un adepto celestial aleatorios en la mano.","","Escama de dragón (Dragón del eclipse, Draco obscuratus)\nNotas: La escama tiene unas propiedades ópticas fantásticas. Es altamente reflectante bajo la luz solar directa.\nGarabatos: ¡TAMBIÉN BRILLA POR LA NOCHE!\n- Notas de Anden Mayne, investigador de Huevotesta","Unidad",["DRAGÓN"],["Targon"],"RARA"],"03MT076":["Adivino de la montaña","Las cartas celestiales cuestan 1 menos.\nAlianza: Convocar.","","''Tenemos mucho que aprender de las estrellas, son una maravillosa guía. Para nosotros son una constante, una forma de trazar nuestro camino''.","Unidad",[],["Targon"],"RARA"],"03MT029":["Pastora de estrellas","Cuando curas a un aliado dañado, consigo +2|+0.","","''La primera vez que vi su estela en el cielo nocturno, me enamoré de los cosmicornios. ¡Ojalá supiera entonces cuántos iba a conocer!''.","Unidad",[],["Targon"],"RARA"],"03MT219":["El templo del Velo","Cada ronda, la primera vez que juegas otras 2 cartas, recuperas 2 de maná y otorga +1|+0 a tu aliado más fuerte.","","Es en este lugar, en el reino espiritual, donde Alune comulga con su hermano Aphelios. Ella es la que susurra reconfortantes palabras al silencioso asesino y la que traspasa el velo para entregarle sus armas de venganza.","Hito",[],["Targon"],"RARA"],"03MT079":["Pícaro estelar","Si hay una carta celestial visible, cuesto 2 menos.","","\"Los adultos son un rollazo. La única gente que mola por aquí son Zoe y sus amigos. He aprendido mucho de ellos, ¿eh? No como con esa sacerdotisa radiante tan pesada. Es que... Agh\".","Unidad",[],["Targon"],"COMÚN"],"03MT007":["Cría de cosmicornio","","","''Como cualquier otro polluelo, los cosmicornios jóvenes tienen que alzar el vuelo tarde o temprano. En ese sentido, son como el resto de las estrellas del cielo del anochecer: se caen constantemente. Por suerte, estamos aquí para recogerlos y, cuando estén listos, devolverlos a su hogar''. - Lidari, vigilante de las estrellas","Unidad",[],["Targon"],"COMÚN"],"03MT038":["Protector llamablanca","","","Fueron los chiquillos de Targon los primeros en hacerse amigos de los dragones más jóvenes y pacíficos. Quizá estas juveniles criaturas podían percibir la curiosidad inocente de los críos... Y quizá por eso, en lugar de herirlos, decidieran ofrecerles protección. ","Unidad",["DRAGÓN"],["Targon"],"COMÚN"],"03MT014":["Heraldo de dragones","Los dragones aliados cuestan 1 menos.","","Las nubes se retorcían en torno a sus inmensas siluetas, y el propio cielo parecía temblar ante sus agudos lamentos. Sabía lo que estaba a punto de llegar, pero no sentía miedo. El abrazo del destino la envolvía.","Unidad",[],["Targon"],"RARA"],"03MT110":["Quita de en medio","Durante el resto de la partida, las mejoras aliadas de \"esta ronda\" (menos Barrera) son permanentes. Roba 1.","","\"You know I mean everything that I say\nWhen you see me coming get out of the way\nI came to slay I came to slay\nBack and I'm better and ready to stay\".\n- Kai'Sa, \"THE BADDEST\".","Hechizo",[],["Targon"],"ÉPICA"],"03MT017":["Emblema del mensajero","Crea 5 Mensajeros en tu mazo.","","''El tiempo pasa, los cielos cambian. La Serpiente se aparta y el Mensajero ocupa su lugar en las alturas. Nos espera una temporada de abundancia...''. - Sacerdotisa lunari","Hechizo",[],["Targon"],"RARA"],"03MT025":["Fragmentos de la montaña","Llena tu mano con copias de Gemas.","","\"Si giras una gema del modo preciso, resplandecerá bajo la luz. Como las vidas de los mortales, cada una oculta cierto fuego interior\". - Taric","Hechizo",[],["Targon"],"ÉPICA"],"03MT216":["Sombras celestiales","Cuando se me invoca, recuperas 2 de maná de hechizos si hay una carta con Anochecer visible.","","\"Madre Luna, permíteme recordar\nque, aunque en soledad me halle,\ntus hijas danzan sobre mí,\ny eso significa que nunca estoy solo\".\n- Plegaria lunari","Unidad",[],["Targon"],"COMÚN"],"03MT012":["Juez de la cima","Cuesto 1 menos por cada vez que hayas seleccionado como objetivo o apoyado a aliados en esta partida.","","El Juez es la prueba final de la montaña, pues solo el guardián puede ver más allá de las acciones del alpinista y contemplar su espíritu.","Unidad",[],["Targon"],"ÉPICA"],"03MT085":["Silencio","Silencia una unidad esta ronda.","","\"Conocerán la paz\". - Soraka","Hechizo",[],["Targon"],"RARA"],"03MT081":["Exploradores de la montaña","Apoyo: Otorga +2|+2 al aliado al que apoye. Si tiene Apoyo, el aliado al que apoye consigue +2|+2 y así sucesivamente por cada aliado apoyado.","","Todo individuo que se aventura a ascender el Monte Targon tiene su razón. Algunos lo hacen para demostrar su valía a ojos de sus compañeros. Otros, para demostrarse algo a sí mismos.","Unidad",[],["Targon"],"ÉPICA"],"03MT030":["Contemplador de estrellas","Cuando curas a un aliado dañado, le concedes Elusión esta ronda.","","\"La estrellas nos acompañan solo un tiempo determinado. Cuando han recibido los debidos cuidados, las devuelvo al firmamento con un fulgor inmediato de luz estelar... y agitación de pezuñas\".","Unidad",[],["Targon"],"RARA"],"03MT088":["Soldado solari","Amanecer: Consigo +1|+1 esta ronda.","","Sintiendo como lo calentaba el sol, hacía guardia en la prisión de herejes e ignoraba las débiles súplicas que de pronto se tornaban en silencios amargos.","Unidad",[],["Targon"],"COMÚN"],"03MT033":["Abuelo Rumul","Jugar: Otorga +0|+4 a 2 aliados.","","''Escucha, Osu. ¿Oyes eso? ¡Son campanas! ¡El abuelo ha vuelto!''. - Illi, pastora de estrellas","Unidad",[],["Targon"],"RARA"],"03MT035":["Cascada pálida","Concede +1|+1 a un aliado esta ronda.\nAnochecer: Roba 1 carta.","","''Al abrigo de la noche, bajo la mirada de una pálida luna''.\n- Diana","Hechizo",[],["Targon"],"COMÚN"],"03MT075":["Sacerdotisa lunari","Anochecer: Convocar.","","''Oh, estrellas del cielo, peregrinas en el vasto paraje de la noche... Quedaos con nosotros un instante, habladnos de vuestro camino''. - El panegírico del atardecer","Unidad",[],["Targon"],"RARA"],"03MT218":["Hueso estelar","Si un celestial es visible, crea 1 El Mensajero en tu mazo y otorga +1|+1 a los aliados celestiales estén donde estén.","","\"Que el Mensajero juegue,\ny que con su dicha\nilumine las estrellas\".\n- Plegaria lunari","Hechizo",[],["Targon"],"ÉPICA"],"03MT074":["Burbuja somnífera","Aturde a un enemigo. Crea 1 Pádel estelar Fugaz en la mano.","","\"¡Hora de la siesta! Una brilliposa, dos brilliposas, tres bri... ¡Anda, ¿qué es eso de ahí?!\". - Zoe","Hechizo",[],["Targon"],"RARA"],"03MT072":["Marca ardiente","","","Un sinfín de desafíos aguarda a aquellos que escalan el Monte Targon. Algunos, como el incesante ascenso, consumen sus fuerzas poco a poco. Otros son de efecto más inmediato.","Unidad",["DRAGÓN"],["Targon"],"COMÚN"],"03MT039":["Porilla","","","En el espacio, nadie te oye chillar de alegría.","Unidad",["PORO"],["Targon"],"COMÚN"],"03PZ019":["Porobot actualizado","Mientras esté en la mano, tengo una palabra clave aleatoria que cambia cada ronda. Cuando se me invoca, consigo dicha palabra clave.","","No es tan achuchable como el de verdad, pero sí que es igual de mono.","Unidad",["PORO"],["Piltover y Zaun"],"RARA"],"03PZ005":["Bot balístico","Comienzo de ronda: Crea 1 Ignición en la mano.","","El sujeto solicitó que no alteráramos su mente, pues dice que \"ahí es donde guardo rencor a todos mis enemigos\".\n- Registro del Mejorador, entrada 1011","Unidad",[],["Piltover y Zaun"],"COMÚN"],"03PZ004":["Rayo de la muerte - Mk 1","Inflige 1 de daño a una unidad. Crea 1 Rayo de la muerte - Mk 2 entre las 3 cartas de arriba del mazo.","","\"Hoy he conseguido demostrar que se puede concentrar la energía radiante para formar un único y poderoso láser. Con las mejoras adecuadas, este rayo podría convertirse en una herramienta de precisión sin igual, pero aún queda mucho trabajo\".\n- Notas de diseño de Viktor","Hechizo",[],["Piltover y Zaun"],"RARA"],"03PZ003":["Viktor","Cuando se me invoca o al comienzo de ronda: Crea 1 Mejora de núcleo hex en la mano.","Has jugado 7 o más cartas creadas.","\"Zaun, has presenciado incontables tragedias, y ahora ha llegado el momento de cambiar. Y este cambio, como todos los cambios significativos, ha de comenzar desde el interior\".","Unidad",[],["Piltover y Zaun"],"Campeón"],"03PZ010":["Mimo mecánica","Atacar: Consigo todas las palabras clave de mis aliados.","","\"Soy como tú, pero mejor\".","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"03PZ022":["A darlo todo","Mejora el poder y la vida de todos los aliados al nivel de poder o vida del aliado que tenga más.\nOtorga a todos los aliados las palabras clave aliadas.","","\"I know I know\nYou want some more\nIf you ready let's go\nGiving it all\".\n- Seraphine, 'MORE'","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"03PZ014":["Creaciones precisas","Crea 1 Cabezalata armado, Bot balístico o Miaudroide en la mano y le otorga +1|+1.","","\"La racionalidad y la capacidad de elección separan a los humanos de sus instintos animales básicos\". - Viktor","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"03PZ013":["Repetir es mejorar","Elige un adepto y crea una copia de él con +1|+1 en la mano.","","\"La mejora personal es un juego en el que uno mismo es tanto el héroe como el villano. Sufrirás. Quizá incluso llegues a pensar que has ganado. Pero, al final, el único que se interpone en tu camino eres tú\". - Mimo mecánica","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"03PZ025":["Prueba de estrés","Elimina Fugaz de todas las cartas de la mano. Cuando se me descarta, robas 1 con Fugaz.","","\"Es algo simple, en realidad. Reemplacé el marco de acero por una aleación más resistente que inventé. Después, redireccioné el circuito separándolo de las bisagras para que los sistemas no se cortocircuitasen. Nada del otro mundo\".\n- Jefa mecanicista Zevi","Hechizo",[],["Piltover y Zaun"],"RARA"],"03PZ012":["Cabezalata armado","","","\"¡Venga, un brazo nuevo! Siempre he querido uno de estos. ¿Y ahora qué? ¿Ruedas en lugar de piernas? ¿Electrocinturones? ¿Dientes de metal? Bueno, la cara mejor no me la toques, que me gusta\".","Unidad",[],["Piltover y Zaun"],"COMÚN"],"03PZ020":["Fundición de núcleos hex","Comienzo de ronda: Todos los jugadores roban 1 carta.","","\"Que digan lo que quieran acerca de mis métodos. No podrán detener el progreso. ¡La luz de mi sabiduría ilumina la oscuridad de la ignorancia!\". - Viktor","Hito",[],["Piltover y Zaun"],"RARA"],"03PZ002":["Miaudroide","","","\"No me abrí paso con uñas y dientes por el mundo académico de Piltover para que ahora vengan y decidan que mis inventos son 'demasiado peligrosos' y mi presencia, ¡'demasiado adorable'! Miau largo a Zaun, que sé que ahí me espera una mente preclara que comparte mis ambiciones...\".","Unidad",["GATO"],["Piltover y Zaun"],"RARA"],"03PZ011":["Réplica sísmica","Inflige 3 de daño a una unidad o destruye un hito.","","\"Este rayo de luz guiará nuestro avance hacia Piltover. ¡Nada se interpondrá en el camino de la gloriosa evolución!\".\n- Viktor","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"03PZ017":["Improbulador de rayo triple","Inflige 1 de daño a una unidad. Invoca un adepto aleatorio de coste 1. Si me tienes en la mano, cuando juegues una carta de coste 3, ambos aumentan en 1.","","''... y uno, dos, ¡¡¡y TRES!!! Ay. Ay, caramba... ¡¿otro resultado imprevisto?!''. - Heimerdinger","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"03PZ018":["Cañón de poros","Descarta 1 para jugar esta carta.\nCrea 2 Poros atrevidos en la mano.","","Dos suaves siluetas se arquean elegantemente sobre la multitud que los adora, y a su paso dejan un rastro de pelos y un ligero aroma a recién salido del horno.","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"03SI004":["Sombras acechantes","Elige un adepto de las 4 cartas de más arriba de tu mazo.\nLa robas, coloca el resto en tu mazo y luego crea 1 copia exacta con Endeble en la mano.","","\"Id... Rodeadlos...\". - Nocturne","Hechizo",[],["Islas de la Sombra"],"RARA"],"03SI001":["Acechador de la penumbra","Anochecer: Crea una copia de mí en la mano.","","\"Al principio solo era un par de ojos y una voz solitaria que parloteaba entre las sombras. Cada vez que miraba de nuevo, había empeorado. Mostraba más ira; hacía más ruido. En cuanto vi el Diente, eché a correr\". - Saqueador del Diente de Ballena","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"03SI018":["Gula","Mata a un aliado con Último aliento para invocar un adepto de tu mazo que cueste 1 más.","","\"¡HORA DEL CALDO!\". - Carnicero voraz","Hechizo",[],["Islas de la Sombra"],"RARA"],"03SI012":["Pasaje inmerecido","Destruye todas las unidades que se hayan invocado (y no jugado) esta ronda.","","\"Pues claro que la muerte está presente en Demacia. Vemos cómo se lleva a nuestros seres queridos y sabemos perfectamente que algún día vendrá a por nosotros. Pero en esas islas... casi puedo saborearla. La siento en mis pulmones al respirar, la oigo susurrarme en el oído. Y no se trata de una noción abstracta. Está aquí sentada conmigo. Ahora. Y al final se quedará con todos nosotros\". - Notas de Jens Tommen, historiador","Hechizo",[],["Islas de la Sombra"],"RARA"],"03SI014":["Sombras envolventes","Otorga +2|+2 y Endeble a todos los aliados de tu mazo y de la mano.","","\"Ya sea física o psicológicamente, me temo que las Islas de la Sombra terminarán por destrozarnos a todos, y la demencia será la que reine hasta el fin de los tiempos\". - Notas de Jens Tommen, historiador","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"03SI016":["Todo o nada","Drena 1 de una unidad.\nCrea dos copias de Todo o nada en tu mazo. Una de cada tres veces que esto ocurre, transforma todas las copias en Haz las maletas estén donde estén.","","\"We go hard, 'til we get it, get it\nWe go hard, we so in it, in it\nWe Pop Stars (Pop Stars), only winning, winning now\nAin't nobody bringing us down, down, down, down\".\n- Evelynn, 'POP/STARS'","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"03SI007":["Velo de oscuridad","La próxima vez que invoques a un aliado esta ronda, le concede +1|+0 y Escudo de hechizos esta ronda.","","\"Justo al salir del Diente, los sentirás. Unos dedos en la nuca tan ligeros como la llovizna. Las criaturas no se mueven cuando vas hacia ellas, no. No le temen a mi espada ni a mi antorcha. A nada. Qué horror de bichos\". - Saqueador del Diente de Ballena","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"03SI005":["Nocturne","Anochecer: Otorga Vulnerable a un enemigo y -1|-0 a los enemigos esta ronda.","Has atacado con 5 o más aliados con Anochecer o Temible.","\"Parece ser que, una vez perturbadas las suficientes almas, puede inmiscuirse en nuestro mundo. Solo la esperanza es capaz de devolver a esa monstruosidad al reino al que pertenece... Desgraciadamente, la esperanza murió hace mucho aquí, con el último aliento de una reina y el grito eterno de su rey\". - Notas de Jens Tommen, historiador","Unidad",[],["Islas de la Sombra"],"Campeón"],"03SI006":["Bestia de la ruina","Anochecer: Drena 2 de vida del nexo enemigo.","","Cada noche que pasaba, los viajeros estaban más fatigados. No encontraban descanso en la noche, solo intensos sueños. Dormir ya no era un alivio, sino que les arrancaba la vida de los huesos.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"03SI015":["Espectro inoportuno","Último aliento: Crea 2 copias de mí en el mazo del rival.","","La mayor parte de los espíritus de las Islas de la Sombra son criaturas terroríficas y sádicas. Algunas, sin embargo, solo son... un incordio tremendo.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"03SI003":["Vigía estigio","Anochecer: Consigo +2|+0 y Temible esta ronda.","","Conforme el sol se derrite para dejar paso a la brea, los horrores de este lugar despiertan, observan y aguardan.","Unidad",["AVE"],["Islas de la Sombra"],"COMÚN"],"03SI002":["Horror inenarrable","Drena 1 de vida de cualquier unidad o del nexo.\nAnochecer: Crea una carta con Anochecer aleatoria en la mano.","","''Cada día que pasa consume mi espíritu, me aleja del vigor que me llevó a encontrar este lugar. El Diente de Ballena está lleno de demacrados que parecen haber perdido todo rumbo, y me temo que, cuanto más tiempo paso aquí, más me parezco a ellos''. - Notas de Jens Tommen, historiador","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"03SI010":["Jinete del crepúsculo","Anochecer: Consigo +1|+0 por cada vez que has activado Anochecer esta partida.","","Cada vez que el sol se pone, la noche extiende sus oscuras alas y ensombrece los últimos resquicios de esperanza del día.","Unidad",[],["Islas de la Sombra"],"RARA"],"03SI013":["Niebla en alza","Invoca 1 Espectro de la niebla.","","Los espectros de la niebla se mueven por los planos sin que los ojos mortales puedan verlos, aparecen sin previo aviso e infunden miseria a todo aquel con el que se encuentran.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"03IO025":["Ráfaga de puñetazos","Otorga +1|+0 y Ataque rápido a un aliado. Si ya lo tiene, le otorga Ataque doble.","","''Ataca mucho, ataca rápido y ataca con fuerza''. - Cuernos del dragón","Hechizo",[],["Jonia"],"RARA"],"03IO017":["¡Pix!","Apoyo: Concede +2|+1 al aliado al que apoye esta ronda.","","''Pix es el mejor, es pequeño, chachi y excelente,\nle encanta jugar con la gente y disfruta... hmhmhmhmhmente!''. - Lulu","Unidad",["HADA"],["Jonia"],"COMÚN"],"03IO008":["¡Banal!","Transforma a un adepto en Ardilla 1|1 y lo silencia esta ronda.","","''¡Adorablus!''. - Lulu","Hechizo",[],["Jonia"],"COMÚN"],"03IO001":["Chiquilla de las flores","Cuando cuento con apoyo, consigo +2|+0.","","Todo el mundo quiere un familiar, pero nadie está listo para asumir las responsabilidades que conlleva. Hay que sacarlos a pasear, controlarles la dieta..., enseñarles a hacer pipí fuera. Es mucho trabajo.","Unidad",["HADA"],["Jonia"],"COMÚN"],"03IO019":["Voluntad singular","Elige un aliado. Retira al resto de unidades e hitos.","","''Yo camino en soledad''. - Sacerdotisa solitaria","Hechizo",[],["Jonia"],"ÉPICA"],"03IO002":["Lulu","Apoyo: Las estadísticas del aliado al que apoyo aumentan a 4|4 esta ronda.","Los aliados han recibido apoyo 3 o más veces.","''¡No te preocupes, Pix! ¡Vamos a salir de este claro y a adorablusar todas las cosas del mundo! ¡¿Estás listo?!''.","Unidad",["YORDLE"],["Ciudad de Bandle","Jonia"],"Campeón"],"03IO011":["Ardilla mazada","Golpear: Mi poder se duplica.","","Se toma cuatro batidos de bellotas en polvo al día. Ese es su secreto.","Unidad",["HADA"],["Jonia"],"RARA"],"03IO009":["Fae sabroso","","","Energía: 104 kJ (25 kcal), carbohidratos: 5.88 g, azúcar:\n3.53 g, fibra: 3 g, grasa: 0.18 g, proteína: 0.98 g, agua: 92 g...","Unidad",["HADA"],["Jonia"],"COMÚN"],"03IO003":["Fae guía","Jugar: Otorga Elusión a un aliado.","","''¡Shh! ¡Por aquí! Tenemos que girar hacia la izquierda tras la casa del árbol andante, y después pasar de largo junto a las flores parlantes. Lu, ¿me oyes? ¿Lu? ¡Lu! ¡Lulu! Ni se te ocurra darles de comer. Ni se te ocurra''.","Unidad",["YORDLE"],["Jonia"],"RARA"],"03IO007":["Trevor Traseroquieto","Apoyo: Crea 1 Murmuduende en ataque con las estadísticas del aliado al que apoyo.","","Se supone que tienes que perseguir tus sueños, no manifestarlos con un conjuro involuntario murmurado mientras duermes flotando por un antiguo bosque mágico. Es que hay que ver.","Unidad",["YORDLE"],["Jonia"],"ÉPICA"],"03IO010":["Bruja joven","Apoyo: Concede Ataque rápido y +1|+0 al aliado al que apoye esta ronda.","","Sir Ribery Montague abandonó su hogar para cumplir una importante misión o conseguir el favor de una casa de renombre. Sin embardo, el destino lo condujo a un bosque mágico donde la joven Bri lo convirtió en una rana y se lo llevó consigo en sus aventuras. ¡Pobre Rib!","Unidad",[],["Jonia"],"COMÚN"],"03IO020":["¡Negatizar!","Detengo un hechizo veloz o uno lento que cueste 3 o menos.","","\"¡Ni se te ocurra hacer eso, cabeza hueca! ¡Que puedes hacerle daño a los antílopes!\". - Lulu","Hechizo",[],["Jonia"],"RARA"],"03IO022":["A por ello","Retira a un aliado para invocar una copia endeble exacta en su lugar. Reduce su coste a 0 esta ronda.","","\"More\nKnow I got it,\nSo here you go,\nYou look like you could use some more\".\n- Akali, 'MORE'","Hechizo",[],["Jonia"],"ÉPICA"],"03IO018":["Guardián peludo","Cuando cuento con apoyo, recibo +0|+3 esta ronda.\nApoyo: Concede +3|+0 al aliado al que apoyo.","","Las hadas púrpura son criaturillas tan dulces que cualquiera que se las encuentre cuida de ellas. Bueno, casi cualquiera.","Unidad",["YORDLE"],["Jonia"],"RARA"],"03DE008":["Teniente de la Guardia de dragones","Cuando se me invoca, si una carta dragón es visible, consigo Contendiente.","","\"Cuando perdí a mis compañeros de batalla en Wrenwall, creí que también había perdido mi determinación... pero resulta que no hay nada que una lucha no pueda suscitar en antiguos soldados\".","Unidad",[],["Demacia"],"COMÚN"],"03DE001":["Confrontación","Otorga Contendiente a un aliado.\nSi es un dragón, roba 1.","","\"¡Que nadie se nos escape!\". - Shyvana","Hechizo",[],["Demacia"],"COMÚN"],"03DE015":["Supresión pétrea","TODOS los hechizos cuestan 1 más.","","Lo que empieza siendo un tosco bloque amorfo de petricita enseguida coge forma entre las hábiles manos de su escultor. Es en ese momento cuando una obra comienza a cobrar vida.","Unidad",[],["Demacia"],"RARA"],"03DE006":["Dragón chirriante","","","Todas las criaturas del mundo protegen a sus crías con fiereza, pero muy pocas disponen de tantas herramientas para ello como los dragones.","Unidad",["DRAGÓN"],["Demacia"],"COMÚN"],"03DE025":["Aliento de lava","Un aliado con Furia golpea a los 2 enemigos más débiles, primero a uno y después al otro.","","Durante siglos, los demacianos solo habían vivido la furia de los dragones a través de las leyendas. Después de Wrenwall, todo cambió.","Hechizo",["ELEMENTAL"],["Demacia"],"RARA"],"03DE002":["Ráfaga aérea","Un aliado y un enemigo se golpean el uno al otro. Después, si el aliado es un dragón, lo cura 5 de vida.","","Cuando caballero y dragón se separaron, temblorosos y heridos, el último pareció cobrar fuerza. Olía la sangre y sentía sed de más.","Hechizo",[],["Demacia"],"RARA"],"03DE011":["Shyvana","Atacar: Consigo +1|+1 esta ronda.","Los dragones aliados han infligido 16 o más de daño.","\"Por un lado, su naturaleza la convierte en nuestro peor enemigo, pues históricamente los suyos solo han procurado angustia a Demacia. Pero por otro, se ha ganado la confianza del príncipe y ha demostrado tener lo necesario para ser una soldado resoluta y una valiosa aliada. Lo único que espero es que no traicione la confianza que hemos depositado en ella\".\n- Hoja del informe del teniente Jerik en Wrenwall","Unidad",["DRAGÓN"],["Demacia"],"Campeón"],"03DE003":["Centinela de la Guardia de dragones","Cuando se me invoca, si una carta dragón es visible, prepara el ataque.","","\"¡Allí a lo lejos! ¿Es eso un...?\".\n\"Eso parece\".\n\"¿Cómo puedes saberlo con certeza?\".\n\"No hay forma de confundirlos. Tápate las orejas. El estruendo va a ser fuerte\". - Anden y Yessenia","Unidad",[],["Demacia"],"RARA"],"03DE013":["Madre al acecho","","","\"¡Cuidado, soldados! Si vigilamos dónde pisamos y no tocamos el nido, la madre dragón no se pondrá agresiva. Pero si la molestamos un poco más... Espero que estéis en forma para salir por patas\". - Anden Mayne, investigador de Huevotesta","Unidad",["DRAGÓN"],["Demacia"],"COMÚN"],"03DE005":["Investigador de Huevotesta","Cuando se me invoca, crea un dragón aleatorio en la mano.","","Huevo de dragón (Dragón chirriante, Draco murmurationis) \nLocalización: Rescatado por el investigador Anden Mayne en una expedición. \nNotas: Periodo de gestación desconocido. Se observa movimiento en el interior de la cáscara. El huevo reacciona al calor, la luz y el martillo. Los estudios actuales no son concluyentes. \n- Notas de Anden Mayne, investigador de Huevotesta","Unidad",[],["Demacia"],"COMÚN"],"03DE007":["Kadregrin, el Infernal","Cuando se me invoca, otorga a otros dragones aliados +4|+4 estén donde estén.","","Cuando Demacia sufrió una oleada repentina de ataques de dragones, Shyvana sabía que Kadregrin el Infernal estaba detrás. Otros dragones, inspirándose en su carácter audaz y su poderosa llama, aterrorizaron a los demacianos. ","Unidad",["DRAGÓN"],["Demacia"],"ÉPICA"],"03DE012":["Por los caídos","Cuando invocas a una unidad Élite, mi coste se reduce en 1.\nPor cada aliado que haya muerto esta ronda, invoca 1 Vanguardia Impertérrita.","","''Si un soldado cae, otro deberá ocupar su lugar. Nuestro estandarte ha de permanecer en alto''. - Garen","Hechizo",[],["Demacia"],"ÉPICA"],"03DE014":["Visión aguda","Concede +1|+2 y Visión aguda a un aliado esta ronda.","","Todo aquel que ose rebasar las fronteras de Demacia se encontrará con una compañía entera prevenida y armada hasta arriba.","Hechizo",[],["Demacia"],"COMÚN"],"03FR020":["La Terratriz","Cuando un aliado sobrevive al daño, le otorga +1|+0 y Aguante.","","En la Garra Invernal, hay muchos lugares de honor, pero uno de los más importantes es la Terratriz, un rincón en el que las naves de guerra que regresan de incursiones tras haber sufrido daños se modifican para convertirlas en lugares de reunión para los guerreros y sus familiares. Estas embarcaciones representan a la tribu que las construyó, pues son resistentes y versátiles.","Hito",[],["Freljord"],"ÉPICA"],"03FR007":["Carroñero trol","Cuando se me invoca, si una carta de 8 o más de coste es visible, obtengo +3|+0.","","El explorador se agachó de rodillas junto a un deshilachado trozo de tela oculto entre la nieve. El olor a sudor humano y a humo de una hoguera aún flotaba en el gélido aire.\nTiró del material y observó el talismán que colgaba de una esquina, sin brillo bajo el cielo tormentoso. Avarosanos. ","Unidad",[],["Freljord"],"COMÚN"],"03FR004":["Rugido revitalizante","Elige una unidad de la mano para revelarla. Cura a tu nexo una cantidad equivalente a su poder.\nIluminación: Reduce su coste a 0.","","''Los troles adultos tienen pelajes gruesos y huesos densos que se regeneran con rapidez, lo que los convierte en temibles adversarios. Acabad con ellos rápido o se recuperarán y volverán al combate''. - Tirador avarosano","Hechizo",[],["Freljord"],"RARA"],"03FR017":["Oráculo de los ancianos","Jugar: Si una carta de 8 o más de coste es visible, otorga Abrumar y Regeneración a un aliado.","","Según dicen, muy pocos troles aprenden los cantos de los antiguos, pero aquellos que los saben pueden invocar a sus antepasados para hacer que su grupo goce de una fuerza extraordinaria.","Unidad",[],["Freljord"],"RARA"],"03FR006":["Trundle","Cuando se me invoca, crea 1 Pilar de hielo en la mano.","Te he visto jugar Pilar de hielo.","Una a una, las antorchas del pasadizo se encendieron y revelaron el entorno. Había decenas y decenas de troles, quizá cientos, y cada uno de ellos era tan inmenso como letal.\n\"Os lo pediré una vez más,\" gruñó Trundle a la par que se apoyaba a Escalofrío sobre el hombro. \"¿Os dais por vencido o queréis que os aplastemos el cráneo?\".","Unidad",[],["Freljord"],"Campeón"],"03FR008":["Alud helado ","Concede -3|-0 a TODAS las unidades esta ronda. Inflige 3 de daño a TODAS las unidades.","","''¡Enterradlos en vida!''. - Trundle","Hechizo",["ELEMENTAL"],["Freljord"],"ÉPICA"],"03FR002":["Cántico de trol","Concede +0|+2 a un aliado y -2|-0 a un enemigo esta ronda.","","Los troles cuentan con cantos muy variados. Cada grupo tiene los suyos, y muchas veces resultan incomprensibles. Eso sí, presenciar uno de ellos es una experiencia escalofriante. ","Hechizo",[],["Freljord"],"COMÚN"],"03FR011":["Uzgar, el Anciano","","","Lo sintieron antes de escuchar nada, pues el suelo comenzó a temblar bajo sus pies. Pronto se volvió audible, como un trueno distante que se acercaba cada vez más.\nMeyrick alzó la cabeza con los ojos muy abiertos y escuchó.\n\"¿Qué es eso?\", susurró Anya con urgencia al tiempo que tensaba su arco. Pero Meyrick ya había echado a correr hacia el camino.\n\"¡Corre!\".","Unidad",[],["Freljord"],"RARA"],"03FR005":["Saqueadora trol","Cuando se me invoca, si una carta de 8 o más de coste es visible, obtengo Regeneración.","","Una vez se vieron entre cabañas avarosanas, llamaron a Hgar. Con una carcajada, ella alzó a Garranevada y se preparó para reducir los hogares de madera a pilas de astillas.","Unidad",[],["Freljord"],"COMÚN"],"03FR018":["Llamada a lo salvaje","Roba todos los yetis, poros y elnuks de las primeras 4 cartas del mazo. Después, coloca el resto en tu mazo.","","''... y entonces un elnuk enorme salió volando de entre los árboles con un poro diminuto a lomos, y había también un simpático yeti que quería jugar con sus amigos y todos bajaron corriendo por la montaña gritando '¡Raaaaaaaar!' y entonces...''. - Ingvar, la Joven","Hechizo",[],["Freljord"],"COMÚN"],"03FR010":["Rostros de los ancianos","Comienzo de ronda: Si una carta de 8 o más de coste es visible, obtienes una gema de maná adicional esta ronda.","","''Alzaos, antiguos, alzaos.\nGobernad el hielo. Quebrad el cielo.\nAlzaos, antiguos, alzaos.\nDadnos fuerzas para enterrar cabezas''.\n- Canto trol","Unidad",[],["Freljord"],"COMÚN"],"03FR019":["Voces de los ancianos","Obtén 2 gemas de maná vacías.\nRoba todas las unidades de coste 8 o superior que haya en las primeras 5 cartas de tu mazo. Después, coloca el resto en tu mazo.","","Durante generaciones, los pobladores avarosanos oían sonidos extraños e inexplicables entre el tumulto de las tempestades invernales. Finalmente, cuando se atrevieron a desplazarse mucho más al norte, descubrieron la fuente de estos sonidos: eran antiguos monolitos de los troles que emitían susurros en lenguas olvidadas cuando el viento barría sus amplias cavidades.","Hechizo",[],["Freljord"],"COMÚN"],"03FR025":["Dones de trol","Otorga a un aliado Regeneración o +2|+2 si ya la tiene.","","Compadeced a quienes ven la victoria en la sangre de un trol.","Hechizo",[],["Freljord"],"RARA"],"03FR022":["Subidón","Invoca 2 campeones aleatorios diferentes de tu mano y tu mazo. Mejora sus estadísticas hasta 10|10.","","\"We got it all in our hands now\nSo can you handle what we're all about?\".\n- Ahri, 'POP/STARS'","Hechizo",[],["Freljord"],"ÉPICA"],"04PZ001":["Ekko","Golpear: Crea 1 Truco temporal Fugaz en la mano.","Has activado Predicción 4 veces o más. Cuando subo de nivel, crea 3 Fisuras temporales en el mazo.","La clave no es el tiempo que tengas, sino en qué lo inviertes.","Unidad",[],["Piltover y Zaun"],"Campeón"],"04PZ005":["Quíreo del Sumidero","Cuando invocas otra copia de Quíreo del Sumidero, me destruyes y todos los Quíreos del sumidero aliados, estén donde estén, se transforman en Pandillas del Sumidero.","","Los primeros mineros zaunitas que descubrieron a los quíreos pensaron que eran criaturas tímidas y sencillas. Con los años, sin embargo, se fueron acomodando a los humanos y revelaron los fuertes lazos que conectan sus grupos sociales, así como su afinidad innata con la tecnología.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"04PZ014":["Arranque productivo","Para jugar esta carta, gasta todo el maná. Invoca torretas aleatorias cuyo coste combinado equivalga a la cantidad de maná gastada.","","\"¿Cómo que te faltan recursos? El primer dispositivo mecánico que construí lo hice a partir de piezas de relojería desechadas y un condensador térmico oxidado. ¡Hay que apañárselas con lo que se tiene a mano!\". - Heimerdinger","Hechizo",[],["Piltover y Zaun"],"RARA"],"04PZ003":["Engranaje temporal","Para jugar esta carta, descarta 1.\nInflige 1 de daño a un enemigo o al nexo enemigo y 1 a otro.","","\"¡Cuidado!\". - Ekko","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"04PZ011":["Golpe anunciado","Roba 1.\nCrea 1 Convergencia paralela en tu mazo.","","\"Dividiendo líneas temporales...\". - Ekko","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"04PZ002":["Felino caído","Cuando se me invoca, se crea 1 Cristal de hexita entre las 10 cartas de abajo de tu mazo.","","\"¡PERO MI PLAN...! ¡MIAAAU!\".","Unidad",["GATO"],["Piltover y Zaun"],"RARA"],"04PZ020":["Cambiabot defectuoso","Jugar: Intercambia mis estadísticas con las de otra unidad.","","\"¿Un nuevo robot tragaperras? ¿No habían cerrado la fábrica que los producía hace años?\".\n\"Eso creía. He oído por ahí mencionar 'bombas rodantes' e 'incendios accidentales'\".\n\"Vaya\".\n\"¿... Jugamos?\".\n\"Por supuesto\".\n- Mecenas zaunitas","Unidad",[],["Piltover y Zaun"],"RARA"],"04PZ013":["Elnuk voluntario","Cuando se me invoca, se crea un elnuk aleatorio entre las 6 cartas de arriba del mazo.","","\"BUENO, PEQUEÑÍN, ESPERA AHÍ UN SEGUNDO MIENTRAS LE DOY A ESE INTERRUPTOR, ¡Y PAM! ¡JA! ¡ELNUKS POR TODAS PARTES! Nos va a hacer falta un buen pasto, la verdad. Y mucho más espacio\". - Perfeccionista práctica","Unidad",["ELNUK"],["Piltover y Zaun"],"RARA"],"04PZ010":["Realidades simultáneas","Otorga a los adeptos en tu mano \"Cuando me juegas, elige 1 de otros 3 adeptos con mi coste y transfórmame en ese adepto\".","","\"Aquí las reglas las pongo yo\". - Ekko","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"04PZ016":["Babuino explosivo","Cuando se me invoca, crea 1 ¡Mascafuegos! en la mano.","","Hace tiempo, Jinx contaba con un proveedor más convencional, pero tuvieron un pequeño problemilla: el saqueador se cayó por la ventana. Bueno, o puede que lo empujara una explosión. Una explosión provocada por Jinx.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"04PZ007":["Truco temporal","Activa Predicción y, después, roba 1 carta.","","\"El futuro es lo que yo decida...\". - Ekko","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"04PZ012":["Perfeccionista práctica","Jugar: Activa Predicción. Crea 3 copias de la carta elegida en el mazo.","","\"Kay mola mogollón. Tiene esa mentalidad de 'La práctica hace al maestro', y la verdad es que no para de practicar\".\n- Shomi","Unidad",[],["Piltover y Zaun"],"RARA"],"04PZ017":["Gloriosa evolución","Tus cartas cuestan 1 menos, tienen Mejora, son creaciones de Gloriosa evolución y son unidades Tecnológicas.","","\"El progreso lo es todo. Traeré el futuro a esta ciudad, independientemente de si está o no preparada para él\".\n- Viktor","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"04PZ015":["Adaptatrón 3000","Cuando invocas a una unidad Tecnológica, compartimos palabras clave.","","\"¡Anda, claro! ¡El Adaptatrón 3000! ¡Un diseño flexible, innovador y con un aspecto inmejorable! Si pudiera hablar, seguro que tendríamos mucho que comentar\".\n- Heimerdinger","Unidad",["TECNOLOGÍA"],["Piltover y Zaun"],"ÉPICA"],"04PZ004":["Abordatableros","Si aparezco al activar Predicción, se me invoca.","","\"Ay, no hay nadie como Shomi con los deslizadores. Una vez, pasó de un picado 360º a un deslizamiento trasero, ¡y después hizo un triple tirabuzón aéreo! O algo así, vaya. La cosa es que mola un montón, ¿vale?\". - Perfeccionista práctica","Unidad",[],["Piltover y Zaun"],"COMÚN"],"04BW002":["Espetón de huesos","Un aliado golpea a un enemigo y después pasa a la parte de arriba de tu mazo.","","\"Un regalo de despedida...\". - Pyke","Hechizo",[],["Aguas Estancadas"],"ÉPICA"],"04BW007":["Trictux afilado","Jugar: Todos los aliados acechantes golpean a un enemigo aleatorio.","","\"No hay nada como un trictux afilado para ayudarte a descubrir en quién puedes confiar y a quién debes matar\".\n- Pyke","Unidad",["ACECHANTE"],["Aguas Estancadas"],"ÉPICA"],"04BW001":["Faucemartillo rosado","Jugar: Otorga Vulnerable a un enemigo.","","Cuando un faucemartillo destruye la quilla de un barco, parece que lo hace por puro disfrute. No suelen devorar a la tripulación; en su lugar, la dejan a la merced de las criaturas que llegarán después.","Unidad",["ACECHANTE"],["Aguas Estancadas"],"COMÚN"],"04BW005":["Pyke","Cuando acecho, me transformo en Muerte de las profundidades.","Los Pykes aliados han infligido 15 o más de daño.","\"Las visiones han vuelto. Veo su mirada desesperada mientras el trictux afilado lo engulle entre sus fauces. Intentamos sacarlo del agua, pero el barco era demasiado pequeño y la bestia, demasiado grande. No tenía elección. Tenía que cortar la cuerda\".\n- Carta empapada de sangre.","Unidad",["ACECHANTE"],["Aguas Estancadas"],"Campeón"],"04BW010":["Arpón para monstruos","Asalto: Mi coste se reduce 2.\nInflige 5 de daño a una unidad.","","\"¡Tenemos a la bestia atravesada, camaradas! Ahora, ¡a seguir dándole hasta que deje de moverse y las aguas se tiñan de rojo!\". - Matarife","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"04BW014":["¡Preparadlos!","Invoca 1 Barril de pólvora.\nCrea 1 Derribadlos en la mano.","","\"Ya está hecho, capitán. Con una pequeña chispa, quedará liquidada\". - Grumete del Heraldo","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"04BW011":["Dado trucado","En la siguiente ronda, birla 1 cuando inflijas daño al nexo enemigo.","","\"Bueno, camarada, ¿qué estás dispuesto a jugarte?\". - Tahm Kench","Hechizo",[],["Aguas Estancadas"],"ÉPICA"],"04BW015":["Cría de tiburón","","","\"Puede que no parezcan gran cosa, pero están sedientos de sangre. Si los dejas acercarse, te buscarán en cuanto crezcan. Mejor que uses guantes\". - Navío cazamonstruos","Unidad",["ACECHANTE"],["Aguas Estancadas"],"COMÚN"],"04BW003":["Cardumen carnicero","Jugar: Comienzo un ataque gratis.","","\"Ploc, ploc; gota a gota la sangre se derrama;\nnada que te nada, a saciar su hambre llega la plaga.\nTris, tras, sus fauces no descansa y el miedo nos alcanza;\na sumirse en las profundidades, que de ahí no se vuelve\".\n- Rima infantil de Aguas Estancadas","Unidad",["ACECHANTE"],["Aguas Estancadas"],"COMÚN"],"04BW009":["Bahía del Destripador","Cuando atacan los aliados, antes de activar Acechar, otorga Acechar al aliado de más arriba del mazo y se convierte en acechante.","","Las calas más traicioneras de toda Aguas Estancadas no tardaron en convertirse en el hogar de todo tipo de bestias marinas. Ahora descansan ahí, esperando a la próxima tripulación de incautos que ignore las advertencias del supervisor del puerto.","Hito",[],["Aguas Estancadas"],"RARA"],"04BW008":["Fortuna perdida","Roba un Tesoro. Si no tienes ninguno para robar, crea 2 Tesoros en el mazo.","","\"¡Somos ricos!\". - Carnicero abrupto","Hechizo",[],["Aguas Estancadas"],"RARA"],"04BW013":["Mandato del segador","Cuando mi Cuenta atrás avanza, invoca un adepto aleatorio de coste 1.\nCuenta atrás - 2: Otorga +2|+1 y Temible a todos los aliados de coste 1.","","\"¿Así que crees tener lo que hay que tener para hacerte llamar Garfio? Ya veremos, truhan. Cuando hayamos acabado contigo, sabremos si vales tu peso en oro o si te hundirás bajo las olas. ¡Serías el cebo perfecto para las bestias!\". - Suboficial","Hito",[],["Aguas Estancadas"],"RARA"],"04BW004":["Cebo de sangre","Crea 1 Cardumen carnicero en la parte superior del mazo.","","\"Si pudiera elegir, preferiría que me devorara un trictux afilado antes que esas aberraciones. Prefiero morirme pronto que agonizar a voces delante de mis compañeros\".\n- Carnicero abrupto","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"04BW016":["Rex arruinado","Jugar: Lanza Andanada de cañón a un enemigo seleccionado de forma aleatoria por cada carta que hayas robado esta ronda (hasta un máximo de 6 veces).","","\"¿... Rex?\". - Suboficial","Unidad",[],["Aguas Estancadas"],"RARA"],"04BW006":["La lista","Aplica Vulnerable a un enemigo. Si ya es Vulnerable, el aliado más fuerte comienza un ataque gratis al desafiarlo con Contendiente.","","\"Tú tienes un nombre, yo tengo una lista\". - Pyke","Hechizo",[],["Aguas Estancadas"],"RARA"],"04IO008":["Danza desafiante","Aplica Retirada a una unidad.\nActiva 1 Danza de las cuchillas.","","\"¡Retiraos! Es hora de despejar el escenario para el próximo número\". - Zinneia, el Crescendo del Acero","Hechizo",[],["Jonia"],"COMÚN"],"04IO005":["Irelia","Cuando se me invoca o al comienzo de ronda: Si tienes la ficha de ataque, crea 1 Dúo impecable en la mano.","Has atacado con 14 o más aliados.","\"Antes estudiábamos el arte y la belleza, y nuestras almas volaban con libertad. Pero quebraron nuestras murallas y derramaron nuestra sangre, así que tuvimos que anclarnos a la tierra...\".","Unidad",[],["Jonia"],"Campeón"],"04IO020":["Cúmulo disperso","Jugar: Roba 1 hechizo lento, veloz o una ráfaga de hechizos.\nIluminación: Tengo Elusión.","","Las canciones celestiales de los surcanubes, extrañas, hermosas e hipnóticas, consiguieron mantener la Niebla Negra a raya... pero no durante mucho tiempo.","Unidad",[],["Jonia"],"RARA"],"04IO004":["Filo en flor","Jugar: Activa 2 Danzas de las cuchillas.","","\"Los hay que consideran que las flores son algo frágil, delicado. Se olvidan de la fuerza necesaria para aferrarse a la tierra y transmitir esperanza con cada florecer\".\n- Zinneia, el Crescendo del Acero","Unidad",[],["Jonia"],"COMÚN"],"04IO003":["Filo de la vanguardia","Elige un aliado para que ataque junto a Cuchillas y después activa 3 Danzas de las cuchillas.","","\"¡Frenad su retirada! Los noxianos comenzaron esta guerra, pero nosotros le pondremos fin\". - Irelia","Hechizo",[],["Jonia"],"RARA"],"04IO015":["Gota danzante","Cuando me retiro, roba 1 carta.","","\"El agua es flexible; se adapta. Adopta la forma necesaria en cada momento, ya sea fluyendo con libertad o retirándose de la costa\". - Monje jonio","Unidad",[],["Jonia"],"COMÚN"],"04IO014":["Aprendiz de la sombra","Cuando invocas a un aliado endeble, consigo +1|+0 esta ronda.","","\"Eres una voluta de humo, un susurro en el viento. Que tus puños se fundan con la oscuridad como la sombra se deshace en la penumbra. ¡Otra vez!\". - Maestra Shi","Unidad",[],["Jonia"],"COMÚN"],"04IO002":["Zinneia, el Crescendo del Acero","Cuando activas Danza de las cuchillas, ataco con Cuchillas.\nJugar: Activa 1 Danza de las cuchillas.","","\"Venid todos a mi lado. Hoy nos deslizaremos sobre la tierra que nos ha visto crecer con la técnica que nuestra familia nos ha enseñado. Somos hijos de Jonia, ¡y hoy danzamos por el arte, por la libertad y por cada uno de nosotros!\".","Unidad",[],["Jonia"],"ÉPICA"],"04IO007":["Síncopa","Intercambia a 2 aliados.","","\"Danzar es moverse en armonía con el resto de las cosas\".\n- Zinneia, el Crescendo del Acero","Hechizo",[],["Jonia"],"RARA"],"04IO011":["Marcando el ritmo","Retira a un aliado para crear 1 Dúo impecable en la mano.","","\"Les daremos un espectáculo inolvidable\". - Zinneia, el Crescendo del Acero","Hechizo",[],["Jonia"],"COMÚN"],"04IO013":["Protector sagrado","Jugar: Concede Barrera a un aliado esta ronda y roba 1 Shen.\nLos aliados con Barrera tienen Ataque doble.","","\"Igual que nosotros luchamos para proteger estas tierras, ellas mismas se alzan para defendernos a nosotros. Sacaremos fuerzas de la ira de Jonia para expulsar a nuestros enemigos. Y el equilibrio permanecerá intacto\". - Sacerdote jonio","Unidad",[],["Jonia"],"ÉPICA"],"04IO012":["Sombras del pasado","Retira a todos los aliados para invocar 1 Sombra viviente en lugar de cada aliado retirado.","","\"Golpearán a las sombras y sus filos se perderán en la oscuridad\". - Zed","Hechizo",[],["Jonia"],"RARA"],"04IO009":["Bailacintas","Jugar: Activa 1 Danza de las cuchillas.","","\"¡Qué lástima! Tanto poder y tan poco ritmo para acompañarlo. Supongo que no todos nacemos siendo estrellas...\".","Unidad",[],["Jonia"],"RARA"],"04IO001":["Músicos de combate","Cada ronda, después de que hayas invocado a otros 3 aliados, recarga el maná de hechizos y roba 1.","","Para algunos, la música ofrece abrigo ante la adversidad y la violencia. Para otros, es una herramienta de rebelión.","Unidad",[],["Jonia"],"ÉPICA"],"04IO006":["Defensor de la costa","Cuando invocas a otro aliado, consigo +2|+0 esta ronda.","","Mi querido Kay:\nHan llegado esta mañana... Una hilera de navíos ha quebrado el horizonte y oscurecido el amanecer. Sus invenciones han prendido fuego a las Llanuras de Plata, que ahora se ahogan en una densa cortina de humo. No podemos aguantar. Armados con rastrillos, palas, guadañas o espadas, hoy debemos enfrentarnos a nuestro destino. \nTe quiero más de lo que puedo expresar con palabras.\n- Carta chamuscada\n","Unidad",[],["Jonia"],"COMÚN"],"04SH100":["Plan cauteloso","Para jugar esta carta, coloca una carta de la mano en el mazo.\nActiva Predicción y, después, crea una copia exacta de la carta elegida en la mano.","","\"Las acciones de hoy plantan las semillas del mañana\". - Tai, cronomante en ciernes","Hechizo",[],["Shurima"],"COMÚN"],"04SH070":["Indigno","Concede -4|-0 a un adepto enemigo esta ronda.\nSi tienes menos gemas de maná que tu rival, este muere en su lugar.","","\"El sol volverá a iluminar las tierras shurimanas\". - Portavoz de los Alzados","Hechizo",[],["Shurima"],"ÉPICA"],"04SH081":["Tejedora de arena baccai","Jugar: Otorga -1|-0 y Vulnerable a un enemigo.","","Cada grano derramado les arranca un segundo de vida, y los va desgastando poco a poco como el viento.","Unidad",[],["Shurima"],"RARA"],"04SH077":["Portavoz de los Alzados","Si has subido de nivel a un campeón, los aliados tienen +2|+0.","","\"Hace tiempo, la vi hablar\". El viejo soldado sonrió y, durante un instante, su nieta fue capaz de imaginarse una Shurima áurea y resplandeciente, con Azir presidiéndola orgulloso y acompañado por la Portavoz de los Alzados. \"Despertó en nosotros una pasión que habíamos dado por perdida\".","Unidad",[],["Shurima"],"ÉPICA"],"04SH019":["Rek'Sai","Cuando activo Acechar o al atacar: Otorga +1|+0 a todos los aliados acechantes estén donde estén.\nFin de ronda: Me transporto al mazo.","He atacado con 10 o más de poder.","\"El joven Jhuraa estaba explorando, como siempre, ¡y descubrió unos textos antiguos en una pequeña cueva oculta! Se los llevamos a un traductor de Marrowmark y resulta que los pergaminos hablan de un terror ancestral que acechaba a generaciones pasadas. Una reina, ¡la reina de los xer'sai!\".\n- Fezhaur, anciano vekaurano","Unidad",["ACECHANTE"],["Shurima"],"Campeón"],"04SH138":["El Absolvedor","Concede +2|+1 a un aliado esta ronda. Si has subido de nivel a un campeón esta partida, crea 1 El regreso del Absolvedor en la mano.","","\"Todo el mundo me dijo que no utilizara esto. 'Nadie debería esgrimir un arma tan poderosa', decían\". - Akshan","Hechizo",[],["Shurima"],"COMÚN"],"04SH089":["Naturalista del desierto","Jugar: Destruye un hito. Si es aliado, invoca 1 Oso rocoso enfurruñado.","","\"¡Kadira se ha vuelto a cargar algo! Esta vez no fue más que una pared de piedra, pero parecía vieja y seguro que hace mucho tiempo alguien la consideró importante. Se excusó diciendo que las paredes de Tereshni son más resistentes, ¡pero ya le vale! Estoy muy cabreada\".\n- Diario de Zaifa","Unidad",[],["Shurima"],"RARA"],"04SH015":["Raz Crinsangrienta","Atacar: Concede -2|-0 a los enemigos esta ronda.","","\"Cuando nació este cocodrilo que tienes aquí delante, los demás hicieron apuestas para determinar cuánto aguantaría. Se creían que era el más debilucho de todos. Lo que nadie esperaba era que acabara merendándose a todos sus hermanos. Je\".","Unidad",[],["Shurima"],"ÉPICA"],"04SH058":["Esculpearenas","Atacar: Invoca 1 Soldado de arena en ataque.","","Muy pocos aprenden los secretos del desierto, y muchos menos gozan del poder de controlar las arenas como Azir. Ambos son regalos que el emperador solo comparte con sus seguidores más fieles y diestros.","Unidad",[],["Shurima"],"COMÚN"],"04SH080":["Llamada de la manada","Para jugar esta carta, coloca una carta de la mano en la parte de arriba del mazo.\nCrea 2 adeptos aleatorios acechantes en la mano.","","\"Que el sol brille y los xer'sai duerman\".\n- Oración de mercader","Hechizo",[],["Shurima"],"COMÚN"],"04SH035":["Día de paga","Crea 1 Hallazgo fortuito en la mano.","","\"He tenido días mejores y días peores, como todo el mundo. En esta profesión, en los peores días te juegas el cuello y en los mejores, te haces rica\". - Sivir","Hechizo",[],["Shurima"],"COMÚN"],"04SH028":["Planes ancestrales","Jugar: Activa Predicción.\nCuenta atrás - 2: Invoca 1 Relojizo.","","Aunque muchos consideran que se han perdido en el tiempo y han quedado enterrados bajo siglos de vaivén de las arenas, los autómatas se colocaron con gran precisión y aguardan a que alguien los despierte.","Hito",[],["Shurima"],"COMÚN"],"04SH054":["Buscatesoros","Cuando se me invoca, crea 1 Arenas despiertas en la mano.","","\"Vale, Davu: entras ahí, te llevas... la cosa esa, ¡y seremos ricos! Voy a ser rica. Me vas a hacer rica. ¿Lo pillas? Bueno, y si resulta que es una trampa, lo siento mucho por adelantado\".","Unidad",[],["Shurima"],"COMÚN"],"04SH002":["Segador baccai","Cuando asesinas a una unidad, consigo +1|+0.","","\"Tras la fallida Ascensión, los baccai huyeron en masa, y nadie los ha vuelto a ver desde entonces. ¿Quién sabe cuánto tiempo llevan escondidos en esas oscuras tumbas, ocultando su vergüenza?\". - Escriba Kah'Nir, Historia de la Hueste Ascendida","Unidad",[],["Shurima"],"RARA"],"04SH042":["Oso rocoso hibernando","Cuenta atrás - 3: Invoca 1 Oso rocoso enfurruñado.","","\"ME LLAMO ZAIFA Y ME GUSTA ESCRIBIR TONTERÍAS EN MI ESTÚPIDO DIARIO CUANDO CREO QUE LOS DEMÁS ESTÁN DORMIDOS, SAMI INCLUIDO\".\n- Diario de Zaifa","Hito",[],["Shurima"],"COMÚN"],"04SH032":["Aplastahuesos despiadada","Reputación: Cuesto 1 menos y, cuando se me invoca, consigo Abrumar.","","El soldado trató de aferrar su lanza, pero ella se apoyó con más fuerza sobre su pecho y se vio obligado a detenerse. \"No, no\", le reprochó ella al tiempo que le enseñaba los afilados colmillos con una sonrisa siniestra. \"Ahora esto me pertenece\".","Unidad",[],["Shurima"],"COMÚN"],"04SH055":["Navegaruinas","","","Antes de adentrarse en las cámaras, los mercenarios y saqueadores de tumbas de Shurima tuvieron que aprender a sobrevivir a las amenazas más directas del desierto. Lo primero, el sol abrasador. Lo segundo, el sinfín de matones sedientos de sangre.","Unidad",[],["Shurima"],"COMÚN"],"04SH039":["Zilean","Jugar: Crea 4 Bombas de relojería en tu mazo y después activa Predicción.","Te he visto destruir 2 o más Bombas de relojería aliados.","Con el paso de los años, Zilean fue construyendo una red de magos prometedores de diferentes épocas, todos ellos capaces de continuar con su labor si llegaba a darse lo impensable. Aunque era un mentor amable e inspirador, un dolor profundo le surcaba el ceño. Cuando buscaba la soledad, su mirada reflejaba un agotamiento que solo alguien que ha vivido varias vidas podría alcanzar a comprender.","Unidad",[],["Shurima"],"Campeón"],"04SH073":["Taliyah","Jugar: Invoca una copia idéntica de un hito aliado.","Has invocado 5 o más hitos.","\"El paso de los nómadas es siempre ligero, pues no se ve ralentizado por raíces del pasado. Su hogar espera siempre en el horizonte\".\n- Las sociedades de Shurima","Unidad",[],["Shurima"],"Campeón"],"04SH091":["Khahiri el Alumno","Cuando se me invoca, consigo +1|+1 si has realizado una Predicción esta partida.","","\"Recuerda lo aprendido\", dijo Zilean con un tono más gentil y solemne de lo habitual. \"¿Seguro que estás preparado?\".\nKhahiri le dedicó una sonrisa reconfortante a su mentor. \"Volveré pronto. Llevo años preparándome para este momento. Si no lo hago ahora, ¿cuándo?\".","Unidad",[],["Shurima"],"COMÚN"],"04SH024":["Torre de sal","Cuenta atrás - 2: Invoca 1 Oso rocoso enfurruñado. Después, si has invocado 4 o más hitos en esta partida, otorga +2|+2 al aliado más fuerte.","","Los salineros shurimanos no tardan en aprender qué depósitos deben recolectarse y a cuáles es mejor ni acercarse.","Hito",[],["Shurima"],"COMÚN"],"04SH003":["Azir","Cuando los aliados atacan, invoca 1 Soldado de arena en ataque.","Has invocado a 12 o más aliados o hitos.","\"Cuando Azir asumió el cargo de emperador de Shurima, lo hizo con ciega arrogancia. Llevaba mucho tiempo acumulando poder y planeando su Ascensión, y ahora ansiaba alzarse como gobernante no solo de Shurima, sino del mundo entero\". - Escriba Kah'Nir, Historia de la Hueste Ascendida","Unidad",["ASCENDIDO","AVE"],["Shurima"],"Campeón"],"04SH011":["Investigadoras de xenotipo","Cuando se me invoca, 3 aliados aleatorios de tu mazo obtienen +3|+3.","","El Vacío está lleno de sorpresas. Sigue creciendo cada día y buscando nuevas formas de infiltrarse en la torre, como si se tratara de la planta trepadora más letal nunca vista. Por este motivo, estudiarlo resulta complicado, pues la investigación requiere de expertas astutas e ingeniosas que sean capaces de comprender y anticipar sus avances.","Unidad",[],["Shurima"],"RARA"],"04SH130":["Akshan","Cuando se me invoca o al golpear: Invoca 1 Palacio del señor de la guerra o avanza su cuenta atrás 1 ronda.","La cuenta atrás de Palacio del señor de la guerra ha terminado. Cuando subo de nivel, crea 1 Alijo del señor de la guerra.","\"El código de los Centinelas parece estar repleto de complejas restricciones. Cosas como 'Nunca arrebates una vida en nombre de la venganza' y 'Lucha por el mundo, nunca por ti mismo'. Yo, personalmente...\".","Unidad",[],["Shurima"],"Campeón"],"04SH114":["Cólera del desierto","Otorga +1|+0 a tus Soldados de arena aliados estén donde estén.\nInvoca 2 Soldados de arena.","","No descansan. No dudan. No perdonan, no sienten, no ceden.","Hechizo",[],["Shurima"],"RARA"],"04SH067":["Renekton","Cuando desafío a un enemigo, consigo +2|+1 esta ronda.","He infligido 10 o más de daño.","\"No resultaría difícil olvidar que, tiempo atrás, fue humano, pues su nueva apariencia de cocodrilo encaja a la perfección con su desbocada sed de sangre...\". - Escriba Kah'Nir, Historia de la Hueste Ascendida","Unidad",["ASCENDIDO","REPTIL"],["Shurima"],"Campeón"],"04SH120":["Posibilidades concebidas","Crea un hito aleatorio con Cuenta atrás en la mano o avanza la cuenta atrás de todos tus hitos 1 ronda.","","\"El tiempo es efímero\". - Zilean","Hechizo",[],["Shurima"],"RARA"],"04SH119":["Ricochet","Reputación: Cuesto 3 menos.\nInflige 1 a un enemigo aleatorio o al nexo enemigo 5 veces.","","\"Puede que la cosa se complique\". - Sivir","Hechizo",[],["Shurima"],"COMÚN"],"04SH068":["Invocador de los xer'sai","Jugar: Activa Predicción.","","No todos los xer'sai nacen para destruir. Los hay que tienen la capacidad de invocar a sus semejantes con unos agudos alaridos que atraviesan tanto las arenas como los sentidos.","Unidad",["ACECHANTE"],["Shurima"],"COMÚN"],"04SH093":["Roca moldeada","Concede a un aliado +1|+1 esta ronda.\nSi has invocado un hito esta partida, le concede +2|+1 en su lugar.","","\"¡Nos defenderemos con la ayuda de estas tierras!\". - Taliyah","Hechizo",[],["Shurima"],"COMÚN"],"04SH079":["Arenas augurales","Utiliza Predicción.\nConcede -2|-0 a un enemigo esta ronda.","","\"He visto mi destino. Esta vez, nadie me detendrá\". - Azir","Hechizo",[],["Shurima"],"RARA"],"04SH038":["Saltarocas","Cuando se me invoca, invoca 1 Arenas turbulentas.","","\"¡Hoy comienza nuestro viaje a Nashramae! Sami ha decidido cruzar el Gran Sai antes de la próxima luna llena y la está liando mucho. No sabía que una simple tabla podría derrumbar una duna entera, ni Sami tampoco. No le ha pasado nada\".\n- Diario de Zaifa","Unidad",[],["Shurima"],"COMÚN"],"04SH104":["Conservacionista","Jugar: Avanza la cuenta atrás de un hito aliado 3 rondas.","","Cuando busca un instante de paz, Zilean regresa al último jardín de Icathia, tal y como lo recordaba.","Unidad",[],["Shurima"],"RARA"],"04SH128":["Vagabunda vekaurana","Cuando se me invoca, invoca 1 Palacio del señor de la guerra o avanza su cuenta atrás 2 rondas.","","Al ver a Akshan colgando bajo la ventana del cuarto piso, Najah maldijo por lo bajo. Ese maldito guaperas había llegado antes que ella. Otra vez. Pensó en qué debía decirle mientras jugueteaba con su daga. Quizás esta vez al fin le hiciera un poco de caso.","Unidad",[],["Shurima"],"COMÚN"],"04SH109":["Arena voraz","Concede -4|-0 a un enemigo o -1|-0 a 2 enemigos esta ronda. Desactiva sus palabras clave positivas esta ronda.","","En algunas zonas del desierto, las ruinas antiguas se han hundido en la arena y han creado agujeros en los que los viajeros más incautos encuentran su fin. ","Hechizo",["ELEMENTAL"],["Shurima"],"COMÚN"],"04SH043":["Arenas movedizas","Inflige 4 de daño a una unidad.\nInvoca 2 Soldados de arena.","","\"Adelante. Rodeadlos. No podrán contra estas tierras\". - Azir","Hechizo",[],["Shurima"],"RARA"],"04SH099":["¡Alzaos!","Invoca 1 Soldado de arena.\nCrea 1 ¡Alzaos! Fugaz en la mano.","","\"¡Se ha dado la orden!\". - Azir","Hechizo",[],["Shurima"],"RARA"],"04SH048":["Santuario interior","Reputación: Cuesto 3 menos.\nCuenta atrás - 1: Crea 2 Hallazgos fortuitos en la mano.","","\"Algunos mapas tardan años en descifrarse. Ciertas trampas precisan de meses para desarmarse. Hay cámaras cuya exploración requiere semanas... Pero conseguirlo hace que cada segundo haya merecido la pena\". - Sivir","Hito",[],["Shurima"],"COMÚN"],"04SH056":["Usurera","Cuando se me invoca, crea 1 Hallazgo fortuito en la mano.","","\"Solo para ti, he recuperado esta incomparable maravilla de la mismísima Tumba de los Emperadores. El gran Renekton la aferraba entre sus garras. Cuando me iba, me vi rodeado por diez... no, ¡veinte jinetes de saurios, todos sedientos de sangre! Es un milagro que haya conseguido hacértela llegar, camarada\".","Unidad",[],["Shurima"],"COMÚN"],"04SH020":["Sivir","","Has infligido 30 o más de daño.","Sivir se gana la vida como mercenaria y ha tenido que aceptar tanto los riesgos como las recompensas que acarrea esa elección. Una vez, se embarcó en una catastrófica expedición que estuvo a punto de costarle la vida, pero, mientras su sangre se derramaba sobre la arena shurimana, consiguió despertar un poder ancestral que las llevaría a ella y a su patria a la grandeza.","Unidad",[],["Shurima"],"Campeón"],"04SH057":["Mariscal alentadora","Cuando invocas a otro aliado, obtiene +2|+0 esta ronda.","","Recibir la bendición de Azir es un gran honor, pero otorgar una bendición en su nombre es una maravilla aún mayor.","Unidad",[],["Shurima"],"RARA"],"04SH103":["Cazadora despiadada","Jugar: Otorga Vulnerable a un enemigo.","","\"Ya está. Bien sujeto y preparado. A Renekton le gusta que su comida aún se retuerza en el plato\".","Unidad",[],["Shurima"],"COMÚN"],"04SH065":["Xerxa'Reth, el Titán de las Profundidades","Ataque: Si tengo 8 o más de poder, recibo Temible, Abrumar y Escudo de hechizos esta ronda.","","\"Cuenta la leyenda que, hace cientos de años, a orillas del río Khaleek descansaba una gran ciudad comercial conocida como Taraleek. Hasta que, un terrible día, una bestia inmunda atravesó la tierra y acabó con el asentamiento y con todos aquellos que lo llamaban hogar. Pero ¿qué clase de monstruo podría cometer semejante atrocidad?\". - Historiador shurimano","Unidad",["ACECHANTE"],["Shurima"],"ÉPICA"],"04SH034":["Mano del Reloj","Cuando se me invoca, se crean 2 Siglos instantáneos en la mano.","","El ronroneo constante que invade los pisos más bajos de la torre se debe a la Mano del Reloj, el guardián del edificio, que se encarga de dar cuerda con regularidad a los engranajes del sótano.","Unidad",[],["Shurima"],"ÉPICA"],"04SH082":["Sendero de ruina","Roba 1.\nSi has asesinado a una unidad esta ronda, drena 2 de vida del nexo enemigo.","","Los asolaarenas reclutan principalmente de entre las filas enemigas. Los que sobrevivan a su asalto inicial tienen que elegir: unirse a ellos o morir.","Hechizo",[],["Shurima"],"RARA"],"04SH075":["Falange imperial","Aplica Vulnerable a los enemigos esta ronda e invoca 6 Soldados de arena.","","\"Mis soldados no se detienen\". - Azir","Hechizo",[],["Shurima"],"ÉPICA"],"04SH018":["Ritual de dominio","Mata a un aliado o destruye una de tus gemas de maná para aplicar -2|-0 a todos los enemigos esta ronda.","","\"¡Nosotros luchamos, ellos sangran!\". - Renekton","Hechizo",[],["Shurima"],"RARA"],"04SH009":["Baccai desbocado","Jugar: Si has asesinado a 4 o más unidades esta partida, un enemigo y yo nos golpeamos el uno al otro.","","El resentimiento de los rencorosos es cada vez más intenso, a pesar de que los responsables de su agravio lleven mucho tiempo muertos.","Unidad",[],["Shurima"],"RARA"],"04SH049":["Poro predestinado","Comienzo de ronda: Si ya has conseguido que un campeón suba de nivel, me transformo en Poro eminente.","","No sabía con exactitud lo que acababa de encontrarse, pero brillaba con fuerza y tenía pinta apetitosa.","Unidad",["PORO"],["Shurima"],"COMÚN"],"04SH045":["Extenuación","Concede -2|-0 y Vulnerable a un enemigo esta ronda.","","Los moradores del desierto saben cómo resguardarse del sol abrasador y el calor asfixiante, pero aquellos que no vengan preparados verán que pronto se quedan sin fuerzas.","Hechizo",[],["Shurima"],"COMÚN"],"04SH037":["Tierra comprometida","Invoca 2 Arenas turbulentas.\nRoba 1.","","El Gran Sai es un lugar hermoso, pero no es para los débiles. Miles de vidas han quedado sepultadas entre sus dunas. Los xer'sai se llevan su parte, pero las arenas también cobran en sangre.","Hechizo",["ELEMENTAL"],["Shurima"],"RARA"],"04SH107":["Auge de los Ascendidos","Todos los aliados Ascendidos de nivel 1 suben de nivel.","","\"¡Los Ascendidos escribirán el porvenir!\". - Azir","Hechizo",[],["Shurima"],"ÉPICA"],"04SH047":["Nasus","Tengo +1|+1 por cada unidad que hayas asesinado esta partida.","He golpeado con 10 o más de daño en un solo golpe.","\"La bendición que acababa de obtener permitiría a Nasus pasarse un sinfín de vidas estudiando y observando la naturaleza de la vida y la muerte. Sin embargo, todos esos años de vida adicionales acabarían por convertirse también en una maldición tras la caída de Shurima\". - Escriba Kah'Nir, Historia de la Hueste Ascendida","Unidad",["ASCENDIDO","PERRO"],["Shurima"],"Campeón"],"04SH097":["Procuradora del santuario","Jugar: Mata a un adepto enemigo. Si has asesinado a 13 o más unidades esta partida, mata a todos los adeptos enemigos y después invoca una copia de mí.","","Los baccai se encargan de defender el santuario interno y de proteger los tesoros ancestrales que descansan en su interior. También mantienen a raya a los mortales que se creen lo suficientemente astutos o poderosos como para aguantar el peso del juicio de la Procuradora.","Unidad",[],["Shurima"],"ÉPICA"],"04SH026":["Guardián de las dunas","Cuando se me invoca, invoca 1 Soldado de arena.","","\"Tanto las arenas como yo obedecemos las órdenes del emperador\".","Unidad",[],["Shurima"],"COMÚN"],"04SH102":["Embajadora áurea","Alianza: Roba un campeón y le otorga +2|+2.","","\"Nuestro resplandeciente futuro aguarda bajo las arenas, y abrir paso para Azir queda en nuestras manos. ¡El áureo imperio del desierto se alzará de nuevo!\".","Unidad",[],["Shurima"],"COMÚN"],"04SH001":["Cronomante en ciernes","Jugar: Activa Predicción.","","Durante el tiempo que pasó estudiando la cronomancia, Tai se vio obligado a reconciliar sus dudas con su determinación. Es mejor dejarse llevar por la esperanza que quedarse meditando todas las cosas que podrían salir mal.","Unidad",[],["Shurima"],"COMÚN"],"04SH022":["Quiebradunas de los xer'sai","","","Todos los xer'sai son diestros a la hora de excavar túneles, pero solo los quiebradunas disponen de la masa y la potencia necesarias para atravesar las venas de roca que recorren el Gran Sai y adentrarse en tierras lejanas para continuar su cacería.","Unidad",["ACECHANTE"],["Shurima"],"RARA"],"04SH030":["Alteración del tiempo","Concede a un campeón aliado \"La próxima vez que vaya a morir esta ronda, recupero toda la vida y consigo +3|+3 en su lugar\".","","\"No podemos detener lo inevitable, pero sí posponerlo\".\n- Zilean","Hechizo",[],["Shurima"],"RARA"],"04SH013":["Cámara de conservación","Cuando se me invoca, roba 1 carta.\nCuenta atrás - 2: Roba 1 carta.","","Zilean enseña a quienes lleva a la torre lo que se proponen restaurar. Poco a poco, el Conservador les revela todo lo que puede.","Hito",[],["Shurima"],"RARA"],"04SH062":["Disco solar enterrado","Comienzo de la partida: Invoca 1 copia de mí de tu mazo si es entero de Shurima. Cuenta atrás - 25: Restaura el disco solar. Avanzo 9 rondas cada vez que un aliado Ascendido sube de nivel en la partida.","","Cuando Azir contempló el disco solar de la capital shurimana, no vio lo que era, sino lo que podría llegar a ser: la clave para recuperar la gloria pasada del imperio.","Hito",[],["Shurima"],"ÉPICA"],"04SH016":["Golpe absorbente","Un aliado golpea a una unidad.\nSi muere, los campeones aliados obtienen +2|+2 estén donde estén.","","\"Mediré tu alma\". - Nasus","Hechizo",[],["Shurima"],"RARA"],"04SH125":["Abrecámaras vekaurana","Jugar: Otorga +2|+0 a un aliado y aplica -2|-0 a un enemigo esta ronda.","","Tena esperaba pacientemente mientras la saliva cáustica de su mascota iba desgastando poco a poco los barrotes dorados de la puerta trasera del palacio. Pronto se encontraría un enorme alijo de tesoros de un valor incalculable a la vuelta de la esquina... Más que suficiente para recuperar la gloria pasada de Vekaura\".","Unidad",[],["Shurima"],"RARA"],"04SH108":["Cuchilla bumerán","Un aliado golpea al enemigo más fuerte y al más débil, primero a uno y después al otro.","","\"¡Yo de ti me agacharía!\". - Sivir","Hechizo",[],["Shurima"],"RARA"],"04SH066":["Tiempo embotellado","Activa Predicción y avanza la cuenta atrás de un hito aliado 2 rondas.","","\"Si vierais el tiempo como lo veo yo, os daríais cuenta de que nada es inevitable\". - Zilean","Hechizo",[],["Shurima"],"COMÚN"],"04SH021":["Khahiri el Regresado","Cuando se me invoca, crea una copia de mí en tu mazo. Cuando me ves en una Predicción, otorga +2|+2 a todas las copias de mí aliadas estén donde estén.","","Khahiri desapareció durante un solo instante antes de materializarse de nuevo. Había envejecido casi una década y esgrimía un arma con aspecto letal. Los demás lo recibieron con una mezcla de asombro y preocupación.","Unidad",[],["Shurima"],"RARA"],"04SH101":["Consejo fiel","Comienzo de ronda: Si has subido de nivel a un campeón, tus campeones y tu nexo se curan 2 de vida.","","\"¡He jurado lealtad a Azir y a Shurima, mi hogar! Y tú, ¿seguirás mis pasos?\".","Unidad",[],["Shurima"],"RARA"],"04SH012":["Hierofante estimado","Cuando se me invoca, tu Disco solar enterrado avanza 3 rondas.","","\"¡Ah! ¡Pero si es Padjuman, uno de los ancianos de Nashramae! ¡Parece que hoy todo el mundo ha venido a la ciudad, papá!\". - Espectadora entusiasmada","Unidad",[],["Shurima"],"COMÚN"],"04SH031":["Futuro prometedor","Otorga a un hito aliado \"Mi efecto al completar la cuenta atrás se activa dos veces\".","","\"Los mortales pasan gran parte de su tiempo esperando. Ojalá se vean recompensados por su inagotable paciencia\". - Zilean","Hechizo",[],["Shurima"],"ÉPICA"],"04SH004":["Pesaje del juicio","Inflige 2 de daño a un campeón o 4 a un adepto.","","\"Una vida a cambio de tantas... Una sola vida para que las demás puedan prosperar\". - Nasus","Hechizo",[],["Shurima"],"COMÚN"],"04SH059":["Ritual de negación","Mata a un aliado o destruye una de tus gemas de maná para detener todos los hechizos veloces, lentos y las habilidades enemigas.","","El análisis es uno de los pilares de la cronomancia, pues con frecuencia es necesario detenerse a considerar soluciones futuras.","Hechizo",[],["Shurima"],"ÉPICA"],"04SH044":["Conservador mecánico","Jugar: Avanza la cuenta atrás de un hito aliado 2 rondas.","","Los guardianes de la torre de Zilean pueden sobrevivir a las condiciones más extremas del desierto durante milenios, y no solo gracias a su ingenioso diseño.","Unidad",[],["Shurima"],"COMÚN"],"04SH076":["Reloj de arena ancestral","Destruye a un aliado para invocar 1 Estatua en estasis en su lugar con el aliado almacenado en su interior.","","\"¡Ah, Tai! ¡Ven aquí! Nos vendría bien que nos echaras una mano\".\n- Xetsa, investigadora del Vacío","Hechizo",[],["Shurima"],"RARA"],"04SH118":["Arenas despiertas","Invoca 1 Embestidor de las arenas.","","\"Quizá esa caja valga algo, pero está claro que lo que tiene dentro no merece la pena. Mejor que ni te acerques. Habla la voz de la experiencia\". - Sivir","Hechizo",[],["Shurima"],"COMÚN"],"04SH072":["Apaciguador","Cuando se me invoca, otorga Escudo de hechizos a los campeones e hitos aliados.","","\"Ah, no esperabais encontraros con agua en mitad del desierto, ¿verdad? Tranquilos. Venid, bebed, lavaos los pies. Descansad un rato a la sombra. Así es el nuevo imperio de Shurima de Azir: un oasis\".","Unidad",[],["Shurima"],"COMÚN"],"04SH041":["Vigía del Sai","Jugar: Activo Predicción. Si eliges un hito, obtengo Elusión.","","\"¡Antes tuvimos problemas! Había una gran tormenta en el oeste, y Taliyah se cruzó con túneles xer'sai por el sur. Yo vi un templo al norte, y ahora estamos refugiados tras sus paredes de terracota. Los demás siguen dormidos y, poco a poco, mi llama se va apagando. Me deseo felices sueños\".\n- Diario de Zaifa","Unidad",[],["Shurima"],"COMÚN"],"04SH005":["Saqueador sanguinario","","","Los asolaarenas lo hacen todo en grupo: luchar, cazar, matar... y comer.","Unidad",[],["Shurima"],"COMÚN"],"04SH083":["Premonición salvaje","Activa Predicción.","","\"Las aletas inspiran miedo y las fauces otorgan muerte\".\n- Refrán shurimano","Hechizo",[],["Shurima"],"RARA"],"04SH092":["Ha llegado la hora","Invoca 1 Relojizo.\nSi has realizado una Predicción esta partida, invoca 2 en su lugar.","","\"¡Para ya y ven aquí! Tienes arena en los engranajes\". - Tai, cronomante en ciernes","Hechizo",[],["Shurima"],"COMÚN"],"04SH046":["Quimera de arenisca","Cuesto 1 menos por cada vez que un aliado haya atacado en esta partida.","","Tras el regreso de Azir, los shurimanos tuvieron la oportunidad de contemplar bestias de leyendas ancestrales. Eran de arena, pero resultaban igual de sobrecogedoras.","Unidad",[],["Shurima"],"RARA"],"04SH105":["Sepultura de arena","Cuando los aliados atacan, invoca 1 Embestidor de las arenas en ataque.","","Mientras avanzaban por el desfiladero, el esculpearenas pronunció las palabras mágicas. Una ráfaga de viento atravesó el cañón y se convirtió en el estruendo de cascos que se escuchaba cada vez más cerca.","Hito",[],["Shurima"],"RARA"],"04SH131":["Gancho","Un aliado al que hayas seleccionado como objetivo esta ronda golpea a un enemigo.","","\"¡Nunca ven venir el gancho!\". - Akshan","Hechizo",[],["Shurima"],"RARA"],"04SH074":["Cría de los xer'sai","","","En ocasiones, una vez que impiden que una caravana pueda seguir avanzando, los cazadores se retiran para permitir que sus crías se encarguen de la matanza. Ahí es cuando los jóvenes xer'sai comienzan a desarrollar sus instintos y aprenden a distinguir los sonidos del desierto de los de sus presas.","Unidad",["ACECHANTE"],["Shurima"],"COMÚN"],"04SH137":["Enjambre vibrante","Cuando se me invoca, se crea 1 copia de mí en la mano si has subido de nivel a un campeón esta partida.","","Se creía que los escarabajos gigantes habían perecido con la caída del imperio shurimano. Sin embargo, los tentáculos de la Niebla se hundieron en las profundidades de las dunas y vincularon a estas ancestrales criaturas a la voluntad de Viego.\n","Unidad",[],["Shurima"],"ÉPICA"],"04SH069":["Depredador implacable","Concede +2|+0 a un aliado y Vulnerable a un enemigo esta ronda.","","\"¡Hacedlos pedazos!\". - Renekton","Hechizo",[],["Shurima"],"COMÚN"],"04SH121":["Ritual de llamada","Mata a un aliado o destruye una de tus gemas de maná para robar a un campeón.","","\"Un sacrificio necesario\". - Nasus","Hechizo",[],["Shurima"],"COMÚN"],"04SH110":["Tejedura","Manifiesta un hito que puedas pagar.","","\"Venga, ¡queda tanto por descubrir!\". - Taliyah","Hechizo",["ELEMENTAL"],["Shurima"],"ÉPICA"],"04SH051":["Estrado del emperador","Cuando los aliados atacan, invoca 1 Soldado de arena en ataque.","","Los esculpearenas alzaron las manos para obligar a las dunas a adoptar la familiar silueta de soldados con armadura y sin rostro: un ejército incansable y dispuesto a luchar por su dios emperador. ","Hito",[],["Shurima"],"RARA"],"04SH106":["Fuego espiritual","Otorga a los enemigos -2|-0 y \"Fin de ronda: Recibo 2 de daño\" esta ronda.","","\"Sus espíritus arderán\". - Nasus","Hechizo",[],["Shurima"],"RARA"],"04SH129":["Luchador vekaurano","Golpear: Crea 1 Hallazgo fortuito en la mano.","","\"Vale, Barb. Ese era el último de los guardias de este piso. Tenemos que seguir sin llamar la atención\".\n\"¡BLARGH, BLAAA!\".\n\"Voz de interior, Barbara\".\n\"Blarb\".\n\"Mucho mejor\".","Unidad",[],["Shurima"],"RARA"],"04FR006":["Inquisidor Draklorn","Cuando se me invoca, invoca 1 Siervo helado.\nFin de ronda: Si la cuenta atrás de alguno de tus Siervos helados es igual o menor que 4, avanza hasta llegar a 0.","","\"Mi señora se me aparece en sueños, y su voz es apenas un susurro. 'Sígueme', me indica. Jamás desobedecería esa orden\".","Unidad",[],["Freljord"],"ÉPICA"],"04FR012":["Entierro gélido","Destruye a todos los enemigos para invocar 1 Tumba helada en su lugar con el enemigo almacenado en su interior.","","\"Con el tiempo, el frío lo aplasta todo\". - Lissandra","Hechizo",["ELEMENTAL"],["Freljord"],"ÉPICA"],"04FR016":["Botín de guerra","Otorga +1|+2 a un aliado.\nAsalto: Obtiene +2|+4 en su lugar.","","\"Vuestros campos fértiles os han vuelto débiles y orondos, avarosanos. Descansad esta noche, patéticos enclenques, mientras os arrebatamos las riquezas del mañana que codiciáis en sueños\". - Madretriz Vrynna","Hechizo",[],["Freljord"],"COMÚN"],"04FR013":["Resistencia al frío","Obtén una gema de maná vacía y otorga +0|+2 a un aliado.","","\"Cuidado con el hielo y, sobre todo, ¡cuidado con lo que aguarda en su interior!\". - Garabato en la pared de una posada freljordiana","Hechizo",["ELEMENTAL"],["Freljord"],"COMÚN"],"04FR005":["Lissandra","Cuando se me invoca, invoca 1 Siervo helado y avanza su cuenta atrás 2 rondas.","Has invocado 2 o más aliados que cuesten 8 o más. Cuando subo de nivel, crea 1 Vigilante en la mano.","\"Los Vigilantes acechan al otro lado de estas paredes, atrapados en el hielo, congelados en el tiempo... Y, mientras ellos aguardan, yo debo encargarme de poner mis planes en marcha\".","Unidad",[],["Freljord"],"Campeón"],"04FR011":["Sucumbid al frío","Aplica Escarchar a un enemigo.\nInvoca 1 Siervo helado.","","\"Cada uno responde al frío a su manera. Veamos cómo reaccionas tú\". - Lissandra","Hechizo",["ELEMENTAL"],["Freljord"],"COMÚN"],"04FR001":["Siervo helado","Cuenta atrás 9: Invoca 1 Siervo de la Guardia de Hielo.","","Las filas del ejército de Trundle contaban con suficientes guerreros de pocas luces como para absorber golpes en la vanguardia, de eso no cabía duda. Sin embargo, Lissandra deseaba algo más leal, algo que estuviese únicamente a su servicio...","Hito",[],["Freljord"],"COMÚN"],"04FR007":["Sepultura","Destruye una unidad para invocar 1 Tumba helada en su lugar con la unidad almacenada en su interior.","","\"Arrodíllate o muere congelado\". - Lissandra","Hechizo",["ELEMENTAL"],["Freljord"],"RARA"],"04FR017":["Bendición ancestral","Otorga +2|+2 al aliado de más arriba del mazo.\nIluminación: Otorga +2|+2 a todos los aliados del mazo en su lugar.","","El frío inclemente y las tormentas arrolladoras de Freljord acaban con casi todos aquellos que se adentran en sus baldías llanuras. Sin embargo, aquellos que logran sobrevivir descubren en el proceso una fuerza interna que les empuja hacia delante durante el resto de sus vidas.","Hechizo",[],["Freljord"],"COMÚN"],"04FR014":["Desfiladero maldito","Cuando se me invoca, tu nexo se cura 2 de vida.\nCuenta atrás 1: Inflige 2 de daño a todas las unidades.","","Extrañas siluetas de Hielo Oscuro emergen por todos los recovecos del desfiladero, y sus púas mantienen a raya a los intrusos.","Hito",[],["Freljord"],"RARA"],"04FR009":["Fragmento de hielo","Inflige 1 de daño a TODO.","","\"Enterraré el mundo bajo el hielo\". - Lissandra","Hechizo",["ELEMENTAL"],["Freljord"],"COMÚN"],"04FR015":["Poro de leyenda","Cuando se me invoca, otorga una palabra clave aleatoria a los poros aliados.","","Se dice que existe una figura legendaria para todos los poros. Las historias cuentan que, en sus viajes, otorga a sus peludos amigos todo tipo de regalos forjados mágicamente.","Unidad",["PORO"],["Freljord"],"RARA"],"04FR019":["Madre de dientehielos","Cuando se me invoca, invoca 1 Manada de dientehielos.","","Los lobos dientehielos rodearon al drüvask, que se puso en guardia. El hedor de la muerte se aferraba a su pelaje y abrumaba los sentidos.","Unidad",["PERRO"],["Freljord"],"RARA"],"04FR018":["Guardián abominable","Comienzo de ronda: Cuando estoy en la mano, si tienes 2 o más yetis, se me invoca y creas una copia de mí en el mazo.\nJugar: Roba un yeti.","","\"¡Y son de lo más escurridizos! La última vez que anduve por la zona, me tuve que refugiar en una cueva y me encontré con un montón de yetis bebés ahí escondidos, profundamente dormidos. Intenté mantenerme lejos, pero uno de los más grandes regresó a la guarida cubierto de hielo. ¡Era alto como una montaña! Créeme cuando te digo que...\". - Bjerg balbuceante","Unidad",["YETI"],["Freljord"],"ÉPICA"],"04FR010":["Tres hermanas","Crea 1 Congelación instantánea, Furia del norte o Sepultura Fugaz en la mano.","","Las hermanas freljordianas Avarosa, Serylda y Lissandra gozaban de un poder inigualable, pero lo empleaban de forma piadosa, bélica y maligna, respectivamente.","Hechizo",[],["Freljord"],"RARA"],"04NX002":["Palabras susurradas","Reputación: Cuesto 2 menos.\nRoba 2.","","Antes de las noticias llegan los rumores. Antes de los rumores, está la acción; y antes de nada, el plan.","Hechizo",[],["Noxus"],"RARA"],"04NX010":["Espina de la Rosa","Cuando se me invoca, crea 1 Astucia en la mano.","","\"Aelana, ¡mi querida amiga y compañera! ¿Has hablado con Lord Duin sobre...? Ay, qué pena. Tenía muchas ganas de ponerme al día. Espero que se lo haya tomado con calma esta noche. Sería terrible si le pasara algo al pobre hombre...\". - Lady Auvray, espía de la Rosa Negra","Unidad",[],["Noxus"],"COMÚN"],"04NX021":["Justiciero jubilado","Cuando me seleccionas como objetivo, obtengo +1|+0.","","Tras un sinfín de batallas, Beryn juró que no volvería a alzar su espada, aunque eso le costara la vida. Sin embargo, cuando esa neblina tan extraña arrasó Noxus y poseyó a Thea, supo que tendría que romper su promesa. La liberaría a cualquier precio.","Unidad",[],["Noxus"],"RARA"],"04NX022":["Justiciera arruinada","Cuando se me invoca, crea 1 Saqueo a medianoche en la mano.","","Cuando su sentencia llegó a su fin, Thea sabía que nunca podría volver a unirse a su gente. La guerra y Noxus la habían cambiado, la habían convertido en una asesina. No volvería a conocer la paz. En su lugar, aprovechó sus nuevas destrezas para ganarse la vida en la arena.","Unidad",[],["Noxus"],"RARA"],"04NX015":["Asunto sangriento","Reputación: Cuesto 2 menos.\nUn aliado con 5 o más de poder golpea a un enemigo.","","\"Las amenazas que pasan desapercibidas son las más peligrosas de todas\". - LeBlanc","Hechizo",[],["Noxus"],"COMÚN"],"04NX019":["Dinosaurio desbocado","Cuando un enemigo me bloquea, consigo +3|+0 esta ronda.","","Sorprendido por el aguante de la criatura que habían encontrado en las costas jonias, el joven general insistió en llevársela de vuelta a casa para investigar los límites de su fuerza.","Unidad",["REPTIL"],["Noxus"],"ÉPICA"],"04NX008":["Estratega inclemente","Reputación: Cuesto 2 menos.\nCuando se me invoca, prepara el ataque.","","En las salas privadas de la Rosa Negra, la nobleza noxiana pone en marcha sus planes y sus víctimas perecen en la distancia.","Unidad",[],["Noxus"],"RARA"],"04NX006":["Espía de la Rosa Negra","Reputación: Cuando se me invoca, me transformo en una copia idéntica del aliado más fuerte que haya golpeado esta ronda.","","\"Un secreto no vale más que el precio que supone guardarlo\".","Unidad",[],["Noxus"],"ÉPICA"],"04NX001":["Mímica","Reputación: Cuesto 3 menos.\nCuando juegas tu siguiente hechizo esta ronda, lo copias con los mismos objetivos.","","La imitación es una forma de adulación, y la adulación puede resultar letal.","Hechizo",[],["Noxus"],"RARA"],"04NX004":["LeBlanc","","Te he visto infligir 15 o más de daño. Cuando subo de nivel, crea 1 Imagen especular en la mano.","\"Bueno, basta ya de rencillas internas. Por ahora, evitaremos actuar con imprudencia. Volveremos a reunirnos tras haber escuchado el mensaje de nuestro emisario. Al fin y al cabo...\".","Unidad",[],["Noxus"],"Campeón"],"04NX016":["Hilandera aullante","Atacar: Concede +2|+0 a los aliados arácnidos esta ronda.","","\"Vamos, pequeñas. Que los demás oigan vuestra llamada. Se emocionarán... y yo me daré por satisfecha\". - Elise","Unidad",["ARAÑA"],["Noxus"],"RARA"],"04NX007":["Atakhan, Heraldo de la Ruina","Jugar: Revive al aliado más fuerte que haya muerto.\nAtacar: Obtengo poder igual a la suma total de poder de todos los aliados.","","Una aberración sin nombre se alzaba sobre ellos entre el denso humo que invadía la cámara. Los magos entonaban una melodía disonante con voces quebradas y febriles. El monstruo respiró profundamente para sentir el miedo que crecía en su interior, y con cada aliento se volvía más poderoso.","Unidad",[],["Noxus"],"ÉPICA"],"04NX018":["Corresangres carmesí ","La próxima vez que invoques a otro aliado, le infliges 1 de daño y consigo +1|+1.","","\"Muy pocos se arriesgan a tenerlos de mascota, pues un roce de nada con una de esas garras suyas te puede cortar una vena... Pero bueno, a mí no me importa\". - Clara, discípula carmesí","Unidad",["GATO"],["Noxus"],"COMÚN"],"04NX003":["Sello de malicia","Reputación: Cuesto 2 menos.\nInflige 2 de daño a cualquier unidad o estructura.","","Tras hacerse con la victoria, uno nunca debe dudar, sino aprovechar para avanzar y aniquilar al enemigo.","Hechizo",[],["Noxus"],"COMÚN"],"04NX017":["Ventaja numérica","Invoca 2 Saqueadores de la Legión.","","Los soldados de Noxus no suelen dejar supervivientes, pero los saqueadores son aún más inclementes.","Hechizo",[],["Noxus"],"COMÚN"],"04NX009":["Filo con espinas","Concede a un aliado +5|+0 esta ronda.","","\"Te comportarás con elegancia y cortesía. Pronunciarás cumplidos apaciguadores. Escucharás y aprenderás. Y, cuando llegue el momento, golpearás... Y matarás\". - LeBlanc","Hechizo",[],["Noxus"],"COMÚN"],"04SI005":["Kindred","Cada ronda, la primera vez que asesinas a una unidad, marco al enemigo más débil.\nFin de ronda: Asesino a las unidades marcadas.","Te he visto asesinar a 2 o más unidades marcadas.","Tiempo atrás, un hombre solitario\ndecidió partirse por la mitad.\nAsí terminó su calvario,\nPues no volvió a sufrir de soledad.","Unidad",[],["Islas de la Sombra"],"Campeón"],"04SI055":["Viego","La primera vez que otro aliado muere en cada ronda, invoca 1 Niebla envolvente.","He visto a aliados morir que sumaban 20 o más de poder.","\"Hay algo en el joven rey que me preocupa en gran medida. Algo en su corazón... Un hambre insaciable, un deseo imposible de satisfacer\". - Archivos de Nunyo Necrit de Camavor","Unidad",[],["Islas de la Sombra"],"Campeón"],"04SI016":["Sanguijuela espectral ","Jugar: Mata a un aliado para robar 2.","","Acechan en las sombras, esperando un gesto agotado o una mente absorta. Entonces llegan las garras, las fauces desencajadas y, por último, la oscuridad.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"04SI007":["Demonio del éter","Jugar: Mata a un aliado para matar a un enemigo.","","\"Ahora que se me agota el tiempo, mis pensamientos vagan cada vez más hacia la segunda muerte. ¿Quién será la última alma que recuerde mi nombre? Y, cuando a ella también le llegue su hora... ¿qué será de mí?\". - Benefactor eminente","Unidad",["AVE"],["Islas de la Sombra"],"RARA"],"04SI011":["Hacia el crepúsculo","Roba 1.\nAnochecer: Activa el efecto de Anochecer de un aliado e ignora las partes que requieran un objetivo.","","\"Ven, acércate. No tengas miedo\". - Madre de las máscaras","Hechizo",[],["Islas de la Sombra"],"RARA"],"04SI018":["El Bosque Retorcido","Si he visto a 3 o más aliados con Temible o Anochecer atacar, se me destruye para invocar a Vilemaw.","","Sus altares permanecen inactivos y sus caminos, durmientes,\npero las oscuridad no se aletarga y la bestia acecha, inminente.","Hito",[],["Islas de la Sombra"],"ÉPICA"],"04SI015":["Escarabajo marino","Cuando otro aliado muere o Último aliento: Desecha 1.","","\"Bueno, venga. ¡A recoger esas trampas! Y recordad: si veis a uno de esos escarabajos marinos, cortáis la cuerda y os olvidáis del tema. No pienso jugarme la quilla por algo que lleven a medio comer, ¿entendido?\". - Capitana de Aguas Estancadas","Unidad",["MONSTRUO MARINO"],["Islas de la Sombra"],"RARA"],"04SI004":["Las alas y la ola","Jugar: Entro en juego como Primera oleada o Última brisa.","","Los kinkou solo conocen dos dioses: la primera oleada, que envuelve a la vida en sus cálidas aguas, y la última brisa, que apaga su luz con un gélido aliento.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"04SI017":["Canción de las islas","Otorga Robo de vida, Temible y Endeble a un aliado.","","\"Acércate. Ve lo que yo veo, siente lo que yo siento. No tengas miedo a la oscuridad\". - Portador de la llama","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"04SI054":["Soldado camavorano","Cuando se me invoca, invoca 1 Niebla envolvente.","","Los soldados de Camavor avanzaron junto a Viego en vida, y su lealtad se mantiene firme tras la muerte.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"04SI001":["Respiro de cordera","Concede \"No puedo recibir daño ni morir esta ronda\" al aliado más débil.","","\"¡Brilla una vez más antes del fin!\". - Cordera","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"04SI056":["Niebla marchita","Drena 2 de vida a 2 enemigos.","","\"Me llevaré lo que desee y me desharé de lo que no me interese\". - Viego","Hechizo",[],["Islas de la Sombra"],"RARA"],"04SI012":["Zorro astral","Jugar: Mata a un aliado para infligir 3 de daño al nexo enemigo.","","Hay unas cuantas tribus de Targon que hablan del Zorro, un dios de la muerte que se manifiesta como una estrella solitaria en el firmamento nocturno. Cuenta la leyenda que, con cada muerte, el Zorro desciende a la montaña y se lleva el alma a los cielos para crear su propia constelación oscura.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"04SI029":["Desesperación","Elige una unidad para que golpee tu nexo y, después, esta unidad morirá.","","\"Lo he dado todo por encontrarla, y no es suficiente\". - Viego","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"04SI009":["Tejedor de almas","Cuando se me invoca, consigo +1|+1 y Temible si un aliado muere esta ronda.","","\"Tiempo atrás, un desafortunado muchacho trató de conquistar a una araña sin jamás plantearse que podría acabar atrapado en su red...\".","Unidad",["ARAÑA"],["Islas de la Sombra"],"COMÚN"],"04SI013":["Madre de las máscaras","Jugar: Mata a un aliado para otorgarme sus estadísticas y palabras clave.","","Dicen que la Madre de las máscaras creó a Kindred y también a todas las demás encarnaciones de la muerte. Pero ¿quién le otorgó a ella su máscara? ¿Acaso la fabricó ella misma?","Unidad",[],["Islas de la Sombra"],"COMÚN"],"04SI021":["Dracovíbora trepadora","Para jugar esta carta, golpeo a un aliado o inflijo 3 de daño a tu nexo.","","Al principio, los soldados demacianos creían haber escuchado montones de garras arrastrarse sobre las baldosas. Sin embargo, no fue hasta que se adentraron en la torre de vigilancia que comprendieron que todas ellas pertenecían a la misma criatura.","Unidad",["DRAGÓN"],["Islas de la Sombra"],"COMÚN"],"04SI002":["Viaje espiritual","Mata a una unidad y después la revive.","","\"Esto es tan solo un interludio\". - Cordera","Hechizo",[],["Islas de la Sombra"],"RARA"],"04SI053":["Hidravid invasiva","Cuando se me invoca o al comienzo de ronda: Invoca 1 Niebla envolvente.","","Maokai trabajó incansablemente para cultivar la vida en las Islas de la Sombra. La ambivalencia de la Niebla no suaviza la crueldad de las ironías que alimenta.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"04SI003":["Icono debilitado","Cuando se me invoca, invoca a La presa.","","¿Quién iba a olvidarse de su propio dios de la muerte? Aquellos que cargan con la maldición de la inmortalidad, por supuesto. Y no hay mayor tortura para un dios que el terror de caer en el olvido. ","Unidad",[],["Islas de la Sombra"],"COMÚN"],"04SI028":["Dragón camavorano","Para jugar esta carta, golpeo a un aliado o inflijo 3 de daño a tu nexo.\nCuando asesino a otra unidad, drenas 1 de vida del nexo enemigo.","","Durante siglos, la Niebla Negra ha avanzado en busca de criaturas de todo el mundo, envolviéndolas y haciéndolas mutar, convirtiéndolas en engendros de pesadilla, ecos de lo que fueron en otro tiempo.","Unidad",["DRAGÓN"],["Islas de la Sombra"],"RARA"],"04MT014":["Ojo de los Ra-Horak","Cuenta atrás - 1: Aturde a los 2 enemigos más débiles.\nAmanecer: Invoca una copia de mí con 2 de Cuenta atrás.","","\"Que el sol nos bañe con su luz. ¡Los débiles e indignos quedarán expuestos ante su resplandor!\". - Sacerdotisa solari","Hito",[],["Targon"],"RARA"],"04MT008":["Malphite","Jugar: Aturde a un enemigo.","Has invocado hitos por un valor de 10 o más de maná. Cuando subo de nivel, si tienes la ficha de ataque, crea 1 Fuerza imparable en la mano.","\"Y esta es la última parada de la visita guiada de Chip por Targon: ¡Este es PAPÁ! Es el más grande de todos los gigantes de Targon y canta que te mueres, la verdad. ¡Pero nada de intentar escalarlo! Los pinchos le hacen cosquillas, y como os estornude encima a medio camino, ¡uf!\".\n- Aventuras con Chip, parte 6","Unidad",[],["Targon"],"Campeón"],"04MT010":["Cima estrellada","Cuenta atrás - 2: Crea 2 cartas celestiales aleatorias que cuesten 3 o menos en la mano.","","Aquellos que se proponen escalar el Monte Targon no tardan en disfrutar de algunas de las vistas más espectaculares de toda Runaterra. Cuanto más arduo resulta el ascenso, más sobrecogedoras son sus recompensas.","Hito",[],["Targon"],"RARA"],"04MT005":["Chip","Cuando hayas invocado un hito en esta partida, consigo +2|+2.","","\"Bueno, ¡hola! Soy Chip y he venido a enseñaros Targon. ¡Es enoooorme y muy alto, así que espero que vengáis con zapatos cómodos! ¡VÁMONOS!\".\n- Aventuras con Chip, parte 1","Unidad",[],["Targon"],"COMÚN"],"04MT009":["Escalera de caracol","Cuenta atrás - 3: Crea 1 Semilla de fuerza en la mano.","","\"¡Esta es la primera parada de la visita guiada! A este lo llamo 'el tiemblapiernas', porque madre mía, ¡cuántos peldaños! Y la vista es una pasada. Las vistas en Targon son espectaculares. ¡Bueno, VAMOS!\".\n- Aventuras con Chip, parte 2","Hito",[],["Targon"],"RARA"],"04MT001":["Sendero derruido","Cuenta atrás - 2: Destruye al enemigo más débil.","","\"A ver, todos a tener CUIDADITO porque esta caída es poca broma. Me he caído un par de veces y, OYE, ¡parece que no hay fondo! Y yo, claro, reboto, pero vosotros no tenéis esa suerte... Así que mucho cui... ¡Anda, Cliff! ¡Vamos a saludar!\". - Aventuras con Chip, parte 3","Hito",[],["Targon"],"COMÚN"],"04MT018":["Íbice aterrado","Cuando recibo apoyo, tanto yo como el aliado que me apoya recibimos +1|+1 esta ronda.","","\"Nunca temas al furioso vendaval\nQue atraviesa la montaña y el valle en temporal.\nNo te preocupes, no hay nada que temer,\nDescansa, cariño; mamá te va a proteger\". - Nana de Targon","Unidad",[],["Targon"],"COMÚN"],"04MT004":["Coloso celeste","Último aliento: Invoca 1 Emblema de perspicacia.","","\"Bueno, chicos, ¡saludad a Azul! ¡Hola, Azul! Una vez pensé que me había respondido, pero, ahora que lo pienso, quizá es que el sonido rebotó en la pared. EN FIN, qué le vamos a hacer. Es mágico y azul, así que la verdad es que no le hace falta hablar para nada. ¡BUENO, AZUL, HASTA LUEGO!\".\n- Aventuras con Chip, parte 5","Unidad",[],["Targon"],"COMÚN"],"04MT013":["Águila solar","Amanecer: Aturde al enemigo más fuerte.","","Los solari creen que las resplandecientes águilas de Targon fueron lo que llamó la atención de la Llama inmortal, y que también inspiraron el origen de su ciclo de muerte y renacimiento.","Unidad",["AVE"],["Targon"],"COMÚN"],"04MT003":["Elemental de tierra","Cuando hayas invocado 4 o más hitos en esta partida, consigo +3|+0.","","\"¡Bueno, este es Cliff! Es un tipo bastante grandote que se conoce esta zona DE MARAVILLA. Sé que tiene pinta guay y parece buen chaval, pero lleva cosas muy pesadas a la espalda y a veces se le caen. ¡Así que con cuidado, ¿vale?! ¡Venga, vamos!\".\n- Aventuras con Chip, parte 4","Unidad",[],["Targon"],"COMÚN"],"04MT002":["Quiebrarrocas","Jugar: Si has invocado 4 o más hitos en esta partida, inflige 4 de daño a un enemigo y 2 de daño al nexo enemigo.","","De vez en cuando, los colosos de Targon despiertan de su letargo para abrirse paso a nuevas zonas de la gran montaña. Suelen ser acontecimientos ruidosos y bastante peligrosos.","Unidad",[],["Targon"],"ÉPICA"],"04MT006":["Epifanía estelar","Activa Convocar.\nSi tienes un aliado Celestial, remplaza tu mazo con 20 copias de Contemplad el infinito.","","\"¡Mira, Kulun! Las estrellas tienen millones de historias que contar. ¿Cuál quieres que leamos esta noche?\". - Sueñalunas","Hechizo",[],["Targon"],"ÉPICA"],"04MT012":["Llamada del destino","Otorga +8|+8 a un aliado de la mano.","","\"Acepta tu destino y brilla con más fuerza de lo que nunca nadie hubiera imaginado\". - Taric","Hechizo",[],["Targon"],"ÉPICA"],"04MT007":["Golpe en el suelo ","Aturde a un enemigo. Le infliges 3 de daño si has invocado un hito en esta partida.","","\"¡Aaaay, eso sí que es el suelo, que se mueve! No ha sido papá, ¿eh, VALE? ¡Bueno, vamos, adelante y ARRIBA!\". - Chip","Hechizo",["ELEMENTAL"],["Targon"],"RARA"],"04MT015":["Firmamento alineado","Amanecer: Crea una carta aleatoria con Anochecer en la mano.\nAnochecer: Crea una carta aleatoria con Amanecer en la mano.","","El ciclo del día y la noche continúa, y se sucederán durante toda la eternidad.","Hechizo",[],["Targon"],"COMÚN"],"04DE004":["Rastreadora ferviente","Cuando invocas a una unidad Élite, mi coste se reduce en 1.","","Aunque los noxianos habían preparado la trampa con gran destreza, lo cierto es que nadie conocía esos bosques como los exploradores demacianos. Cada rama quebrada y cada huella les acercaban un poco más a su príncipe.","Unidad",["ÉLITE"],["Demacia"],"RARA"],"04DE014":["Manjar de dragón","Cuando juegas un dragón, me golpea y robas 1.","","\"¿Ese alarido que escuchas en las alturas? No es un ave, chiquillo. Es el grito de un dragón que ha salido de caza\".\n- Granjero demaciano","Unidad",[],["Demacia"],"COMÚN"],"04DE001":["Lord honorable","La primera vez que desafío a un enemigo gracias a Contendiente, consigo Barrera en esta ronda.","","Tras recibir noticias de la desaparición de su hijo, el rey Jarvan III encargó a su fiel amigo Lord Barrett Buvelle que organizara un equipo de búsqueda. El príncipe regresó sano y salvo. Sin embargo, por desgracia para el rey, Lord Buvelle no tuvo tanta suerte.","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"04DE012":["Ascenso de combate","La próxima vez que juegues una unidad esta ronda, obtiene Vigía. Ahora es una unidad Élite.","","Si la ocasión lo requiere, los demacianos siempre están preparados para demostrar su inquebrantable temple.","Hechizo",[],["Demacia"],"COMÚN"],"04DE003":["Cataclismo","Un aliado comienza un ataque gratis al desafiar con Contendiente a un enemigo.","","\"¡Por el rey!\". - Jarvan IV","Hechizo",[],["Demacia"],"RARA"],"04DE002":["Protección áurea","Concede Barrera a un aliado esta ronda.\nPrepara el ataque.","","\"¡Una vez más, soldado de Demacia!\". - Jarvan IV","Hechizo",[],["Demacia"],"RARA"],"04DE006":["Pericia bélica","Otorga +1|+1 a un aliado.","","\"Tengo un par de cosas que enseñarte\". - Lord Buvelle","Hechizo",[],["Demacia"],"COMÚN"],"04DE008":["Jarvan IV","Cuando atacas, gasta el maná que cuesto para invocarme y hacer que desafíe con Contendiente al enemigo más fuerte.","Los aliados han sobrevivido a 3 o más golpes por parte de unidades enemigas en bloqueo.","Los noxianos sabían dónde acabaría la búsqueda del príncipe Jarvan. Sabían cuántos demacianos marcharían a su lado y sabían también que su honor jamás le permitiría contemplar la huida. La trampa estaba lista.","Unidad",["ÉLITE"],["Demacia"],"Campeón"],"04DE005":["Cithria, la Dama de las Nubes","Cuando se me invoca, se duplican el poder y la vida de los demás aliados, que también obtienen Contendiente.","","\"Para salvar a su príncipe, Demacia envía a la mismísima Dama de las Nubes\". - Rey Jarvan III","Unidad",["ÉLITE"],["Demacia"],"ÉPICA"],"04DE020":["Guardia de dragones arruinado","Cuando un aliado con Furia mata a una unidad, recibe +1|+1 adicional.","","La Niebla retorció la mente de Gregem y lo obligó a revivir Wrenwall una y otra vez. Alimentado por una rabia y una amargura que llevaban mucho tiempo enterradas en su interior, traicionó a los compañeros que antes luchaban a su lado.","Unidad",[],["Demacia"],"COMÚN"],"04DE010":["Rey Jarvan III","Cuando se me invoca, roba a Jarvan IV.\nSi ya está en juego, otorga Contendiente y Vigía a los aliados esta ronda.","","\"Dime, ¿qué está dispuesto a sacrificar un padre para salvar a su hijo? ¿Y un rey por su príncipe?\". - LeBlanc","Unidad",["ÉLITE"],["Demacia"],"ÉPICA"],"04DE016":["Kadregrin, el Arruinado","Jugar: Otorga Contendiente y +1|+1 a un aliado.","","Kadregrin se dedicaba a sembrar el caos y el terror desde mucho antes de que la Niebla Negra alcanzara Demacia. Sin embargo, a las órdenes de Viego, sus habilidades potenciarían en gran medida los ejércitos del Rey Arruinado.","Unidad",["DRAGÓN"],["Demacia"],"RARA"],"04DE013":["Cuernopétreo descomunal","No recibo daño de los hechizos ni las habilidades enemigas.","","Cuenta la leyenda que los magníficos cuernopétreos nacieron cuando el bosque de petricita aún era joven; ahora, sus astas están compuestas de un material similar al de esos árboles ancestrales.","Unidad",[],["Demacia"],"COMÚN"],"04DE015":["Vuelo del alarrauda","Jugar: Crea 1 Vanguardia alargéntea, Asalto cegador o Rastreador plumaveloz en la mano. Ataque: Otorga +1|+1 al resto de unidades aliadas que están desafiando con Contendiente esta ronda.","","Los alaraudas inspiran a los soldados demacianos en el campo de batalla. En cuanto los ven descender de los cielos, se sienten renovados y listos para continuar la lucha con todas sus fuerzas.","Unidad",["ÉLITE","AVE"],["Demacia"],"ÉPICA"],"04DE007":["Escudera penitente","Cuando se me invoca, crea 1 Estandarte andrajoso en la mano si hay una unidad Élite Visible.","","Cuando al fin alcanzó la muralla de la ciudad, sus piernas se dieron por vencidas. La Vanguardia Impertérrita se encargaría de llevarle su mensaje al rey para asegurarse de que salvaba al príncipe. Con ello, corregiría su grave error y protegería su honor.","Unidad",[],["Demacia"],"COMÚN"],"04DE009":["Jinete gallardo","La primera vez que desafío con Contendiente a un enemigo, me transformo en Caballería de la Vanguardia.","","Una vez emitida la orden, todos los soldados demacianos fueron convocados inmediatamente para partir en busca del príncipe. En estas circunstancias, el propio interés era la clave.","Unidad",["ÉLITE"],["Demacia"],"RARA"],"05BC058":["Kennen","Cuando se me invoca, crea 1 Marca de la tormenta en la mano.","Has invocado al mismo aliado 5 veces o más.","Kennen también lo oyó: el rugido de algo... nunca antes visto. Persona o monstruo, no importaba. Los kinkou protegerían su tierra a cualquier precio.","Unidad",["YORDLE"],["Ciudad de Bandle","Jonia"],"Campeón"],"05BC010":["Domador de tiburones","Cuando los aliados atacan, invoca 1 Diente pequeñín en ataque.","","La rutina del domador es la misma todas las noches: pescado y cerveza para cenar, unas caladitas a la pipa de burbujas y un cuento y unos besitos en el hocico a los tiburones antes de dormir.","Unidad",["YORDLE"],["Ciudad de Bandle","Aguas Estancadas"],"RARA"],"05BC102":["Mago marchito","Comienzo de ronda: Recuperas 1 de maná de hechizos.","","Si no hay mayor dolor que cortarse con un papel... Entonces nadie comprende mejor el dolor que los bibliotecarios.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC230":["Portal espiritual","Para jugar esta carta, descarta 1. Otorga +1|+1 a los aliados.","","\"Nunca recuerdo cómo funcionan estas cosas\". - Poppy","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC099":["Explorador mazado","Cuando se me invoca, consigo +1|+1 por cada otro yordle aliado que tengas.","","\"¿Que cuál es mi secreto? Pregúntaselo a mis bíceps, ellos sí que saben\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC133":["Tristana","Tengo +1|+0 por cada aliado de varias regiones que hayas invocado en esta partida.\nCuando invocas un aliado de varias regiones, le otorga +1|+0.","Has invocado 5 o más aliados multirregión.","\"Vale, plan A: nos abrimos paso con dinamita y comenzamos a disparar. Si eso no funciona, pasamos al plan B: nos abrimos paso con dinamita y seguimos disparando. Luego, nos reunimos y cambiamos al plan C, que básicamente es el plan A...\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"Campeón"],"05BC023":["Minipeludito","Fin de ronda: Si has infligido daño al nexo enemigo esta ronda, me transformo en Megapeludito.","","Cosas que les gustan a los minipeluditos: dormir la siesta sobre las cálidas rocas junto a las tierras de la tribu Nakotak. Cosas que no les gustan a los minipeluditos: que yordles descarados los echen de dichas rocas...","Unidad",[],["Ciudad de Bandle"],"ÉPICA"],"05BC029":["Yuumi","Comienzo de ronda: Otorga +1|+1 a la unidad a la que estoy vinculada. Si no, consigo +1|+1.","La unidad a la que estoy vinculada o yo hemos atacado 3 veces.","Yuumi tenía que admitir que, a pesar de todas sus pataletas, Libro le caía superbien. Le gustaba su olor, sus ilustraciones... Le gustaba incluso saltar por sus portales; pero nada era tan bueno como tener a Norra de vuelta en casa, sana y salva.","Unidad",["HADA","GATO"],["Ciudad de Bandle","Targon"],"Campeón"],"05BC078":["Arpón eléctrico","Para jugar esta carta, descarta 1. Inflige 2 de daño a una unidad y 2 al nexo enemigo.","","\"¡Empieza el espectáculo!\". - Rumble","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC106":["Gruñebabosa","","","\"A pesar de su reducido tamaño, la gruñebabosa tiene un gran apetito y posee lo que solo puedo describir como un mal genio de cuidado\". \n- Entrada del día 17 del diario ecológico del conchólogo","Unidad",[],["Ciudad de Bandle","Aguas Estancadas"],"COMÚN"],"05BC161":["Gnar","Golpear: Crea 1 Palito en la mano o, si ya tienes una copia, su coste se reduce en 2.","Fin de ronda: Has infligido daño al nexo enemigo esta ronda.","Hace mucho tiempo, Gnar y los suyos habitaban el valle de Nakotak. Era un lugar inocente, ajeno a cualquier modernidad. Qué mala suerte que el paso del tiempo le haya arrebatado este lugar a Gnar. Pero qué suerte que el tiempo no funcione exactamente como uno se espera en Ciudad de Bandle.","Unidad",["YORDLE"],["Ciudad de Bandle","Freljord"],"Campeón"],"05BC073":["Química ingeniosa","Cuando se me invoca, invoca 1 Bomba rudimentaria.","","Giselle era una de las mejores alumnas del profesor Heimerdinger hasta que descubrió los extraños experimentos que Ziggs llevaba a cabo en Zaun. Luego solo le interesaban los hexplosivos y que la recomendaran para las prácticas. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC039":["Granadero huraño","Alianza: Invoca un adepto yordle aleatorio que cueste 3 de maná o menos.","","\"Mi pequeña Alicia tiene dos balas: una para saludar y otra para despedirse. ¿Quieres conocerla?\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC148":["Fae furioso","Cuando se me invoca, si has infligido daño al nexo enemigo 4 veces o más en esta partida, consigo 4 de Impacto.","","Correoso por fuera, duro y crudo por dentro.","Unidad",["HADA"],["Ciudad de Bandle","Piltover y Zaun"],"COMÚN"],"05BC119":["Súbdito","Último aliento: Crea una copia mía en la mano en el siguiente Comienzo de ronda.","","\"¡Un verdadero supervillano siempre necesita más súbditos! Pequeños amiguitos que sepan cuál es su lugar, que te obedezcan en todo y que siempre vuelvan para recibir nuevas instrucciones\".\n- Extracto del capítulo 2 de Cómo convertirse en supervillano, de lord Veigar","Unidad",[],["Ciudad de Bandle","Islas de la Sombra"],"COMÚN"],"05BC019":["Pez arcoíris","","","El pez arcoíris se alegró de hacer un reconocimiento aéreo, incluso cuando eso significaba dar un salto más grande que ninguno. Haría cualquier cosa, por mínimo que fuera, por alejarse de la hambrienta mirada de Yuumi.","Unidad",["HADA"],["Ciudad de Bandle"],"COMÚN"],"05BC093":["Veigar","Cuando se me invoca, crea 1 Oscuridad en la mano si no tienes. Comienzo de ronda: Otorga a tu Oscuridad 1 de daño adicional esté donde esté.","Has infligido 12 o más de daño con Oscuridad.","\"Este mundo me temerá. Portará mis cicatrices durante toda la eternidad. Sufrirá ante mi poder. ¡Se estremecerá bajo la sombra de mi grandeza!\".\n- Extracto del capítulo 1 de Cómo convertirse en supervillano, de lord Veigar","Unidad",["YORDLE"],["Ciudad de Bandle","Islas de la Sombra"],"Campeón"],"05BC007":["Apiladores de piedras","","","Los yordles todavía no comprenden muy bien cómo funciona la gravedad, pero esta tampoco comprende Ciudad de Bandle.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC174":["¡Amistad!","Concede a un aliado Barrera o Escudo de hechizos esta ronda.","","\"¡Te protegeré con mi salvaje y furioso... miau!\". - Yuumi","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC185":["Juego de conchas","Recarga el maná de hechizos. Concede Elusión y +1|+1 a un aliado esta ronda.","","\"Los he visto meterse en la concha de la izquierda, pero cuando elijo esa concha, está vacía. Empiezo a pensar que este juego está amañado...\".\n- Entrada del día 14 del diario ecológico del conchólogo","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC096":["Tenor del terror","Cuando se me invoca, si has jugado una carta creada o has eliminado a una unidad con un hechizo en esta partida, invoca 1 Bajo del pesar.","","Si Veigar necesitara ayuda para equilibrar las escalas de la justicia, no habría nadie mejor para hacerlo que estos dos. Se las saben todas, excepto el modo mixolidio.","Unidad",["YORDLE"],["Ciudad de Bandle","Islas de la Sombra"],"RARA"],"05BC088":["Rumble","Jugar: Descarta hasta 3 cartas para otorgar a los Rumbles aliados estén donde estén Impacto con la primera, Ataque rápido con la segunda y Escudo de hechizos con la tercera.","He visto a yordles mechas aliados infligir 12 o más de daño.","\"Y... eso debería bastar\".\n\"ERROR\".\n\"¿QUÉ? ¡Acabo de arreglarlo!\".\n\"FALLO DE SISTEMA INMINENTE\".\n\"Apágalo. ¡APÁGALO!\".\n- Rumble y Tristy","Unidad",["MECHA","YORDLE"],["Ciudad de Bandle","Noxus"],"Campeón"],"05BC056":["Monje de viento","Cuando se me invoca, crea 1 Posición de la nube en la mano.","","\"La técnica de nuestra escuela proviene del control de la respiración, al igual que una tempestad nace a partir de un simple soplo de viento\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC190":["Mechacomentarista de la arena","Atacar: Concede +2|+0 al resto de aliados en ataque esta ronda.","","\"¿Que cómo lo hago? ¿Comentar combates noche tras noche? Hago gárgaras con aceite para motores. Cinco minutos por la mañana y cinco por la noche\".","Unidad",["YORDLE"],["Ciudad de Bandle","Noxus"],"ÉPICA"],"05BC042":["Batido de moras","Hace que un aliado pase a tener 3|3 esta ronda.","","\"Antes era como tú, no podía levantar ni un champiñón. Pero entonces 'Batido de moras' llegó a mi vida. Tiene todo lo que necesitamos los yordles para pasar de cero a héroe. Así que, después de entrenar, ¡recarga las pilas con 'Batido' y en un santiamén te habrán crecido unos músculos como estos!\". \n- Panfleto publicitario","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC205":["Horizonte de sucesos","Aturde a un enemigo y después aturde a todos los enemigos con 2 o menos de poder.","","\"Solo tienes que... quedarte ahí...\". - Veigar","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC223":["Trampantojo","Elige 1 de entre 3 unidades o hechizos del mazo enemigo y coloca 3 Boletus venenosos en todas sus copias.","","\"Regla 986: Las trampas no son juguetes... ¡Pero sí que son de lo más divertidas!\".","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC091":["Promotora de la arena","Jugar: Descarta 1 para Manifestar un yordle mecha y reduce su coste en 1.","","\"¡ENTRADAS! ¡COMPRAD YA VUESTRAS ENTRADAS! ¡AHORA A MITAD DE PRECIO! Cáspita, si no vendo estas entradas, mi jefe me va a matar... literalmente\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC163":["Ziggs","Atacar: Inflijo 1 de daño a la unidad que me bloquee y al nexo enemigo.","Has destruido 4 o más hitos aliados.","\"Es muy importante que causemos una buena primera impresión. El inspector de seguridad va a pasarse por aquí, ¡y ya sabéis lo que eso significa!\".\n\"¿Nada de explosiones?\".\n\"¡¿Qué?! ¡No! ¡Pero las explosiones donde no pueda verlas! ¿Cómo que nada de explosiones? ¡¿Se te ha ido la olla?!\".\n- Ziggs y Otto","Unidad",["YORDLE"],["Ciudad de Bandle","Shurima"],"Campeón"],"05BC151":["Maga de los espejos","Cuando juegas un adepto creado, invoca una copia exacta. Cuando lanzas un hechizo creado, vuelve a lanzarse con los mismos objetivos.","","\"Ay, sí, es una experta en espejos. Hace que mis diseños queden aún mejor y, con un pequeño truco con las luces, hasta consigue darle un poco de verticalidad a mis clientes, esa que tanto necesitan...\". - Sastre arrogante","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"05BC027":["Campo de hexplosivos","Cuando se me invoca o me destruyes, aturde al enemigo más fuerte.","","\"¿Por qué dices que esto no parece del todo seguro?\". - Ziggs","Hito",[],["Ciudad de Bandle"],"COMÚN"],"05BC200":["Portal yordle","Para jugar esta carta, descarta 1. Manifiesta un yordle que cueste 3 o menos y lo invoca.","","\"¡Ningún artillero se queda atrás!\". - Tristana","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC021":["Bomba rebotante","Inflige 2 de daño a una unidad o 1 de daño a dos enemigos.","","\"¡Agarraos, que va!\". - Ziggs","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC167":["Comando de Bandle","Golpe al nexo: Crea 1 Buhogatito hambriento en la mano.","","\"¡Por las calles patrullo y a los niños envueltos en sábanas arrullo!\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC179":["Guardabosques yordle","Atacar: Otorga +0|+1 a los aliados con un poder equivalente o inferior al mío.","","\"¡Poppy! Has llevado a cabo nuestra última táctica de maravilla. ¿Qué te parece si la llamamos 'Tormenta de pétalos de cacahuete'?\n\"Eh, pues le acabo de dar un golpe al enemigo con el martillo, ¿por qué no la llamamos 'Martillazo', sin más?\"\n\"¡Pero si ese es el nombre de las tres últimas!\". - Kip y Poppy","Unidad",["YORDLE"],["Ciudad de Bandle","Demacia"],"ÉPICA"],"05BC214":["Megabomba incendiaria","Inflige 1 de daño a todos los enemigos. Se repite.","","\"Saca a... ¡'la grandullona'!\". - Ziggs","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC221":["Velo de seta","Cuando se me invoca o al comienzo de ronda: Consigo poder esta ronda igual al número del resto de hadas aliadas en juego o vinculadas.","","Las pequeñas con cabezas de alfiler son bastante bonitas y por sí solas pueden crecer un montón.","Unidad",["HADA"],["Ciudad de Bandle","Jonia"],"RARA"],"05BC041":["Poppy","Atacar: Otorga +1|+1 a los aliados con un poder equivalente o inferior al mío.","He atacado con aliados 3 veces.","La humildad va implícita en los héroes, aunque muchos historiadores coinciden en que la humildad de Poppy es un poco forzada.","Unidad",["YORDLE"],["Ciudad de Bandle","Demacia"],"Campeón"],"05BC176":["Misil acechador","Otorga +1|+0 a un aliado. Inflige 1 de daño a un enemigo.","","\"¡Zuuuuum!\".- Yuumi","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC105":["Artilleros de Bandle","Cuesto 1 menos por cada aliado de varias regiones que hayas invocado esta partida.\nCuando se me invoca, consigo 3 de Impacto.","","Un escuadrón de ensueño.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC066":["Pluma rápida","","","\"¿D... ó... n... d... e... e... s... t... á... N... o... r... r... a...? Ay, madre, ¿qué le digo?\". - Ratón mayordomo","Unidad",["HADA"],["Ciudad de Bandle"],"COMÚN"],"05BC177":["Dragón de papel","","","\"Y si lo plegamos por aquí... ¿ves? ¡Una jirafa! Se llama Calcetines\". \n\"¿Calcetines? ¿Por qué?\". \n\"A Norra le encantan los calcetines, ¡así que esto también le encantará!\". - Ratón mayordomo","Unidad",["HADA"],["Ciudad de Bandle"],"ÉPICA"],"05BC136":["Desguace","Para jugar esta carta, descarta 1.\nManifiesta un yordle mecha.","","\"Porquería, chatarra, basura... ¡Anda, esto sí que me va a venir de perlas!\". - Rumble","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC164":["Dardo venenoso","Inflige 1 de daño a cualquier unidad o estructura y coloca 3 Boletus venenosos en el mazo enemigo.","","\"¡Ja, ja! ¡En el blanco!\". - Teemo","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC194":["El árbol de Bandle","Comienzo de ronda: Crea un adepto de una nueva región en la mano. Después, si he visto a aliados de 10 regiones, ganas la partida.","","El árbol de Bandle, que se alza una gran distancia hasta rozar el cielo, es un elemento esencial del centro de la ciudad. Bajo sus grandes y retorcidas ramas, algunos yordles lo ven como un rayo de esperanza y amistad, mientras que otros lo consideran un monolito siniestro y enigmático. Eso sí, todos coinciden en que están ante el alma de un ser muy antiguo y poderoso.","Hito",[],["Ciudad de Bandle"],"ÉPICA"],"05BC127":["Rissu, la Tormenta Silenciosa","Cuando se me invoca, invoca 1 Nube de tormenta.","","Hacía falta tiempo para tejer una nube de tormenta. Un tiempo con el que Rissu no contaba. Sus manos no paraban de trabajar mientras se acercaba la aberración. Un poco de nube por aquí, algún relámpago por allá. Entonces... ¡CRAC! ¡BUM! Lo había conseguido, pero ¿bastaría?","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"05BC216":["Artilugio yordle","Destruye un hito o crea 2 adeptos de varias regiones aleatorios en la mano.","","\"¡Ojo, que vamos motorizados!\". - Bombarderos gemelos","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC212":["Inspector de seguridad","Comienzo de ronda: Crea 1 ¡Inspección pasada! en la mano.","","Wilfred antes era un escéptico. Y de los buenos. De hecho, fue un escéptico hasta el final. Pero Ziggs y los demás expertos en hexplosivos le demostraron que eran capaces de crear un espectáculo de fuegos artificiales maravilloso. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC141":["Estribillo heroico","Concede +2|+1 a 2 aliados esta ronda.","","\"Y allí estaban los héroes, luchando con gran esmero...\"\n\"... ¡luchando con gran trasero! jejejejeje\"\n\"¡N... no! ¡Peppy, si vas a interrumpirme, al menos que no sea en los momentos dramáticos!\". \n- Relatos en torno a una fogata yordle","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC209":["Defensa antiestrés","Convierte las estadísticas de una unidad en 1|6 en esta ronda.","","Las gallinatrices son unas monturas leales y rápidas en circunstancias normales. Sin embargo, si se ven sometidas a mucho estrés, pueden reaccionar de forma... un tanto inusual.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC210":["Escupellamas","Otorga +2|+0 e Impacto a un aliado.","","\"¡Hasta que no empiezan a aullar, no está lo suficientemente caliente! Je, je\". - Rumble","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC013":["Tentáculos traviesos","Tu oponente descarta su carta de menor coste.","","\"Nota mental: en la próxima expedición, los objetos de valor siempre delante\". \n- Entrada del día 19 del diario ecológico del conchólogo","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC100":["Trufita","Golpear: Coloca 3 Boletus venenosos en el mazo enemigo.","","\"¿Qué dices? ¿Que dos de los reclutas estaban investigando el bosque y se encontraron con un monstruo de hierba terrible y que ahora podrían morir entre terribles sufrimientos? ¡Te sigo!\". - Teemo","Unidad",["PERRO"],["Ciudad de Bandle"],"COMÚN"],"05BC098":["Catalizador retorcido","Golpear: Otorga a Oscuridad 1 de daño adicional esté donde esté.","","La oscuridad adopta todo tipo de formas y tamaños. Algunas de ellas son increíblemente adorables.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC122":["Yordle principiante","Cuando invocas a otro yordle, consigo +2|+0 esta ronda.","","\"Gigantus cespedus. Estas terroríficas criaturas se tumban en la hierba para camuflarse y atacan a los pobres desgraciados que les ponen un pie encima. Si te encuentras con alguna, ¡sal por patas!\". - Ava hazañosa","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC120":["Capitán yordle","Cuando invocas a otro aliado con un poder equivalente o inferior al mío, consigue +1|+1.","","\"¡Aventurarse significa encontrar a malotes y convertirlos en colegas!\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC046":["Puño de trueno","Cuando se me invoca, si has invocado 1 Puño de trueno esta partida, me transformo en Masa: Trueno rompedor.","","Cuando Masa golpeó el objetivo de entrenamiento, del puño le salió un fogonazo relampagueante que hizo que la madera se rompiera en dos y se le erizara el vello de las manos. Tiró de la cuerda para volver a coger la mano de bronce y reflexionó sobre su entrenamiento: por fin estaba preparado. De pronto, un rugido monstruoso resonó en la distancia.","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC018":["Caballero pomposo","","","\"Novecientos noventa y ocho... Novecientos noventa y nueve... ¡Mil! Ya hemos llegado, Bawky, y estás igual de impecable que siempre. Venga, ¡ahora me toca a mí!\".","Unidad",["YORDLE"],["Ciudad de Bandle","Demacia"],"RARA"],"05BC132":["Tiro destructor","Cuesto 2 menos si tienes 1 Tristana o si has jugado cartas de 4 o más regiones en esta partida.\nInflige 3 de daño a una unidad.","","Cada catablam alberga en su interior un catapum que espera su momento.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC168":["Sapo moteado","Fin de ronda: Si has infligido daño al nexo enemigo esta ronda, me transformo en Giga-gromp.","","Durante generaciones, los yordles del valle de Nakotak habían intentado entender a sus vecinos gromp. Primero, el jefe Hegabo intentó pincharlos con un palo. Después, el jefe Babobu intentó pincharlos con un palo. El jefe Nakotak tenía un nuevo e ingenioso plan: iba a pincharlos con un palo.","Unidad",[],["Ciudad de Bandle"],"RARA"],"05BC014":["Pequedáctilo","Fin de ronda: Si has infligido daño al nexo enemigo esta ronda, me transformo en Terrordáctilo.","","Las criaturas del valle de Nakotak son tan variadas y peculiares como el lugar que habitan... e igual de propensas a explotar.","Unidad",["AVE"],["Ciudad de Bandle"],"COMÚN"],"05BC138":["Manitas","La primera vez que descartas una carta o infliges daño al nexo enemigo, consigo +2|+1.","","\"Vale, buena pelea. Habéis estado genial. Ahora limpiad esta chatarra y, eh, ya sabéis como va la cosa: cualquier cosa salvable, arregladla y a la tienda, ¡que volveremos a vendérsela! ¡JA, JA, JA, JA!\". - Karl, Jefe de la arena","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"05BC198":["Foto de grupo","Inflige 1 de daño a una unidad. Si tienes 4 aliados o más, inflige 2 de daño.","","\"Vale, esta es para el boletín de noticias. ¡Y que no se os olvide sonreír! ¡Uno..., dos..., tres...!\". - Tristana\n","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC181":["Posición de la nube","Concede +2|+0 y \"Fin de ronda: Me retiro\" a un aliado esta ronda.","","\"¡Vuelve a respirar y halla la fuerza!\". - Monje de viento","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC160":["Poro prehistórico","","","Antiguamente, los poros tenían la cabeza mucho más gruesa en comparación con los de ahora, por lo que eran un poco más tontos, pero mucho más cabezones.","Unidad",["PORO"],["Ciudad de Bandle","Freljord"],"COMÚN"],"05BC005":["Doncellas de las algas","Golpe al nexo: Crea 1 Mofa en la mano.","","\"Querido yo: he tenido un sueño de lo más extraño. Estaba buscando mi sombrero de conchas entre las algas marinas cuando, de repente, oí una melodía maravillosa. Justo después, me veo aquí sentado, pluma en mano, escribiendo estas palabras. No recuerdo haberme sentado para echarme una siesta...\".\n- Entrada del día 22 del diario ecológico del conchólogo","Unidad",[],["Ciudad de Bandle"],"RARA"],"05BC020":["Ayudante de la biblioteca","Golpe al nexo: Roba un hechizo de coste 3 o menos.","","\"¡Jelly es mi MEJOR COMPI! Bueno, después de ti, Libro, claro. Y de Norra. Bueno... ¡Jelly es mi TERCER MEJOR COMPI! Sigue estando bastante bien, ¿no?\". - Yuumi","Unidad",["HADA"],["Ciudad de Bandle"],"COMÚN"],"05BC049":["Conchólogo","Jugar: Manifiesta un hechizo de tus regiones de coste 3 o menos.","","\"Hoy no cabe duda de que es un día especial: ¡toca explorar las profundidades! Espero que todo salga... de MARavilla. ¡Jo, jo!\". \n- Entrada del día 1 del diario ecológico del conchólogo","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC001":["Minimutación","Transforma a una unidad en Minipeludito 3|3 y lo silencia.","","\"¡Ay, ay, qué cosa tan mona! ¡Tan adorable! ¡Y pequeñita!\".\n- Veigar","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC026":["Caminos ocultos","Cuesto 2 menos si has creado 2 o más cartas en esta partida. Roba 2.","","Solo unos pocos forasteros saben cómo llegar hasta Ciudad de Bandle, pero las marcas de las rocas y los árboles de Runaterra son una pista estupenda para aquellos que saben qué están buscando.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC152":["Viajeros esquivos","Cuando se me invoca, todos los jugadores roban 1 carta. Después, el oponente descarta la carta de mayor coste.","","\"El peor viaje de la historia\". - Elle","Unidad",["YORDLE"],["Ciudad de Bandle","Piltover y Zaun"],"COMÚN"],"05BC070":["Ava hazañosa","Cuando se me invoca o en Fin de ronda: Coloca 3 Boletus venenosos en el mazo enemigo.\nLas trampas de las cartas enemigas se duplican al activarse.","","\"Regla 378: ¡Un buen explorador siempre actuará con valentía, estará siempre preparado y siempre al acecho!\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"05BC015":["Lagarto chiquito","Fin de ronda: Si has infligido daño al nexo enemigo esta ronda, me transformo en Lagarto de lava.","","\"¡Cómete el pimiento!\", gritó Nakotak. \"¡No, cómetelo TÚ!\", replicó Jojo. Mientras discutían, una pequeña lagartija que perseguía a una mosca se coló entre ellos. Ambos yordles miraron al reptil, luego al pimiento y después el uno al otro. De existir las bombillas, una se habría encendido.","Unidad",["REPTIL"],["Ciudad de Bandle"],"COMÚN"],"05BC145":["Escudera yordle","Jugar: Crea 1 Escudito o 1 Lancita en la mano.","","\"Mi lanza también perteneció a una gran heroína... ¡Poppy la tuvo en sus propias manos un minuto entero!\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC140":["Trineo de poros","Atacar: Invoca 1 poro aleatorio de coste 1 en ataque.","","\"¡Y luego el poro ece de Bobjim dijo \"¡Por ahí!\", y allá que ce fueron, hacia el horizante, con el rezto de poroz correteando con la lengua fuera, luchando por no quedarce atráz!\".\n- Ingvar, la Joven","Unidad",["PORO"],["Ciudad de Bandle","Freljord"],"ÉPICA"],"05BC129":["Jefe de la arena","","","\"Nace un imbécil cada minuto y yo voy a sacarle provecho a todos y cada uno... ¡Esta arena de mechas va a ser una mina de oro!\".","Unidad",["YORDLE"],["Ciudad de Bandle","Noxus"],"COMÚN"],"05BC004":["Nutriarrinco","Cuando se me invoca, crea 1 Mofa en la mano.","","\"Los nutriarrincos, curiosos y juguetones, son unas criaturas de lo más alegres. ¿Nutriarrincos u orninutrias? A ver, ¿yo no me había traído un tercer bocata?\". \n- Entrada del día 7 del diario ecológico del conchólogo","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"05BC155":["Monje de fuego","Cuando invocas a otro aliado, consigo +1|+0.","","\"Las chispas se convierten en un resplandor embravecido. ¡Somos las ascuas de vuestra destrucción!\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC104":["Fuerza primigenia","Otorga +2|+2 e Impacto a un aliado.","","Sí, es muy bonito. Sí, tiene mala leche. No, no quieres comprobarlo.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC218":["Auxilio de las hadas","Crea 1 Buhogatito hambriento en la mano y otorga +1|+1 a las hadas aliadas de la mano.","","\"¿Pero quién sigue alimentando a estas cosas?\". - Poppy","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC192":["Bombarderos gemelos","Cuando se me invoca, crea un hito aleatorio de coste 2 o menos en la mano.","","El artilugio Bombatómico-X recargado ha hecho exactamente lo que tenía que hacer: sembrar el caos. Y, además, luego ha sido muy fácil aparcarlo en paralelo. ","Unidad",["YORDLE"],["Ciudad de Bandle","Shurima"],"COMÚN"],"05BC162":["Jefe Nakotak","Cuando un aliado se transforma, se cura por completo y consigue +1|+1 e Impacto.","","El jefe Nakotak se declaró líder de la tribu tras encontrar un enorme hueso de dinosaurio entre la nieve que rodeaba su pueblo. Nadie se preguntó por qué un hueso de dinosaurio convertía a Nakotak en líder, pero tampoco les importaba demasiado. Muy típico de ellos.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC032":["Farol reluciente","Cada ronda, la primera hada que juegas cuesta 2 menos.","","\"¡El farol sigue a Norra, las polillas lunares al farol, y los ratones a las polillas! ¡Sigue, sigue!\".","Unidad",["HADA"],["Ciudad de Bandle"],"RARA"],"05BC166":["Palito","Inflige 1 de daño a cualquier unidad o estructura. Roba 1.","","Primera regla de la experimentación: dale con un palo y descubre lo que ocurre.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC006":["El Arsenal","Cuando se me invoca, consigo una palabra clave aleatoria por cada hito aliado que hayas destruido en esta partida.\nCuando destruyes un hito aliado, consigo una palabra clave aleatoria.","","Allá donde iba Ziggs, Arnie lo seguía con total serenidad, el complemento perfecto para la personalidad entusiasta y caótica de Ziggs. Sus tareas iban desde asegurarse de que había munición suficiente y apagar incendios hasta taparle las orejas a Ziggs cuando a este se le olvidaba, para variar, protegerse los oídos. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"05BC110":["Escalador erudito","","","\"Que sí, que ya me has contado lo mucho que le gustas tú, el té, los calcetines, los botones y coleccionar cositas, ¡pero es que aún no me has dicho qué aspecto tiene!\". ","Unidad",["YORDLE"],["Ciudad de Bandle","Targon"],"COMÚN"],"05BC063":["Guerrera tornado","Cuando se me invoca, consigo +1|+0 y una palabra clave aleatoria.\nMantengo esta mejora de las estadísticas y palabras clave cuando me retiro.","","La Guerrera tornado mantiene la calma con ejercicios de respiración... y canalizando su agitación interna en un huracán despiadado de cuchillas letales. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC217":["Hada retoño","Manifiesta un hada y le otorga +1|+1.","","Todo ser vivo necesita sustento. Las hadas no son diferentes al resto, aunque puede resultar difícil descubrir exactamente para qué lo emplean.","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC180":["Acelerar","Retira a una unidad con 3 o menos de poder.","","\"¡Somos rápidos! \"¡Somos el viento!\". - Kennen","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC040":["Intercambio de talismanes","Manifiesta 1 Nutriarrinco o uno de los 2 hechizos de tus regiones de coste 3 o menos.","","\"¡Suelta mi bocata ahora mismo!\". - Conchólogo","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC213":["Golpazo","Inflige 1 de daño a un enemigo y lo aturde.","","\"¡Ahanga!\". - Gnar","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC208":["Carga heroica","Un aliado golpea a un enemigo. Si sobrevive, lo aturde.","","\"¡Muévete!\". - Poppy","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC085":["Rata de cloaca granuja","Jugar: Descarta 1 para Manifestar un yordle mecha y le otorga Escudo de hechizos.","","\"¡Que se calle ya! ¡Con todo este ruido no puedo ni oírme contar todo este dinero!\". - Karl, Jefe de la arena","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC112":["Plántula de piña explosiva","Jugar: Consigo Barrera esta ronda o consigo Impacto.","","Las plántulas de piña explosiva son criaturas tímidas y, aunque lo más probable es intenten escapar, si se ven amenazadas...","Unidad",["HADA"],["Ciudad de Bandle","Jonia"],"COMÚN"],"05BC135":["Redoble","Un aliado golpea a un enemigo. Si el aliado es de varias regiones, vuelve a golpear al enemigo.","","\"Bellota M1-85: un fusil de calibre de roble totalmente automático con una mira de madera del bosque de Bandle y acabado en color mora. ¡Hoy mamá tendrá algo estupendo para cocinar!\". - Comando de Bandle","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"05BC084":["Chillón","Jugar: Descarta 1 para Manifestar un yordle mecha.","","De poca estatura pero gran personalidad.","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"05BC184":["Baladistas balbuceantes","Cuando se me invoca, crea 1 Buhogatito hambriento en la mano.","","\"¡Esta es mi oda\na Poppy la fortachona!\n¡Poppy la poderosa, la más hermosa... como una osa!\". \n- Letra tachada de Libro de canciones de Reginaldáctilo y Faltimisquez, unos bardos extraordinarios","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC116":["Alcalde de Ciudad de Bandle","Cada ronda, la primera unidad multirregión que juegas cuesta 1 menos.\nJugar: Manifiesta un adepto de varias regiones.","","No se sabe muy bien si en Ciudad de Bandle han llegado a votar al alcalde alguna vez, pero tener un bigote enorme seguro que es un requisito obligatorio para la alcaldía.","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"05BC111":["Yordles a las armas ","Concede a los aliados +2|+2 esta ronda. Si has jugado cartas de 4 o más regiones, les concede +3|+3 en su lugar.","","\"Ahora mismo... molamos un montón\". - Tristana","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC224":["Transposición","Retira a un aliado. El siguiente aliado que juegues esta ronda de coste igual o inferior cuesta 0.","","\"¡Cuerpo veloz, mente veloz!\". - Kennen","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC130":["Calentón","Atacar: Otorga +1|+1 y una palabra clave aleatoria al campeón de más arriba del mazo.","","Las barbacoas veraniegas de Otto gozaban de cierta reputación. Aunque era un verdadero entusiasta de la parrilla, sus invitados solo podían elegir entre carne \"muy hecha\" o \"extremadamente hecha\".","Unidad",["YORDLE"],["Ciudad de Bandle","Shurima"],"COMÚN"],"05BC191":["Veredicto de la guardiana","Coloca una unidad enemiga en la parte superior del mazo enemigo.","","\"¡Y no vuelvas!\". - Poppy","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC052":["Basura, divino tesoro","Llena tu mano con cartas aleatorias con Fugaz de coste 0. Solo puedes jugar 3 cartas más esta ronda.","","La basura de un mortal es un montón de piezas de repuesto para un yordle.\n","Hechizo",[],["Ciudad de Bandle"],"RARA"],"05BC050":["Benémona","Cuando se me invoca, se crean 2 Mofas en la mano.","","\"Aquellos con tendencia a las náuseas deberán acercarse a este gigante bonachón con sumo cuidado. Vuestro estómago os lo agradecerá... Y hablando de estómago, no debería haberme comido el segundo bocata de champiñones...\". \n- Entrada del día 3 del diario ecológico del conchólogo","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"05BC094":["Acólito bulboscuro","Cuando se me invoca, crea 1 Oscuridad en la mano si no tienes.","","\"Claro, no me cabe duda de que el tipo del tejado tiene muchas cosas que contar. Todos lo sabemos. Lo que pasa es que no tenemos ni idea de qué es lo que dice exactamente\".\n- Sastre arrogante","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC146":["Pintora de Bandle","Jugar: Descarta 1 para crear un adepto de varias regiones en la mano y reducir en 1 su coste.","","\"Pintar no consiste en copiar lo que ves, sino en expresar tu visión del mundo. Y ahora mismo, veo que te has vuelto a mover. ¡Por favor, no muevas ni un pelo!\".","Unidad",["YORDLE"],["Ciudad de Bandle","Piltover y Zaun"],"COMÚN"],"05BC235":["Herrero yordle","Atacar: Concede Ataque rápido a los aliados con un poder equivalente o inferior al mío esta ronda.","","\"Poppy nunca me hace ni caso, así que presta atención: no depende del martillo, sino del yordle que lo porta\".\n","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC175":["Telescopio zancudo","Jugar: Manifiesta un celestial que cueste 3 o menos, épico, o un adepto de varias regiones.","","Lo más raro no fue que el telescopio se pusiera en pie, se estirara y comenzara a andar por la habitación, sino que quisiera abrigarse, así que se tuvo que buscar una bufanda cómoda adecuada.","Unidad",["HADA"],["Ciudad de Bandle","Targon"],"RARA"],"05BC182":["Ataque del rayo","Retira a un aliado para infligir 2 de daño a cualquier unidad o estructura.","","\"¡Primero el chasquido, después el estruendo!\". - Kennen","Hechizo",["ELEMENTAL"],["Ciudad de Bandle"],"RARA"],"05BC069":["Yordle ponente","Atacar: Crea 1 Dardo venenoso Fugaz en la mano.","","No le deis cuerda.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC057":["Sastre arrogante","Cuando se me invoca, reduce en 1 el coste de tu Oscuridad esté donde esté.","","\"A la hora de crear una conspiración, es importante que cada uno de los dementes miembros lleve puesto algo único a la reunión de supervillanos. Por ejemplo, uno de mis compañeros tiene un estilo mortal...\".\n- Extracto del capítulo 4 de Cómo convertirse en supervillano, de lord Veigar","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"05BC108":["Explorador yordle","Cuando invocas a otro Yordle, consigue +1|+0.","","\"La gloria de la exploración no tiene precio, pero los mejores descubrimientos siempre son... ejem... rentables\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"05BC183":["Hada anciano","Cuando se me invoca, crea 1 Buhogatito hambriento en la mano.\nCuando invocas a otra hada, le otorga +1|+0.","","\"Venid y sentaos, que no será nada,\npues voy a contaros la triste historia del anciano hada.\nCada día alimentaba a las hambrientas aves,\ncon una extraña mezcla de semillas y agave...\".\n- Cuento de Ciudad de Bandle","Unidad",["HADA"],["Ciudad de Bandle","Jonia"],"RARA"],"05BC188":["Concháceos curiosos","Cuando eliges una carta que no sea un campeón de las opciones aleatorias, crea una copia en la mano y reduce su coste en 1.","","Los concháceos, tímidos y escurridizos por naturaleza, se ocultan en las conchas hasta que les pica mucho la curiosidad. Una vez salen de ellas, sacan a relucir su personalidad juguetona, llegando incluso a imitar los sonidos de otros seres marinos para gastar bromas.","Unidad",[],["Ciudad de Bandle"],"ÉPICA"],"05FR001":["Chamán del lóbrego","Fin de ronda: Si has infligido daño al nexo enemigo esta ronda, me transformo en Furioso del lóbrego.","","\"¡Jamás morimos como cobardes! Si caemos, caeremos con garras y colmillos hendidos, honrando así al lóbrego\". - Vidente Hyara","Unidad",[],["Freljord"],"COMÚN"],"05FR002":["Chamán del mamut","Fin de ronda: Si has infligido daño al nexo enemigo esta ronda, me transformo en Furioso del mamut.","","Cuando son atacados por depredadores, las manadas de mamuts rodean a sus crías y hembras preñadas. Y es por esto que los chamanes del gran espíritu del mamut no solo apelan a la fuerza física de su espíritu, sino también a la fuerza de la unidad con que protege a su familia.","Unidad",[],["Freljord"],"RARA"],"05FR013":["Udyr","Cuando se me invoca o al golpear: Crea 1 Cambio de posición en la mano o, si ya tienes una copia, su coste se reduce a 0.","Has jugado a Cambio de posición 3 o más veces.","\"Los espíritus dan forma a nuestro mundo al igual que nosotros al suyo. Al extraer el poder de ellos, también lo extraemos de nuestro interior\".","Unidad",[],["Freljord"],"Campeón"],"05FR016":["Llamada del chamán","Crea 2 Cambios de posición Fugaces de coste 0 en la mano.","","\"Seréis testigos... Grandes espíritus de garras y colmillos, escamas y plumas. Y, en ese momento, os inundará el temor y el asombro, pues sabréis que los dioses antiguos no nos han olvidado\". - Vidente Hyara","Hechizo",[],["Freljord"],"COMÚN"],"05FR012":["Vidente Hyara","Cuando se me invoca, crea 1 Cambio de posición en la mano.\nLa primera copia de Cambio de posición que juegues en cada ronda cuesta 0.","","Venerada por todos, la gran vidente Hyara perdió la vista hace mucho tiempo, aunque nunca dejó de ver a través de los ojos de los halcones y las águilas que anidan en la cima de su montaña. Ahora, noticias problemáticas la obligan a volver de su exilio... esperando que sus presagios no sean más que meras visiones.","Unidad",[],["Freljord"],"RARA"],"05FR014":["Ira de Freljord","Jugar: Aplica Escarchar a un enemigo.\nLos enemigos con 3 de poder o menos no pueden bloquear.","","\"Yo también pasé por ello, hace años... Primero llegó el frío, mordaz e implacable. Luego una tormenta, furiosa y destructora. Por último un rugido, tan feroz que me heló los huesos. Caí de rodillas y recé por que no hubiéramos cometido un grave error. Invocar a un gran espíritu es implorar su venganza... y su misericordia\". - Vidente Hyara ","Unidad",[],["Freljord"],"ÉPICA"],"05FR017":["Bestia interna","Concede +1|+1 a un aliado esta ronda. Crea 1 Cambio de posición en la mano.","","\"Reuníos, espíritus. Reuníos...\". - Udyr","Hechizo",[],["Freljord"],"COMÚN"],"05FR006":["Oradora del colmillo","Jugar: Inflige 1 de daño a ambos nexos.","","Pocas familias de chamanes han servido a la Garra Invernal tanto tiempo como la familia de Chuluun. Como chamán de la gran morsa, anuncia y presagia las bondades del mar... y sus peligros. ","Unidad",[],["Freljord"],"COMÚN"],"05FR015":["Espíritus liberados","Otorga +1|+1 a los aliados estén donde estén. Después, inflige 1 de daño a todo.","","\"Ancestros, protegednos contra el frío que nos invade, y expulsad a nuestros enemigos con tormentas de viento y hielo. Pues no os hemos olvidado, ni los honores que os corresponden\".\n- Plegaria del chamán del lóbrego","Hechizo",[],["Freljord"],"RARA"],"05FR005":["Osteomante","Cuando sobrevivo al daño, inflige 1 de daño al nexo enemigo.","","Pocos adivinan el futuro tan bien como los chamanes que sirven al Alce de Hueso. Y muchos menos pueden soportar la visión de la inminente muerte de los que vienen buscando sus presagios.","Unidad",[],["Freljord"],"COMÚN"],"05FR004":["Nómada vulpina","Cuando se me invoca, crea 1 Cambio de posición en la mano.","","\"Ansioso y cauteloso. Rápido y silencioso. El camino del zorro es poder ver sin ser visto. En los viajes y en la guerra, un líder sabio honra a quienes siguen al espíritu del zorro. Pues ninguna batalla se gana sin exploradores\". - Madretriz Vrynna","Unidad",[],["Freljord"],"COMÚN"],"05IO003":["Antiguo sin rumbo","Cuesto 2 menos por cada unidad que hayas retirado en esta ronda.","","\"Himon'she, es un honor viajar a tu lado. Los otros me cuentan que no existe nadie más sabio que tú. ¿Hacia dónde nos dirigimos?\".\n\"Ay, madre. ¡Yo te estaba siguiendo a ti!\". - Ahri y el Antiguo sin rumbo","Unidad",[],["Jonia"],"COMÚN"],"05IO004":["Ahri","Atacar: La primera vez que Ataco y golpeo, me intercambio por el aliado de mi derecha y después se Retira.","Has retirado a 5 unidades o más.","Se buscaba a sí misma en los secretos de los demás. Se veía a través de los ojos de muchos otros. A medida que se acercaba al bosque, se preguntaba si no sería más que otra lente o si, solo esta vez, encontraría un espejo.","Unidad",[],["Jonia"],"Campeón"],"05IO023":["Hechizar","Retira a un aliado y le otorga Vulnerable a un enemigo esta ronda.","","\"Cuéntame un secreto\". - Ahri","Hechizo",[],["Jonia"],"COMÚN"],"05IO020":["Cantavientos","Jugar: Retira a una unidad.","","El caos da garras a los mansos. Un lobo persigue a su presa y una rama caída le impide alcanzarla. Un halcón se lanza en picado y cae a causa de un inesperado vendaval. Somos la rama. Somos el viento.","Unidad",[],["Jonia"],"COMÚN"],"05IO007":["Sai'nen de mil colas","Cuando se me invoca, roba 2 cartas y otorga +1|+1 a los aliados esta ronda.","","El bosque cuenta sus secretos sin reservas... pero pocos tienen el valor de preguntar.","Unidad",[],["Jonia"],"ÉPICA"],"05IO021":["Plántula del Sauce Divino","Jugar: Retira a un aliado para invocar una copia endeble del mismo. Cuenta atrás - 3: Invoca otra copia endeble del aliado.","","Antaño, el Sauce Divino crecía en Omikayalan. Puede que lo que florece en ese lugar a partir de ahora sea más fuerte, o quizá más débil. Lo que importa es que es nuevo.","Hito",[],["Jonia"],"RARA"],"05IO024":["Hijos del bosque","Retira a un aliado o gasta 8 de maná para invocar copias Endebles de los 3 adeptos más fuertes que hayas retirado esta partida.","","Los recuerdos tienen colmillos.","Hechizo",[],["Jonia"],"ÉPICA"],"05IO001":["Guardiana del bosque","Cuando se me invoca, consigo +1|+0 y Elusión esta ronda.","","\"Dicen que no hablas para salvar a los demás del peso de tu sabiduría. Mmm... Apuesto a que simplemente te has cansado de responder preguntas\". - Ahri","Unidad",[],["Jonia"],"COMÚN"],"05IO025":["Matriarca con colas","La primera vez que retiras a un adepto en cada ronda, invoca una copia endeble e idéntica del mismo.","","Un misterio es más grande que la conclusión del mismo.","Unidad",[],["Jonia"],"RARA"],"05IO026":["Luto","Golpe al nexo: Me Retiro.","","Si veneras la caza, debes detenerte a llorar por las presas caídas.","Unidad",[],["Jonia"],"RARA"],"05IO006":["Siete vidas","Invoca 1 Guardián liminar.","","El bosque necesitaba un guardián, alguien que pudiera vigilar sus lindes durante años e incluso siglos sin moverse. Gai'sh fue el voluntario entusiasta y demostró su compromiso de inmediato con una siesta de diez años.","Hechizo",[],["Jonia"],"ÉPICA"],"05IO002":["Capa de memoria","Elige un aliado que sea objetivo de hechizos Veloces, hechizos Lentos o habilidades del enemigo con 1 solo objetivo aliado. Los detiene.","","Una flecha no conoce ni la intención del cazador ni la valía de su presa.","Hechizo",[],["Jonia"],"COMÚN"],"05SH014":["Xerath","Cuando destruyes un hito aliado, inflige 1 de daño al enemigo más débil.","Has destruido 4 o más hitos aliados.","\"Una vez fueron amigos, pero el tiempo y la afinidad que tenían los convirtieron en hermanos. No cabe duda de que Azir no podría haber conseguido todo lo que consiguió sin Xerath a su lado\". \n- Escriba Kah'Nir, Historia de la Hueste Ascendida","Unidad",["ASCENDIDO"],["Shurima"],"Campeón"],"05SH017":["Heraldo del Mago","Cuando se me invoca, si has destruido 4 o más hitos aliados en esta partida, otorga a tus campeones +2|+2 y Abrumar estén donde estén.","","La heraldo extendió sus brazos con amplitud mientras alzaba la cara hacia el sol, que brillaba de color rojo sangre sobre Shurima. \"Postraos ante el Mago Ascendente\", exhaló de forma solemne, mientras su voz retumbaba por el círculo de columnas en ruinas. \"¡Postraos ante Xerath!\".","Unidad",[],["Shurima"],"RARA"],"05SH011":["Devoto eterno","Último aliento: Invoca 1 Sarcófago.","","Por mucho que la tumba estuviera repleta de riquezas, de poco le sirvió a los exiliados y los caídos.","Unidad",[],["Shurima"],"RARA"],"05SH022":["Duelo en el desierto","Concede a un enemigo -2|-0 esta ronda. Un aliado y ese enemigo se golpean el uno al otro.","","\"Solo quien no conoce el desierto no lo teme de verdad\". \n- Proverbio de Shurima","Hechizo",[],["Shurima"],"COMÚN"],"05SH003":["Obelisco de poder","Cuenta atrás de 3 o cuando se me invoca o me destruyes: Otorga +2|+0 al aliado más fuerte.","","Unos pilares brillantes y chisporroteantes surgieron de la arena, elementos alterados de poder que reforzarían al ya poderoso ejército de Xerath.","Hito",[],["Shurima"],"COMÚN"],"05SH016":["Acólito ruinoso","Jugar: Destruye un hito aliado para concederle +1|+1 a Acólitos ruinosos aliados estén donde estén.","","Todos los acólitos de Xerath entregaron algo a cambio de poder, pero sus fieles más poderosos eran meras cáscaras de su antiguo ser y servían como conducto y fuente de poder de la nueva energía del emperador.","Unidad",[],["Shurima"],"COMÚN"],"05SH018":["Esclavitud de la desolación","Invoca 1 Estatua en estasis para guardar en su interior todas las unidades e hitos aliados que murieron o se destruyeron esta ronda.","","La energía mágica no desaparece, solo cambia de forma.","Hechizo",[],["Shurima"],"ÉPICA"],"05SH012":["Altar alzado","Cuenta atrás de 3 o cuando me destruyes: Invoca 1 Dami'yin, el Desencadenado.","","\"En cada lugar poderoso, se alzará un obelisco, un instrumento a través del cual el Mago Ascendente obtendrá el poder que se oculta bajo las arenas\". - Heraldo del Mago","Hito",[],["Shurima"],"ÉPICA"],"05SH020":["Constructo de la desolación","Crea 1 Acólito ruinoso o Obelisco de poder en la mano.","","\"¡Crearé Shurima a mi imagen y semejanza!\". - Xerath","Hechizo",[],["Shurima"],"COMÚN"],"05SH015":["Profetisa de la arena","Cuando se me invoca, roba 1 carta. Si has robado un hito, este efecto se repite.","","El horizonte ante ella trinó con energía. Donde los demás no veían más que arena y cieno, ella veía las líneas ley, lazos de energía pura que estaban ahí para ella.","Unidad",[],["Shurima"],"ÉPICA"],"05SH004":["Energía desatada","Concede +2|+1 a un aliado esta ronda o destruye un hito aliado para concederle +4|+2 esta ronda.","","\"¡Arrancaré el poder del desierto y destruiré a aquellos que se opongan a mí!\". - Xerath","Hechizo",[],["Shurima"],"COMÚN"],"05SH002":["Caminante de los residuos","Cuando destruyes un hito aliado, se me otorga +1|+1.","","Los acólitos lo consiguieron antes de salir en busca de Xerath. Ahora que han estudiado lo mismo que él en su momento, son imparables.","Unidad",[],["Shurima"],"COMÚN"],"05SH007":["Rito del arcano","Destruye un hito aliado o una de tus gemas de maná para infligir 4 a una unidad.","","\"Un pequeño sacrificio a cambio de un gran poder\". - Xerath","Hechizo",[],["Shurima"],"RARA"],"05NX009":["Alma perdida","Cuando se me invoca o se me descarta, crea 1 Renacida de hojas gemelas en la mano.","","Los demacianos corrían hacia sus murallas cuando se encontraron con la muerte que salía de ellas. A pesar de que pudieron acabar con algunos soldados de la Legión Gris, la oleada oscura de la guerra demostró ser imparable.","Unidad",[],["Noxus"],"ÉPICA"],"05NX006":["Granadero renacido","Para jugar esta carta, descarta 1.\nCuando se me descarta, se invoca una copia exacta de mí.","","\"Tenemos un pequeño problemilla. Aunque la mayoría de aquellos a los que revivimos odian volver a la vida, este parece que entiende su situación y disfruta de las oportunidades que se le han concedido. Qué curioso\".\n- Notas del Dr. Esslanger","Unidad",[],["Noxus"],"COMÚN"],"05NX005":["Belicista ancestral","Cuando se me descarta, otorga +2|+0 a tu aliado más fuerte.","","Conforme crecían los poderes de Lady Noradi, se preguntaba si estos echarían raíces en los cuerpos enterrados en las tumbas más antiguas de Noxus. Para ella, la luz de la vida no era más que un leve titileo en los cuerpos. Sin embargo, las sombras de la guerra aún estaban presentes en esas tenues llamas.","Unidad",[],["Noxus"],"RARA"],"05NX001":["Sion","Cuando se me descarta, otorga a tu aliado más fuerte Abrumar y me transporto al mazo.\nConsigo +1|+0 por cada carta que hayas descartado en esta partida (hasta un máximo de +7|+0).","Has descartado o invocado unidades hasta un total de 35 o más de poder.","Sion vio unos destellos fugaces de recuerdos borrosos. Legiones paradas ante él. Galardones. Coronas. Guerra. El estertor de la muerte de un rey. La nada. Sangre. Pero tal y como llegaron los lazos blancos en el viento, desaparecieron.","Unidad",[],["Noxus"],"Campeón"],"05NX003":["Sal y puntos","Para jugar esta carta, descarta 1.\nInvoca 1 Granadero renacido y le otorga +2|+0 esta ronda.","","\"Álzate de nuevo, hijo mío...\". - Dr. Esslanger, médico reflexivo","Hechizo",[],["Noxus"],"RARA"],"05NX015":["Justiciero caído","Cuando se me invoca, concede No puede bloquear al enemigo más débil.\nÚltimo aliento: Crea 1 Justiciero alzado en la mano.","","\"Los primeros minotauros a los que reviví eran unas bestias dóciles e inútiles. Ni siquiera el fulgor de la guerra ni el miedo a morir despertaban sus instintos\".\n- Notas del Dr. Esslanger","Unidad",[],["Noxus"],"RARA"],"05NX019":["¡Por la gloria!","Reputación: Cuesto 3 menos. Invoca 2 Trifarianas buscaglorias.","","Quienes persiguen la gloria no se detendrán ante nada.","Hechizo",[],["Noxus"],"RARA"],"05NX013":["Jinete caído","Cuando se me descarta, crea 1 Jinete alzado en la mano.","","\"Solo después de frotar las hojas de Sombranegra contra la armadura del jinete desapareció la maldad del basilisco. Estas plantas crecen en las montañas, al igual que las bestias, y son tan mordaces como venenosas\".\n- Notas del Dr. Esslanger","Unidad",[],["Noxus"],"COMÚN"],"05NX012":["Rugido del asesino","Para jugar esta carta, descarta 1. Elimina al enemigo más débil.","","\"Aliado, enemigo... Me da igual\". - Sion","Hechizo",[],["Noxus"],"COMÚN"],"05NX014":["Armas de los caídos","Inflige 3 de daño a una unidad e invoca 1 Rompescudos trifariano.","","\"¡Rompescudos!\". - Sion","Hechizo",[],["Noxus"],"COMÚN"],"05NX004":["Médico de ultratumba","Jugar: Descarta 1 para robar una unidad.","","Hubo un tiempo en el que el Dr. Esslanger era un médico respetado y jubilado que se había ganado su reputación a lo largo de años de duro trabajo. Sin embargo, no fue hasta la llegada de una joven mujer a consulta, con la sangre manchada de traición, que comenzó a servir a Noxus.","Unidad",[],["Noxus"],"COMÚN"],"05NX016":["La dama de sangre","Cuando descartas un aliado no Fugaz de la mano, crea una copia Fugaz idéntica en la mano.","","Al abrigo de la noche, Lady Faris Noradi sacó a la Legión Gris de la capital noxiana. Tardaron tres largas y duras semanas, pero por fin se acercaron al pequeño puesto avanzado demaciano que sus exploradores habían encontrado. Había llegado el momento de demostrar de lo que eran capaces.","Unidad",[],["Noxus"],"ÉPICA"],"05NX002":["Noble rebelde","Consigo +2|+1 cuando hayas descartado 3 o más cartas en esta partida.","","\"¿Qué hay mejor para infundir lealtad en un posible traidor que ser testigo del retorno de un conspirador caído que vuelve a la vida para luchar bajo el estandarte noxiano? Todos nos servirán, de una forma u otra\". - La dama de sangre","Unidad",[],["Noxus"],"COMÚN"],"05BW005":["Nami","Cuando lanzas un hechizo, concede +1|+0 al aliado más débil que no sea inmóvil.","Has jugado 5 o más hechizos con una Nami aliada en juego.","\"¿Te has despedido ya, joven Invocadora de Mareas?\".\n\"Sí, abuela\".\n\"¿Tienes miedo?\".\n\"Sí, abuela\".\n\"Bien, tener miedo significa ser prudente. Pero confía en ti misma, como nosotras confiamos en ti. Ahora, vete. Y que las corrientes te guarden\".","Unidad",[],["Aguas Estancadas"],"Campeón"],"05BW006":["Resaca","Inflige 2 de daño a un enemigo o al nexo enemigo de forma aleatoria y crea 1 Flujo en la mano.","","\"¡Presta atención al temperamento de la marea...\". - Nami","Hechizo",["ELEMENTAL"],["Aguas Estancadas"],"COMÚN"],"05BW002":["Saltamares aventurero","","","\"Claro, algunos sí que nos dan caza, como lo hacen con todo. Pero la mayoría de los terrestres que he conocido solo quieren pasárselo bien en el gran azul, al igual que nosotros. Todos somos iguales\".","Unidad",[],["Aguas Estancadas"],"COMÚN"],"05BW008":["Guardián abisal","Cuando lanzas un hechizo, consigo +2|+0 esta ronda.","","\"Gran parte de nuestra tribu piensa que Loto es un tanto enervante. Solo ven a un luchador incansable y la distancia en su mirada afligida. Pero yo sé qué habita en realidad en su corazón: miedo a no ser lo suficientemente fuerte como para salvarnos... y también un amor extraordinario\". - Tama, cantante marai","Unidad",[],["Aguas Estancadas"],"COMÚN"],"05BW011":["Almirante Shelly","Cuando lanzas 2 hechizos en cada ronda, otorga +1|+1 al resto de aliados.","","\"PRESTA ATENCIÓN, SOLDADO. TE AVISO DE QUE TENGO MÁS DE TRESCIENTAS BAJAS CONFIRMADAS Y QUE SOY EL ALTO ALMIRANTE DE LAS FUERZAS MARINAS. ASÍ QUE CUANDO TE DIGO QUE NADES, TÚ NADAS Y PUNTO, ¿ENTENDIDO? BIEN, ¡GRACIAS!\".","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"05BW003":["Maremoto","Inflige 1 de daño a dos enemigos diferentes seleccionados aleatoriamente y crea 1 Oleada rompedora en tu mazo.","","\"¡Océanos, desbordaos!\". - Nami","Hechizo",["ELEMENTAL"],["Aguas Estancadas"],"RARA"],"05BW004":["Avatar de las mareas","Si vas a recibir una gema de maná, en su lugar recarga tu maná de hechizos.\nCuando juegas un hechizo, crea un hechizo aleatorio en la mano de coste 3 o menos y le otorga Fugaz.","","Para los marai, Leo'lei es el heraldo que precede a un gran cambio. Se dice que cada vez que florece, sus gráciles alas afectan al flujo de las mareas.","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"05BW001":["Guardiana marai","Cuando se me invoca, invoca un adepto aleatorio de coste 1.","","Los marai rara vez desean alejarse de su hogar. Pero la curiosidad de Ai'la la acompaña desde su nacimiento y, aunque le debe lealtad a su tribu, se pasa todo el día soñando despierta con el día en el que por fin sea libre.","Unidad",[],["Aguas Estancadas"],"RARA"],"05BW010":["Abuela marai","Cuando se me invoca, crea en el mazo 5 hechizos aleatorios de coste 6 o más y reduce su coste a 3.","","La luz celestial de una piedra lunar protege el hogar ancestral de los marai. Cada cien años, su luz comienza a apagarse y se le encarga la búsqueda de otra piedra a una nueva Invocadora de Mareas, ya que, sin ella, el pueblo de los marai se sumiría en la oscuridad y caería en las garras de los horrores que anidan en las profundidades.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"05BW013":["Cantante marai","Cuando se me invoca, si has lanzado un hechizo esta ronda, consigo Elusión.","","\"El océano cree que la ola volverá de su viaje,\nconfía en la resaca, en el flujo, en el oleaje.\nRompen las olas contra la orilla, \nmientras el océano con el rugido de las mismas se maravilla\".\n- Verso de Serenata para la Invocadora de Mareas","Unidad",[],["Aguas Estancadas"],"RARA"],"05PZ015":["Jinete de la justicia","Cada vez que tu oponente roba una carta, coloca 1 Trampa con bomba destello entre las 8 cartas de más arriba del mazo enemigo.","","\"Se vio a la agente persiguiendo a la sospechosa a gran velocidad hasta una trampa que ella misma había creado. Tras arrestar a la sospechosa, la agente rellenó y presentó la multa por exceso de velocidad, afirmando de forma dramática que: 'La justicia es una calle de doble sentido'\".\n- Extracto del informe especializado de un Guardián","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"05PZ012":["Archivista de la comisaría","Jugar: Elige un hechizo entre las 5 cartas de arriba del mazo y crea una copia Fugaz exacta en la mano. Después, coloca esas 5 cartas en el mazo.","","Los detectives no son nada sin las pruebas. El trabajo de un archivista es recopilar hasta la más mínima información y abrir nuevos caminos donde antes no había nada.","Unidad",[],["Piltover y Zaun"],"RARA"],"05PZ026":["Cadena de montaje","Invoca 2 Trabajadores de la forja.","","\"¡Cambio de turno!\". - Jefa de la forja","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"05PZ019":["El más buscado","Elige a un jugador para que descarte su carta de menor coste y robe 3.","","\"Todo tiene un precio\". - Corina Veraza","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"05PZ031":["Albus Ferros","Cuando se me invoca, roba a Jayce. Atacar: Inflige 3 de daño al nexo enemigo. Por cada hechizo de coste 6 o más que hayas jugado esta partida, aumenta el número en 1.","","\"El magnánimo Albus Ferros ha vuelto a ser el foco de atención al superar notablemente la puja de los clanes Cadwalder y Giopara para hacerse con los derechos de patrocinio de la investigación del portal hextech de Jayce. Tal y como dice el refrán, un gran día para el clan Ferros es también un gran día para Piltover, y no cabe duda de que ayer fue un día magnífico para el clan Ferros\".\n- Extracto de un espacio patrocinado en el Diario de Piltover","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"05PZ027":["Explosión eléctrica","Inflige 3 de daño a un enemigo o al nexo enemigo y 3 a otro.","","\"¡Disparando!\". - Jayce","Hechizo",[],["Piltover y Zaun"],"RARA"],"05PZ022":["Jayce","Jugar: Consigo Ataque rápido o Contendiente.","Has jugado dos hechizos de coste 6 o más. Cuando subo de nivel, crea 1 Portal de aceleración en la mano.","\"Bueno, Rosa, como ya sabes, esta tecnología poderoformativa puede cambiar el mundo\".\n\"Es un trabajo revolucionario, Jayce. Esos coinhibidores se acoplan de una forma increíble\".\n\"¿Verdad? ¡Ha sido idea de Axel! ¿A que sí, amigo mío?\".\n\"Bueno, ya me conoces, colega, no me gusta presumir...\".","Unidad",[],["Piltover y Zaun"],"Campeón"],"05PZ017":["Gases del sumidero","Inflige 2 de daño a una unidad. Si se han añadido 2 o más cartas a tu mano esta ronda, inflige 3 de daño.","","\"Más vale que dejes que tomen un poco de aire. Los defensores del medioambiente no soportan el olor, pero la verdad es que... cuando uno se acostumbra, ¡no hay nada igual!\". - Vendedor ambulante de boletus","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"05PZ013":["Pacificadora de Piltover","Inflige 2 de daño a una unidad y coloca 2 Trampas con bomba destello entre las 8 cartas de más arriba del mazo enemigo.","","\"Esta es mi tarjeta\". - Caitlyn","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"05PZ020":["Emboscada","Concede +2|+0 a un aliado este turno. Si se han añadido 2 o más cartas a tu mano esta ronda, le concede Elusión esta ronda.","","\"Rodearemos la zona mientras usamos bombas de humo para ocultar nuestros movimientos...\". - Caitlyn","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"05PZ024":["Inversor del clan Ferros","Jugar: Manifiesta un hechizo de tus regiones de coste 6 o más.","","\"De lo poco bueno que tiene que el clan Ferros financie mi trabajo es trabajar codo con codo con Reggie. No solo es una de las personas más competentes con las que he trabajado, sino que también es un tipo estupendo\".\n- Extracto del diario de Jayce","Unidad",[],["Piltover y Zaun"],"COMÚN"],"05PZ010":["Información valiosa","Coloca 2 Trampas con bomba destello entre las 8 cartas de más arriba del mazo enemigo.\nRoba 1.","","\"A mi señal\". - Caitlyn","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"05PZ014":["Corina, mente maestra","Jugar: Coloca 5 Trampas con bomba destello entre las 5 cartas de más arriba del mazo enemigo o activa todas las trampas que haya en ellas.","","Corina sonreía mientras los Guardianes de Piltover derribaban su puerta y pisoteaban sus preciosas flores, que desprendieron nubes tóxicas de polen. Tal y como lo había planeado.","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"05PZ002":["Conocimiento privilegiado","Todos los jugadores roban 2 cartas.","","\"Es un caso popular. Acaba de venir un tipo también para echarle un vistazo. ¡Disfrútalo!\". - Archivista de la comisaría","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"05PZ021":["La Forja del Mañana","Cuando se me invoca, invoca 1 Trabajador de la forja. Cuando lanzas un hechizo que cueste 6 o más, muero y recargo tu maná de hechizos.","","Si Piltover es una ciudad guiada por la invención, entonces las forjas son los motores que la mueven.","Hito",[],["Piltover y Zaun"],"RARA"],"05PZ025":["Jefa de la forja","Golpear: Recuperas 1 de maná de hechizos.","","\"Solo se necesitan dos cosas para que una idea pase del papel a las manos. La financiación es una de ellas, y la otra es una buena forja. Y no solo hablo de las herramientas o las máquinas: si la persona al mando no es capaz de liderar, bueno, pues la idea se quedará ahí, plasmada en el papel\".\n- Jayce","Unidad",[],["Piltover y Zaun"],"COMÚN"],"05PZ006":["Caitlyn","Golpear: Coloca 2 Trampas con bomba destello entre las 8 cartas de más arriba del mazo enemigo.","Se han activado 5 o más de tus trampas.","Caitlyn siempre había sido una investigadora testaruda y rigurosa, lo cual hizo que ascendiera rápidamente en las fuerzas del orden de Piltover. Pero cuando tuvo que hacer frente a un tal \"caso C\", uno de los muchos que otros agentes habían abandonado, casi parecía que por fin había dado con la horma de su zapato. Casi.","Unidad",[],["Piltover y Zaun"],"Campeón"],"05PZ004":["Brigada de policía","Cuando se me invoca, crea 1 El más buscado en la mano.","","No tardamos mucho en descargar en silencio los materiales y preparar el golpe. Ahora solo quedaba esperar la señal de Caitlyn.","Unidad",[],["Piltover y Zaun"],"RARA"],"05PZ009":["Agente encubierto","Golpe al nexo: Coloca 2 Trampas con bomba destello entre las 8 cartas de más arriba del mazo enemigo.","","Zanye Asako, como todos los niños zaunitas, tuvo que crecer rápido en esas violentas y oscuras callejuelas. Tras perder a su hermano en uno de los muchos altercados entre bandas sin sentido, decidió unirse a los agentes de Piltover con la esperanza de que el sentido común y la ley hicieran de su hogar un lugar seguro.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"05PZ016":["Golpe de gracia","Coloca a un adepto enemigo en el mazo enemigo. El oponente roba 1.","","La gran ciudad de Piltover es el hogar de algunas de las mentes más privilegiadas de Runaterra. Las cárceles de Piltover también son el hogar de algunas de las mentes más privilegiadas de Runaterra.","Hechizo",[],["Piltover y Zaun"],"RARA"],"05PZ030":["Anomalía hextech","Cuando me robas, me creas en la mano o al comienzo de ronda: Mientras estoy en la mano, me transformo en un hechizo aleatorio de coste 6 o más.","","\"... hacer que la hextech fuera estable es la tarea más complicada a la que me he enfrentado. La mayoría de las noches parecía que los cristales y la hexita conspiraban en mi contra y pretendían hacerme fallar. Al final conseguí que los componentes encajaran en armonía, pero a base de ensayo y error...\".\n- Extracto del diario de Jayce","Hechizo",[],["Piltover y Zaun"],"RARA"],"05PZ028":["Crucero aéreo del clan Ferros","Consigo +2|+0 cuando hayas jugado un hechizo de coste 6 o más esta partida.","","\"La gente de esta ciudad besa el suelo por donde pasa la inteligencia. Pero ¿qué capacidad tiene una persona inteligente de expresarse sin los medios necesarios? Ninguna. Yo le demostraré a Piltover lo que es la grandeza de verdad. Cruzará el cielo. Le hará sombra al sol. Y llevará mi nombre\". - Albus Ferros","Unidad",[],["Piltover y Zaun"],"COMÚN"],"05PZ038":["Lluvia de misiles","Inflige 4 de daño a un enemigo y 1 al resto.","","\"¡Se supone que tienen que ir hacia arriba, NO EN TODAS DIRECCIONES! ¡Ay, mecachis!\". - Heimerdinger","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"05PZ035":["Roedor apestoso","Último aliento: Crea una copia de mí en el mazo del rival con 2 Boletus venenosos asociadas.","","El hedor de los roedores en la temporada de boletus no tiene parangón. Imagínate una cloaca en campo abierto, repleta de pescado de hace una semana y huevos podridos, y te quedas corto.","Unidad",[],["Piltover y Zaun"],"RARA"],"05PZ029":["Operario hextech","Otorga +1|+0 a los aliados tecnológicos estén donde estén cuando hayas jugado un hechizo de coste 6 o más esta partida.","","Al principio, el operario hextech se construyó para que transportara los materiales en bruto por Piltover. Pero, conforme pasaba el tiempo, parece que se ganó un lugar en el corazón de los habitantes de la zona. Los trabajadores de la forja de Jayce le pusieron el apodo de Nugget. Un lord de Piltover le donó uno de sus sombreros y unos niños que pasaban lo adornaron con lo que tenían a mano.","Unidad",["TECNOLOGÍA"],["Piltover y Zaun"],"RARA"],"05SI014":["Compendio de arrepentimientos","Comienzo de ronda: Crea en la mano una copia Fugaz de un hechizo no Fugaz que hayas lanzado en la última ronda.","","Si las Islas Bendecidas lo olvidan, las Islas de la Sombra lo recuerdan. Si las Islas de la Sombra lo olvidan, las Islas Bendecidas lo recuerdan.","Hito",[],["Islas de la Sombra"],"ÉPICA"],"05SI013":["Guardianes de la niebla","Cada ronda, la primera vez que eliminas a una unidad con un hechizo, invoca 1 Espectro de la niebla endeble.","","La Niebla Negra condena a sus víctimas a un ciclo sin fin de tormento autoimpuesto. Gracias a los Atrapanieblas, Tek y Kana les dan a esas almas la oportunidad de romper con ese círculo vicioso.\n","Unidad",[],["Islas de la Sombra"],"RARA"],"05SI009":["Senna","Cuando se me invoca o al Atacar: Crea 1 Oscuridad en la mano si no tienes. El daño y los hechizos de eliminación pasan a Veloz.","Te he visto matar a 3 o más unidades con hechizos o un Lucian aliado ha muerto.","\"Ser un Centinela significa luchar. Perderte a ti mismo y a las personas que quieres. Pero, ¿aparte de eso? Significa vivir. Por ti mismo... y por las personas a las que quieres\".","Unidad",[],["Islas de la Sombra"],"Campeón"],"05SI016":["Sombra incipiente","Mata a una unidad y otorga -2|-0 a todos los enemigos esta ronda.","","\"No hay sombra sin luz. Ni muerte sin vida\". - Senna","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"05SI004":["Vigilante de las Islas","Cada ronda, la primera vez que eliminas a una unidad con un hechizo, inflige 2 de daño al nexo enemigo.","","\"Los cachorros, cachorros son\". - Sabiduría grabada en el alma","Unidad",[],["Islas de la Sombra"],"RARA"],"05SI012":["Centinela solari","Cuando se me invoca, crea 1 Oscuridad en la mano si no tienes.","","\"Ya no siento el sol. Sin embargo, porto sus recuerdos, y eso me basta\".","Unidad",[],["Islas de la Sombra"],"COMÚN"],"05SI008":["Centinela de Ixtal","Cuando se me invoca, crea 1 Oscuridad en la mano si no tienes. Cuando juegas tu siguiente Oscuridad esta ronda, se copia con el nexo enemigo como objetivo.","","\"Senna, me preguntaste qué fue lo que me trajo a esta lucha. No he perdido nada por culpa de la Niebla y tampoco supone una amenaza para mi hogar. Existe y no debería, y estoy aquí para descubrir por qué. ¿Debo haber vivido un drama para unirme a tu causa?\".","Unidad",[],["Islas de la Sombra"],"RARA"],"05SI003":["Oscuridad lacerante","Drena 5 de vida a una unidad.","","\"La vida atrae a la muerte\". - Senna","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"05SI010":["Dess y Ada","Cuando se me invoca, crea 1 Oscuridad en la mano si no tienes. Tu siguiente Oscuridad cuesta 0 esta ronda y obtiene \"Inflijo daño a todos los objetivos enemigos\".","","\"¿Otra pesadilla?\".\n\"No ha sido tan mala, no estabas en ella\".\n\"Qué tonta, ¿y qué ha sido lo peor?\".\n\"Que tú no estabas en ella\".","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"05SI011":["Centinela incipiente","La primera vez que eliminas a una unidad con un hechizo, consigo +2|+1.","","¿Qué verá la Niebla cuando observa a Maeve? Exuberancia, confianza..., un optimismo incontrolable. ¿Cuánto tiempo debe pasar para que se extinga esa llama provocadora? ¿A qué puede tenerle miedo la muerte, más allá de la vida?","Unidad",[],["Islas de la Sombra"],"COMÚN"],"05SI015":["Centinela buhru","La primera vez que eliminas a una unidad con un hechizo, consigo +2|+1.","","La filosofía de los buhru y los Centinelas coinciden en un punto muy importante: todo tiene su final, y algunos deben encargarse de que así sea.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"05MT004":["Camphor, la duda","Cuando se me invoca, si has seleccionado como objetivo a aliados en 4 rondas diferentes, consigo Escudo de hechizos, Abrumar y Contendiente.","","Durante siglos, el demonio Camphor acechaba las tierras de Targon y les quitaba a sus víctimas la propia fuerza que las definía. De los poderosos, robaba la fuerza; de los sabios, la sabiduría. Pero no estaba interesada en ninguno de estos dones. En vez de eso, se daba un festín con el sufrimiento, la incertidumbre y la miseria que causaba. Camphor era un monstruo en todos los sentidos.","Unidad",[],["Targon"],"ÉPICA"],"05MT006":["Llamablanca herido","","","\"Los targonianos no necesitan más pruebas de la crueldad de los dioses. Mirad lo que nos han hecho. Mirad lo que le han hecho a nuestros compañeros más queridos\". - Pantheon.","Unidad",["DRAGÓN"],["Targon"],"RARA"],"05MT008":["Salto con escudo","Otorga +1|+1 a un aliado y Aturde a un enemigo.","","Pantheon estaba bien versado en el arte de la guerra. Gracias a la experiencia de múltiples batallas, sabía que sus enemigos siempre se fijaban en su lanza, pero nunca en su escudo.","Hechizo",[],["Targon"],"RARA"],"05MT014":["Maravilla celestial","Aturde a 2 enemigos.","","\"El cielo nocturno de Targon es de una belleza sin igual. Resulta demasiado fácil abstraerse contemplando las estrellas, sin saber hasta dónde se extienden ni qué seres podrían estar devolviéndonos la mirada...\". - Escalador targoniano","Hechizo",[],["Targon"],"COMÚN"],"05MT003":["Pantheon","","Has seleccionado como objetivo a aliados en 5 o más rondas diferentes.","Aquí se encuentra Atreus, al que los mismísimos Aspectos que veneraba le quitaron la libertad. Aquí se encuentran las ascuas de la guerra, que le otorgaron dones a Atreus que pocos pueden comprender. Aquí se encuentra un hombre listo para luchar y morir por aquellos a los que quiere.","Unidad",[],["Targon"],"Campeón"],"05MT013":["Iula","Jugar: Otorga Escudo de hechizos o Abrumar a un aliado. Si no, otórgamelo a mí.","","Iula aún recuerda el dolor ardiente que sintió cuando se enteró de la muerte de su marido. Cuando Pantheon fue en su busca y le preguntó que si lo ayudaría a destruir a una criatura que se alimentaba de ese mismo dolor, no dudó.","Unidad",[],["Targon"],"COMÚN"],"05MT009":["Vínculos de batalla","Otorga +2|+2 a 2 aliados.","","Luchar contra los dioses parecía una misión imposible, pero los gritos y las cicatrices del pasado habían sido los maestros de aquellos con valor en su corazón. Los dioses eran unos ególatras egoístas que habían perdido el regalo del espíritu de equipo. Esa sería su arma y su armadura en esta guerra.","Hechizo",[],["Targon"],"COMÚN"],"05MT010":["Mística cegada","Jugar: Otorga +1|+1 a un aliado y Silencia a un adepto enemigo.","","Antaño, Eshiyme era una venerada oráculo que usaba su visión para guiar a los necesitados. Sin embargo, Camphor le robó este don, pues quería darse un festín con su inevitable angustia. El demonio subestimó enormemente a la valiente Eshiyme.","Unidad",[],["Targon"],"COMÚN"],"05MT002":["La unión hace la fuerza","Concede a 2 aliados +1|+2 esta ronda.","","\"Es en los vínculos de las alianzas donde debemos hallar la fuerza\". - Pantheon","Hechizo",[],["Targon"],"RARA"],"05MT012":["Coloso liberado","Cuando se me invoca o al Atacar: Crea 1 Gema en la mano.","","Los colosos son antiguos y venerados protectores de los sitios más respetados de Targon. Causarles daño es un insulto a la mismísima montaña. Torturarlos es un crimen que ningún targoniano puede tolerar.","Unidad",[],["Targon"],"COMÚN"],"05MT011":["Contra todo pronóstico","Si tu oponente tiene más unidades que tú, otorga a un aliado +1|+1 por cada unidad extra que tenga.","","Estos pocos valientes sabían que estaban a punto de enfrentarse a seres con un poder inimaginable. Era probable que murieran. Pero, aun así, dieron un paso al frente.","Hechizo",[],["Targon"],"ÉPICA"],"05MT005":["Buscador de saga","","","Tor sintió como su vida se desvanecía con cada latido. Sin embargo, es esa oscuridad solemne e inminente, donde se suponía que tenía que abrazar a la muerte, encontró un propósito. No solo afrontaría la muerte por propia voluntad, sino que se llevaría consigo al mismísimo demonio que se había atrevido a acortar su vida. Así es como lo recordarían. Esta sería la saga de Tor.","Unidad",[],["Targon"],"COMÚN"],"05DE003":["Gorlith el Inescalable","Jugar: Intercambia mi vida con la de tu nexo.\nLos enemigos con menos vida que yo no pueden bloquearme.","","\"Un honorable tributo a aquellos que nos han dejado, pero que nunca serán olvidados. El pueblo de Demacia conocerá la esperanza cuando vea los rayos del sol brillar sobre su pétrea piel, y el indomable espíritu que inspiró su construcción vivirá a través de él\".\n- Placa del taller de Durand","Unidad",[],["Demacia"],"ÉPICA"],"05DE009":["Galio","Cuando se me invoca, otorga +0|+3 al resto de aliados.","Fin de ronda: Tus aliados tienen 25 o más de vida en total.","Durante muchos años tras su creación, Galio permaneció inerte e impasible. No fue hasta que la magia le dio vida y pudo experimentar la emoción de la batalla que sintió la alegría de estar vivo. Ahora, durante su letargo, ¡extrañaba volver a experimentar esas cosas tan maravillosas!","Unidad",[],["Demacia"],"Campeón"],"05DE020":["Escudo de Durand","Otorga +0|+3 a un aliado. En el siguiente comienzo de ronda, le otorga +0|+2.","","La sola imagen de Galio es suficiente para inspirar los nobles corazones de los demacianos.","Hechizo",[],["Demacia"],"RARA"],"05DE021":["Poder de la Vanguardia","Gasta todo tu maná para jugar esta carta. Invoca 1 Vanguardia Impertérrita y aumenta sus estadísticas hasta alcanzar la cantidad de maná gastada. Si has gastado 9 o más de maná, el resto de aliados de Élite obtienen +2|+2.","","Cuando parece que no queda esperanza, los soldados de Demacia confían en la Vanguardia.","Hechizo",[],["Demacia"],"ÉPICA"],"05DE017":["Vientos de guerra","Cura por completo a un aliado. Después, ese aliado y un enemigo se golpean el uno al otro.","","\"¡Hora de reventar!\". - Galio","Hechizo",[],["Demacia"],"RARA"],"05DE010":["Escultora de Durand","Cuando invocas a otro aliado, le otorga +0|+1.","","\"Puede que no resulte evidente para los principiantes, pero el golpe de cincel más importante en una gran obra es siempre el siguiente\".","Unidad",[],["Demacia"],"COMÚN"],"05DE013":["Ciervo de petricita","Apoyo: Recibo todo el daño dirigido al aliado al que apoyo esta ronda.","","Detrás del guardabosques montado en ciervo, el guardián de petricita empequeñecía a la misma criatura que había inspirado su elegante diseño.","Unidad",[],["Demacia"],"ÉPICA"],"05DE015":["Dragón de montaña","Furia: Consigo +0|+2 en lugar de +1|+1.","","Los dragones de montaña son criaturas tranquilas pese a su apariencia, y su estoicismo frente a otras bestias los convierte en protectores naturales de criaturas más vulnerables.","Unidad",["DRAGÓN"],["Demacia"],"ÉPICA"],"05DE019":["Arquitecto de Durand","Apoyo: Concede +0|+2 y Formidable al aliado al que apoye esta ronda.","","\"El guardabosques Corazón de Olmo trae graves noticias,\" dijo con calma el arquitecto, concentrándose en volver a enrollar el pergamino para ocultar lo mucho que le temblaban las manos. Se dirigió a los escultores que lo acompañaban y asintió lentamente. \"Ha llegado el momento de que los protectores invisibles de Demacia dejen de esconderse\".","Unidad",[],["Demacia"],"RARA"],"05DE014":["Pupila de Durand","Jugar: Otorga +0|+1 y Aguante a un aliado.","","Shireen apartó la vista de su trabajo al oír el ruido de los cascos. La prisa del guardabosques la dejó a la par inquieta y curiosa. Instó a su ave de petricita a levantar el vuelo y seguir su estela.","Unidad",[],["Demacia"],"COMÚN"],"05DE012":["Alagrande de petricita","Cuando invocas a otro aliado, consigo Contendiente.","","Cuando el alagrande sobrevoló el campo de batalla, los maltrechos soldados demacianos soltaron un grito de júbilo, inspirados por su estoica presencia.","Unidad",[],["Demacia"],"RARA"],"05DE018":["Sabueso de petricita","","","\"Siempre es una alegría verlos cobrar vida. Te olvidas de lo distintos que son, de que sus personalidades son el reflejo del artista que los creó\". - Escultora de Durand","Unidad",[],["Demacia"],"COMÚN"],"06NX024":["Lord Broadmane","Jugar: Inflige 2 de daño a un enemigo.\nTus hechizos veloces, lentos y las habilidades reciben: \"Cuando inflijo daño a un enemigo aturdido o dañado, este muere\".","","\"Acto II: Un señor hipócrita con poco más que un guantelete kashuri robado fascina al público jonio. Sin embargo, su máscara es de lo más rudimentaria y se puede ver a través de ella. Suplica por su vida, alegando ignorancia. La mano de hierro con la que pretendía gobernar yace vacía\".","Unidad",[],["Noxus"],"RARA"],"06NX033":["Ejecución estratégica","Aturde a 2 enemigos o gasta 6 de maná para invocar 1 General de la Legión.","","La asignación de las tropas es una de las primeras grandes decisiones que hay tras toda batalla. Un buen comandante sabe que la clave para la victoria...","Hechizo",[],["Noxus"],"RARA"],"06NX012":["Annie","Atacar: Inflijo 2 de daño a la unidad que me bloquee. Si muere o desaparece, inflijo 2 de daño al nexo enemigo en su lugar.","Te he visto lanzar 6 hechizos veloces, lentos o habilidades. Cuando subo de nivel, crea Tibbers en la mano.","Hace más de una década, Amoline Kiosar huyó del conservatorio Flor de Cuervo, con una poderosa e incandescente posesión bajo su control. Los exploradores la buscaron hasta en los lugares más recónditos del imperio, pero ninguna de las pistas los llevó hasta Amoline. Y así, años después, cuando llegaron rumores de una niña que se había perdido y que ardía de la furia en las montañas Puntahierro, Fynn Retrick recogió todas sus cosas y partió para investigar. No esperaba encontrar nada, pero qué equivocado estaba...","Unidad",[],["Noxus"],"Campeón"],"06NX029":["La botica gris","Cuando un aliado con 5 o más de poder muere, crea 1 adepto aleatorio con 5 o más de poder en la mano.","","\"Hoy he vuelto a pensar en la pequeña clínica que tuve en la colina Penrose, y los años que me pasé intentado descubrir los secretos de la fisiología. ¡Cuánto tiempo! Ahora que llevo unos meses trabajando para lady Noradi, me doy cuenta de que no había aprendido nada. Qué idiota fui. Qué desgraciado\".\n- Notas del Dr. Esslanger","Hito",[],["Noxus"],"ÉPICA"],"06NX032":["Perrodraco obediente","Cuando un aliado ataca, yo ataco con él.","","\"Los perrodracos son maravillosos, ¿no crees? Muy fáciles de complacer y de controlar. Ojalá mis enemigos tuviesen las mismas cualidades\". - Espina de la Rosa","Unidad",["PERRO"],["Noxus"],"COMÚN"],"06NX030":["Desertor de la legión","Recibo las mejoras de todas las unidades aliadas, estén donde estén.","","\"Acto I: Un antiguo soldado, tras abandonar su puesto tras el robo de un antiguo artefacto kashuri, se oculta en un bar de Qayanvi, con una actitud arrogante y más bebido de la cuenta. Sin embargo, ¡jamás se habría imaginado que el tesoro robado le susurra todo lo que ve a su dueño! Su vida se derrama al igual que el vino: carmesí noxiano sobre oro jonio\".","Unidad",[],["Noxus"],"RARA"],"06NX013":["Lanzador de hechizos","Jugar: Aturde a un enemigo. Si ya está aturdido, le inflige 2 de daño en su lugar.","","\"Estudiante: Sydell Kythera.\nProfesora: J. Willough.\nInforme: Tengo una picadura de araña en el brazo izquierdo. Sydell dice que ha sido un malentendido, pero su macabra sonrisa lo delata. Se le han asignado dos semanas más de labores (comedor)\".\n- Ficha disciplinaria de Flor de Cuervo","Unidad",["ARAÑA"],["Noxus"],"COMÚN"],"06NX040":["Fosos de entrenamiento trifarianos","Cada ronda, la primera vez que un aliado con 5 o más de poder ataca, prepara el ataque.","","\"En cuanto os lo ordene, ¡comenzaréis a luchar! Si matáis a vuestro compañero de combate, ¡buscaos otro! Si caéis, ¡moriréis sabiendo que vuestra muerte ha fortalecido a Noxus! Soldados trifarianos..., ¡comenzad!\". - Asesora trifariana","Hito",[],["Noxus"],"ÉPICA"],"06NX028":["Conservatorio Flor de Cuervo","Cuenta atrás - 11: Crea 1 Tybaulk en la mano.\nAvanzo 1 ronda por cada hechizo veloz, lento o habilidad que hayas lanzado esta partida.","","\"No cabe duda de que te han llegado las noticias del rotundo fracaso de la academia Guardiarrosa. Espero que aprendas de los errores de la escuela de tu hermana. Más vale que gestiones las instalaciones de forma que beneficie al imperio\".\n- Carta chamuscada encontrada entre las ruinas del conservatorio","Hito",[],["Noxus"],"RARA"],"06NX014":["Desintegración","Elige una unidad. La próxima vez que reciba 1 o más de daño esta ronda, muere.","","La jefa de estudios Telsi habló largo y tendido sobre los principios noxianos, lo que le sirvió para aburrir y preocupar a sus pupilos a partes iguales. Pero, aunque la mayoría de los estudiantes contuvieron su rabia, Annie no pudo. Primero, surgió el humo, y luego, el fuego.","Hechizo",["ELEMENTAL"],["Noxus"],"COMÚN"],"06NX031":["Yeti cautivo","Reputación: Cuesto 4 menos.","","El público se quedó boquiabierto al ver que habían traído dos yetis encadenados al legendario foso de combate de Bordent. Nadie imaginaba que las bestias eran lo suficientemente fuertes como para romper sus cadenas, ya que no se habían enfrentado antes al poder de un yeti.","Unidad",["YETI"],["Noxus"],"COMÚN"],"06NX009":["Espalda plateada cautivo","Atacar: Inflijo 3 de daño a la unidad que me bloquee. Si muere o desaparece, inflijo 3 de daño al nexo enemigo en su lugar.","","\"Acto III: Una cruel guardiana y su mascota. El espalda plateada es inocente incluso con tal macabro propósito: el artefacto que porta obliga a someterse. La guardiana se niega a gritar cuando se ve forzada a ser la comida de su mascota. Ojalá todos los noxianos fueran tan nobles en su caída\".","Unidad",[],["Noxus"],"COMÚN"],"06NX015":["Estudiante de Almaná","Cada ronda, la primera vez que lanzas un hechizo veloz, uno lento o una habilidad, juego Ascuas mágicas.","","\"Conocí a Daani hace algunos años. Un muchacho estupendo con una familia maravillosa. En mi último viaje, pasé por su pueblo y me encontré al pobre de Daani sentado solo en la plaza. Me dijo que estaba esperando a que su familia volviese a casa. El pobre debía de llevar meses ahí sentado. No tuve valor para decirle lo que había visto en mi camino...\". - Fynn Retrick","Unidad",[],["Noxus"],"COMÚN"],"06NX037":["Tellstones de Noxus","Crea 1 Determinación inquebrantable, Espiral de muerte o Armas de los caídos Fugaz en la mano.","","\"Clara, querida, tienes que limpiar la sangre de los símbolos\". - Ophelia Noradi, aristócrata carmesí","Hechizo",[],["Noxus"],"RARA"],"06NX008":["La Prefecta","Cuando lanzas un hechizo veloz, uno lento o una habilidad, consigo +1|+0.","","\"Muchos de los niños están en una edad en la que sus tendencias naturales les llevan a rebelarse contra cualquier instrucción formal. Por suerte, la mayor de todos cuenta con la gracia del resto y dócil bajo nuestro control. Si los estudiantes deciden ignorar nuestras lecciones, entonces les enseñaremos a través de ella\". - Jefa de estudios Telsi","Unidad",[],["Noxus"],"ÉPICA"],"06MT044":["Cosmicornio de los solari","Amanecer: Concede +0|+2 a otros aliados esta ronda.","","Los cosmicornios nacen a partir de las estrellas, y unos brillan más que otros.","Unidad",[],["Targon"],"COMÚN"],"06MT036":["Consulta celestial","Cura por completo a todos los aliados y, después, aumenta su poder hasta que sea igual a su vida.","","\"En primer lugar, debemos tenernos compasión. El resto ya vendrá solo\". - Soraka","Hechizo",[],["Targon"],"ÉPICA"],"06MT039":["Nido de dragones","Cuenta atrás 3: Invoca 1 Inviolus Vox.","","\"Se dice que los dragones celestiales nacen de las mismísimas nebulosas y que surgen completamente formados de entre el polvo cósmico. Pero, ¿cómo van a saberlo unos simples mortales? Desde tan lejos, solo vemos su luz\". - Heraldo de dragones","Hito",[],["Targon"],"ÉPICA"],"06MT045":["Trifecta celestial","Convoca una carta celestial de coste bajo, medio y alto.","","\"Las estrellas me indican que se avecina algo con un enorme potencial. ¿Qué forma tomará? ¡No soy yo quien debe saberlo! ¿Qué te parece a ti, Kulun?\". - Sueñalunas","Hechizo",[],["Targon"],"RARA"],"06MT043":["Tellstones de Targon","Crea 1 Contemplad el infinito, Silencio o Bendición de Targon Fugaz en la mano.","","\"Qué cosa más rara, Shorin... Sin tener que darle la vuelta a la piedra, sé exactamente la constelación que hay pintada en ella\". - Tyari el Viajero","Hechizo",[],["Targon"],"RARA"],"06MT029":["Esmus, el Aliento del mundo","Cuando se me invoca, se coloca 1 Campana en la primera carta del mazo.\nApoyo: Otorga +1|+1 al aliado al que apoye.","","\"He oído que el mismísimo Guardián creó a Esmus y que, con su nacimiento, ¡el mundo se llenó de sonidos!\".\n\"¡Menuda sarta de mentiras! También se dice que Esmus posee el rostro de una antigua cantante que tenía el corazón de un ángel pero la voz de la muerte... ¡hasta que Bardo le otorgó una voz celestial!\".\n\"¡Mentira! Esmus es...\".\n - Un extracto del Nacimiento de Esmus, un popular pasatiempo de bardos","Unidad",[],["Targon"],"COMÚN"],"06MT038":["Luz sinuosa","Anochecer: Concede +2|+1 y Abrumar a otros aliados esta ronda.","","\"Madre luna, préstanos tu fuerza,\npues aunque la oscuridad nos rodee,\ncon tu luz, saldremos victoriosos\".\n- Plegaria lunari","Unidad",[],["Targon"],"COMÚN"],"06MT047":["Vórtice místico","Cuando se me invoca o cuando avanzo en mi cuenta atrás, coloca 3 Campanas en tu mazo. Cuenta atrás 2: Roba 1.","","\"Entonces lo vi: miles de criaturas como esa, cantando y bailando y todo eso. Cuando me quise dar cuenta, pam, un destello de luz y desaparecieron todos, llevándose el templo, ¡no quedó ni una piedra! ¿Y en mis manos? Le dejaron al viejo de Gaff una campana\". - Parte 3 de la historia del anciano Gaff","Hito",[],["Targon"],"RARA"],"06MT041":["Manada de sabuesos estelares","Mis mejoras de Destino se otorgan a las Manadas de sabuesos estelares aliadas estén donde estén.","","Los montañistas eran incapaces de llamar la atención o persuadir a los sabuesos estelares. Eran distantes, y parecían acostumbrados a la magia de la montaña.","Unidad",["PERRO"],["Targon"],"COMÚN"],"06MT049":["Bendición de Mikael","Otorga +1|+2 a un aliado y elimina todas sus palabras clave negativas.","","Quienes escuchan el repiqueteo de la campana se quedan anonadados por la pureza de su sonido.","Hechizo",[],["Targon"],"RARA"],"06RU025":["Evelynn","Origen: Abrazo agónico.\nCuando se me invoca, invoca 1 Sombra aleatoria.","Cuanto te veo a ti o a un aliado matar a una Sombra aliada, obtengo sus palabras clave positivas esta ronda y subo de nivel.","Las pupilas de la sacerdotisa se dilataron al máximo, y sus manos temblaban a causa de la emoción; estaba preparada. Evelynn esperaba este momento más que ningún otro. Sonrió y se deshizo lentamente de su rostro. Entonces, comenzaron los gritos, como de costumbre.","Unidad",[],["Runaterra"],"Campeón"],"06RU001":["Bardo","Origen: El Guardián Errante.\nAtacar: Coloca 3 Campanas en tu mazo.","Has aumentado las estadísticas totales de los aliados en juego o en la mano en 20 o más.","\"Ay, ¡el viejo Gaff ha visto cosas de lo más inusuales! Primero, al mismísimo Guardián, así es. Como una estrella fugaz que surca el cielo. Fue como si el mundo se hubiese detenido un minuto y solo estuviésemos él y yo...\". - Parte 1 de la historia del anciano Gaff","Unidad",[],["Runaterra"],"Campeón"],"06RU002":["Jhin","Origen: El Virtuoso.\nAtacar: Inflige 2 de daño a todos los enemigos aturdidos.","Has lanzado 12 o más hechizos veloces, lentos o habilidades.","\"Apertura: comenzamos en la ciudad de Qayanvi, donde un maestro anciano convoca a un joven pupilo. Se le encomienda la tarea de acabar con un grupo de villanos y recuperar los artefactos sagrados que han robado. El actor se muestra entusiasmado, pero aún no ocupa su puesto. De momento se queda entre bastidores, preparándose\".","Unidad",[],["Runaterra"],"Campeón"],"06FR029":["Congelado por el miedo","Aplica Escarchar a un enemigo e invoca 1 Manada de dientehielos.","","Al frío lo acompañan los dientehielos, aunque no necesitan alcanzar a su presa..., solo esperar.","Hechizo",["ELEMENTAL"],["Freljord"],"ÉPICA"],"06FR033":["Jabalí cazador","Último aliento: Obtienes una gema de maná vacía.","","El ciclo de la vida y la muerte es diferente en Freljord. La dureza del entorno hace que no se desaproveche nada en absoluto.","Unidad",[],["Freljord"],"COMÚN"],"06FR038":["Alas de la Criofénix","Inflige 3 de daño a TODAS las unidades.\nIluminación: En su lugar, inflige 3 de daño a todos los enemigos y cura a tu nexo 3 de vida.","","A la sombra de las enormes alas de la Criofénix, sus aliados daban brincos de alegría, mientras que los enemigos se estremecían.","Hechizo",["ELEMENTAL"],["Freljord"],"RARA"],"06FR030":["Heraldo de siervos","Jugar: Invoca 1 Siervo helado o avanza todos tus Siervos helados 1 ronda.","","Apenas se oía el extraño y agudo llanto de la criatura, pero, al resonar contra los muros de piedra del barranco, a los exploradores se les clavó hasta en los huesos. Ante sus ojos comenzaron a aparecer unas grietas en la superficie del hielo, que crecían de forma desproporcionada y avanzaban a toda velocidad.","Unidad",["AVE"],["Freljord"],"COMÚN"],"06FR039":["Ferocidad de garrasalvaje","Transforma a un adepto aliado en 1 Garrasalvaje alfa.","","\"Gran espíritu de la garra, ¡concédenos tu poder!\". - Udyr","Hechizo",[],["Freljord"],"RARA"],"06FR028":["Revna, Guardiana de la sabiduría","Cuando se me invoca, otorga mis estadísticas a las unidades de tu mazo y, después, roba una unidad con 5 o más de poder.","","Los guardianes de la sabiduría tradicional avarosana suelen ser ancianos de la tribu, protectores del pueblo y cuentacuentos con gran experiencia. Mantienen viva la tradición de la caza y la lucha a través de la historia y las canciones. ","Unidad",[],["Freljord"],"ÉPICA"],"06FR037":["Hielo agrietado","Otorga a un enemigo \"Aplícame Escarchar en el siguiente comienzo de ronda\".","","Siempre hay que comprobar el estado del hielo antes de saltar sobre él, no importa lo espeso que parezca.","Hechizo",["ELEMENTAL"],["Freljord"],"COMÚN"],"06BC045":["¡Polvo de estornudos!","Otorga a los aliados +1|+1 esta ronda. Si los has creado, otórgales +2|+2.","","\"Hola. Yo ser seta. Yo hablar, pero no saber cómo ni qué pasar. Porfa, dejar a seta en paz. Porfa, gracias, adiós\". - Seta","Hechizo",[],["Ciudad de Bandle"],"ÉPICA"],"06BC036":["Paparo, el Bueno","Jugar: Manifiesta un yordle.\nAtacar: Otorga +1|+0 a tus yordles aliados.","","\"¡Todo el mundo adora a Paparo! Cada verano nos trae talismanes de todas partes del mundo, ¡y siempre son deliciosos, preciosos o destartalados! Y, a veces, ¡las tres cosas a la vez!\". - Ava hazañosa","Unidad",["YORDLE"],["Ciudad de Bandle"],"ÉPICA"],"06BC040":["Tellstones de Bandle","Crea 1 Artilugio yordle, Estribillo heroico o Arpón eléctrico Fugaz en la mano.","","Los yordles siempre están dispuestos a echar una partida... ¡pero no te lleves las manos a la cabeza si cambian las reglas a su antojo!","Hechizo",[],["Ciudad de Bandle"],"RARA"],"06BC039":["Suelta la bomba","Inflige 2 de daño a una unidad e invoca 1 Bomba rudimentaria.","","\"Vaya, eso no pinta nada bien\", dijo Giselle mientras se escondía tras algo de cobertura.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"06BC044":["Cadenas cósmicas","Inflige 2 de daño a un enemigo y aturde a otro. Coloca 6 Campanas en tu mazo.","","\"Mamá, ¿adónde ha ido el Guardián?\".\n\"Va a todas partes, hasta donde alcanza la vista\".\n\"¿Y por qué?\".\n\"Ay, cariño. No le busques un motivo. Ni siquiera nuestros sabios ancianos entienden cómo actúa el Guardián...\".\n- Una madre y su hija","Hechizo",[],["Ciudad de Bandle"],"RARA"],"06BC026":["Byrd, el Campanero","Cuando se me invoca, planta 1 Campana en la primera carta del mazo.","","\"La segunda vez fue peor. Estaba barriendo el suelo cuando, de repente, vi que toda la cena se había desparramado por la mesa, y las ollas y sartenes iban derechitas hacia la puerta a toda prisa. Las seguí tan rápido como me lo permiten estas rodillas y me las encontré en el templo hurgando en las estanterías, como si estuviesen buscando algo\". - Parte 2 de la historia del anciano Gaff","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"06BC030":["Boletus de proximidad","Inflige 1 de daño a una unidad. Si una de tus trampas o bendiciones se han activado esta ronda, inflige 3 en su lugar.","","\"Si comienza a brillar, ¡es que va a explotar!\". - Regla 463 del explorador de Bandle","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"06BC031":["Maduli, el Celador","Cuando se me invoca, coloca 1 Campana en la primera carta de tu mazo y, luego, duplica las bendiciones del mismo.","","\"Me dio un buen susto, lo admito. Le salían brazos de todas partes y tenía unos dientes enormes como rocas. Ay, y cuando la criatura se pasó el mazo ese por los dientes, hizo un ruido escalofriante. Corrí por mi vida, así fue. Pero no sin antes ver... ¡que el cielo estaba lleno de agujeros! ¡Debía de haber cientos de ellos!\".\n- Parte 4 de la historia del anciano Gaff","Unidad",[],["Ciudad de Bandle"],"RARA"],"06BC035":["El Árbol de papel","Cuando un aliado con un vínculo ataca, ese vínculo obtiene +1|+0.","","Las hojas del Árbol de papel brillan con la misma magia feérica que creó al propio árbol. Al igual que los pájaros que inspiraron su forma, les es imposible resistirse a la llamada de las cosas brillantes.","Hito",[],["Ciudad de Bandle"],"RARA"],"06IO005":["Teatro horripilante","Retira a una unidad con 3 o menos de vida.","","\"Las prisas no son amigas de los artistas\". - Jhin","Hechizo",[],["Jonia"],"COMÚN"],"06IO038":["Apoyo moral","Cuesto 2 menos si has apoyado a un aliado en esta partida. Concede Barrera a un aliado esta ronda.","","\"Confía en el equilibrio. Recorre la brecha\". - Shen","Hechizo",[],["Jonia"],"COMÚN"],"06IO012":["Llamada de los kinkou","Invoca 1 Protector de las máscaras ahora o en el siguiente comienzo de ronda. Roba 1.","","\"Máscaras antiguas para ojos jóvenes\".\n- Protector de las máscaras","Hechizo",[],["Jonia"],"COMÚN"],"06IO009":["Emboscada del dragón","Comienza un ataque gratis con 2 Crías de dragón.","","\"El deseo se materializa\".\n - Maestro de dragones","Hechizo",[],["Jonia"],"COMÚN"],"06IO033":["Tormenta de cuchillas","Durante el resto de la partida, invocas 1 Cuchilla en ataque cuando activas Danza de las cuchillas.\nDanza de las cuchillas 1.","","\"¡Marca el ritmo y yo te sigo!\". - Bailacintas","Hechizo",[],["Jonia"],"ÉPICA"],"06IO004":["La Hacedora","Jugar: Retira a una unidad con menos poder que yo.","","\"Una creadora extraordinaria, esa Hacedora. ¡Una legendaria artesana! Un arte inigualable con una ejecución impecable. Es un gran honor contar con su presencia y, más aún, empuñar un instrumento de su creación\". - Testigo kashuri","Unidad",[],["Jonia"],"RARA"],"06IO010":["Loma ventosa","Cuando se me invoca, roba a Yasuo y aturde al enemigo más fuerte.\nCuando consigas la ficha de ataque, aturde al enemigo más fuerte.","","Para la mayoría, estar en paz implica un hogar feliz y la cálida quietud que acompaña al abrazo de un ser querido. En cuanto a Yasuo, él está en paz en las raras ocasiones en las que el viento se calma y le ofrece promesas, en lugar de recuerdos. ","Hito",[],["Jonia"],"ÉPICA"],"06IO036":["Tellstones de Jonia","Crea 1 Teatro horripilante, Ritual de renovación o Mantenerse unidos Fugaz en la mano.","","\"Aprender a leer a tu oponente es indispensable incluso fuera de combate. Pero lo más importante es pasárselo bien, ya que ese es el propósito de todo juego. ¡Ahora lávame los pies!\".\n- Mentor ejemplar","Hechizo",[],["Jonia"],"RARA"],"06IO003":["Tramoyista","Jugar: Aturde a un enemigo.","","\"Acto IV: una joven sacerdotisa se une a nuestra historia. Su relato es una tragedia que cuentan los pálidos labios de aquellos a los que traicionó. Desesperada por arrepentirse de sus actos, lleva una gran carga entre sus brazos: un regalo dorado para los noxianos a los que recibió en su tierra. Nos queda la duda: ¿fue la pena o la bala lo que le atravesó el corazón?\".","Unidad",[],["Jonia"],"COMÚN"],"06IO035":["Discípulo kinkou","Cuando otro aliado recibe Barrera, consigo Barrera esta ronda si no la tengo ya.","","\"Abraza el equilibrio a todos los niveles: mente, cuerpo y espíritu. Resiste las impetuosas ansias de la juventud. Eleva tu perspectiva\". - Shen","Unidad",[],["Jonia"],"RARA"],"06PZ032":["Reproductor de música descontrolado","Elige uno de los dos hechizos nuevos de coste 2 para crear 1 en la mano y reducir su coste a 0 esta ronda. Repítelo dos veces más.","","El primer reproductor de música de Zaun salió bastante bien. La única pega que tenía era que nadie sabía cómo bajarle el volumen.","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"06PZ042":["Imperfeccionista malvada","Jugar: Escoge una carta de la mano. Añade a tu mazo 4 copias exactas de esa carta y reduce su coste en 1.","","\"Bueno, solo voy a decir que lo de hoy podría haber salido mejor, nada más. Yo del futuro..., ya sabes a qué me refiero\".\n- Diario de Kay","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"06PZ025":["Soledad","Cuando se me invoca, invoca 1 Sombra aleatoria.\nCuando invocas un aliado de coste 1, otórgale una palabra clave aleatoria.","","\"Mientras volvía a casa por el Entresuelo, volví a ver a esa pobre vagabunda llorando en una callejuela. Que tantísima gente la esquive tan decididamente me rompe el corazón, y provoca que su angustia sea cada vez más palpable. Mañana, si nuestros caminos se vuelven a cruzar, la ayudaré como pueda\".\n- Notas del diario de Lady Sempescu","Unidad",[],["Piltover y Zaun"],"RARA"],"06PZ043":["Tellstones de Piltover","Crea 1 Réplica sísmica, Transmodulador hextech o ¡Día del Progreso! Fugaz en la mano.","","\"No encontrarás piezas mejores en ningún otro rincón del mundo, señor. Mi hija ha puesto cuerpo y alma en cada detalle\". - Corin Reveck ","Hechizo",[],["Piltover y Zaun"],"RARA"],"06PZ027":["Invitación discreta","Crea 1 Personaje sospechoso o Quematrastes punki Fugaz en la mano y reduce su coste en 1.","","La mejor vida nocturna de todo Zaun es de acceso restringido. Si no estás en la banda, debes ser alguien importante para poder pasar. O encontrarte una invitación en el suelo.","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"06PZ038":["Camuflaje rescatado","Otorga Elusión y \"Golpe al nexo: Roba 1\" a un aliado.","","\"¡No os vais a creer lo que me he encontrado hoy!\".\n- Chatarrero del sumidero","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"06PZ039":["Chatarra reciclada","Para jugarla, descarta hasta 2 cartas. Crea una cantidad equivalente de adeptos de tus regiones que cuesten 1 más y reduce sus costes en 1.","","En las profundidades de Zaun, los lugareños se ven obligados a convertir los restos y residuos que encuentran en materiales maleables. Tras décadas de práctica, son bastante hábiles.","Hechizo",[],["Piltover y Zaun"],"RARA"],"06BW006":["Illaoi","Atacar: Engendra 1 y luego suma el poder de tu Tentáculo más fuerte al mío esta ronda.","He visto como las copias de Tentáculos aliadas o yo hemos infligido 15 o más de daño.","\"El ojo de Nagakabouros\" no es más que un nombre, pero Illaoi se toma muy enserio eso de vivir como si su diosa la acompañase y se aburriese en todo momento.","Unidad",[],["Aguas Estancadas"],"Campeón"],"06BW036":["Rata del embarcadero","Consigo +1|+0 por cada ronda en la que has infligido daño al nexo enemigo.","","\"No hay lugar más sangriento en Aguas Estancadas que la bahía. Solo hay que mirar a las ratas, recubiertas de sangre. No se cansan de estas idas y venidas, las malditas\". - Carnicero abrupto","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"06BW038":["Megacolmillo","Si estás en apuros, cura a tus aliados y al nexo 3 de vida.","","\"¡¿Qué es lo que quiere?!\".\n\"Viene en busca... ¡de las naranjas!\".\n¡Por la Dama Barbuda! ¡Dale toda la fanega!\".\n- Marineros desdichados","Unidad",["MONSTRUO MARINO"],["Aguas Estancadas"],"COMÚN"],"06BW030":["Ojo de Nagakabouros","Engendra 2.\nRoba 2.","","Nagakabouros es la diosa de la providencia, siempre y cuando se sobreviva al acto de la adoración.","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"06BW011":["Nagakabouros","Cuando se me invoca o al comienzo de ronda: Engendra 2. Luego, si tu Tentáculo más fuerte tiene 12 o más de poder, crea 1 Berrinche de Nagakabouros en tu mano.","","\"La Madre Serpiente. Gran Kraken. Dama Barbuda. A Nagakabouros poco le importan los nombres que le pongan, y todavía menos la alteración de los muertos\". - Illaoi","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"06BW021":["Sermón de la marea","Inflige 3 de daño a una unidad enemiga.\nEngendra 3.\nInflige 1 de daño al nexo enemigo.","","\"De pequeños aprendemos a deslizarnos por las peligrosas aguas. Luchar contra ellas implica morir. Por tanto, es natural que la primera prueba a la que se enfrenta toda sacerdotisa consista en olvidar esa lección: debemos luchar contra la resaca con todas nuestras fuerzas, ya que una Portadora de la Verdad no es la nadadora, sino la corriente\". - Illaoi","Hechizo",[],["Aguas Estancadas"],"ÉPICA"],"06BW045":["Sangre en el agua","Inflige 1 de daño a cualquier unidad o estructura. Después, activa Al ataque.","","No hay mucho que sirva para mantener a raya a los tiburones de la Bahía del Destripador. Una vez han probado la sangre, ya no hay vuelta atrás.","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"06BW028":["Aplastamiento con tentáculo","Engendra 2. Después, tu Tentáculo más fuerte y un enemigo se golpean el uno al otro.","","\"La vida es un examen y el dolor es el profesor que nos ayuda a aprender más a menudo de lo que nos gustaría\". - Illaoi","Hechizo",[],["Aguas Estancadas"],"RARA"],"06BW035":["La voz del mar","Atacar: Engendra 1 y concede a tu Tentáculo más fuerte Abrumar esta ronda.","","Invocar a Nagakabouros no tiene mucha complicación en lo que al ritual se refiere. Ella responde a la llamada de aquellas almas que están a la altura de la del océano, de cada oleaje, de cada sacudida. Es una batalla que no muchos pueden librar.","Unidad",[],["Aguas Estancadas"],"RARA"],"06BW015":["Plegarias respondidas","Engendra 2 o gasta 5 de maná para engendrar 4 en su lugar.","","Las plegarias a Nagakabouros no consisten en suplicarle, ni en pedirle para recibir su ayuda. Su bendición no tiene comparación: esfuérzate, lucha, dalo todo y, al final, recibirás tu recompensa.","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"06BW007":["Ídolo protector","Comienzo de ronda: Recibo 2 de daño y engendra 1.","","Cuando los espantos pululan por las Islas de la Sombra, el ídolo brilla con fuerza, como un faro en el horizonte.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"06BW037":["Rescate millonario","Manifiesta un adepto con un coste que te puedas permitir.","","\"Vale, Baz. ¿Seguro que quieres probar de nuevo?\".\n\"A la tercera va la vencida, Gav. Además, imagino que ya hemos luchado contra todo lo que tiene esta apestosa ciudad\".\n\"Luchado y perdido, Baz\".\n- Baz y Gav, cazarrecompensas principiantes","Hechizo",[],["Aguas Estancadas"],"ÉPICA"],"06BW041":["Timo","Elige 1 de entre 2 cartas que no sean campeones de la mano del enemigo y crea una copia en tu mano. Asalto: Cuesto 1 menos.","","\"¿Cinco ases? ¡Parece que he vuelto a ganar!\". - As del billar","Hechizo",[],["Aguas Estancadas"],"RARA"],"06BW016":["Centinela buhru","Cuando se me invoca, engendro 3.","","La vida es más dulce cuanto más simple es. Sentir la sal en la cara, oír el canto de los pájaros... y ver a un enemigo facilón en el horizonte.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"06BW009":["Líder buhru","Jugar: Un aliado de coste 1 comienza un ataque gratis.","","\"¡No olvides la sabiduría que transmite el mar! Si no te mueves, ¡ya te moverán! Sigue mi voz si has perdido el camino, pues tu enemigo seguramente sí que sabe su rumbo\". ","Unidad",[],["Aguas Estancadas"],"RARA"],"06BW043":["Tellstones de Aguas Estancadas","Crea 1 ¡Más pólvora!, Gamberro juguetón o Carnaza para tiburones Fugaz en la mano.","","\"No intentes pillar a alguien yendo de farol en una partida de Tellstones. Aguas Estancadas está infestada de grandes mentirosos. Si de verdad quieres ganar, fíjate en las manos\".\n- Twisted Fate","Hechizo",[],["Aguas Estancadas"],"RARA"],"06BW018":["Steem","Cuando se me invoca, invoca 1 Sombra aleatoria.\nCuando invocas un aliado de coste 1, aplicas Vulnerable al enemigo más fuerte.","","Cuando Evelynn conoció a Steem, tuvieron una aventura violenta y apasionada. Evelynn recuerda cómo sonrió de puro placer cuando lo flagelaba, y cómo la hizo sufrir cuando fue su turno. Tras subyugar a Steem, Evelynn decidió no destruir al demonio menor. En lugar de eso, eligió vincularlo a ella para toda la eternidad. Quizás pensase que podían compartir su mutuo amor por las masacres con el mundo.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"06SH014":["Abominación del Vacío","Cuando se me invoca, otórgame todas las palabras clave positivas que tus aliados hayan tenido durante esta partida.\nCuando un aliado tiene una nueva palabra clave, otórgamela.","","\"Ya habíamos escuchado antes historias sobre brechas del Vacío, y la devastación que las acompaña. Sin embargo, ver algo así con mis propios ojos... No sé si alguna vez conseguiré dejar de verlo, ni si mi corazón se librará de ese terror\".\n- Superviviente de Belveth","Unidad",[],["Shurima"],"ÉPICA"],"06SH016":["Heraldo de la colmena","Jugar: Otórganos a mí y a otra unidad las palabras clave positivas del otro.","","Me habló como si... me conociese. Era como si quisiese que conociese... algo...\". - Kai'Sa","Unidad",[],["Shurima"],"RARA"],"06SH009":["Kai'Sa","Cuando se me invoca o al comienzo de ronda: Si tienes la ficha de ataque, crea 1 Segunda piel en la mano.","Has evolucionado.","Hace tan solo unos días, Kai'Sa notó que su segunda piel se encrespada de la emoción, tirando de ella con cada vez más fuerza hacia la costa shurimana. Algo no andaba bien y, cuando Kai'Sa estaba llegando a Belveth, no tardó en percatarse de la magnitud de la pesadilla que se erguía ante ella.","Unidad",[],["Shurima"],"Campeón"],"06SH048":["Rito de iniciación","Manifiesta un hito aliado que haya sido destruido en esta partida e invócalo.","","\"Un momento que se conserva para siempre\". - Zilean","Hechizo",[],["Shurima"],"COMÚN"],"06SH037":["Garramarchita baccai","Jugar: Concede Vulnerable a un enemigo.\nCuando se desafía a un enemigo con Contendiente, se le concede -2|-0 esta ronda.","","La locura se disolvió como las dunas en el viento y, en su lugar, floreció la semilla de la rabia; una furia que ni las aguas del desierto podían calmar.","Unidad",[],["Shurima"],"COMÚN"],"06SH008":["Anciana de Belveth","","","Shalatai se tambaleó al presenciar el horror que se erigía ante ella. Más adelante yacía Ferai, la amable hija del carnicero, aplastada hasta morir. Junto a ella se encontraba Gorrub, el hijo del pescador, intentando alcanzar a su amada con sus inertes manos. Tantísimos recuerdos y vidas perdidos. Con una mueca, Shalatai se giró hace ese mal, decidida a dar su vida por salvar al resto de su gente.","Unidad",[],["Shurima"],"COMÚN"],"06SH042":["Tellstones de Shurima","Crea 1 Depredador implacable, Pesaje del juicio o Fuego espiritual Fugaz en la mano.","","\"Las partidas de Tellstones nunca van de quién gana o pierde, ¡sino de la cara que pones mientras juegas!\". - Akshan","Hechizo",[],["Shurima"],"RARA"],"06SH050":["Arenas del tiempo","Otorga -2|-0 a los enemigos esta ronda. Crea 1 Siglo instantáneo Fugaz en la mano.","","Las arenas del tiempo fluyen sin tomarse ni un segundo para reconsiderar su camino, con una implacable y cruel indiferencia, pero no todos son esclavos de sus despiadados planes...","Hechizo",[],["Shurima"],"RARA"],"06SH049":["Llamada de la gloria","Cuesto 2 menos por cada aliado Ascendido distinto que hayas invocado esta partida.\nManifiesta una carta del mazo del emperador que cueste 9 o menos.","","\"Contempla tu obra, todo lo que hemos construido\". - Azir","Hechizo",[],["Shurima"],"RARA"],"06SH036":["Cámara de renovación","Cuando invocas a un campeón, se me destruye para otorgarle +2|+1 y Escudo de hechizos.","","Nasus emergió del sarcófago, con la mente despejada y las heridas curadas por completo. Garabateó algunas notas y le echó un vistazo a los sarcófagos que colgaban sobre él, preguntándose acerca del estado mental en el que se encontrarían las monstruosas aberraciones que descansaban en su interior. Solo el tiempo diría si toda aquella magia había servido para devolverles la cordura a los baccai, una magia que los demás Ascendidos rechazaron. Pero ahora ya no estaban, y Renekton y su locura sí. Nasus escribió unas cuantas palabras más, con la esperanza de encontrar al fin la forma de salvar a su hermano.","Hito",[],["Shurima"],"ÉPICA"],"06SH011":["Supercarga","Otorga Abrumar y Escudo de hechizos a un aliado.","","\"Te enseñaré a luchar\". - Kai'Sa","Hechizo",[],["Shurima"],"COMÚN"],"06SH017":["Buscador del Vacío","Inflige 1 de daño a un adepto. Si has evolucionado, en su lugar inflige 3 de daño a una unidad.","","\"Duele, ¿verdad?\". - Kai'Sa","Hechizo",[],["Shurima"],"RARA"],"06SH007":["Ente del Vacío","Mientras esté en la mano, tengo una palabra clave aleatoria que cambia cada ronda. Cuando se me invoca, consigo dicha palabra clave.","","Dharna recordó haber abierto las ventanas de golpe aquella mañana, y oler las hogazas de pan recién horneadas. En la calle, los pescadores ya habían comenzado a llevar la pesca del día a los mercados. Recordó haber sonreído y pensar que sería un buen día.","Unidad",[],["Shurima"],"COMÚN"],"06SH010":["Artificiero del Vacío","","","La erupción del Vacío que se produjo en la ciudad de Belveth fue tan repentina como terrorífica. El caos que rápidamente envolvió la ciudad aterrorizó a la mayoría de sus habitantes, que huyeron tan rápido como pudieron hasta un lugar seguro. Eso hizo la mayoría, pero no Koyemi.","Unidad",[],["Shurima"],"COMÚN"],"06SH034":["Dominación","Cuando se me invoca, invoca 1 Sombra aleatoria.\nCuando invocas un aliado de coste 1, otórgale +1|+0.","","A veces, lo único que quieren los poderosos es sentirse impotentes.","Unidad",[],["Shurima"],"ÉPICA"],"06DE045":["Luz ejemplar","Otorga Optimismo a los aliados.","","\"¡Se acabó eso de esconderse! ¡Da un paso hacia la luz y brilla junto a mí!\". - Lux","Hechizo",[],["Demacia"],"COMÚN"],"06DE038":["Lord Eldred, líder de los Cazadores de Magos","Los demás aliados y tu nexo tienen Aguante.\nCuando un aliado sobrevive tras recibir daño, recibe +1|+1.","","\"No he podido evitar escuchar tus fervientes susurros, mi querida esposa. Te sugiero ser más cautelosa al discutir sobre asuntos familiares en un sitio tan público. Nunca se sabe quién podría estar escuchando\".","Unidad",[],["Demacia"],"ÉPICA"],"06DE037":["Decreto real","Concede +2|+2 y Contendiente a un aliado esta ronda o invoca 1 Lord honorable.","","\"De inmediato, rey Jarvan. Lo conseguiremos a cualquier precio\". - Barrett Buvelle, Lord honorable","Hechizo",[],["Demacia"],"RARA"],"06DE035":["Pilar de petricita","TODOS los hechizos cuestan 2 más.\nCuenta atrás 2.","","Los Cazadores de Magos colocan obeliscos de petricita por todos sus lares, asegurándose así de que incluso los magos más fuertes no tengan nada que hacer.","Hito",[],["Demacia"],"COMÚN"],"06DE042":["Tellstones de Demacia","Crea 1 Barrera prismática, Arresto o ¡Por Demacia! Fugaz en la mano.","","\"¿Por qué lo llaman 'Gambito de rey'? ¡Que las reinas también corren sus riesgos!\". - Cithria de Cloudfield","Hechizo",[],["Demacia"],"RARA"],"06DE036":["Padre protector","Atacar: Roba una unidad. Si es un dragón, lo invocas en ataque.","","\"Por suerte, mis investigaciones sugieren que los padres de las crías pasan la mayor parte del tiempo cazando a una buena distancia de las mismas. Ni que decir tiene que, si el macho volviese, ¡seríamos pienso para dragones! ¡Ja, ja!\". - Anden Mayne, investigador de Huevotesta","Unidad",["DRAGÓN"],["Demacia"],"ÉPICA"],"06DE030":["Seducción","Invoca 1 Sombra aleatoria y otórgale +1|+0.","Missing Translation","\"Acércate, cariño...\". - Evelynn","Hechizo",[],["Demacia"],"COMÚN"],"06SI012":["Gwen","Atacar: Cuando otro aliado obtiene poder gracias a Consagrar, yo también lo obtengo. Drena 2 de vida del nexo enemigo.","He infligido 10 o más de daño.","Gwen cortó, cortó y cortó hasta atravesar la Niebla Negra, pensando en lo extraño que era que hubiese envuelto por completo la zona. Cuando hubo terminado, la capilla encantada destacó frente a los lóbregos bosques de su alrededor como si fuese un faro. No es de extrañar que Gwen se sintiese atraída por ella. Era de lo más misteriosa..., ¡pero también grandiosa!","Unidad",[],["Islas de la Sombra"],"Campeón"],"06SI020":["Púa de odio","Asesina a un aliado para infligir 3 de daño a una unidad y, si Evelynn estaba en tu mazo inicial, invoca 1 Sombra aleatoria.","","\"Gime. No te cortes\". - Evelynn","Hechizo",[],["Islas de la Sombra"],"RARA"],"06SI013":["Bailarinas eternas","Atacar: Revive una copia endeble en ataque del aliado muerto más fuerte con mi poder o menos, que no sea Bailarinas eternas.","","Siempre resulta más sencillo unirse a alguien en la pista de baile que ser el primero en ella. Sin embargo, las gemelas adoran demostrar al resto del mundo cómo se hace.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"06SI037":["Tellstones de las Islas de la Sombra","Crea 1 Marca de las Islas, Viaje espiritual o Derrumbe Fugaz en la mano.","","\"Adornos... pulidos. Fichas... normas para aprender. Qué juego tan curioso. Impresionante... Una obra de artesanía sin parangón... Inolvidable\". - Diario encontrado","Hechizo",[],["Islas de la Sombra"],"RARA"],"06SI040":["Regreso del Harrowing","Revive al adepto aliado más fuerte que haya muerto y le otorga Endeble y Temible. Concede -1|-0 a los enemigos esta ronda.","","Los espíritus pueden desaparecer durante un tiempo, pero siempre vuelven.","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"06SI027":["Enhebrando la aguja","Mata a un aliado para infligir una cantidad de daño equivalente a su poder a un enemigo.","","\"¡Ahí van las agujas!\". - Gwen","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"06SI018":["Vora","Cuando se me invoca, invoca 1 Sombra aleatoria.","","A diferencia de otros demonios, que atraen a sus víctimas con falsos pretextos, los antojos de Vora son demasiado directos y sus deseos la abruman. En lugar de ser una depredadora que acecha a su comida, se trata de una bestia salvaje a la que se debe alimentar.","Unidad",[],["Islas de la Sombra"],"RARA"],"06SI015":["Que toque la banda","Invoca 2 Bandas espantosas.","","\"¡Con más viveza! ¡Ahora el doble de rápido!\". - Director de la Niebla","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"06SI030":["Invitación formal","Crea en la mano copias de 2 adeptos aliados que hayan muerto en esta partida.","","\"Ya hemos llegado, cariño. He oído que la velada de esta noche será espléndida, ¡y sospecho que nos reuniremos con muchas caras conocidas!\". - Invitado espectral","Hechizo",[],["Islas de la Sombra"],"RARA"],"06SI026":["Director de la Niebla","Último aliento: Crea 1 Banda espantosa en la mano.","","\"¡Seguid tocando, amigos! ¡Nuestro concierto será más vivaz que nunca!\".","Unidad",[],["Islas de la Sombra"],"RARA"],"06SI033":["Tumba embrujada","Cuenta atrás 2: Revive al aliado más fuerte que haya muerto.","","El sonido de la espada sobre el escudo era como el tañido de la muerte; atraía a todos los espíritus que aún seguían atados a este mundo, cuya determinación ni siquiera desaparecía al hallar la muerte.","Hito",[],["Islas de la Sombra"],"ÉPICA"],"06SI016":["Anfitrión escandaloso","","","\"Queda cordialmente invitado a la fiesta de su vida en el Deleite de medianoche. ¡Únase a nosotros en la Capilla de porcelana para beber, bailar y gozar! (La celebración acabará de forma repentina durante la decimotercera hora)\".\n- Invitación escrita con una elegante letra cursiva","Unidad",[],["Islas de la Sombra"],"RARA"],"06SI028":["Mayordomo espectral","","","¿Qué sería de un elegante festejo sin piscolabis que estén a su altura?","Unidad",[],["Islas de la Sombra"],"COMÚN"],"06SI043":["Enramada","Desecha 3.\nDrena 2 de vida a una unidad.","","Hasta en las Islas de la Sombra, la antigua fronda siempre se abre camino.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"06SI022":["Amante fantasmagórico","","","Ya fuese un fantasma, un recuerdo o un sueño, algo de él te resulta familiar...","Unidad",[],["Islas de la Sombra"],"COMÚN"],"06SI019":["Sultur","Cuando se me invoca, invoca 1 Sombra aleatoria.","","\"Cuidado con quienes sonrían en estas islas malditas. Quizá acaben de llegar y todavía no comprenden la brutalidad de este lugar, quizá hayan enloquecido o quizá sean algo totalmente distinto, pero tened cuidado\".\n- Notas de Jens Tommen","Unidad",[],["Islas de la Sombra"],"COMÚN"],"06NX022":["Cargo legionario","Roba un aliado con 5 o más de poder o hace que un aliado pase a tener 5 de poder esta ronda.","","\"Pocos gozan de la oportunidad de servir en la Legión Trifariana. No desaproveches esta oportunidad\". - Asesora trifariana","Hechizo",[],["Noxus"],"ÉPICA"],"06NX019":["Desertor noxiano","Atacar: Iguala mi poder al del aliado equipado más fuerte esta ronda.","","\"Otra vez he vuelto a tener esos sueños donde oigo una voz en la oscuridad. Diez años... Me he pasado toda una década siendo el fiel perro del imperio. Ve allí, mata aquello y... ¿Para qué? ¿Por la gloria de Noxus? La gloria no es más que una farsa, y yo me lo creí, pero eso se acabó. Kayn me ha mostrado un nuevo camino: el camino de la venganza\".\n- Diario de Royce, el Carnicero","Unidad",["SECTARIA"],["Noxus"],"COMÚN"],"06NX023":["Experta pescadora de Jonia","Cuando se me invoca, improviso.","","La vida de Trisk estaba patas arriba cuando, durante el que sería su último torneo de pesca, consiguió echarle el anzuelo a un Jax balbuceante. Este se niega a hablar del tema, pero el monstruo marino del que Trisk lo rescató se hace más grande cada vez que cuenta la historia.","Unidad",["MAESTRO DE ARMAS"],["Noxus","Jonia"],"COMÚN"],"06NX044":["Tirahilos acechante","Atacar: Hago que el poder del resto de aliados en ataque aumente hasta alcanzar el mío esta ronda.","","\"Una buena madre enseña a sus crías a cazar... Una madre excelente caza para ellas\". - Elise","Unidad",["ARAÑA"],["Noxus"],"COMÚN"],"06NX041":["Paloma carmesí","Apoyo: Inflige 1 de daño al aliado al que apoyo para concederme +1|+1 esta ronda.","","\"Alimentar a las aves es bastante divertido. Aposté con el pobre Feoward a que beberían la sangre con la misma intensidad que un basilisco de Bordent. Y fíjate: ¡las palomas sí que son noxianas!\". - Edvin Cortain, conservador carmesí","Unidad",["AVE"],["Noxus"],"ÉPICA"],"06NX020":["La balista de los Oscuros","Puedes gastar 8 de maná para que entre en juego como Naganeka de Zuretta.","","No era ningún secreto que las estepas al este de Valoran era un yermo baldío, incapaz de alimentar ni dar cobijo al pueblo de Noxus. Pero, con el paso de los siglos, surgió un nuevo imperio con sed de expansión. Las tierras en barbecho se volvieron fértiles al usar nuevas técnicas agrícolas y las armas que yacían enterradas volvieron a vez la luz del sol.","Equipamiento",["OSCUROS"],["Noxus"],"ÉPICA"],"06NX039":["Festín del huésped","Inflige 2 de daño a un aliado y concede +2|+0 a los aliados esta ronda.","","\"El verdadero festín no comienza hasta que alguien se pone a gritar. Así que grita, chico\". - Vladimir","Hechizo",[],["Noxus"],"COMÚN"],"06NX026":["Grandes martillos","","","Vessid no es el justiciero más rápido de Bordent, pero cuando asesta un golpe con sus enormes martillos, no hay oponente que pueda plantarle cara.","Equipamiento",[],["Noxus"],"COMÚN"],"06NX034":["Portador furioso","Un aliado equipado golpea a un enemigo.","","\"Hermanos de sangre, una vez más\". - Desertor noxiano","Hechizo",["SECTARIA"],["Noxus"],"RARA"],"06NX036":["Escudero rúnico","Cuando se me invoca, se activa Reforjar.","","Había trabajado muy duro durante meses, un día tras otro; una labor sacrificada que parecía no acabar nunca. Pero terminó. Al fin podría demostrar de qué era capaz.","Unidad",[],["Noxus"],"COMÚN"],"06NX027":["Escaramuza brutal","Destruye el equipamiento de un enemigo. Un aliado y ese enemigo se golpean el uno al otro.","","\"Uno, dos, ¡mira como grita!\nEste soldado detesta el fuego.\nTres, cuatro, ¡mira como arde!\nTibbers quiere entrar en juego\". - Annie","Hechizo",[],["Noxus"],"RARA"],"06MT035":["Xolaani la Tejesangre","Tengo +2|+2 por cada aliado que haya muerto con su poder aumentado.\nPotenciación 16: Me transformo en Xolaani, Perdición de los Aspectos.","","Xolaani observó cómo Anaakco caía de rodillas, subyugado por el mismo enemigo al que ansiaba desesperadamente destruir. Lentamente, el latido de su corazón fue uniéndose al unísono de los demás. Otro corazón que controlar. Otro cuerpo que dirigir.","Unidad",["OSCUROS"],["Targon"],"ÉPICA"],"06MT007":["Guiverno seráfico","Potenciación 5: Abrumar.","","\"Ah, ya veo... Las formas que dejaron en la montaña no eran más que huellas... conductos para los seres del reino de más allá de las estrellas\". - Guardián de la sabiduría Skai'en","Unidad",["DRAGÓN"],["Targon"],"RARA"],"06MT037":["Sello de acero","Destruye un aliado y crea 1 Forma corrupta con sus estadísticas.","","No era nada fácil derrotar a los guerreros dioses caídos que se enterraron con estas armas, por lo que, en su lugar, se optó por contenerlos.","Hechizo",[],["Targon"],"RARA"],"06MT031":["Mihira, Aspecto de la Justicia","Fin de ronda: Otorga +1|+1 a los aliados en juego y en la mano.\nPotenciación 5: Elusión, Robo de vida y Abrumar.","","\"Algunos veneran a los Aspectos como dioses. Otros los ven como mensajeros del más allá. Otros les temen... y quizás con razón\". - Guardián de la sabiduría Skai'en","Unidad",[],["Targon"],"ÉPICA"],"06MT010":["Juicio divino","Concede \"No puedo recibir daño ni morir\" a un aliado esta ronda.\nConcede +1|+0 a todos los aliados esta ronda.","","\"¡Me escudo en las llamas de la justicia!\". - Kayle","Hechizo",[],["Targon"],"RARA"],"06MT016":["Mensajero alado","Potenciación 3: Elusión.","","\"Sí... Te reconozco. El mensaje que llevas... solo puede ser una llamada\". - Ryze","Unidad",[],["Targon"],"COMÚN"],"06MT015":["Llamas purificadoras","Otorga +2|+2 a dos aliados de la mano.","","\"¡El mal arderá!\". - Kayle","Hechizo",[],["Targon"],"COMÚN"],"06MT042":["Protector crepuscular","Amanecer: Otorga +1|+1 a los aliados con Amanecer esta ronda.\nAnochecer: Otorga +1|+0 a los aliados con Anochecer.","","Desde el crepúsculo hasta justo antes del amanecer puede oírse al búho, cuya llamada es un recordatorio de la transición entre el anochecer y la alborada.","Unidad",["AVE"],["Targon"],"RARA"],"06MT008":["Kayle","Tengo +1|+0 por cada vez que un aliado haya atacado con poder aumentado.\nCuando se me invoca, concede +1|+0 a los aliados.\nPotenciación 6: Ataque rápido.","Comienzo de ronda: Tengo 11 de poder o más.","\"Los demacianos la consideran su protectora alada, pero los que vivimos bajo la bóveda de las estrellas de Targon la conocemos como la hija de la justicia, portadora del propósito divino y de la espada de fuego estelar\". - Guardián de la sabiduría Skai'en","Unidad",[],["Targon"],"Campeón"],"06MT004":["Pastor errante","Jugar: Elige un aliado para que improvise. Si no, yo improviso.","","Jax ayudó a Chaska a rescatar a su rebaño de las manos de los faes furiosos. Y después, Chaska salvó a Jax de estas mismas criaturas. Cuando uno de los dos no se pierde, siempre viajan juntos.","Unidad",["MAESTRO DE ARMAS"],["Targon","Ciudad de Bandle"],"COMÚN"],"06MT017":["Clérigo divino","Potenciación 3: Robo de vida.","","\"Se dice que cuando Mihira abandonó este lugar, dejó una parte de sí misma atrás: una llama sagrada que arde con fuerza. Mi familia ha cuidado esta llama durante generaciones, manteniéndola encendida con la esperanza de que ella vuelva algún día\".","Unidad",[],["Targon"],"RARA"],"06MT040":["Protección de la infinidad","Cuando hayas equipado a un aliado esta partida, cuesto 2 menos.\nConcede Escudo de hechizos a un aliado esta ronda.","","Alza la vista al cielo nocturno y céntrate en una pequeña fracción del firmamento. Ahora, imagina a todos los que vivieron en él, todo su conocimiento y sus experiencias a lo largo de incontables milenios. Imagina toda esa información concentrada en un fragmento que podría caber en la palma de tu mano. Piensa cuánto conocimiento poseerías. Cuánto poder.","Hechizo",["SECTARIA"],["Targon"],"RARA"],"06MT034":["Impacto celestial","Destruye a una unidad o un hito. Cura 3 de vida a tu nexo.","","\"¿Quién nos ayudará cuando más lo necesitemos?\". - Anciano de Shurima","Hechizo",[],["Targon"],"RARA"],"06MT033":["Vendas dracónicas","Mi portador es un dragón.","","Muchos invocan el poder de los dragones, aunque este se manifiesta de forma diferente en Runaterra. Aquellos que invocan el poder de un dragón celestial es posible que descubran que tienen una fuerza interior que brilla con la misma fuerza que una estrella.","Equipamiento",[],["Targon"],"COMÚN"],"06MT053":["Artesana generosa","Cuando juegas un hechizo, otorga +1|+1 a un aliado aleatorio en la mano.","","Con una mirada amable pero escondiendo su rostro tras un velo, ofrece abalorios de oración a aquellos que se disponen a comenzar su peregrinaje. No les pide nada a cambio, pues el precio lo pagarán en la montaña.","Unidad",[],["Targon"],"ÉPICA"],"06MT006":["El imán de los Oscuros","Apoyo: Otorga +1|+1 al aliado al que apoye.\nPuedes gastar 8 de maná para que entre en juego como Horazi.","","Tal vez aquellos que encarcelaron a los Oscuros pensaban que dando sepultura a la legendaria guerrera Horazi en un orbe de metal estelar bastaría para disminuir su irascible voluntad. Pero, al igual que hizo su general, Horazi se negaba a tirar la toalla, y descubrió que incluso los protectores ancestrales de Targon caían en la tentación de las promesas lejanas.","Equipamiento",["OSCUROS"],["Targon"],"ÉPICA"],"06MT018":["Enjuiciador","Jugar: Aturde a los enemigos con menos poder que yo.","","\"Temo que finalmente haya llegado el día... La justicia regresa con alas rodadas. ¡Y con ella un ejército radiante!\".\n- Guardián de la sabiduría Skai'en","Unidad",[],["Targon"],"COMÚN"],"06MT052":["Bendición celestial","Otorga Optimismo a un aliado en juego y a un aliado de la mano.","","\"Por gracia divina\". - Kayle","Hechizo",[],["Targon"],"COMÚN"],"06MT032":["Sectaria lunari","Cuando se me invoca o hayas equipado a un aliado en esta partida, crea 1 Gema en la mano.","","Buscaba ponerle fin al conflicto entre el Sol y la Luna, el día y la noche. El arco le ofrecía poder, aunque a un precio horrible; pero se entregó a él igualmente, con la esperanza de que aquello pusiese fin a la guerra de una vez por todas. ","Unidad",["SECTARIA"],["Targon"],"COMÚN"],"06RU008":["Jax","Origen: Maestro de armas.\nAutoequipar: La luz de Icathia.","Los aliados equipados han atacado con 16 o más de poder total.","Hace siglos, Jax perdió su hogar por culpa del Vacío. Ahora viaja por el mundo en busca de guerreros con la voluntad y el descaro suficientes para poder enfrentarse algún día a ese horrible enemigo.","Unidad",["MAESTRO DE ARMAS"],["Runaterra"],"Campeón"],"06RU006":["Ryze","Origen: El Hechicero Rúnico.\nCuando se me invoca o al comienzo de ronda: Crea 2 Ahondar en los pasados en tu mazo.","Veo 3 o más Runas Geogénicas únicas.","\"Ryze subió a la cresta acompañado por el silencioso sirviente de Kayle. Miró hacia abajo, a una tierra desgarrada por la guerra, y divisó las beligerantes monstruosidades oscuras. Durante siglos, había observado a la humanidad navegar de catástrofe en catástrofe. ¿Y si sus esfuerzos eran inútiles y Runaterra estaba condenada a perecer?\".","Unidad",[],["Runaterra"],"Campeón"],"06RU005":["Kayn","Origen: La Guadaña de las Sombras.\nAutoequipar: La guadaña de los oscuros.\nCuando mato a un enemigo, me curo 2 de vida.","He golpeado dos veces. Cuando subo de nivel, me retiro.","Con la caída de otro cuerpo, Kayn soltó una risotada, sabiendo que pronto se haría con la segunda arma de los Oscuros que allí yacía. Y, con ello, crecía la expectación de Rhaast, sabiendo que la perdición de Kayn por fin estaba cerca.","Unidad",["OSCUROS"],["Runaterra"],"Campeón"],"06RU026":["Aatrox","Origen: El Aniquilador de mundos.\nAutoequipar: La Espada de los Oscuros.\nCuando se me invoca o al Golpear: Cura 2 de vida a tu nexo y crea 1 Aniquilador de mundos en la mano si no tienes.","Has jugado Aniquilador de mundos.","Incluso desde el otro lado del mundo, Aatrox sintió su despertar. Cómo su odio seguía ardiendo. Ya había demolido sus estatuas, y ahora podía librar su guerra final contra la cobarde de Icathia y, a través de su destrucción, acabar con su lamentable existencia.","Unidad",["OSCUROS"],["Runaterra"],"Campeón"],"06RU009":["Varus","Origen: La Flecha del Castigo.\nSe autoequipa El arco de los Oscuros.","Has seleccionado como objetivo a 7 aliados o más.","¿Y si, con el tiempo, el hombre que se convirtió en Oscuro se acordase de sí mismo, alentado por las voces mortales de su interior? ¿Y si, en lugar de ignorar esas voces por completo, consiguiese creer en ellas?","Unidad",["OSCUROS"],["Runaterra"],"Campeón"],"06FR004":["Aprendiz de herrera","La primera vez que equipas a un aliado, lo forjas.","","Ornn creó la Forja viviente hace muchos pero que muchos años, pero hasta ahora no había salido en su busca. Nunca pensó que podría marcharse por su cuenta a buscar un nuevo dueño.","Unidad",[],["Freljord"],"COMÚN"],"06FR011":["Ornn","Jugar: Me equipo una copia exacta del equipamiento de un aliado o el equipamiento más poderoso de la mano.\nAtacar: Me forjo dos veces.","Un aliado ha golpeado con 8 o más de daño en un solo golpe.","Si alguien le preguntaba a Ornn por qué tenía tan poca paciencia, se limitaba a decir que él sí que era paciente, y mucho, además, y precisamente por ello hacía un trabajo incomparable. Lo que pasa es que no tiene paciencia para aguantar a la gente, pero como nadie le preguntó al respecto, jamás lo dijo.","Unidad",[],["Freljord"],"Campeón"],"06FR035":["Al rescate","Concede a un aliado +0|+3 esta ronda. Si ha recibido daño, le concede +2|+3 en su lugar.","","\"No temas, pequeño poro. ¡Estoy contigo!\". - Braum","Hechizo",[],["Freljord"],"COMÚN"],"06FR034":["Frío implacable","Aplica Escarchar al enemigo más fuerte. Si has equipado a un aliado esta partida, crea una copia de mí.","","Anaakca se movía con tal rapidez que hasta Freljord parecía seguirla. Aquellos que sobrevivieron a su masacre pronto sintieron cómo se congelaba su piel y sus corazones se paraban.","Hechizo",["SECTARIA"],["Freljord"],"COMÚN"],"06FR018":["La lanza de los Oscuros","Atacar: Otorga +1|+1 a los 2 aliados de más arriba del mazo.\nPuedes gastar 8 de maná para que entre en juego como Anaakca.","","\"Comandante, el invierno se ha endurecido. Los avarosanos han huido dejando atrás sus puestos de avanzada. Al norte está el mar... Nuestro único camino es en dirección este\".\n\"No le hagas caso, comandante. Ese camino conduce a la Pálida, y más allá, a los bosques susurrantes. Yo digo que es mejor morir aquí que enfrentarse a esa tierra maldita\".\n\"Qué suerte para ambos que ninguno deba decidir el destino de mi pueblo\".\n\"Así es, comandante. Pero tal vez haya un tercer camino. Déjame viajar al este. Mejor perder a un solo explorador en la oscuridad que a todo nuestro pueblo\".\n- Comandante Sejuani, dialogando con sus generales","Equipamiento",["OSCUROS"],["Freljord"],"ÉPICA"],"06FR012":["Artesana predilecta","Cuando se me invoca, crea 1 Tiempo y esmero en la mano.","","\"Mi madre me habló de Ornn, al igual que hizo su madre, y la madre de su madre... y yo ahora a ti. Presta atención y no me interrumpas. Hace mucho tiempo, tras un gran y agitado mar ardiente...\".","Unidad",[],["Freljord"],"COMÚN"],"06FR005":["Forja de Ornn","Cuando se me invoca o al comienzo de ronda: Crea 1 Tiempo y esmero Fugaz en la mano.","","Estar solo en la forja de Dulcehogar, sin nada a su alrededor salvo el rumor del río de lava que fluía apacible por abajo y el tañido del yunque con los golpes del martillo... Cómo le gustaba aquello.","Hito",[],["Freljord"],"RARA"],"06FR040":["Guardián de las tribus","Cuando se me invoca, otorga +1|+1 a los aliados por cada subtipo distinto que hayas invocado en esta partida.","","\"... y había una criatura muy GRANDE que cuidaba de tooooodas las pequeñitas...\". - Ingvar, la Joven","Unidad",[],["Freljord"],"ÉPICA"],"06FR020":["Fractura","Inflige 1 de daño a TODO o destruye el equipamiento de una unidad.","","El frío no perdona nada ni a nadie.","Hechizo",["ELEMENTAL"],["Freljord"],"RARA"],"06FR027":["Caracolomilla lanuda","Potenciado 8: Regeneración.","","Aunque no se conoce a los troles por su inteligencia, pueden ser sorprendentemente ingeniosos.","Unidad",[],["Freljord"],"RARA"],"06FR032":["Regalo de los sangreardiente","Cura 4 de vida a tu nexo y otorga +1|+1 a todos los aliados y el equipamiento de tu mazo. Roba 1 de ellos.","","\"Ven aquí, caliéntate junto al fuego\". - Reparador de los sangreardiente","Hechizo",[],["Freljord"],"ÉPICA"],"06FR022":["Aliento de fuelle","Forja un aliado e inflige 1 de daño a TODAS las unidades. Se repite.","","\"Una voluntad de hierro se forja\". - Ornn","Hechizo",["ELEMENTAL"],["Freljord"],"RARA"],"06FR021":["Poro enfurruñado","Potenciado 3: Abrumar, Regeneración y Aguante.","","\"¡Vamos, tienes que tomar tu medicina! ¡No te sentirás mejor hasta que lo hagas!\". - Ingvar, la Joven","Unidad",["PORO"],["Freljord"],"COMÚN"],"06FR023":["Coloso forjado","La primera vez que se me equipe, crea una copia mía de coste 4 en la mano y le otorga las estadísticas del equipamiento.","","Aunque era incapaz de admitirlo, Ornn estaba encantado con los colosos. Hacían exactamente lo que les pedía y, lo mejor de todo, no decían ni mu.","Unidad",[],["Freljord"],"ÉPICA"],"06FR008":["Reparador de los sangreardiente","Jugar: Forja a un aliado dos veces, y cura 3 de vida a él y a tu nexo.","","Cuando Ornn decidió abandonar el mundo, los sangreardiente habían desaparecido, todos y cada uno de ellos. Fueron pasando las generaciones y su nombre cayó en el olvido. Sin embargo, no hace mucho resurgieron las historias de Ornn y se rumoreaba que unos pocos habían retomado las costumbres de los sangreardiente.","Unidad",[],["Freljord"],"COMÚN"],"06FR009":["Herrero versado","Jugar: Forja un aliado.","","Cuando Fiske se planteó tener un aprendiz, se imaginaba a alguien con dedicación, respeto por su trabajo, fuerte y hábil. Sin embargo, Kindra no era nada de eso. Más bien le gustaba pasarse el día soñando despierta y jugando en lugar de trabajar. Siempre estaba preocupada por esa tortuguita suya... Sin embargo, estaba aprendiendo y eso era todo lo que importaba.","Unidad",[],["Freljord"],"COMÚN"],"06FR024":["Garrote de hueso","","","\"¡Crac!\". - Tarkaz el Sin Tribu","Equipamiento",[],["Freljord"],"COMÚN"],"06FR017":["Sectario glacial","Tus aliados equipados obtienen Abrumar.","","La Garra Invernal tenía razón. Los avarosanos habían sido demasiado blandos. Necesitaban un nuevo líder; uno que no buscase unificar Freljord mediante la paz, sino gobernarlo. ","Unidad",["SECTARIA"],["Freljord"],"RARA"],"06FR041":["Toque invernal","Obtienes una gema de maná vacía. Iluminación: Cuesto 1. Roba 1.","","Sientes pulsaciones de la gema que sostienes en tu mano. Con un inquietante destello, su superficie desprende una luz helada que sube y se enrolla alrededor de tu brazo en forma de espiral. Pero este frío no congela; es más bien estimulante, como si te infundiera su esencia. ","Hechizo",["ELEMENTAL"],["Freljord"],"ÉPICA"],"06FR036":["Misticismo salvaje","Obtienes una gema de maná vacía.\nInvoca 1 Místico salvaje.","","\"Los espíritus y las estrellas vuelven a reunirnos\". - Vidente Hyara","Hechizo",[],["Freljord"],"ÉPICA"],"06BC015":["Norra","Golpe al nexo: Coloca 1 Portal misterioso entre las 4 cartas de más arriba de tu mazo.","Has invocado 6 aliados creados o más.","Norra trabajaba a toda prisa, pensando en su hogar. Los portales eran algo complicado y todavía no se había tomado ni la primera taza de té. Pero a Norra le encantaban los rompecabezas, sobre todo esos que le permitían perderse en dimensiones de bolsillo entre el espacio y el tiempo. Redobló sus esfuerzos, con su gata en mente, que seguro que estaría preocupada y esperando la cena.","Unidad",["YORDLE"],["Ciudad de Bandle"],"Campeón"],"06BC043":["Historias de poros","Crea 3 poros aleatorios de coste 1 en la mano.","","\"... Y, ENTONCES, EL PORO SE PUSO EN PLAN '¡OYE! QUE YO TAMBIÉN QUIERO UN SNACK!' ASÍ QUE LOS POROS SE JUNTARON EN LA GRAN REUNIÓN PORO PARA HABLAR SOBRE TODOS LOS PROBLEMAS PORILES, COMO DÓNDE ESTABAN LOS SNACKS Y POR QUÉ NO HABÍA MÁS POROS Y...\". - Ingvar, la Joven","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"06BC051":["Cañón platanero","Jugar: Inflijo daño equivalente a mi poder a una unidad.","","\"¡EH! ¿ALGUIEN QUIERE POTASIO?\". - Banano, momentos antes del famoso \"incidente\". ","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"06BC047":["Gemes","Otorga a un aliado con un vínculo las estadísticas y palabras clave de su vínculo durante esta ronda. Tras esto, traslada el vínculo a otro aliado.","","Se podría pensar que un pastor no tiene cabida en el campo de batalla, pero sus habilidades resultan de gran utilidad. La idea es ver a los combatientes como ovejas que necesitan que las dirijan.","Hechizo",["MAESTRO DE ARMAS"],["Targon","Ciudad de Bandle"],"RARA"],"06BC019":["Preparadora de tés","Cuando se me invoca, coloca 1 Portal misterioso entre las 4 cartas de más arriba de tu mazo.","","Ashane fue otrora una famosa preparadora de tés antes de perderse en la Frontera del Reino. Mientras probaba nuevos sabores, se sumió en un profundo sueño provocado por una desafortunada mezcla de dos hojas. Tuvo unos sueños rarísimos: criaturas extrañas y estructuras imposibles contra un horizonte infinito. Pero, al despertarse, se dio cuenta de que no había estado soñando.","Unidad",["HADA"],["Ciudad de Bandle"],"COMÚN"],"06BC029":["El bastón de los Oscuros","Golpear: Recupera 1 de maná de hechizos.\nPuedes gastar 8 de maná para que entre en juego como Baalkux.","","Llegaron a la conclusión de que el bosque de Bandle parecía el lugar perfecto para esconder un arma de los Oscuros. Es casi imposible de explorar, y los yordles sabían que convenía alejarse de una maldad tan poderosa. Pero los targonianos no se dieron cuenta de la eficacia de la magia de Bandle, ni de los efectos que tendría sobre la flora local.","Equipamiento",["OSCUROS"],["Ciudad de Bandle"],"ÉPICA"],"06BC038":["Crecimiento repentino","Cuando hayas equipado a un aliado esta partida, cuesto 2 menos.\nHace que un aliado pase a tener 4|4 esta ronda.","","\"Encerramos un gran poder\". - Varus","Hechizo",["SECTARIA"],["Ciudad de Bandle"],"RARA"],"06BC017":["Portales a raudales","Coloca 2 Portales misteriosos entre las 4 cartas de más arriba de tu mazo.\nRoba 1.","","\"¡Me encantaría pasear por los Senderos bajos más a menudo! ¡Qué tonta soy! Siempre se me olvida tener cuidado con la cabeza...\".\n- Norra","Hechizo",[],["Ciudad de Bandle"],"RARA"],"06BC020":["Doblador de origami","Consigo +1|+0 por cada una de tus trampas o bendiciones que se hayan activado esta ronda.","","La magia de la papiroflexia puede ser un tanto impredecible. En ella, influye tanto la intención de crear algo nuevo como el deseo de la creación de tomar forma.","Equipamiento",[],["Ciudad de Bandle"],"RARA"],"06BC028":["Sectario floreciente","Cuando hayas equipado a un aliado en esta partida, consigo Elusión.","","Persona, animal o planta; la corrupción de los Oscuros no perdona nada ni a nadie.","Unidad",["SECTARIA"],["Ciudad de Bandle"],"COMÚN"],"06BC021":["Constructo de chatarra","Último aliento: Coloca 1 Portal misterioso entre las 4 cartas de más arriba de tu mazo.","","Solo llevaba un día con vida, pero Marv —como Norra lo llamaba con cariño— estaba orgullosísimo de ser su ayudante. Sin embargo, insistía en que lo llamase \"chatarra\" y no \"basura\", ya que este último apelativo tenía una connotación negativa.","Unidad",["HADA"],["Ciudad de Bandle"],"COMÚN"],"06BC042":["Bebés hada curiosos","Cuando un adepto aliado se transforma en otro adepto, me transformo en una copia exacta de él.","","Camaleón ver, camaleón ser.","Unidad",[],["Ciudad de Bandle"],"RARA"],"06BC023":["Señales desconcertantes","Devuelve un hechizo veloz o uno lento a la mano, o destruye el equipamiento de una unidad. Roba 1.","","\"¡Querida yo! ¿Era por aquí, por allá... o por acá? ¡Nunca me acuerdo!\". -  Norra","Hechizo",[],["Ciudad de Bandle"],"RARA"],"06BC041":["Cachivaches de Skrappy","Descártame para invocarme. Cuando invocas a un yordle mecha, obtiene una palabra clave aleatoria.","","No importa si es grande o pequeño, inanimado o no; si buscas cualquier chisme, ¡ven al almacén de Skrappy! Pero no preguntes a Skrappy dónde está, porque a Skrappy no le va lo de catalogar cosas.","Hito",[],["Ciudad de Bandle"],"RARA"],"06BC011":["Periplo mágico","Coloca 1 Portal misterioso entre las 4 cartas de más arriba de tu mazo y coloca 1 Campana en la primera carta de tu mazo.","","Bardo, que viaja de un reino a otro según le apetece, escucha atentamente, sabiendo que se acerca un gran conflicto, uno que podría silenciar la canción de la creación.","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"06BC032":["Colección ecléctica","Por cada aliado, coloca 1 Portal misterioso y 3 Campanas entre las 10 cartas de más arriba de tu mazo y coloca 1 Trampa con bomba destello y 3 Boletus venenosos en el mazo enemigo.","","\"¡Portales por todas partes!\".\n- Norra","Hechizo",[],["Ciudad de Bandle"],"ÉPICA"],"06BC024":["Guardián del reino","Cada ronda, la primera vez que se activa una de tus trampas o bendiciones, otorgo +1|+1 e Impacto a los aliados esta ronda.","","Gaspar fue el primer yordle en llegar a la Frontera del Reino. Durante muchos años, deambuló en solitario, atravesando caminos laberínticos y portales que parecían no conducir a ningún sitio. Tras decidir que nadie debería pasar nunca por lo mismo que él, ahora ayuda a otros viajeros perdidos a encontrar el camino a casa.","Unidad",["HADA"],["Ciudad de Bandle"],"RARA"],"06BC033":["Mechapulverizador","Para jugar esta carta, descarta 1.","","\"¡Atención! De las ruinas de un barco hundido, extraje el guante de boxeo. De las profundidades de la ciudad que llaman Zaun, recuperé los resortes, y de las forjas de Demacia, traje el metal. ¡Se trata, sin duda, de una creación del mundo!\". - Paparo, el Bueno","Equipamiento",[],["Ciudad de Bandle"],"COMÚN"],"06BC016":["Biblioteca viviente","Cuando se me invoca, si una de tus trampas o bendiciones se han activado esta ronda, roba 1.","","Cree que su labor consiste en albergar un gran conocimiento, por lo que se hace con tomos de diferentes viajeros que atraviesan la Frontera del Reino. Por desgracia, parece que todo ese saber se le ha subido a la cabeza.","Unidad",["HADA"],["Ciudad de Bandle"],"COMÚN"],"06IO044":["Cantante celestial serena","Cuando se me invoca, reduce el coste de tus hechizos en tu mazo a la mitad redondeando hacia arriba.","","\"Algunos buscan la paz mediante la meditación. Otros buscan conocimiento para entenderse mejor a sí mismos. Aquellos que encuentren el equilibrio en la expresión y la creación serán capaces de traer paz también a los demás\". - Karma","Unidad",[],["Jonia"],"ÉPICA"],"06IO013":["Estilo Wuju","Concede +2|+0 a un aliado esta ronda.\nCrea 1 Meditar en la mano.","","\"Uno de los muchos cortes que le seguirán\".\n- Maestro Yi","Hechizo",[],["Jonia"],"RARA"],"06IO023":["El abanico de los Oscuros","Ataque: Invoca 1 Cría de dragón en ataque.\nPuedes gastar 9 de maná para que entre en juego como Praa el Cruzabrechas.","","\"Hace tiempo que percibo una sombra en el puente entre los mundos; una sombra que late con una silenciosa rabia. Aunque sé que no debo adentrarme en la oscuridad tras ella, este latido es cada vez más fuerte y más rápido, y temo que las criaturas del reino espiritual pronto empiecen a buscarla\". - Shen","Equipamiento",["OSCUROS"],["Jonia"],"ÉPICA"],"06IO029":["El espíritu de Wuju","Fluir: Cuesto 2 menos.\nCuando se me invoca, roba un hechizo.","","\"El maestro Doran creía que cada ojo del espíritu de Wuju ofrecía un conocimiento único de aquellos a quienes miraba. Pero, por más que lo intente, lo único que veo a través de los cristales de mi casco son diferentes tonos de verde. ¿Qué estoy haciendo mal?\". - Lui, Discípula de Doran","Unidad",[],["Jonia"],"COMÚN"],"06IO037":["La Llama Negra","Jugar: Captura a un aliado. Cuando atacas por primera vez en cada ronda, invoca una copia suya endeble en ataque.","","\"¿Qué es una vida, sino una sombra de la existencia? Abraza la oscuridad y vivirás eternamente\". - Zed","Hito",[],["Jonia"],"ÉPICA"],"06IO031":["Espada onírica","Flujo: Cuesto 2 menos.","","\"¡Espada y cuerpo!\". - Maestro Yi","Equipamiento",[],["Jonia"],"COMÚN"],"06IO014":["Discípulo vastaya","Golpe al nexo: Me retiro y me transformo en Viento de los shimon.","","Ting sonreía mientras los atacantes entraban en el templo. ¡Por fin tenía oportunidad de demostrar su valía! Primero Wukong, luego Yi... Ambos habían negado su talento. Que los demás corrieran a buscar a su maestro, que él estaba preparado. Era el viento de los shimon. ","Unidad",[],["Jonia"],"ÉPICA"],"06IO008":["Maestro Yi","Comienzo de ronda: Reduce en 1 el coste de un hechizo de tu mano y Fluir: Otorga +2|+0 a todos los Maestro Yi aliados estén donde estén.","Maestro Yi aliado ha infligido 12 o más de daño en total.","Maestro Yi se desconcentró con un pensamiento acerca del arma de los Oscuros. Desde que la descubrió, no podía quitarse de la cabeza una horrible premoción. Tenía a algunos estudiantes interesados, quizá demasiado, así que puso las hojas curvas bajo custodia, en las profundidades del templo. Con cierto esfuerzo, consiguió alejar esos pensamientos que le rondaban por la mente y continuó con su meditación. Lo importante era transmitir el arte del Wuju, y Jun parecía ser una gran promesa.","Unidad",[],["Jonia"],"Campeón"],"06IO040":["Técnica de los vientos gemelos","Elige un adepto. Invoca una copia endeble idéntica del mismo. Si es un enemigo, lo aturde.","","Para los jonios, el viento es el más caprichoso de los elementos. Caprichoso, pero no indomable. ","Hechizo",[],["Jonia"],"RARA"],"06IO011":["Jun, la Prodigio","La primera vez que estoy equipado, consigo Barrera y Robo de vida esta ronda.","","A su señal, Jun asestó una serie de golpes tan precisos como los del mismísimo Yi. Aunque esquivó el ataque con gran habilidad, le hizo una reverencia con gran orgullo.","Unidad",[],["Jonia"],"RARA"],"06IO015":["La Testigo","Fluir: Cuesto 2 menos.\nJugar: Aturde a un enemigo.","","¿Cuál es su papel en este extraño y espantoso espectáculo? No es simplemente parte del público..., sino una observadora que examina cuidadosamente todas las cosas y juzga la verdad y la belleza en ellas. ¡La Testigo!","Unidad",[],["Jonia"],"COMÚN"],"06IO030":["Nieblalumbra","Cuando se me invoca, roba un equipamiento.\nLa primera vez cada ronda que se equipe a un aliado, recuperas 2 de maná de hechizos.","","\"Nieblalumbra es un lugar sagrado. Las espadas de este lugar llevan aquí siglos... y creo que todas las que tienen un poema en la empuñadura invitan a los espíritus perdidos de sus portadores a otorgarles su bendición\".\n- Discípula de Doran; pergamino escrito a mano","Hito",[],["Jonia"],"RARA"],"06IO034":["Elección crucial","Si has equipado a un aliado esta partida, cuesto 1 menos.\nConcede a un aliado +2|+0 o +0|+2 esta ronda.","","Las lágrimas de frustración recorrían el rostro de Jun mientras observaba los cuerpos en el suelo. Les había fallado, y también a su maestro. Ahora solo quedaba una opción...","Hechizo",["SECTARIA"],["Jonia"],"RARA"],"06IO028":["Cebo cautivador","Concede Contendiente a un aliado esta ronda. Si se ha equipado, roba 1.","","Todos pican con el cebo adecuado.","Hechizo",["MAESTRO DE ARMAS"],["Jonia","Noxus"],"RARA"],"06IO025":["Fanático filosombrío","Cuando hayas equipado a un aliado en esta partida, crea 1 Sombra malvada en la mano.","","La había visto en la oscuridad: un arma capaz de atravesar las sombras. Y, en ese momento, oyó una voz que lo llamaba, lejana pero poderosa. Esta voz lo llevó hasta Kayn, con la verdad de sus palabras como guía.","Unidad",["SECTARIA"],["Jonia"],"COMÚN"],"06IO039":["Colilargo de Navori","Jugar: Invoca 1 Forajido de Navori o concede +1|+1 a otros aliados esta ronda.","","El colilargo se hizo amigo por primera vez de su colega forajido una noche de invierno, cuando ambos compartieron los restos de una hoguera abandonada. Al final de la semana, los dos habían descubierto que su interés por las travesuras y por el brillo dorado de las monedas era mutuo.","Unidad",[],["Jonia"],"COMÚN"],"06IO032":["Alma indigna","Fluir: Cuesto 2 menos.\nRetira a una unidad o un hito. Si tiene algún vínculo, lo destruye primero.","","\"No mereces el poder que posees\". - Rhaast","Hechizo",[],["Jonia"],"RARA"],"06IO001":["Discípula de Doran","Cuando se me invoca, crea 1 Preparación en la mano.","","\"He aprendido todo lo que he podido para continuar con este arte sagrado. En cuanto a Doran, su maestro y el maestro de este... espero que sus espíritus guíen mi martillo\".\n- Discípula de Doran; pergamino escrito a mano","Unidad",[],["Jonia"],"COMÚN"],"06IO016":["Invocador de dragones","Comienzo de ronda: Fluir: Invoca 1 El Empíreo y le otorga Endeble.","","\"La forma del agua refleja la forma de tu anhelo. Dime, viajero... ¿qué ves?\".","Unidad",[],["Jonia"],"ÉPICA"],"06PZ034":["Hexliberador","Inflige 6 de daño a una unidad. Si fuera a morir, la destruye en su lugar.","","Para algunas criaturas, la muerte no basta.","Hechizo",[],["Piltover y Zaun"],"RARA"],"06PZ006":["Bis","Crea un hechizo nuevo aleatorio de coste 2 en la mano, reduce su coste en 2 y le otorga Fugaz.","","No hay nada mejor que la reverberación.","Hechizo",[],["Piltover y Zaun"],"RARA"],"06PZ021":["Seraphine","Cuando se me invoca, crea un hechizo nuevo aleatorio de coste 2 en la mano.","Has lanzado 9 hechizos nuevos o más.","Seraphine nunca le contó nada a su padre sobre sus viajes \"secretos\" a la Ciudad Subterránea, o sobre los pequeños cambios que le iba haciendo a su escenario. Estaba segura de que le prohibiría participar en el duelo musical más grunge de Zaun; pero, una noche, su padre deslizó el panfleto bajo su puerta. Ella sonrió, y en seguida se puso manos a la obra.","Unidad",[],["Piltover y Zaun"],"Campeón"],"06PZ040":["Bar del callejón","Cuando se me invoca, invoca 1 Tabernero del callejón.\nTus cartas nuevas cuestan 1 menos.","","Tras secar el último vaso, el tabernero se tomó un minuto para echar un vistazo a su local. Este lugar, esta segunda casa, había visto a desconocidos convertirse en amigos, y tenía pintadas y golpes de más de una noche loca. El tabernero sonrió. No era un lugar perfecto, pero era el suyo.","Hito",[],["Piltover y Zaun"],"ÉPICA"],"06PZ008":["El arpa de los Oscuros","Puedes gastar 8 de maná para que entre en juego como Styraatu.","","Mientras los targonianos sopesaban por dónde debían desperdigar las armas Oscuras, uno de ellos propuso las tierras que más tarde serían conocidas como Zaun. Pensaron que dejarlas sepultadas entre los muros de los profundos y serpenteantes pasadizos sería perfecto. Lejos del alcance de los humanos. Pero no de los quíreos.","Equipamiento",["OSCUROS"],["Piltover y Zaun"],"ÉPICA"],"06PZ018":["Nota alta","Inflige 2 de daño a una unidad. Si has jugado más de 6 hechizos nuevos en esta partida, inflige 1 de daño a otra unidad.","","Alto y claro.","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"06PZ014":["Presidenta del club de fans","Jugar: Manifiesta un hechizo de coste 5 y establece su coste en 2.","","\"No importa la fuerza de tu voz, ¡sino la de tu corazón!\".\n- Presidenta del club de fans","Unidad",[],["Piltover y Zaun"],"RARA"],"06PZ030":["Planos inspirados","Atacar: Crea un hechizo nuevo de coste 2 en la mano y le otorga Fugaz.","","\"Ay, madre... Parece que va a llover\".\n\"¿Eh? Pero si el cielo está despejado\".\n\"¡Rápido, cubre los planos! ¡Se viene una TORMENTA de ideas!\".\n\"¡Papá...!\".\n - Seraphine y su padre","Equipamiento",[],["Piltover y Zaun"],"RARA"],"06PZ046":["Fórmula","Roba 2. Recarga el maná de hechizos.","","\"La magia no es más que una verdad científica aún por descubrir\". - Jayce","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"06PZ007":["Sectario ambicioso","Cuando hayas equipado a un aliado en esta partida, crea en la mano un hechizo nuevo de coste 2 y reduce su coste a 0 esta ronda.","","\"Siempre he estado dispuesto a hacer sacrificios en nombre de la ciencia. No importa cuánto haya arriesgado; el poder ilimitado e inagotable que conseguí a cambio fue recompensa más que suficiente\".","Unidad",["SECTARIA"],["Piltover y Zaun"],"COMÚN"],"06PZ041":["Gato ingenioso","Cuando se me invoca, si se me ha creado, roba 1 y consigo +2|+1.","","Cuando no están durmiendo a plena luz del día o vomitando en mitad de la noche, los gatos siempre están haciendo travesuras.","Unidad",["GATO"],["Piltover y Zaun"],"COMÚN"],"06PZ036":["La Diva de Zaun","Jugar: Inflige 1 de daño a todos los enemigos. Si has jugado más de 6 hechizos nuevos esta partida, inflige 3 en su lugar.","","\"¡Qué pasa, Zaun! ¡Espero que estéis listos para gritar, porque vamos a volver a hundir esta ciudad!\". - La Diva de Zaun","Unidad",[],["Piltover y Zaun"],"RARA"],"06PZ010":["Ingeniero acústico","Golpear: Crea un hechizo nuevo aleatorio de coste 2 en la mano.","","Tiempo atrás, había soñado con abandonar Zaun y viajar por el mundo con una canción en su corazón. Ahora, el mundo dormía en su habitación, a la espera de las canciones que pudiera traer el mañana.","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"06PZ022":["Solo de batería","Roba 2.\nFluir: Reduce en 1 su coste.","","En la música lo más importante es el compás, pero, a veces, hay que dejarse llevar.","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"06PZ029":["Favorita del público","Concede +2|+0 y Ataque rápido a un aliado esta ronda.\nFluir: Crea un hechizo nuevo de coste 2 en la mano.","","\"¡Más alto, Zaun!\". - Seraphine","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"06PZ020":["Bellota, el hextécnico","Golpe al nexo: Reduce en 1 el coste del hechizo más caro que tengas en la mano.","","Su nombre no aparece en los planos ni en los créditos de ninguna canción, pero cualquiera estaría de acuerdo: Bellota era el corazón de toda la operación.","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"06PZ009":["Riff cáustico","Flujo: Cuesto 2 menos.\nInflige 1 de daño a todos los enemigos.","","Hace falta un sonido especial para atravesar el traqueteo de Zaun, pero la Diva siempre lo consigue.","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"06PZ037":["Disonancia violenta","Inflige 1 de daño a una unidad. Si has equipado a un aliado esta partida, crea una copia de mí con el mismo objetivo.","","Si la disonancia es la cacofonía de la destrucción, que comience el caos.","Hechizo",["SECTARIA"],["Piltover y Zaun"],"RARA"],"06PZ019":["Portero de Zaun","Comienzo de ronda: Fluir: Recuperas 2 de maná de hechizos.","","Si fuera por él, NADIE entraría.","Unidad",[],["Piltover y Zaun"],"COMÚN"],"06PZ033":["Gatalizador 1.0","Tus hechizos y habilidades infligen 1 de daño adicional.","","\"Ubicación: sector 3, camino 19B\nObjeto: arma de fuego ilegal\nNotas: confiscada durante la operación Luz del sumidero. El arma es de lo más peligrosa. Manipular con sumo cuidado\".\n- Informe de campo de guardia de Piltover","Equipamiento",[],["Piltover y Zaun"],"COMÚN"],"06BW029":["Exiliado piltovano","Cuando se me invoca, improviso.","","Pesh conoció a Jax en una pelea en el muelle, y su oportuna huida fue más conveniencia que alianza. Pero Pesh lleva alrededor de Jax desde entonces, porque todo lo que le rodea acaba rompiéndose, y si hay algo que le guste más a Pesh que una buena riña es arreglar cosas.","Unidad",["MAESTRO DE ARMAS"],["Aguas Estancadas","Piltover y Zaun"],"COMÚN"],"06BW034":["Metal pesado","Destruye el equipamiento de una unidad y le inflige 2.","","\"¡¿PERO A QUIÉN SE LE OCURRE LANZAR UN ANCLA EN UNA PELEA DE BAR?! ¡¿QUÉ OS PASA?!\". - Tabernero de Aguas Estancadas","Hechizo",[],["Aguas Estancadas"],"RARA"],"06BW027":["Partes de un todo","Para jugar esta carta, descarta 1. Roba 2 y, si has descartado un equipamiento, invoca 1 Espejismo de Icathia.","","La tripulación de Jax es la prueba de que el todo puede ser mejor que la suma de sus partes. Aun así, Pesh insiste en verlo de otra forma: a veces, las partes son geniales de por sí.","Hechizo",["MAESTRO DE ARMAS"],["Aguas Estancadas","Piltover y Zaun"],"RARA"],"06BW039":["La ola interminable","Cuando hayas equipado a un aliado esta partida, cuesto 2 menos.\nRoba 2 cartas y otórgales Fugaz.","","Aunque los antiguos huesos de Ibaaros se movían despacio, las olas que creaba se movían a una velocidad casi incomprensible.","Hechizo",["SECTARIA"],["Aguas Estancadas"],"RARA"],"06BW026":["Sectaria buhru","Cuando los aliados equipados atacan, inflige 1 de daño al nexo enemigo.","","Daba igual de dónde viniera el poder, a su diosa no le importaba. Lo importante era la gloria que le brindaría al asesinar monstruos.","Unidad",["SECTARIA"],["Aguas Estancadas"],"COMÚN"],"06BW014":["El arpón de los Oscuros","Atacar: Roba 1 carta en el siguiente comienzo de ronda y le otorga Fugaz.\nPuedes gastar 9 de maná para que entre en juego como Ibaaros.","","\"Aléjate, aléjate del estrecho de Daray;\nsus aguas susurrantes y vientos malhechores\nen toda criatura despiertan temores.\nLa oscura profundidad del estrecho de Daray\".\n - Rima de Aguas Estancadas","Equipamiento",["OSCUROS"],["Aguas Estancadas"],"ÉPICA"],"06BW004":["Prueba de espíritu","Concede Vulnerable a un enemigo esta ronda. Si muere esta ronda, inflige 1 de daño al nexo enemigo.","","\"¿Resistirás o te acobardarás?\". - Illaoi","Hechizo",[],["Aguas Estancadas"],"RARA"],"06BW044":["Tritonzuelo astuto","Golpe al nexo: Roba 1 y otórgale Fugaz.","","\"Son unos pequeños monstruos ladronzuelos y desagradables. Aunque, al menos, es fácil pillarles cuando han pescado algo\".","Unidad",["REPTIL"],["Aguas Estancadas"],"COMÚN"],"06BW047":["Marai traviesa","Cuando juegas un hechizo, invoca 1 Barril de pólvora.","","\"Bibi es un poco... alocada, sí. ¡Pero por eso la queremos tanto!\". - Ai'la, guardiana marai","Unidad",[],["Aguas Estancadas"],"RARA"],"06BW023":["Sable mellado","Asalto: Cuesto 2 menos.","","\"Como dice el refrán: nada acaba con una pelea de Aguas Estancadas más rápido que un sable\".\n\"Bueno, tal vez una pistola\".\n\"Cierra el pico, Baz\".\n- Baz y Gav, cazarrecompensas en ciernes","Equipamiento",[],["Aguas Estancadas"],"COMÚN"],"06BW042":["Navío cargado","Inflige 2 de daño a una unidad. Roba 1 al siguiente comienzo de ronda por cada punto de daño infligido y le otorga Fugaz.","","\"Rex se encargará de la explosión, no te preocupes, y yo, del tesoro. Y me llevaré también su parte: si no, intentará meterla en el cañón y luego es un lío\". - Suboficial","Hechizo",[],["Aguas Estancadas"],"ÉPICA"],"06BW040":["Ojo de la diosa","Atacar: Engendra 2.","","\"¡Manteneos firmes ante su mirada!\". - Illaoi","Equipamiento",[],["Aguas Estancadas"],"RARA"],"06SH032":["Arsenal sepultado","Cuenta atrás 2: Crea 1 Tesoro de las arenas en la mano.","","\"¿Por qué tienes que tocarlo todo?\".\n\"¿Qué pasa? ¿Crees que es una trampa? ¿Te piensas que va a salir una roca rodando de...?\".\n\"¡Correeee!\".\n- Argus y Silvio, saqueadores de tumbas.","Hito",[],["Shurima"],"COMÚN"],"06SH035":["Altar de sangre","Cuando asesinas a una unidad, reduce en 1 el coste de la siguiente unidad de los Oscuros que juegues.","","El altar palpitaba con vida una vez más, agitando las arenas que lo rodeaban con un ritmo lento y firme. Todos y cada uno de los discípulos de Xolaani lo sintieron en lo más profundo de sus corazones. Cada músculo, cada pensamiento, cada momento... Todo estaba ahora bajo su control.","Hito",[],["Shurima"],"RARA"],"06SH046":["Relicario del acólito","Cuando se me invoca, se crea 1 Acólito ruinoso en la mano. Cuando se me destruye, crea 1 Relicario del acólito entre las 5 cartas de arriba de tu mazo.","","\"¡Nuestras manos esculpen el desierto!\". - Acólito ruinoso","Hito",[],["Shurima"],"RARA"],"06SH033":["Maldición de la tumba","Predicción. Concede a una unidad \"Recibo el doble de daño y, si fuera a morir, me destruyo en su lugar\" esta ronda.","","\"Solo los necios persiguen el poder que escapa a su control\".\n- Xerath","Hechizo",[],["Shurima"],"RARA"],"06SH028":["Puerta del Vacío","Cuando invocas a un aliado o un aliado muere, otorga cada una de sus palabras clave positivas a 3 aliados de tu mazo.","","El heraldo de la colmena alzó ambas manos hacia la colosal estructura. \"UN TRONO\", gritó, \"PARA UNA EMPERATRIZ\". La puerta del Vacío palpitaba con vida. Llegaba su momento.","Hito",[],["Shurima"],"ÉPICA"],"06SH005":["Baccai proscrito","Jugar: Predicción. Si eliges a un Oscuro o un equipamiento, consigo +1|+1.","","Tenía un cinturón bordado en la mano, un regalo de su amigo Rhaast antes de la ceremonia de la Ascensión; pero, aunque respetaba enormemente el poder del Oscuro, en secreto su corazón albergaba resentimiento.","Unidad",["SECTARIA"],["Shurima"],"COMÚN"],"06SH056":["Castigo","Mata a TODOS los adeptos.","","A veces la luz te llama, otras viene hacia ti.","Hechizo",[],["Shurima"],"RARA"],"06SH040":["Resurrección imprudente","Cuando hayas equipado a un aliado esta partida, cuesto 2 menos. Revive al campeón aliado caído más fuerte.","","\"Jamás morirás, porque no te lo permitiré\".\n- Xolaani","Hechizo",["SECTARIA"],["Shurima"],"ÉPICA"],"06SH021":["Horror camuflado","Jugar: Golpeo a un enemigo.","","A medida que continuaba el asalto, del portal surgían criaturas más grandes e incluso más feroces. La ciudad de Belveth estaba perdida, y su cruel destino haría perdurar su nombre en la historia.","Unidad",[],["Shurima"],"RARA"],"06SH051":["Pastora de osos rocosos","Cuando invocas a otro aliado, avanza 1 ronda la cuenta atrás más elevada de tus hitos.\nCuando se me invoca, invoca 1 Oso rocoso hibernando.","","\"Los salientes tratan a Sadira como a una de los suyos. La muy bribona se escaparía con ellos en un santiamén si la dejara\".\n- Kadira, naturalista del desierto","Unidad",[],["Shurima"],"RARA"],"06SH055":["Sacerdotisa de la luz del desierto","Comienzo de ronda: Recibo 4 de daño. Roba un campeón y le otorga +2|+2. Si tu mazo empezó con 6 o más campeones diferentes, lo invoca.","","Los fieles aguantan en pie mientras el mal gana terreno, haciendo unos últimos esfuerzos para invocar la luz de la justicia. Un llamamiento desesperado que no será en vano, pues saben que obtendrán respuesta antes de que la oscuridad los consuma.","Unidad",[],["Shurima"],"ÉPICA"],"06SH004":["Cartas sangrientas de los Oscuros","Último aliento: Si mi portador no es Siervos de los Oscuros, invoca 1 Siervos de los Oscuros.\nPuedes gastar 6 de maná y matar a un aliado para que entre en juego como Xolaani.","","A medida que rugía el combate, Jun, desesperada y gravemente herida, se entregó a la voz que le susurraba. \"Jamás morirás porque no lo permitiré\", le dijo, suave como una lluvia de verano.","Equipamiento",["OSCUROS"],["Shurima"],"ÉPICA"],"06SH038":["Cuchilla oscilante","Golpear: Crea 1 Hallazgo fortuito en la mano.","","\"Persigue tu meta sin reparos\". - Navegaruinas\n","Equipamiento",[],["Shurima"],"COMÚN"],"06DE048":["Oso tejón bloqueador","","","\"Bienvenidos sean los amigos de los Marai, pero que se preparen aquellos intrusos cuyo corazón albergue maldad, ¡pues su protector desatará sobre ellos la más terrible de las venganzas!\".","Unidad",["ÉLITE"],["Demacia"],"COMÚN"],"06DE024":["¡Pilla!","Concede +1|+1 a un aliado esta ronda o se le equipa un equipamiento de coste 2 o menos en la mano.","","Este movimiento duele más si el grupo todavía no ha comido.","Hechizo",["MAESTRO DE ARMAS"],["Demacia","Freljord"],"RARA"],"06DE025":["Recluta bondadoso","Cuando se me invoca, concede Barrera a todos los aliados equipados esta ronda.","","\"El chico es una carga. Me negaba en rotundo a traerlo a cazar con nosotros, pues todavía se refiere a la vil criatura como su 'hermana'. Es tan iluso que me da hasta asco. Aunque supongo que en el fondo me da pena. Al menos esto le servirá de lección\". - Extracto del diario personal de Sirius Rowill, montaraz entusiasta","Unidad",[],["Demacia"],"RARA"],"06DE033":["Silenciar y reprimir","Destruye el equipamiento de una unidad. Si es un adepto, lo silencia.","","\"Esto es culpa tuya\". - Lord Eldred, líder de los Cazadores de Magos","Hechizo",[],["Demacia"],"RARA"],"06DE039":["Rugido de Icathia","Invoca 2 Espejismos de Icathia equipados con hasta 2 equipamientos en la mano que cuesten 2 o menos.","","Jax ha soñado innumerables veces que luchaba junto a su pueblo perdido. Algunas batallas las ganan, otras las pierden, pero siempre están unidos.","Hechizo",["MAESTRO DE ARMAS"],["Demacia"],"RARA"],"06DE011":["El Escudo Oscuro","Puedes gastar 5 de maná para que entre en juego como Joraal.","","\"Escucha, hijo mío. Jamás debes usar ese escudo. Fue entregado a nuestra familia como regalo hace mucho tiempo, con la condición de que lo protegiésemos y no lo tocásemos. Es mi responsabilidad, y cuando muera, será la tuya. ¿Lo entiendes? Nunca vuelvas a intentar cogerlo. Nunca lo toques\".\n\"Pero, mamá, escucho su voz... Me lo está pidiendo. Parece muy triste\".\n\"Razón de más para evitarlo, hijo mío\".\n- Lady Fortis y su hijo","Equipamiento",["OSCUROS"],["Demacia"],"ÉPICA"],"06DE021":["Vayne","Cuando se me invoca o al comienzo de ronda: Crea 1 Pirueta en la mano o, si ya tienes una copia, reduce su coste en 1.","Te he visto atacar 4 veces.","\"Nuestro objetivo fue humano en otro tiempo, lo que significa que es más listo que una bestia corriente. Un movimiento en falso nos podría conducir a todos a la muerte. No perdáis de vista al grupo, avisad de cualquier cosa extraña que veáis y, por encima de todo, recordad...\".","Unidad",[],["Demacia"],"Campeón"],"06DE043":["Cabracánido leal","La primera vez que invocas a una unidad Élite, consigo +2|+2.","","\"No es tan veloz como un alargéntea, pero te sorprendería lo lejos que puede llegar con esas patitas\". - Cithria, la Dama de las Nubes","Unidad",["PERRO"],["Demacia"],"COMÚN"],"06DE018":["Condena","Si has atacado dos o más veces esta ronda, cuesto 5 menos.\nUn aliado golpea a un enemigo.","","\"Virotes purificadores\". - Vayne","Hechizo",[],["Demacia"],"COMÚN"],"06DE041":["Fuerza de los campeones","Concede a los aliados +4|+4 y Al ataque esta ronda.","","\"¡A luchar con corazones resplandecientes!\". - Lux","Hechizo",[],["Demacia"],"ÉPICA"],"06DE026":["Mitos de Icathia","Crea 1 Espejismo de Icathia en la mano que cuesta 0 esta ronda o crea 1 Espátula dorada en la mano.","","Cuentan las leyendas que el portador original de la Espátula Dorada fue una criatura marina de gran destreza culinaria, que buscaba convertirse en un guerrero tan fuerte y valiente como Jax.\n\nOtras leyendas, más plausibles, dicen que las otras historias se las inventó cierto cocinero bastante ido de la olla.","Hechizo",[],["Demacia"],"RARA"],"06DE044":["Corcel de petricita","No recibo daño de los hechizos ni las habilidades enemigas.","","\"No hay nada más fuerte que la petricita\". - Arquitecto de Durand","Unidad",[],["Demacia"],"RARA"],"06DE017":["Pelea de pescado","Un aliado y un enemigo se golpean el uno al otro, o bien un aliado equipado golpea a un enemigo y después se desequipa.","","\"¡Toma pescado!\". - Experta pescadora de Jonia","Hechizo",["MAESTRO DE ARMAS"],["Demacia"],"COMÚN"],"06DE040":["Posibilidad tentadora","Elige un adepto o equipamiento de las 4 cartas de arriba de tu mazo. Lo robas y coloca el resto en tu mazo.","","Unos susurros suaves y sugerentes plantan la semilla del deseo en lo más profundo de los corazones. Como una astilla, se encona y crece, lo que alimenta las ansias. Estas ansias dan lugar a la transgresión, que trae consigo la muerte. Y así el ciclo continúa.","Hechizo",["SECTARIA"],["Demacia"],"COMÚN"],"06DE028":["Arpía maldita","Jugar: Me equipo con un equipamiento de coste 2 o menos desde la mano.\nLa primera vez que muero mientras estoy equipado, me curo por completo y se destruye el equipamiento en mi lugar.","","\"Kian, si estás leyendo esto... espero estar muerto. No soy capaz de controlar lo que me está ocurriendo. No consigo quitarme la sangre de debajo de las uñas. Me pica todo. Me rasco una y otra vez, pero no me alivia. Me duele. Quiero que pare. Si sigo vivo, por la razón que sea, prométeme que dejarás de buscarme.\n\nTe pediría perdón, pero no me lo merezco. Pórtate bien con madre, ¿vale?\".\n- Carta arrugada encontrada en un morral destrozado","Unidad",[],["Demacia"],"ÉPICA"],"06DE027":["Montaraz entusiasta","Atacar: Concede +1|+1 a los aliados equipados esta ronda.","","\"Te llamabas Janan, ¿no? ¿Qué sabes sobre Sirius?\".\n\"Ah, ¿el montaraz Rowill? Le revocaron el título hace unos años. Al parecer, ignoraba todas las órdenes que le daban. Hace lo que le da la gana y no acepta un 'no' por respuesta\".\n\"Ya veo\".\n\"Bueno... ¿y por qué le has dejado venir a esta caza?\".\n\"Yo no le he dicho nada\".\n\"Entonces, ¿por qué...? Ah, claro. Fantástico\".\n- Vayne y Janan, la Cazadora Viuda","Unidad",[],["Demacia"],"RARA"],"06DE019":["Cazadora viuda","Jugar: Me equipo con un equipamiento de coste 2 o menos desde la mano.","","\"Aunque la mujer parece una luchadora bastante hábil, aún se encuentra afligida por una pérdida que podría consumirla. La desesperación puede llegar a ser una buena motivación, eso lo sé bien; pero ¿sin control? ¿Acaso quiere morir...?\". - Extracto del diario personal de Sirius Rowill, montaraz entusiasta","Unidad",[],["Demacia"],"COMÚN"],"06DE032":["Acero demaciano","","","La espada y el escudo típicos que eligen los soldados con yelmos de Demacia.","Equipamiento",[],["Demacia"],"COMÚN"],"06DE029":["Alce inalterable","La primera vez que se equipe a un aliado, consigo Aguante.","","\"¡Atrás, vil criatura! ¡Toca un solo pelo del impecable pelaje de Pureza y me aseguraré de que AGONICES POR TODA LA ETERNIDAD!\". - Sirius Rowill, montaraz entusiasta","Unidad",[],["Demacia"],"COMÚN"],"06DE010":["Montaraz desertora","Cuando hayas equipado a un aliado en esta partida, consigo Vigía.","","Tras muchos años reprimiendo sus habilidades mágicas, acabó odiándose muchísimo a sí misma, lo cual acababa pagando con sus víctimas. Cuando desertó de los montaraces, su furia ya no tenía objetivo, hasta que una voz la llamó en la oscuridad. Hablaba de un nuevo orden en el que podría dar rienda suelta a su crueldad.","Unidad",["SECTARIA"],["Demacia"],"RARA"],"06DE006":["Cocinero de combate","Cuando se me invoca, improviso y me forjo.","","Tras pasar una época en el ejército de Demacia, Breshi pensaba que se jubilaría y se dedicaría a cocinar en una tranquila taberna de pueblo, pero Jax echó por tierra sus planes con una pelea de bar y una opinión especialmente crítica sobre sus huevos duros. Desde entonces, Breshi tiene una nueva meta en la vida: enseñarle lo que es bueno a Jax.","Unidad",["MAESTRO DE ARMAS"],["Demacia","Freljord"],"COMÚN"],"06DE034":["Perra loba fiel","Si un aliado ha muerto esta ronda, cuesto 2 menos.\nJugar: Me equipo con un equipamiento de coste 2 o menos desde la mano y me forjo.","","\"Tengo a Maggie desde que era una cachorrita. Ya tiene unos años, pero sigue tan avispada como siempre. Daría mi vida por ella, y sé que ella haría lo mismo por mí\". - Janan, la Cazadora Viuda","Unidad",["PERRO"],["Demacia"],"COMÚN"],"06SI045":["Cuchilla de almas","Mata a un aliado para invocar 2 copias endebles.","","Tampoco les hacía falta.","Hechizo",[],["Islas de la Sombra"],"RARA"],"06SI007":["La alabarda de los Oscuros","Para jugarme, mata a un aliado.\nPuedes gastar 10 de maná para que entre en juego como Taarosh.","","Presionando contra los confines de su celda, Taarosh escuchó la llamada de su general. Respondería, fuera como fuera.","Equipamiento",["OSCUROS"],["Islas de la Sombra"],"ÉPICA"],"06SI034":["Espectro de ecos","Fin de ronda: Por cada aliado que haya muerto esta ronda, otorga +1|+1 a todas sus copias aliadas estén donde estén.","","\"No sé qué magia perversa usan y NO quiero saberlo. Todo lo que sé es que si se levantan, los pienso matar. Otra vez\".\n- Vigilante de las Islas","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"06SI029":["Lanza maléfica","Si un aliado ha muerto esta ronda, cuesto 2 menos.","","\"No puede haber justicia. Solo venganza\". - Kalista","Equipamiento",[],["Islas de la Sombra"],"COMÚN"],"06SI032":["Sentencia final","Mata a una unidad con un total de 4 o menos de poder y vida, o destruye el equipamiento de una unidad.","","Sea cual sea la forma en la que llegue la muerte en las Islas de la Sombra, más vale que sea rápida.","Hechizo",[],["Islas de la Sombra"],"RARA"],"06SI031":["Espadas de los caídos","Concede a un aliado \"Último aliento: Invoca 1 Espejismo de Icathia con mi equipamiento\" esta ronda.","","A veces lo mejor que se puede hacer por un aliado caído es coger su arma y seguir luchando.","Hechizo",["MAESTRO DE ARMAS"],["Islas de la Sombra","Shurima"],"RARA"],"06SI014":["Vestíbulo opulento","Cuando se me invoca, invoca 1 Banda espantosa.\nComienzo de ronda: Si tienes la ficha de ataque, invoca 1 Banda espantosa.","","\"Los intérpretes están en sus puestos, el escenario está preparado, el público espera. ¡Música, maestro!\". - Anfitrión escandaloso","Hito",[],["Islas de la Sombra"],"ÉPICA"],"06SI038":["Prodigio redimido","Atacar: Invoca 1 Banda espantosa en ataque.","","La búsqueda de la perfección era limitante, rígida. La perfección no tenía vida, ni podía respirar. Sin embargo, la perfecta imperfección... Eso sí que era algo por lo que luchar.","Unidad",[],["Islas de la Sombra"],"RARA"],"06SI003":["Fireth, Cosechadora de las arenas","Cuando se me invoca, improviso.","","Jax le preguntó a Fireth su nombre varias decenas de veces en las primeras semanas de viaje juntos, pero solo le decía: \"¡Soy la Cosechadora!\". Breshi encontró una solución estupenda: prepararía una tarta, y necesitaba el nombre del miembro más fuerte del equipo para celebrar en su honor.","Unidad",["MAESTRO DE ARMAS"],["Islas de la Sombra","Shurima"],"ÉPICA"],"06SI006":["Guardiana de la caja","Cuando hayas equipado a un aliado en esta partida, consigo Robo de vida.","","\"La caja no comparte sus secretos sin más, Shieda Kayn: hay que pagar un precio terrible. Pero, si te atreves a mirar en la sombra de las sombras, verás que en su interior se ocultan cosas horribles y maravillosas\". - Ysdra, guardiana de la caja","Unidad",["SECTARIA"],["Islas de la Sombra"],"COMÚN"],"06SI039":["Forma del miedo","Mata a un aliado para invocar 1 Niebla envolvente.","","Solo un insensato se quedaría mirando la Niebla Negra con la esperanza de hallar una forma familiar.","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"06SI042":["Caballero inmortal","Si fuera a obtener Endeble, consigo +1|+1 en su lugar.","","Los soldados entrenados para soportar el castigo en la vida solo eran más diligentes y capaces en la muerte. Ni el frío, ni el dolor ni el miedo los intimidaba.","Unidad",[],["Islas de la Sombra"],"RARA"],"06SI036":["Devastación total","Mata a todas las unidades excepto los aliados oscuros y los aliados equipados.","","En cuanto cogió las armas, perdió su humanidad y, en su lugar, una esencia cargada de odio llenó el receptáculo vacío de la que otrora fue la estudiante Jun. La arrasó de arriba abajo, por dentro y por fuera, e hizo salir al mundo al Oscuro adormecido.","Hechizo",["SECTARIA"],["Islas de la Sombra"],"RARA"],"06SI046":["Centinela incesante","Último aliento: Roba 1 carta.",""," \"Y velaré durante el resto de la eternidad, pues mi deber va más allá de la vida y de la muerte\".","Unidad",[],["Islas de la Sombra"],"COMÚN"],"06SI041":["Guardián del valle de luna","Cuando invocas a un aliado con Endeble, obtiene +1|+0.\nAnochecer: Invoca 1 Pimpollo.","","Lejos de las costas de las Islas de la Sombra, se encuentran los cadáveres de árboles muertos tiempo atrás, torcidos e inmóviles; pero los observadores más atentos se darán cuenta de que, en ese suelo iluminado por la luna, comienza a surgir nueva vida.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"07PZ009":["Relojizo mejorado","Jugar: Predicción. Roba 1 y reduce su coste en 1.","","''Este pequeñín solo necesitaba unos pequeños ajustes. Cambiar unos engranajes por aquí, un brazo nuevo por allá, ¡y listo para una segunda vida! Siempre digo que el tiempo es un regalo que todos deberían recibir más a menudo''. - Ekko","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"07PZ017":["Vendedor de bombas destello","Cuando juegas un hechizo, coloca 1 Trampa con bomba destello entre las 8 cartas de más arriba del mazo enemigo.","","''¿Y sabes por qué estas peques son mejores que las setas? ¡Porque tú decides cuándo explotan! ¡Eso sí que es útil!''.","Unidad",[],["Piltover y Zaun"],"RARA"],"07PZ005":["Culatazo","Inflige 1 de daño a un enemigo y al nexo enemigo. Descarta hasta 2 cartas para aumentar el daño en 1 por cada carta que hayas descartado.","","\"Vale, vale. Creo que esto solo funcionará una vez, pero hazme caso, ¡va a ser la caña!\". - Jinx","Hechizo",[],["Piltover y Zaun"],"RARA"],"07NX009":["Tiro grácil","Inflige 1 de daño al nexo enemigo. La próxima vez que un aliado golpee el nexo esta ronda, crea 1 Tiro grácil en la mano.","","''No podrías seguirme el ritmo ni aunque pelease con palos y piedras. ¿Has visto estas armas? Ni lo intentes''. - Samira","Hechizo",[],["Noxus"],"ÉPICA"],"07NX008":["Filo elegante","Asalto: Consigo +2|+0.","","''Mis tarifas son altas y no trabajo para cualquiera. Pero, si tienes la suerte de contratar mis servicios, a cambio consigues porte, elegancia y cuchillas que nunca fallan. Y lo que es más importante: estilo. ¿A quién no le va a gustar un asesinato con estilo?''.","Unidad",[],["Noxus"],"COMÚN"],"07NX014":["Pirueta","Asalto: Cuesto 2 menos.\nInflige 1 de daño a cualquier unidad o estructura y aturde a un enemigo.","","''¿Qué te ha pasado? Si solo estaba estirando un poco. No me digas que te he matado estirando''. - Filo elegante","Hechizo",[],["Noxus"],"RARA"],"07NX007":["Samira","Asalto o golpear: Crea 1 Clase en la mano si no tienes una copia ya.","Te he visto jugar 6 cartas. Se reinicia cuando comienzas una ronda con la ficha de ataque.","''Siempre ando detrás de algún canalla con deudas sin saldar. Huir de esas deudas hace que te ganes enemigos... que luego me llaman a mí''.","Unidad",[],["Noxus"],"Campeón"],"07NX006":["Guaperas arrogante","Asalto: Mi poder se duplica.",""," ''Normalmente me gusta poner ciertas normas, como 'nada de zarpas en la cara y el tupé', pero ¿a quién vamos a engañar? No vas a tocarme un pelo''.","Unidad",[],["Noxus"],"COMÚN"],"07NX015":["Dame la Saqueadora","Asalto: Otorga +1|+0 a los aliados.","","''Ah, Dame. Esa tía tiene talento para todo lo dramático. Hay a quien no le gusta su teatralidad, pero, cuando está en su salsa, todos salimos ganando''. - Filo elegante","Unidad",[],["Noxus"],"COMÚN"],"07NX003":["Rienda suelta","Concede a un aliado +2|+0 esta ronda.\nAsalto: Le concede +2|+1 en su lugar.",""," ''Indari ha movido unos cuantos hilos para colarnos sin que nadie se entere... Ya montaré el numerito más tarde''. - Samira","Hechizo",[],["Noxus"],"COMÚN"],"07NX004":["Artesana diestra","Cuando se me invoca, activa el efecto Asalto de todos los aliados.","","''Montar un negocio no es cosa fácil, pero a Lani y a mí nos quitaban la mercancía de las manos. Había algunos mirones, pero esta noche la mayoría buscaban gresca. A decir verdad, saber quién quiere cargarse a quién es una forma muy útil de conocer el terreno''. - Miel","Unidad",[],["Noxus"],"RARA"],"07NX001":["Demoledora intrépida","Jugar: Inflige 1 de daño al nexo enemigo o activa el efecto Asalto de un aliado.","","''Cuando estás en el negocio de las armas, tienes que investigar mucho. Crear un concepto, probar, reconstruir o modificar: todo ello requiere información. ¡Necesitas muchas pruebas de campo y unos cuantos cráteres para crear un buen prototipo!''.\n- Lani","Unidad",[],["Noxus"],"RARA"],"07NX005":["Capitana Indari","Cuando se me invoca, improviso.\nAsalto: Forja al resto de aliados.","","''He trabajado con muchos agentes, unos más fáciles que otros... Y luego está Samira. He aceptado que no voy a poder frenarla. En su lugar, me dedico a orquestar el caos, dirigirlo... y, de vez en cuando, unirme a él''.","Unidad",["MAESTRO DE ARMAS"],["Noxus"],"RARA"],"07BW018":["Vieja loca Babs","Cuando recuperas maná, consigo +1|+0 por cada punto de maná recuperado.","","''Jack, cariñito, he encontrado algo que te puede interesar, ¿vienes?''.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"07BW021":["Bucanera impulsiva","Asalto: Invoca a un adepto aleatorio de coste 1 que recibe Audacia.","","''Yo de ti no me acercaba a ella. Tiene la mala costumbre de pagar sus problemas con los demás''. - Samira","Unidad",[],["Aguas Estancadas"],"COMÚN"],"07BW002":["Jack","Golpear: Crea 1 Moneda en la mano.\nCuando recuperas maná, me curo 1 por cada punto de maná recuperado.","Has gastado 12 o más de maná en una ronda.","''Hay que ser muy valiente o muy tonto para enfrentarse a mí, y el resultado es el mismo en ambos casos. Mi consejo es que te preocupes de salir con vida''.","Unidad",[],["Aguas Estancadas"],"Campeón"],"07BW040":["Nukkle","Cuando se me invoca, crea 1 Mako Fugaz en la mano.","","''Un corte por aquí, una puñalada por allá, ¡pero de buen rollo! Derramar un poquillo de sangre en el mar no hace daño a nadie. Bueno, a mí no me hace na'\". - Nukkle","Unidad",[],["Aguas Estancadas"],"RARA"],"07BW001":["Promotor traicionero","Cuando recuperas maná, crea 1 adepto aleatorio Fugaz en la mano con el máximo coste que te puedas permitir.","","''Si quieres sangre, habla con Jack. Si quieres saber dónde, cuándo, quién y por cuánto, habla conmigo''.","Unidad",[],["Aguas Estancadas"],"RARA"],"07BW003":["Carterista","Último aliento: Crea 1 Moneda en la mano.","","''¡Vuelve aquí, canalla! ¡Que necesito eso para comer!''.\n- Angel","Unidad",[],["Aguas Estancadas"],"COMÚN"],"07BW014":["Pablo Cincopuños","Cuando se me invoca, crea 1 Premio de la lucha Fugaz en la mano.","","\"¡Dale, Jack! ¡Eso es! ¡Enséñales de qué estamos hechos en Aguas Estancadas! Ah, qué buenos tiempos aquellos, cuando me llamaban 'Pablo Carabonita'... ¿Cómo que no? ¡Que sí, que también me llamaban así! Te han reventado tanto el coco que ya no te acuerdas de nada''. - Pablo Cincopuños","Unidad",[],["Aguas Estancadas"],"COMÚN"],"07BW013":["Angel","Asalto: Crea 3 Monedas en la mano.","","''¿Eso es todo? Qué adorable. Ahora me toca a mí''.","Unidad",[],["Aguas Estancadas"],"COMÚN"],"07BW006":["Empresa arriesgada","Inflige 3 de daño a una unidad. Si resulta letal, crea 2 Monedas en la mano.","","''El que no arriesga, no gana... Y estas son las mandíbulas de un ganador''. - Jack","Hechizo",[],["Aguas Estancadas"],"ÉPICA"],"07BW026":["Cadena punzante","Asalto: Cuesto 2 menos.\nRoba 2 cartas en el siguiente comienzo de ronda y les otorga Fugaz.","","Cuando oyes su traqueteo sobre el suelo, ya es demasiado tarde.","Hechizo",[],["Aguas Estancadas"],"RARA"],"07BW027":["Padre Cólera","Asalto: Recupera 1 de maná de hechizos y crea un hechizo aleatorio de coste 1 de una de las regiones en tu mano.","","Los orígenes de Padre Cólera son más turbios que una nube de tormenta y, aunque le preguntes, nunca te da una respuesta directa (ni nada que se pueda oír por encima del estruendo que causa su destrucción).","Unidad",[],["Aguas Estancadas"],"RARA"],"07BW008":["Premio de la lucha","Un aliado y un enemigo se golpean el uno al otro. Sus vidas no pueden bajar de 1 a causa de este golpe.","","A veces, pagas con monedas y aceite de lámpara; otras, con nudillos y dientes. Así son las cosas, pero ¿un intercambio equitativo? ¡Eso sí que es hacer negocios!","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"07BW041":["Golpercebes","Golpear: Crea 1 Moneda en la mano.","","''Reconozco que no son lo más tradicional, tienes razón. Pero dales una oportunidad y en na' de tiempo te acostumbras''.\n- Bull","Equipamiento",[],["Aguas Estancadas"],"RARA"],"07BW004":["La Corte del Rey","Cuando se me invoca, roba 1 Jack.\nCuando invocas a un aliado, crea 1 Premio de la lucha Fugaz en la mano.\nCuando un aliado sobrevive tras recibir daño, le otorga Audacia.","","El barco personal de Jack lo ha llevado a él y los suyos por las aguas de toda Runaterra, desde Aguas Estancadas hasta Jonia. Nadie sabe cómo viaja por debajo del agua sin hundirse, pero se dice que el verdadero peligro está bajo la superficie...","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"07BW025":["Inferna","Cuando activas Asalto, roba 1 y le otorga Fugaz.","","''Ser pirómana en alta mar tiene sus ventajas. El agua impide que el fuego se te vaya de las manos y no te exige parte de los beneficios''.","Unidad",[],["Aguas Estancadas"],"RARA"],"07IO020":["Relevo","Retira a un aliado y crea 1 Moneda en la mano o gasta 5 de maná para retirar a un enemigo y crear 1 Moneda en la mano.","","''Solo entro por dos motivos. El primero es que tu oponente se lo esté pasando demasiado bien dándote una paliza. El segundo, que tú te lo estés pasando demasiado bien, ¡y yo también quiero!''. - Profesional del foso","Hechizo",[],["Jonia"],"RARA"],"07IO014":["Maestro Bingwen, el Tamiz","Jugar: La próxima vez que juegues una unidad esta ronda invoca una copia exacta de ella con Endeble.","","Bingwen el Pájaro era un luchador con una postura y agilidad similares a las de una grulla, de ahí su apodo. Tras retirarse comenzó a ejercer de entrenador y, con buen ojo y mano firme, separa al verdadero talento de la morralla.","Unidad",[],["Jonia"],"ÉPICA"],"07IO023":["El Veterano","Jugar: Retira al enemigo más fuerte. Si has gastado 16 o más de maná esta ronda, retira a todos los enemigos.","","''No me pienso quitar la máscara, muchacha. No me lo pidas más o acabarás como este bicho''.","Unidad",[],["Jonia"],"RARA"],"07IO011":["Sett","La primera vez que mi vida vaya a bajar de 1 al atacar, consigo Barrera en su lugar.","Has gastado 40 o más de maná.","Mientras se regocija en los vítores del abarrotado público en su arena subterránea exclusiva, Sett se detiene un segundo a reflexionar sobre su vida. Recuerda todo por lo que ha luchado y piensa en aquello a lo que aún está por enfrentarse. No obstante, una cosa está clara: qué bien sienta ser el jefe.","Unidad",[],["Jonia"],"Campeón"],"07IO046":["Alabrillo real","Las demás aves aliadas tienen +1|+0 y Ataque rápido.","","''He comprobado, una vez tras otra, que las criaturas más bellas de esta selva son también los depredadores más mortales''. - Anura","Unidad",["AVE"],["Jonia"],"RARA"],"07IO009":["Contable atenta","Golpe al nexo: Crea 1 Moneda en la mano.","","En estos lares abundan los conspiradores y estafadores, pero Lise tiene la cualidad más valiosa de todas para Sett: fiabilidad. No se toma días libres, siempre puede contar con ella y nunca le ha hecho dudar. Así, Lise se ha ganado su apoyo y una advertencia para cualquiera que venga en busca de problemas: el que apuesta en contra de la casa siempre pierde.","Unidad",[],["Jonia"],"RARA"],"07IO019":["Barman enrollada","Jugar: Cura a un aliado o a tu nexo 3 de vida y crea 1 Moneda en la mano.","","''La primera ronda es para saludarse, la segunda para ponerse cómodos. En la tercera ya surgen los problemas y, a partir de la cuarta, se les empieza a soltar la lengua. ¡Ni te imaginas las cosas que he llegado a escuchar!''.","Unidad",[],["Jonia"],"COMÚN"],"07IO017":["Hagan sus apuestas","Roba 2 y crea 2 Monedas en la mano.",""," ''Ellos nos dan dinero y nosotros les damos una oportunidad. Je, je... y pensar que algunos aún no entienden por qué siempre gana la casa...''.","Hechizo",[],["Jonia"],"COMÚN"],"07IO047":["Cobra embaucadora","Cada ronda, la primera vez que juegas a otro adepto, invoca una copia idéntica del mismo. Si tu tablero está lleno, me otorga sus estadísticas y palabras clave en su lugar.","","''¿Crees que estas flores podrían valer algo? Llámame loco, pero... creo que están bailando''. - Cazador furtivo piltovano","Unidad",["REPTIL"],["Jonia"],"ÉPICA"],"07IO013":["Profesional del foso","Cuando se me invoca, crea 1 Moneda en la mano.","","''Hay quien lo hace por la pasta, por oír rugir al público o por pura sed de sangre. ¿Yo? Soy incapaz de elegir. Lo necesito todo y aquí lo consigo de sobra''.","Unidad",[],["Jonia"],"COMÚN"],"07IO012":["Segurata","Cuando se me invoca, crea 1 Segurata Fugaz en la mano y otorga +1|+1 a otro Segurata.\nPotenciación 5: Ataque rápido.","","''Si piensan que eres estúpido, déjalos. Deja que crean que pueden hacer lo que les dé la gana... y disfruta de la sorpresa en sus caras cuando se den cuenta de que te han subestimado''. - Sett","Unidad",[],["Jonia"],"RARA"],"07IO007":["Rompecaras","Aturde a 2 enemigos y crea 1 Moneda en la mano.","","''¿Qué pasa? Dijo algo de un puñetazo en la boca, ¡pero no especificó a quién!''. - Sett","Hechizo",[],["Jonia"],"COMÚN"],"07SH023":["General de las arenas caídas","Tengo +1|+0 por cada aliado con Endeble que hayas invocado en esta partida.","","''Quizás pienses que no eres más que un grano de arena ante este adversario, pero sé que estás ahí. Siento tu presencia en las dunas. ¡Préstame tu fuerza y derrotemos juntos a nuestros enemigos!''.","Unidad",[],["Shurima"],"RARA"],"07SH018":["Guardián del secreto","Cuando se me invoca, crea en la parte inferior de tu mazo 2 campeones aleatorios de nivel 2 que no estén en tu mano, tu mazo o en juego.","","No sabe bien qué vio ni cómo o cuándo llegará el desastre, pero sabe con total certeza que no están preparados. Y puede que nunca lo estén.","Unidad",[],["Shurima"],"ÉPICA"],"07SH008":["Ataque en manada","Comienza un ataque gratis con una copia exacta y endeble de cada gato aliado.","","Una cazadora solitaria es algo temible, pero una manada lo es aún más.","Hechizo",[],["Shurima"],"COMÚN"],"07FR008":["Cachorro Mantohelado","Gasta 6 de maná para que entre en juego como Madre Mantohelado.","","Freljord alberga muchos peligros, sobre todo para aquellos que aún no están familiarizados con su fría inclemencia.","Unidad",["PERRO"],["Freljord"],"COMÚN"],"07FR009":["Herrera innovadora","Cuando se me invoca, improviso.\nCada ronda, la primera vez que forjes o equipes a un aliado, cura 1 de vida a tu nexo.","","''Esta bolita de pelo no me ayuda a trabajar más rápido, pero siempre me saca una sonrisa. Con eso me basta''. - Herrera innovadora","Unidad",["MAESTRO DE ARMAS"],["Freljord"],"RARA"],"07FR005":["Siervo baluarte","No recibo daño de los hechizos ni las habilidades aliadas.","","''Una vez comienza, la avalancha no tiene freno''. - Lissandra","Unidad",[],["Freljord"],"RARA"],"07SI002":["Cosecha de almas","Mata a un adepto con 3 o menos de poder o gasta 3 de maná para matar a un campeón con 3 o menos de poder.","","Es apenas un susurro en el viento, silencioso pero profundo, que cambia una vida por otra.","Hechizo",[],["Islas de la Sombra"],"RARA"],"07SI001":["Erradicación","Mata a todas las unidades con 3 o menos de poder.","","Todo aquel que me mire sentirá el toque del olvido, del cual jamás podrá librarse.","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"07SI007":["Compañero sepulcral","La primera vez que otro aliado muere en cada ronda, roba 1.","","\"¡Acabo de enseñarle un truco nuevo! ¿Quieres verlo?\".\n- Bromista espectral","Unidad",["PERRO"],["Islas de la Sombra"],"COMÚN"],"07MT003":["Potrillo cósmico","Comienzo de ronda: Me curo 1 de vida y curo 1 a tu nexo.","","Surcan el cielo como la estela de una aurora y su brillo calma los corazones, alivia las heridas y arregla aquello que se ha quebrado.","Unidad",[],["Targon"],"RARA"],"07MT001":["Astro ineludible","Inflige 4 de daño a un enemigo que haya atacado esta ronda o que esté aturdido.","","Las estrellas observan nuestros actos, sean buenos o malos. Los justos serán bendecidos y los malvados serán juzgados.","Hechizo",[],["Targon"],"COMÚN"],"07MT007":["Letrado expiatorio","Último aliento: Crea en la mano copias de los 3 primeros hechizos que has usado en mí.","","''Camphor ha arrebatado mucho a demasiada gente. Cuando llegue tu hora, asegúrate de morir bajo tus propios términos. No le des la satisfacción''. - Pantheon","Unidad",[],["Targon"],"ÉPICA"],"07BC005":["Blandefilos tallada","","","''Anda, esto es nuevo''. - Hada blandefilos","Unidad",["HADA"],["Ciudad de Bandle"],"COMÚN"],"07BC009":["Lanzamiento de tarta","Inflige 1 de daño a una unidad. Crea 1 Postre peligroso en la mano.","","Prepárate.","Hechizo",[],["Ciudad de Bandle"],"RARA"],"07BC015":["Condensar","Elige un adepto, crea una copia de él de coste 1 en la mano y sus estadísticas pasan a ser 1|1.","","\"Vaya... ¡Parece que más pequeño no siempre significa más adorable!\". - Lulu","Hechizo",[],["Ciudad de Bandle"],"RARA"],"07DE002":["Orden de registro","Un aliado con 4 o más de poder captura una unidad o un aliado captura un hito.","","''No te muevas y no digas nada. Cualquier tipo de resistencia sería poco prudente''. - Inspector de los Cazadores de Magos","Hechizo",[],["Demacia"],"RARA"],"07DE005":["¡Formación!","Concede +2|+2 a un aliado esta ronda.","","\"¡Mantente firme! ¡Solo han sido unos golpes!\". - Vanguardia Impertérrita","Hechizo",[],["Demacia"],"COMÚN"],"07DE008":["Altar de la unidad","Cuando se me invoca, roba una unidad.\nCuando se invoca a un aliado, aumenta sus estadísticas hasta igualar su coste.","","La primera vez que vio el altar, Cithria se quedó sin palabras. No podía sino admirar la majestuosidad de aquellos venerados héroes. ¿Llegaría el día en que estuviera entre ellos?","Hito",[],["Demacia"],"RARA"],"07PZ019":["Orugamóvil tecnoquímico","Tengo +1|+0 por cada aliado de coste 1 que hayas invocado en esta partida.","","\"Tengo que dibujarle MUCHAS patas al caballito, Señor Lagarto, porque tenemos que llegar al castillo SUPERRÁPIDO. Ay, vaya... Me ha salido un poco raro. Y un poco verde\". - Ingvar, la Joven","Unidad",[],["Piltover y Zaun"],"RARA"],"07PZ021":["Anura y Froop","Los aliados con un subtipo diferente al de otros aliados en juego cuestan 1 menos.","","\"¡No quiero hacerte daño, amiguita! He venido a la selva a investigar, no a destruirla\".","Unidad",["REPTIL"],["Piltover y Zaun"],"ÉPICA"],"07PZ022":["Corriente divina","Inflige 1 de daño a un enemigo o al nexo enemigo y 1 a otro.","","A la mayoría de piltovanos el comportamiento del viento les da exactamente igual. Sin embargo, hasta la más sutil brisa huele a salvación para los zaunitas.","Hechizo",["ELEMENTAL"],["Piltover y Zaun"],"COMÚN"],"07PZ013":["Monumento del Sumidero","Si tu nexo sufre daño que no proviene de Boletus venenoso, tu oponente coloca 5 Boletus venenosos en tu mazo por cada punto de daño infligido en su lugar.","","Incluso en lo más profundo de las callejuelas de Zaun, somos lo que comemos.","Hito",[],["Piltover y Zaun"],"ÉPICA"],"07PZ015":["Aparatrasto épico","Gasta todo tu maná para jugar esta carta. Invoca 1 Chismefacto a la fuga y aumenta sus estadísticas hasta alcanzar la cantidad de maná gastada.","","\"La principal responsabilidad de un científico es controlar las variables. Las consecuencias de un accidente en un campo de estudio como el nuestro... ¡Ay! ¡Tiemblo de solo pensarlo!\".\n- Profesor Heimerdinger","Hechizo",[],["Piltover y Zaun"],"COMÚN"],"07NX028":["Capitán Kalrix","Golpe al nexo: Inflige una cantidad de daño al nexo enemigo equivalente a la mitad de su vida redondeada hacia arriba.","","La esencia de Noxus radica en la conquista por encima de todo. Nada, ya sea madera, piedra o acero, puede detener el avance del ariete noxiano.","Unidad",[],["Noxus"],"ÉPICA"],"07NX034":["Salón del Banquete Carmesí","Los aliados cuestan 1 menos. Cuando juegas a un aliado, le infliges 2 de daño.","","\"¡Acercaos, amigos míos! ¡Sentaos! La compañía es buena y la bebida, abundante. Me muero por enseñaros qué tentempié tenemos preparado\". - Vladimir","Hito",[],["Noxus"],"ÉPICA"],"07NX032":["Tomo del Conservatorio","Cuando mi portador juega una habilidad, la copia.","","El Conservatorio Flor de Cuervo debía su célebre renombre a su colección de escritos, muchos de los cuales acabaron siendo pasto de las llamas provocadas por una alumna particularmente difícil...","Equipamiento",[],["Noxus"],"RARA"],"07NX033":["Acechahueso de tres colas","Cuando se me invoca, consigo +1|+1 por cada subtipo diferente que tengan los demás aliados.","","\"¡Cuidado, idiotas! Los noxianos solo compran bestias de batalla en excelentes condiciones. ¡Os descontaré cada rasguño de la paga!\". - Magnate prominente","Unidad",["GATO"],["Noxus"],"COMÚN"],"07RU015":["El Rey Poro","Origen: Decreto del Rey Poro.\nEn cada ronda, la primera vez que invocas a otro poro, crea 1 Snack para poros en tu mano.","Has invocado a 6 o más poros nuevos. Cuando subo de nivel, crea 1 snack especial aleatorio en la mano.","Ingvar sabe reconocer el potencial cuando lo ve. Dejando a un lado su aspecto casero, este adorable compañero podría fácilmente ser el líder de un megatrillón de poros..., con un poquito de imaginación. ","Unidad",["PORO"],["Runaterra"],"Campeón"],"07RU012":["Neeko","Origen: ¡Coleguis selváticos variopintos!.\nJugar: Puedes camuflarme como 1 de 3 adeptos de coste 2 de mi origen.","Atacar: Has atacado con aliados que tienen 6 o más subtipos diferentes.","Neeko puede transformarse en muchas cosas, pero su corazón nunca cambia: siempre la conduce hasta su familia y su bosque.","Unidad",["CAMBIAFORMAS"],["Runaterra"],"Campeón"],"07BW043":["Invocación de oleaje","Inflige 1 de daño a una unidad. Engendra 1 por cada punto de daño infligido.","","Solo los más sabios pueden doblegar los elementos a su voluntad.","Hechizo",["ELEMENTAL"],["Aguas Estancadas"],"RARA"],"07BW035":["La guarida del estafador","Las cartas en tu mano tienen Fugaz.\nCuando juegas una carta, roba 1.","","\"Juega bien tus cartas o prepárate para perderlo todo\".\n- Twisted Fate","Hito",[],["Aguas Estancadas"],"ÉPICA"],"07BW042":["Cazador de cubierta","Jugar: Manifiesta un adepto con un subtipo diferente al de los aliados en juego.","","\"Hay un motivo por el que tenemos a este pequeño rufián rondando por aquí: ¡no nos hemos topado con una rata en años!\". - Grumete del Heraldo","Unidad",["GATO"],["Aguas Estancadas"],"COMÚN"],"07BW039":["Príncipe dragón Grinzo","La primera vez que se invoca a un aliado de coste 1 en cada ronda, recuperas 1 de maná de hechizos.","","\"Señor Lagarto, ¿qué hace usted aquí? ¡¿Es que también le gustan los poros?!\". - Ingvar, la Joven","Unidad",["DRAGÓN"],["Aguas Estancadas"],"RARA"],"07BW033":["Canto de sirena","Invoca 1 Sombra aleatoria.\nOtorga +1|+1 a los aliados de coste 1 estén donde estén.","","Algunos marineros de Aguas Estancadas se taponan las orejas con algodón en las noches más tranquilas por alta mar. Saben de sobra que la música bajo las olas no conduce sino a una tumba en el fondo del océano.","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"07IO041":["Brisa rejuvenecedora","Cura 3 de vida a tu nexo y roba 2 hechizos.","","\"El viento es el único compañero del errante\". - Yasuo","Hechizo",["ELEMENTAL"],["Jonia"],"COMÚN"],"07IO043":["Oráculo que todo lo ve","Jugar: Elige 1 de 3 hechizos veloces o lentos de la mano o el mazo enemigos. Crea 1 Tallas de adivinación para dicho hechizo.","","El ojo que se libera del mundo material puede verlo todo. Aunque parezca ciego, aquellos que confundan al oráculo con un blanco fácil serán castigados al instante y sin piedad alguna.","Unidad",[],["Jonia"],"RARA"],"07IO049":["Airis","Golpe al nexo: Invoca 1 Sombra aleatoria.","","\"Silencio, que ya casi hemos llegado. Querías conocer a mi amiguita, ¿no? Créeme... Te va a adorar\".","Unidad",[],["Jonia"],"RARA"],"07SH038":["Cachorro pakaa","Emboscada a 1.\nGolpe al nexo: Invoca 1 Protectora pakaa.","","De apariencia adorable pero instintos salvajes. Con el tiempo y el aprendizaje adecuados, hasta el pakiti más diminuto puede convertirse en una feroz bestia.","Unidad",["GATO"],["Shurima"],"COMÚN"],"07SH041":["Comprobación","Manifiesta una carta con Emboscada.","","La labor de reconocimiento en la selva es la más indeseable de todas por una simple razón: está llena de sorpresas.","Hechizo",[],["Shurima"],"RARA"],"07SH004":["Acecho","Concede a un aliado +2|+0 esta ronda. Si es Sombra en la maleza, le concede +2|+2 en su lugar.","","\"Muévete con cautela y golpea con certeza, pakiti\". - Nidalee","Hechizo",[],["Shurima"],"COMÚN"],"07SH013":["Nidalee","Emboscada a 2.","Te he visto invocar o transformar a otros 4 aliados.","\"Siempre te protegeré, niña lagarto. Le daremos su merecido a esos furtivos. Juntas\". - Nidalee","Unidad",["GATO"],["Shurima"],"Campeón"],"07SH009":["Vastaya vengativo","Emboscada a 3.\nCuando me transformo desde Emboscada del vastaya vengativo, detiene todos los hechizos veloces, lentos y todas las habilidades enemigas.","","\"No tengáis miedo, pequeños. Yo os protegeré, y así saldaré mi deuda con Nidalee\".","Unidad",[],["Shurima"],"COMÚN"],"07SH039":["Soldado todoterreno","Emboscada a 0.\nCuando se me invoca o me transformo, concede Vulnerable al enemigo más débil.","","\"Esta preciosidad puede convertir hasta a un novato en todo un profesional de la escalada y el salto de obstáculos. Me ha costado una fortuna, pero seguro que puedo pagar los préstamos con un par de pieles de bestia poco común...\".","Unidad",[],["Shurima"],"RARA"],"07SH044":["Aurora embelesal","Emboscada a 4.\nCuando me transformo, invoca 1 Aurora embelesal.","","\"¡Cómo me gustaría ver una en persona! Muchos exploradores creen que la existencia de la aurora embelesal es un mito, pero hay un joven que afirma lo contrario. Me ha dicho que el ave es de colores brillantes y que la envergadura de sus alas ronda la altura media de un humano. La otra noche me dijo que, si consigues mirarla a los ojos, es que ya te has convertido en su presa\". - Extracto del diario de campo de Anura, día 21","Unidad",["AVE"],["Shurima"],"RARA"],"07SH003":["Furtivo en dirigible","Emboscada a 3.\nCuando me transformo desde Emboscada de furtivo en dirigible, la próxima vez que bloqueo o me bloquean esta ronda, capturo a mi enemigo.","","\"¡Ja! A ver si me pilláis ahora, bestias estúpidas. ¡Ni siquiera la gravedad puede vencer a la especie superior!\".","Unidad",[],["Shurima"],"ÉPICA"],"07SH011":["Emboscada con trampa","Cuando se me invoca o la primera vez que un aliado se transforma cada ronda, otorga Vulnerable al enemigo más débil.","","\"El viento trae olor a sangre\". - Nidalee","Hito",[],["Shurima"],"COMÚN"],"07SH046":["Valle de la Imitación","Cuando juegas a un adepto, me transformo en una copia exacta de él esta ronda.","","\"Esta de aquí es la MEJORCÍSIMA parada de la visita. La visita le ha molado a tantísima gente que han construido un CHIP ENORME Y FUERTE, que será una de nuestras paradas para siempre de los jamases. ¡Vayamos a saludar al Chip gigante! Quiere mucho a todo el mundo, pero sobre todo a la gente que viene a esta visita\". - Aventuras con Chip, parte 6","Hito",[],["Shurima"],"COMÚN"],"07SH043":["Polifante descomunal","Emboscada a 5.","","Como sus habitantes más antiguos, se dice que los polifantes conservan los recuerdos y el corazón de la propia selva. Aunque son criaturas normalmente pacíficas, no dudarán en proteger su hogar de cualquier amenaza, sea grande o pequeña. ","Unidad",[],["Shurima"],"ÉPICA"],"07SH040":["Puercoespinas","La primera vez que un aliado se transforma, consigo +2|+1.","","\"Pequeños mamíferos omnívoros cubiertos de púas, las cuales pueden expulsar a gran velocidad cuando se los molesta. Su cola es ágil y espinosa; parece que la usan como mecanismo de defensa. Según dicen los exploradores más experimentados, son criaturas gruñonas y un tanto difíciles...\". - Extracto del diario de campo de Anura, día 3","Unidad",[],["Shurima"],"RARA"],"07SH005":["Magnate prominente","Jugar: Manifiesta una carta con Emboscada.\nCuando un aliado se transforma, duplica su poder y su vida.","","\"¿Que lo habéis perdido todo contra QUÉ? ¿Un científico y un reptil? Bueno, ¿y a qué estáis esperando, panda de bufones? ¡Id y recuperad mi dinero!\".","Unidad",[],["Shurima"],"RARA"],"07FR011":["Templo al Hielo Puro","Cuando se invoca a un aliado, aumenta su vida hasta igualar su poder.","","Aunque el verdadero significado de este templo se perdió hace mucho, su guardián de piedra aún sigue en pie, resistiendo el peso de incontables avalanchas. Cubierto de escarcha, parece emanar una extraña y fascinante luz...","Hito",[],["Freljord"],"ÉPICA"],"07FR010":["Garrafilada níveo","Asalto: Aumenta las estadísticas de un aliado hasta igualar las mías.","","Aunque el garrafilada níveo de Freljord caza principalmente pequeños mamíferos, sus garras son tan poderosas que puede transformar a casi cualquier criatura en un tentempié.","Unidad",["AVE"],["Freljord"],"COMÚN"],"07FR015":["Ingvar, la Joven","Jugar: Elige a un aliado. Otórgale a él y a todos los aliados con los que comparte un subtipo +1|+1 o manifiesta un adepto con el que comparta un subtipo.","","Autoproclamada porosupervisora y exploradora de Freljord, Ingvar tiene la certeza de que la aventura le espera ahí fuera y está decidida a encontrarla. ","Unidad",[],["Freljord"],"ÉPICA"],"07FR017":["Picurmenta cristalino","Jugar: Inflige 2 de daño a TODAS las demás unidades.","","La violencia desatada por el picurmenta cristalino es indiscriminada e instantánea, y puede cambiar las tornas de la batalla en cuestión de segundos. Muchos consideran que esa ave es el primer augurio de una descomunal tormenta, tan terrible como para alterar por completo la orografía de estas tierras.","Unidad",["AVE"],["Freljord"],"RARA"],"07FR016":["Saurio glacial","Cuando se me invoca, otorga +1|+1 a las 3 unidades de más arriba del mazo. Si un aliado tiene un subtipo diferente al mío, roba una de esas unidades.","","Estas leales monturas, cuyo bondadoso corazón se encuentra protegido por un exterior acorazado, son esenciales a la hora de despejar los helados pasos de montaña.","Unidad",["REPTIL"],["Freljord"],"RARA"],"07SI010":["Araña necrótica","Cuando se me invoca, invoca 2 Arañitas necróticas.\nCuando muere otro aliado, drena 1 de vida al nexo enemigo.","","Estas arañas, autóctonas de las Islas de la Sombra, segregan un necroveneno letal que provoca pérdida de sensibilidad en la piel y putrefacción.","Unidad",["ARAÑA"],["Islas de la Sombra"],"ÉPICA"],"07SI012":["Hilandera copetuda","Jugar: Si un aliado tiene un subtipo diferente al mío, aplica -2|-0 a un enemigo esta ronda.","","Las hilanderas copetudas fabrican sus nidos con sumo cuidado. Son especialmente cariñosas con sus crías... pero igual de despiadadas cuando se trata de posibles amenazas.","Unidad",["ARAÑA"],["Islas de la Sombra"],"COMÚN"],"07SI013":["Espectroscuro proliferante","Último aliento: Crea en el mazo una copia exacta de tu Espectroscuro proliferante más fuerte del mazo y duplica las estadísticas de Espectroscuros proliferantes en el mazo.","","\"Esta Niebla me ha enseñado multitud de cosas, y lo más importante es que he aprendido cuándo huir\". - Centinela de Ixtal","Unidad",[],["Islas de la Sombra"],"RARA"],"07SI004":["Tijeras sagradas","Atacar: Cuando otro aliado obtiene poder gracias a Consagrar, mi portador también lo obtiene.","","\"¡Con un buen par de tijeras y un hilo de calidad puedes arreglar prácticamente cualquier cosa!\". - Gwen","Equipamiento",[],["Islas de la Sombra"],"RARA"],"07MT009":["La era de los dragones","Roba todos los dragones de las primeras 9 cartas del mazo y reduce su coste a 0 esta ronda. Después coloca el resto de forma aleatoria en el mazo.","","\"Conocer a un dragón es conocerse a uno mismo. Conocer a muchos es comprender el mundo\". - Adorador de dragones Ottrani","Hechizo",[],["Targon"],"RARA"],"07MT013":["Llamada cósmica","Convoca un celestial de coste 7 o superior, o paga 8 para reducir el coste de tus celestiales estén donde estén a la mitad redondeando hacia arriba.","","El Juez continúa con su perenne vigilia mientras las bendiciones de los cielos descienden.","Hechizo",[],["Targon"],"COMÚN"],"07MT006":["Amor imposible","Jugar: Retira a un aliado y obtiene mis estadísticas.","","\"Pocos espectáculos hay más maravillosos que aquel en el que sol y luna se reúnen\". - Diana","Unidad",[],["Targon"],"COMÚN"],"07BC020":["Señor Apaños","Cuando una o más de tus trampas o bendiciones se activan, coloca 2 en el mazo de ese jugador.","","Nadie sabe a ciencia cierta cuánto tiempo ha dedicado el Señor Apaños a su colección, ni de dónde proviene. Parece amigable..., si no se tiene en cuenta el problemático rastro de peligros que deja tras de sí.","Unidad",[],["Ciudad de Bandle"],"RARA"],"07BC016":["Retornollave","Descártame para equiparme a un aliado aleatorio.","","\"Voy a serte sincero: pierdo mis herramientas bastante a menudo. ¡Pero esta siempre aparece cuando la necesito!\".\n- Inspector de seguridad","Equipamiento",[],["Ciudad de Bandle"],"COMÚN"],"07BC018":["Estudioso de los portales","Cuando se me invoca, coloca 1 Portal misterioso entre las 4 cartas de más arriba de tu mazo.\nCuando invocas a un aliado creado, este obtiene Impacto.","","En toda investigación surgen sorpresas; por suerte, esta es de las buenas. ","Unidad",["HADA"],["Ciudad de Bandle"],"ÉPICA"],"07BC011":["Blandito pero feroz","Cuando se me invoca, otorga +1|+1 e Impacto al resto de aliados con subtipos.","","Por desgracia para estos furtivos piltovanos, no son tan inofensivos como parecen.","Unidad",["AVE"],["Ciudad de Bandle"],"COMÚN"],"07DE014":["Sargento inquisitivo","Jugar: Elige una unidad de entre las 5 cartas de más arriba de tu mazo que cueste 3 o menos. Invócala y coloca el resto en tu mazo.","","El sargento de reclutamiento demaciano tiene una gran responsabilidad sobre sus hombros. Sus reclutas irán destinados a diferentes puestos, unidos por su deber y su amor por Demacia.","Unidad",["ÉLITE"],["Demacia"],"ÉPICA"],"07DE015":["Leohalcón crestado","Jugar: Si un aliado tiene un subtipo diferente al mío, manifiesta un hechizo de Demacia.","","\"Informe del primer avistamiento confirmado de un leohalcón en casi cincuenta años. Posee una majestuosa cresta azul y ojos inteligentes. Su cuerpo está protegido, pero sus huesos son lo suficientemente ligeros para trepar árboles o incluso planear durante cortas distancias. La forma de sus alas casi recuerda a la de un alargéntea demaciano. Volveré a informar con más detalle sobre sus medidas\". - Extracto del diario de campo de Anura, día 12","Unidad",["AVE"],["Demacia"],"RARA"],"07DE011":["Aprendiz de cazador de magos","Los hechizos de coste inferior a 3 ahora cuestan 3.","","\"¡Silencio! Esto no es un simple juego, como tú dices, sino una traicionera ilusión arcana. Revelaré tu verdadera identidad, mago embustero, ¡aunque tenga que quemar este lugar hasta los cimientos!\".","Unidad",[],["Demacia"],"COMÚN"],"07DE016":["Balen, el Benevolente","Atacar: Otorga +0|+1 a los demás aliados formidables estén donde estén.","","El enorme tamaño de Balen, un antiguo compañero de la familia Durand, contradice su gran precisión. Aunque comenzó como un asistente cualquiera, Balen tiene un don para su oficio, y su trabajo es único. Además, los Durand se enorgullecen de poder llamarlo amigo.","Unidad",[],["Demacia"],"ÉPICA"],"08SI042":["Mordekaiser","Jugar: Mata a un máximo de 2 aliados.\nCuando asesinas a otro aliado, este revive.","Han muerto 15 o más aliados. Los aliados con 5 o más de poder cuentan dos veces.","Encerrado en su armadura, en lo más profundo del Bastión Inmortal, Mordekaiser ha forjado su propio trono en el Reino Gris. Por cada insensato que busca destruirlo, tiene a su servicio a otro centenar de almas dispuestas a servirle tanto en la vida como en la muerte.","Unidad",[],["Islas de la Sombra","Noxus"],"Campeón"],"08SI040":["Erastin, el Caído en Desgracia","Cuando se me invoca, consigo Inmortal.\nAtacar: Concede -1|-0 a los enemigos esta ronda.","","Antaño, los dragones camavoranos eran magnificas criaturas dignas de respecto. Empero, ni siquiera ellos escaparon a la insaciable corrupción de la Ruina. Erastin no es ninguna excepción, por lo que su ya olvidada majestuosidad adoptó la grotesca apariencia de la muerte.","Unidad",["DRAGÓN"],["Islas de la Sombra"],"ÉPICA"],"08SI007":["Legión de los Cercenados","Jugar: Otorga Inmortal a un aliado de la mano.","","No importa qué forma tenían las almas antes de su encarcelamiento en el Reino Gris. Allí, la individualidad tiene poco valor. Sin rostro y sin miedo, la Legión sirve al Renacido de Hierro en pro de su uniformidad.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"08SI003":["Espectros encadenados","Último aliento: La próxima vez que revivas a un aliado, crea una copia mía en la mano.","","\"Hace mucho tiempo, estábamos encadenados. Pronto tú también conocerás nuestro sufrimiento, y todos sufriremos, por siempre jamás, hasta que el Maestro nos conceda el olvido...\".","Unidad",[],["Islas de la Sombra"],"RARA"],"08SI021":["Campababilla solitario","Cuando otro aliado muere o Último aliento: Coloca 4 Campanas en tu mazo.","","No te preocupes por ese siniestro repiqueteo: solo es el viejo Campababilla haciendo su ronda. Le encanta conocer a los recién llegados..., aunque a ellos no les hace ni pizca de gracia toparse con él.","Unidad",[],["Islas de la Sombra"],"COMÚN"],"08SI030":["Tumba acuática","Destruye 6 cartas de la parte inferior del mazo enemigo.","","Un navío cazamonstruos no es más que un aperitivo ligero para algunos de los monstruos marinos que habitan en las profundidades de Runaterra.","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"08SI037":["Sabueso de acero espectral","Para jugar esta carta, mata a un aliado.\nCuando se me invoca, invoca 1 Brindamuertes de mil garras.","","Estos sabuesos nunca olvidan el olor de una presa que ha intentado huir, y cuando la acorralan, cerca siempre suele haber un brindamuertes rondando.","Unidad",[],["Islas de la Sombra"],"RARA"],"08SI041":["Abrazo de la muerte","Mata a un aliado para infligir 5 de daño a una unidad.","","\"La oscuridad es un destino universal. Yo soy la excepción\". - Mordekaiser","Hechizo",[],["Islas de la Sombra"],"COMÚN"],"08SI036":["Umbral del Gris","Jugar: Maldice a un enemigo con Terror.\nCuando invocas un aliado titánico, se me destruye para robar 2.","","\"Te ofrecemos estas almas. Pavimentamos con huesos este camino ante ti. Desgarramos estos reinos para abrir paso a tu ejército de hierro inmortal\". - Sectaria del abrazo de la muerte","Hito",[],["Islas de la Sombra"],"RARA"],"08SI004":["Reino de la muerte","Un aliado comienza un ataque gratis y desafía con Contendiente al enemigo más fuerte.\nMata a todas las demás unidades.","","\"La muerte es mi dominio\". - Mordekaiser","Hechizo",[],["Islas de la Sombra"],"ÉPICA"],"08SI026":["Sectaria del abrazo de la muerte","Cuando se me invoca o se invoca a un aliado titánico, maldice al enemigo más fuerte con Terror.","","A ojos de sus adeptos, el Renacido de Hierro es la única esperanza de aquellos que anhelan el olvido. Estos sectarios reciben con brazos abiertos la paz a través de la dominación.","Unidad",[],["Islas de la Sombra"],"RARA"],"08SI018":["Vigilante espectral","Jugar: Elige un hechizo de explorador que crear en la mano.","","\"El terreno es inescrutable y la visibilidad casi nula. Me he topado con enemigos por todas partes..., pero lo curioso es que también he dado con inesperados aliados\". - Registro expedicionario de la División de Confines Lejanos del gremio de exploradores. Destino: Islas de la Sombra","Unidad",[],["Islas de la Sombra","Targon"],"RARA"],"08SI015":["Amalgama de ritos infames","Para jugar esta carta, mata a un aliado.\nÚltimo aliento: Cura 2 de vida a tu nexo.","","Las bestias de guerra resultan muy valiosas para cualquier ejército. En el Reino Gris, estas bestias son amalgamas de almas torturadas, y cada una de ellas se consume violentamente en su insensibilidad. ","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"08BW008":["Nilah","Atacar: Crea 1 Estela entre las 6 cartas de arriba de tu mazo.","Has robado 15 o más cartas.","En el norte, un nuevo contendiente aguarda a Nilah y a su equipo de cazadores de monstruos: se trata de una criatura llamada Volibear, que amenaza con destruir Freljord, a pesar de que sus gentes lo venerasen antaño. Para Nilah, poner a prueba sus habilidades contra un monstruo al que otros consideran un dios es una oportunidad única en la vida, por no mencionar la lista de monstruosidades de menor tamaño que añadirá a su lista de hazañas por el camino. ","Unidad",[],["Aguas Estancadas"],"Campeón"],"08BW032":["Alegría infinita","Concede a los aliados +1|+0 esta ronda y cura 2 de vida a los aliados dañados.","","\"¡Alegría, rebosante y eterna!\". - Nilah","Hechizo",["ELEMENTAL"],["Aguas Estancadas"],"COMÚN"],"08BW038":["Bailarina del chakram","Jugar: Inflige 1 de daño a cualquier unidad o estructura.\nTus habilidades drenan.","","Se mueve siguiendo una danza de agua y filos, creando acero a partir de la espuma del mar y el rocío. No necesita ver sus armas para sentir sus movimientos: del agua toman su ánima, y al agua siempre han de regresar.","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"08BW015":["La danzamareas","Cuando se me invoca, roba 1 Nilah.\nAl jugar la tercera carta en cada ronda, otorga +2|+0 y Audacia a tus otros aliados esta ronda.\nSi fuera a obtener Fugaz, me revela en su lugar.","","\"Se rumorea que hay por ahí un barco con una forma extraña, el más rápido que se haya visto en Aguas Estancadas. Y ligero. Su capitana es un tanto peculiar, pero yo diría que sabe lo que se hace. Igual podríamos aprender un par de cosas de ella\".\n- Tabernero de Aguas Estancadas","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"08BW002":["Hoja sin forma","Inflige 2 de daño a una unidad. Su vida no puede bajar de 1 con dicho daño.","","\"Aquellos monstruos que se hacen llamar 'dioses' sufrirán una dura caída, sin importar las tierras que habiten\". - Nilah","Hechizo",["ELEMENTAL"],["Aguas Estancadas"],"COMÚN"],"08BW025":["Centinela magistral","Tras robar 3 o más cartas en una ronda de esta partida, consigo +1|+1 y Audacia.","","\"Ey, compa. ¿A qué viene tanto jaleo? ¡Relaja! ¡En el agua no hay nada con lo que no podamos lidiar!\". - Siervo del desafío","Unidad",[],["Aguas Estancadas"],"COMÚN"],"08BW026":["Siervo del desafío","Cuando se me invoca, arremolina tu mano para otorgarme +1|+1 por cada carta arremolinada y robas 2.","","\"Venga ya... ¿Acaso lo estás intentando? Me estás obligando a contenerme... ¡Qué palo!\".","Unidad",[],["Aguas Estancadas"],"RARA"],"08BW028":["Octoaventurero","Jugar: Elige un hechizo de explorador que crear en la mano.","","\"Un espécimen peculiar. Es muy azul... Y tiene unos ojos enormes. Dan repelús. Se debe seguir investigando\".\n- Registro expedicionario de la División de Confines Lejanos del gremio de exploradores. Destino: Piltover","Unidad",[],["Aguas Estancadas","Piltover y Zaun"],"RARA"],"08BW009":["Timonel envejecido","Jugar: Manifiesta 2 hechizos elementales diferentes que hayas jugado en esta partida. Cuestan 0 esta ronda.","","\"La mente es como un río. Con el paso del tiempo, su flujo constante acaba tallando las laderas de las montañas. Además, al igual que la mente, su caudal puede crecer para alcanzar nuevas costas con un poco de impulso\".","Unidad",[],["Aguas Estancadas"],"RARA"],"08BW010":["Diluvio","Durante el resto de la partida, todos tus hechizos elementales y habilidades infligen 1 de daño adicional.","","\"En manos de un sabio, el agua puede dar forma a cualquier cosa\". - Siervo de la sabiduría","Hechizo",["ELEMENTAL"],["Aguas Estancadas"],"ÉPICA"],"08BW031":["Sefirsa, la Calamidad de las Profundidades","Cuando gastas maná para jugar a otra unidad, crea una carta aleatoria en la mano del mismo coste. Cuesta 0 y es Fugaz.","","A pesar de su apetito por hasta las más extrañas criaturas marinas, hay algunos monstruos a los que ni siquiera los capitanes más experimentados de Aguas Estancadas se atreven a cazar. Cuando hablan sobre Sefirsa, lo hacen en susurros; cuentan que es como una luz hipnótica que se mueve bajo las olas, un monstruo que se posa sobre una fosa común de barcos hundidos y pobres ahogados.","Unidad",["MONSTRUO MARINO","DRAGÓN"],["Aguas Estancadas"],"ÉPICA"],"08BW037":["Crupier intachable","Cuando juegas una carta cuyo coste sea igual a mi poder, consigo +1|+1.","","\"A ver, ¿no quieres apoquinar un pelín más? Quien no arriesga no gana, ya sabes. Esta mesa trae suerte, te lo aseguro. Además, la casa reparte de maravilla en este honrado establecimiento... Lo juro por la lengua de mi madre\".","Unidad",[],["Aguas Estancadas"],"RARA"],"08BW036":["Chapitel coralino de los marai","Cuando gastas maná para jugar una unidad, recuperas 1 de maná de hechizos.","","\"Desde tiempos inmemoriales, el arrecife ha sido nuestro refugio y aliado. Cuida de nosotros, al igual que nosotros cuidamos de él, de tal forma que ninguno caigamos en la oscuridad\". - Abuela marai","Hito",[],["Aguas Estancadas"],"COMÚN"],"08BW023":["Vikrash, el Eufórico","Cuando se me invoca, crea 1 Estela entre las 6 cartas de arriba del mazo.","","\"Fijaos bien, amigos. ¡El mundo entero se mueve a nuestro compás! Las olas danzan bajo el casco, el viento baila en las velas y los pájaros se mueven al ritmo de la brisa. Uníos a mí en nuestra más elevada vocación, ¡y regocijaos!\".","Unidad",[],["Aguas Estancadas"],"ÉPICA"],"08PZ007":["Bandada de trinahuracanes","Invoca 1 Golondrina trinahuracán y otórgale +1|+1 por cada otro hechizo y habilidad elementales que hayas jugado en esta partida.\nRoba 1.","","Cuando el trinahuracán vuela bajo, se avecina una tormenta del carajo.","Hechizo",["ELEMENTAL"],["Piltover y Zaun"],"RARA"],"08PZ031":["Anteojos sospechosos","Elige un adepto aliado. Transformo a mi portador en una copia exacta de él mientras me tiene equipado.","","No preguntes cómo funcionan.","Equipamiento",[],["Piltover y Zaun"],"RARA"],"08PZ025":["Prototipo de porobot","Último aliento: Otorga \"Cuando se me juega, invoca 1 Prototipo de porobot\" a un hechizo aleatorio de coste 6 o más de la mano.","","\"Solo es un prototipo\" —lloriqueó el aprendiz mientras las llamas devoraban el laboratorio—. \"¡No lo he programado para que se coma todos los engranajes que vea! ¡Ni siquiera sé dónde irá a parar todo ese metal!\".","Unidad",["PORO"],["Piltover y Zaun"],"RARA"],"08PZ005":["Ojo de la tormenta","Concede +2|+0 a un aliado esta ronda.\nRoba 2.","","\"¡Calma! La tormenta gira a tu alrededor, pero no sufrirás daño alguno\". - Janna","Hechizo",["ELEMENTAL"],["Piltover y Zaun"],"COMÚN"],"08PZ019":["Torbellino divino","Si has robado 3 cartas o más esta ronda, cuesto 2 menos.\nInflige 3 de daño a una unidad y 2 de daño al nexo enemigo.","","\"El poder del viento está a mi servicio\". - Janna","Hechizo",["ELEMENTAL"],["Piltover y Zaun"],"RARA"],"08PZ028":["Dragona tecnoquímica","Cuando juegas un hechizo, roba 1. Cuando robas con la mano completa, inflige 1 de daño al nexo enemigo.","","Zaun exige adaptación, y la dragona tecnoquímica no es una excepción. Su enfermizo resplandor verde ilumina los barrios bajos de la ciudad y las sombras de sus alas envilecidas se ciernen sobre los callejones oscuros, como heraldos de una furia nacida de la angustia de su propia corrupción.","Unidad",["DRAGÓN"],["Piltover y Zaun"],"ÉPICA"],"08PZ001":["Janna","Jugar: Arremolina 2 para robar 2 en el siguiente comienzo de ronda.\nDurante cada ronda, reduce en 1 el coste de las 3 primeras cartas que robes.","Te he visto jugar 8 cartas con coste reducido.","\"Zaun ocupa un lugar especial en el corazón de Janna, más que ningún otro sitio. Después de todo, ella fue la que salvó a las desafortunadas almas que Piltover abandonó a su suerte. Sí... Si puedo encontrar respuestas en algún sitio, es aquí\".\n- Navegabrisas","Unidad",[],["Piltover y Zaun"],"Campeón"],"08PZ026":["Trinar del huracán","Invoca 1 Golondrina trinahuracán.","","\"Todos los hijos del viento responden a mi llamada\". - Janna","Hechizo",["ELEMENTAL"],["Piltover y Zaun"],"COMÚN"],"08PZ006":["Yescila, jerarca de las profundidades","Cuando juegas una habilidad o hechizo elemental, lo copias con los mismos objetivos.","","\"¡Vamos, Yescila! Si Ashlesh sabe tu nombre, quiere decir que eres ancestral. Sin embargo, tu edad o aspecto poco importan. No hay mayor honor para un monstruo que caer ante mi hoja en mar abierto\". - Nilah","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"08PZ018":["Navegabrisas","Si has robado 3 cartas o más esta ronda, cuesto 2 menos.","","\"Tengo todo lo que ansiaba, pero lo he conseguido arrebatándoselo a los demás..., y eso te deja vacío por dentro. Lo primero que hice en la vida fue seguir al viento, así que aquí estoy, rezando por que ella me lleve por el buen camino\".","Unidad",[],["Piltover y Zaun"],"COMÚN"],"08PZ008":["Maryam, guardiana del templo","Jugar: Arremolina 1 para robar 1 o recargar tu maná de hechizos.","","Convencida de que el espíritu del viento la salvó cuando era joven, Maryam se ha dedicado a predicar las virtudes de Janna desde su tierra natal, Shurima, hasta Zaun. Ahora que se ha convertido en la matriarca del templo zaunita, se dedica a transmitir la bondad de Janna a los jóvenes y oprimidos.","Unidad",[],["Piltover y Zaun"],"ÉPICA"],"08PZ009":["Templo sumergido","Fin de ronda: Arremolina tu mano.\nComienzo de ronda: Roba el mismo número de cartas y 1 carta más.","","Se perdió mucho en el catastrófico desplome que acabó separando Zaun de Piltover. Quizá el templo de Janna cayese en el olvido bajo las olas, pero ella consiguió salvar a sus adoradores.","Hito",[],["Piltover y Zaun"],"ÉPICA"],"08PZ002":["Temporal","Inflige 2 de daño a una unidad.\nAumenta mi daño en 1 por cada otra carta que hayas jugado esta ronda (hasta un máximo de 3 veces).","","\"¡Mi furia es como un torbellino!\". - Janna","Hechizo",["ELEMENTAL"],["Piltover y Zaun"],"RARA"],"08PZ024":["Pescadero charlatán","Comienzo de ronda: Todos los jugadores roban 1 carta. Después, otorga Fugaz a la carta de tu oponente.","","\"¡Dos por uno, oferta del día! ¡Solo hoy! ¡Pescado fresco! De... este mes, creo. ¡Dos por uno! ¿Cómo que no quieres el segundo? ¡Si es gratis!\".","Unidad",[],["Piltover y Zaun"],"COMÚN"],"08PZ020":["Clamanubes exaltado","Si has robado 3 cartas o más esta ronda, cuesto 2 menos.\nCuando se me invoca, roba 2 cartas en el siguiente comienzo de ronda.","","\"Mi querido Céfiro. Baja de las nubes y pósate sobre mi hombro, ¿quieres?\". - Janna","Unidad",[],["Piltover y Zaun"],"RARA"],"08FR012":["Invocación del trueno","Roba 1.\nInvoca 1 Sello de la tormenta.","","\"En nombre de Valhir, hacemos esta ofrenda...\". - Profeta de Valhir","Hechizo",["ELEMENTAL"],["Freljord"],"COMÚN"],"08FR033":["Berserker aguerrida","Cuando lanzas un hechizo lento que afecta a un único aliado, me lo aplicas a mí también.","","\"¿Crees que un par de flechitas podrán detenerme? ¡Ja! Cualquier cosa que me lances se convertirá en un arma de mi arsenal. ¡Reforjaré con hielo lo que se pierda!\".","Unidad",[],["Freljord"],"COMÚN"],"08FR019":["Rompecielos","Concede +1|+3 a un aliado esta ronda.","","Cubierto de nubes y envuelto en relámpagos, el dios oso sigue siendo imperturbable en el ojo de la tormenta.","Hechizo",["ELEMENTAL"],["Freljord"],"COMÚN"],"08FR001":["Volibear","Jugar: Juega Tormenta incesante 3 veces. Cada vez prioriza a un enemigo aleatorio diferente, o al nexo enemigo si no hay ninguno.","Fin de ronda: Has infligido 50 o más de daño.","\"¡Arrodíllate ante mí, mortal, y puede que te perdone la vida! Tu poder es débil, pero podría ser digno de servir al mío. ¡Arrodíllate o borraré tu existencia de la faz de la tierra!\".","Unidad",[],["Freljord"],"Campeón"],"08FR018":["Choque de gigantes","Invoca a 2 adeptos titánicos aleatorios.\nCuesto 1 menos por cada habilidad o hechizo elemental que hayas lanzado en esta partida (máx.: 10).","","\"Con su cuerpo, esculpí las montañas. Con el fuego de sus fauces, di lugar a miles de fiordos\". - Volibear","Hechizo",["ELEMENTAL"],["Freljord"],"ÉPICA"],"08FR011":["Caprina invocadora de la llama","Cuando juegas una habilidad o hechizo elemental, me forjo.","","\"El señor de la forja me prometió que llegarían vientos de cambio y rompió las cadenas de la inacción. Un dios débil es la imagen de quienes lo veneran. ¡El poder de Valhir solo se entregará a la gloria de antaño!\".","Unidad",[],["Freljord"],"RARA"],"08FR008":["Heraldo de la tormenta","Inflige 4 de daño a TODAS las unidades, a excepción de los aliados titánicos.","","\"¡Que la tundra se tiña de rojo!\". - Volibear","Hechizo",["ELEMENTAL"],["Freljord"],"RARA"],"08FR024":["Nievecan de Yadulsk","Atacar: Otorga +1|+1 a los 2 aliados de más arriba del mazo.","","Aunque proceden de Yadulsk, multitud de tribus freljordianas han domesticado a estos cachorros para que dominen el rastreo, la caza y los rescates tras las avalanchas. Gracias a su robusta constitución y pasión por la diversión, se han vuelto populares en la tundra y la taiga por igual.","Unidad",["PERRO"],["Freljord"],"COMÚN"],"08FR015":["Rhond, la serpiente de magma","Jugar: Invoca 3 Sellos de la tormenta.","","Aunque aún hay quienes lo veneran, todos los habitantes de Freljord conocen la historia de la gran batalla de Volibear contra Rhond. Mucho antes de que los mortales pusiesen pie en el gélido norte, esta devastadora lucha dio lugar a las montañas y a los ríos de la mismísima tundra.","Unidad",[],["Freljord"],"ÉPICA"],"08FR030":["Boadir Hielo Ennegrecido","Cuando se me invoca, invoca 2 Siervos helados y avanzan hasta llegar a 2.","","\"¡Era totalmente d-despiadada! ¡Convertía a los esclavos en hielo negro, traía avalanchas bajo sus garras y su rugido sacudía la nieve de las montañas! ¡Era una reina guerrera, ya te lo digo yo! M-matar esclavos es labor de una reina guerrera\". - Bjerg balbuceante","Unidad",["DRAGÓN"],["Freljord"],"ÉPICA"],"08FR002":["Profecía de Valhir","Cuando se me invoca, invoca 1 Sello de la tormenta.","","\"Veo lo que los demás ignoran: la tormenta que destrozará la montaña, que destruirá los pilares de la tierra. El Freljord de antaño volverá a forjarse con sangre... Es solo cuestión de tiempo\".","Unidad",[],["Freljord"],"COMÚN"],"08FR028":["Arnés práctico","Tengo +1|+0 por cada subtipo distinto que hayas invocado en esta partida.","","\"Aquí arriba hay bestias que ni siquiera una avalancha podría derribar. Por eso mismo, merece la pena invertir en un buen arnés\". - Trampero avarosano","Equipamiento",[],["Freljord"],"ÉPICA"],"08FR003":["Ursine berserker","Cuando juegas un hechizo o lanzas una habilidad, invoca 1 Sello de la tormenta.","","A veces, los adeptos de Volibear se pierden tanto en su fanatismo que comienzan a asumir la apariencia del mismísimo oso. Nada se interpondrá en el camino de Valhir, ¡ni siquiera aquellos a los que los ursine otrora llamaban compatriotas!","Unidad",[],["Freljord"],"RARA"],"08RU014":["Dragón anciano","Origen: Aspecto del Dragón.\nCuesto 1 menos por cada bendición dracónica distinta que hayas jugado en esta partida.\nJugar: Me aplicas todas las bendiciones dracónicas.","Tus aliados han atacado con 75 o más de poder total.","\"Cuenta la leyenda que este dragón es el más anciano de todos; el rey de todas las bestias aladas. Si conseguimos domarlo... Dime, Alatis, ¿qué se nos resistiría entonces? El mundo comprenderá por fin que los dragones y los hombres somos más fuertes unidos\". - Volix, simpatizante de los dragones","Unidad",["DRAGÓN"],["Runaterra"],"Campeón"],"08NX003":["Escupefuego enfurecido","Jugar: Inflige 2 de daño a un enemigo y 2 de daño al nexo enemigo.","","La expansión noxiana se ha cobrado muchos pueblos, asentamientos y culturas. A menudo, las criaturas salvajes también están a merced de la maquinaria de guerra, pero este dragón responde a cada cruel avance de Noxus con una ira infernal igual de brutal.","Unidad",["DRAGÓN"],["Noxus"],"ÉPICA"],"08NX024":["Legionario de Hierro","Jugar: Inflige 3 de daño a un aliado para infligir 3 de daño a un enemigo.","","\"¡Arrancadles sus almas de esas prisiones de carne y hueso!\". - Mordekaiser","Unidad",[],["Noxus"],"RARA"],"08NX011":["Fuego salvaje","Inflige 1 de daño al nexo enemigo. Esta cantidad aumenta en 1 por cada Fuego salvaje más que hayas jugado. Crea 1 Fuego salvaje en tu mazo.","","\"Polvo al polvo...\". - Annie","Hechizo",["ELEMENTAL"],["Noxus"],"COMÚN"],"08NX028":["Indestructible","Otorga Inmortal a un aliado.","","\"Hierro eterno\". - Mordekaiser","Hechizo",[],["Noxus"],"COMÚN"],"08NX019":["Filomazo de cuerno carmesí","Golpe al nexo: Maldice a tu oponente con Icor.","","Además de ser muy útil para la maquinaria de guerra noxiana, el filomazo también es muy apreciado en los fosos de combate del capitolio. Pocos oponentes, ya sean humanos o animales, se atreven a enfrentarse en la arena a esta bestia, y los escasos combates contra filomazos atraen a espectadores de toda la ciudad.","Unidad",["REPTIL"],["Noxus"],"COMÚN"],"08NX014":["Jefa de estudios Telsi","Los efectos de ataque y apoyo aliados se activan una vez más.","","La clase de la jefa de estudios Telsi sobre la disciplina personal es una mezcla de tareas complicadísimas, castigos y partes de expulsión. Es una asignatura obligatoria para los estudiantes del conservatorio Flor de Cuervo; de lo contrario, nadie asistiría a sus clases.","Unidad",[],["Noxus"],"ÉPICA"],"08NX012":["Adquisidor armado","Jugar: Elige un hechizo de explorador que crear en la mano.","","\"Puede parecer que excavar en el desierto es más sencillo, ¡pero no! Al cabo del tiempo, la arena se convierte en piedra. Vuelvo a solicitar fondos para el reemplazo de las herramientas\". - Registro expedicionario de la División de Confines Lejanos del gremio de exploradores. Destino: Shurima","Unidad",[],["Noxus","Shurima"],"RARA"],"08NX029":["Impacto kashuri","Mata a una unidad dañada. Si no lo está, le inflige 2 de daño.","","\"Esto es por tu bien. Confía en mí\". - Lord Broadmane","Hechizo",[],["Noxus"],"ÉPICA"],"08NX009":["Lord Mallat","","","\"Se necesitaron siglos de planificación para encerrar a tan terrible belicista, y tus patéticos amigos quieren derrotarlo con... ¿alegría? Necia. No conseguirás más que provocar la ira del Renacido. Nos pondrás en peligro a todos\".","Unidad",[],["Noxus"],"COMÚN"],"08NX025":["Renacido apuñalado","Cuando revives a un aliado, le otorga Contendiente.","","\"Sé que me has traicionado, ¡y aun así sonríes! Me ponían buena cara y comían de mi mesa, incluso cuando ya habían decidido apuñalarme por la espalda. No permitiré que nadie vuelva a jugármela. Morirás al igual que todos ellos... ¡pidiendo perdón a gritos!\".","Unidad",[],["Noxus"],"RARA"],"08SH009":["Maldición antigua","Maldice a un enemigo con Terror.","","A veces es mejor no desenterrar nada.","Hechizo",[],["Shurima"],"COMÚN"],"08SH014":["Conjuraenjambres cornudo","Jugar: Otorga -1|-0 a dos enemigos y desactiva sus palabras clave positivas.","","A pesar de su intimidante tamaño, este conjuraenjambres no suele recurrir a la violencia. Cuando su enjambre se aproxima a un asentamiento shurimano, los aldeanos dejan ofrendas, como bayas, en el desierto cercano, para distraer a sus visitantes y evitar que se fijen en cosechas más importantes.","Unidad",["DRAGÓN"],["Shurima"],"COMÚN"],"08SH004":["General de las dunas","Amanecer o cuando activas otra carta con Amanecer: Concede Vulnerable al enemigo más débil.","","Los gigantescos ejércitos de Shurima siempre están listos para demostrar la supremacía del desierto. En cuanto reciben la orden, avanzan sin dudar.","Unidad",["ÉLITE"],["Shurima"],"RARA"],"08SH005":["Defensores del disco solar","Amanecer: Roba 1 Defensores del disco solar.","","\"Somos los guardianes del eterno desierto, historia viviente, quienes recorren un sendero de esplendor. Únicamente nos postramos ante el disco solar, a fin de conseguir que el mundo entero hinque la rodilla ante la gloria de Shurima\". - Azir","Unidad",["ÉLITE"],["Shurima"],"COMÚN"],"08SH012":["Barbara Saqueatumbas","La primera vez que otro aliado muere en cada ronda o Último aliento: Crea 1 Hallazgo fortuito en la mano.","","\"Menudo botín traes, Barb. Sabía que podía contar contigo. Espera, ¡¿cómo que te han visto?!\". - Luchador vekaurano","Unidad",["REPTIL"],["Shurima"],"RARA"],"08SH002":["Tragadunas","Para jugar esta carta, mata a un aliado o gasta una gema de maná 3 veces.","","Los tragadunas descansan a mayores profundidades que sus parientes de menor tamaño, los xer'sai. Son conocidos por devorar a otros depredadores de los xer'sai, pero no es un suceso muy documentado, probablemente porque pueden absorber dunas enteras (y cualquier testigo que haya en ellas) de un solo bocado. ","Unidad",[],["Shurima"],"ÉPICA"],"08MT003":["Morgana","Jugar: Maldice a un enemigo con Grilletes dos veces.","Has seleccionado como objetivo a unidades 10 veces o más.","\"Viniste a mí desangrándote, con el cuerpo herido, y aun así, jamás he visto un semblante más alegre. No cabe duda de que eres una mujer un tanto peculiar, pero aquí estás a salvo. Descansa, y cuando te encuentres mejor, escucharé tu historia de buena gana\".","Unidad",[],["Targon","Demacia"],"Campeón"],"08MT005":["Mihira, Aspecto Ascendente","Jugar: Maldice a 2 enemigos con Grilletes dos veces.","","\"Acepté la divinidad en el nombre de mis hijas. Renuncié a mi propia humanidad por mi familia, para que esta espada ardiente pudiese forjar un mundo nuevo, uno regido por la verdad y la justicia\".","Unidad",[],["Targon"],"ÉPICA"],"08MT042":["Mecanismo de pecador","Maldice a un enemigo con Grilletes.\nAumenta el coste de las maldiciones enemigas en 1 estén donde estén.","","\"Para encontrar la libertad, debes aceptar la oscuridad que esta alberga\". - Morgana","Hechizo",[],["Targon"],"RARA"],"08MT024":["Hechicero de ojos color rubí","Jugar: Otorga Escudo de hechizos o Abrumar a un aliado de la mano.","","\"¡No tengas miedo! ¡Sigue adelante, y no mires atrás! Yo también emprendí este viaje. Y ahora es nuestro deber protegerte durante el tuyo. Apresúrate a su santuario, y la Dama del Velo te otorgará la protección que buscas\".","Unidad",[],["Targon"],"COMÚN"],"08MT045":["Conjurador encadenado","Jugar: Me maldices con Grilletes.","","Los cazadores de magos son expertos en doblegar la voluntad de la gente. Lo habían encadenado, y restringido su magia. Le habían quitado su voz. Sin embargo, ya había sobrevivido a ellos en el pasado y, en esta ocasión, tenía a la Dama del Velo de su parte.","Unidad",[],["Targon"],"RARA"],"08MT015":["Lisa y Dolly","Jugar: Maldice a un enemigo con Grilletes.","","\"¡Mira, Dolly! ¡Mira lo que hago! ¡Como tú me enseñaste! ¿Crees que algún día podremos enseñarle a mamá lo mucho que he aprendido? ¿Crees que ya lo sabe? ¿En serio? Espero que tengas razón\". - Lisa","Unidad",[],["Targon"],"COMÚN"],"08MT030":["Dragón de gemas amable","Cuando lanzas un hechizo veloz, uno lento o una habilidad, otorga a otros dragones aliados +1|+1.","","La apariencia de los dragones es tan variada como su propio temperamento. Por un lado, están los dragones infernales, que tienden a la destrucción total; mientras que, por otro, existen dragones que tienden a la protección incondicional de sus familias y entornos, como el lento y cariñoso dragón de gemas.","Unidad",["DRAGÓN"],["Targon"],"RARA"],"08MT023":["Hechizo oscuro","Aturde a un enemigo y lo maldice con Grilletes.","","\"¡Pagaréis por el sufrimiento que habéis causado!\". - Morgana","Hechizo",[],["Targon"],"RARA"],"08MT031":["Adorador de dragones Ottrani","Cuando se me invoca, tu nexo se cura 2 de vida. Obtienes una gema de maná adicional la siguiente ronda.","","En lo alto de las laderas de Targon, un miembro solitario de los Ottrani ha dedicado toda su vida a los dragones. Se atavía con escamas y huesos viejos, dibujando su camino entre dientes de dragón desperdigados y el enraizado humo que asciende por la montaña.","Unidad",[],["Targon"],"ÉPICA"],"08MT009":["Protector velado","Cuando se me invoca o se invoca a un aliado titánico, cura 3 de vida a tu nexo.","","Este protector velado no ha olvidado la bendición que lo separa de una simple bestia, y paga su deuda asegurándose de que cualquiera que busque cierto santuario en las colinas de Targon llegue a él sano y salvo.","Unidad",[],["Targon"],"RARA"],"08MT006":["Escudo negro","Concede a un aliado Escudo de hechizos esta ronda y lo maldice con Grilletes.","","\"¡Resguardada de la persecución!\". - Morgana","Hechizo",[],["Targon"],"RARA"],"08MT027":["Convergencia del heraldo celestial","Jugar: Activa los efectos de Amanecer y Anochecer de los demás aliados.\nAmanecer: Consigo Abrumar.\nAnochecer: Consigo Escudo de hechizos.","","\"Sobre mí arde un anillo de fuego. En la proclamada oscuridad, todos somos iguales\". - Orador menguante lunari","Unidad",["AVE"],["Targon"],"ÉPICA"],"08MT025":["Fragmento sísmico","Si hay una unidad titánica visible, cuesto 3 menos.\nInflige 7 de daño a una unidad.","","\"Vaya, esto... ¡no te preocupes por eso! No es más que una muesquita de nada en la roca, ha sido sin querer. ¡No ha sido cosa de papi, no! ¡Sigamos!\". - Chip","Hechizo",["ELEMENTAL"],["Targon"],"COMÚN"],"08DE006":["Pionero erudito","Jugar: Elige un hechizo de explorador que crear en la mano.","","\"Hace frío. Tengo frío. Aquí siempre está todo frío. Hay lugares donde la gente no debería vivir. Después de esto, a mí enviadme a un lugar más cálido\". - Registro expedicionario de la División de Confines Lejanos del gremio de exploradores. Destino: Freljord","Unidad",[],["Demacia","Freljord"],"RARA"],"08DE020":["Grilletes mágicos","Otorga +0|+2 a un aliado. Maldice a tu oponente con Supresión.","","\"¡Siente el peso de tus pecados!\". - Morgana","Hechizo",[],["Demacia"],"COMÚN"],"08DE017":["Inquisidor de los Cazadores de Magos","Cuando se me invoca, maldice a tu oponente con Supresión.","","\"No podemos permitir que encuentren el santuario de la hermana caída. Su magia es ancestral y perversa, demasiado como para que yo pueda suprimirla. Rápido, ¡lleva a estas abominaciones de vuelta al barco y sigue al resto hacia la cima de la montaña!\".","Unidad",[],["Demacia"],"RARA"],"08DE025":["Dragón de nube","Cuando se me invoca, reduce en 1 el coste de todas las unidades aliadas de la mano.","","Gracias a que su esponjoso pelaje lo protege del frío, este dragón puede alcanzar altitudes muy superiores a las que llega el resto de dragones. Vivaces y esquivos, se los suele ver volando alto, cercenando nubes con sus alas e impulsándose con las corrientes de viento.","Unidad",["DRAGÓN"],["Demacia"],"ÉPICA"],"08DE010":["Duelo de caballeros","Concede a un aliado +0|+2 esta ronda.\nEse aliado y un enemigo se golpean el uno al otro.","","\"¡En guardia, camarada! ¿Acaso eres tan cobarde como para rechazar batirte en duelo con este caballero?\". - Caballero Laurent","Hechizo",[],["Demacia"],"COMÚN"],"08DE022":["El Cormorán","Cuando se me invoca, roba 1 carta de cada campeón de tu mazo.\nCada ronda, la primera vez que invocas a un campeón, prepara el ataque.","","\"Debes recordar, hijo mío, que cada horizonte que persigas deberá ser en pro del hogar que dejamos atrás\". - Rey Jarvan III","Unidad",[],["Demacia"],"ÉPICA"],"08DE027":["Golpe de garra","Otorga +1|+1 a los pájaros aliados estén donde estén. Un pájaro aliado golpea a un enemigo.","","El graznido del alargéntea solo puede significar una cosa: la muerte se aproxima desde las alturas.","Hechizo",[],["Demacia"],"RARA"],"08DE026":["Alatis, el Gallardo","Tus bendiciones dracónicas afectan a todos los dragones aliados.","","\"Dejemos las cosas claras: no siempre me han gustado los dragones. Alatis me convenció cuando me salvó la vida por primera vez. He aprendido montones de cosas de él, pero la más importante es esta: no hay mejor vida que servir a Demacia a lomos de un dragón\". - Simpatizante de los dragones","Unidad",["DRAGÓN"],["Demacia"],"ÉPICA"],"08DE013":["Simpatizante de los dragones","Cuando se me invoca, roba un dragón si hay un dragón visible.","","\"Sabes que odio admitirlo, viejo amigo, pero no podemos domarlo por nuestra cuenta. Hemos hecho todo lo que estaba en nuestra mano. Avisaré al general y, respaldados por el poder de Demacia, obligaremos a esa fantástica bestia a postrarse\".","Unidad",[],["Demacia"],"COMÚN"],"08IO012":["Dragón de océano","Cuando lanzas un hechizo veloz, uno lento o una habilidad, cura 1 de vida al nexo.","","\"¡Tamaña bestia! Noto tu alegría cuando rasgas las olas con las garras. Si, en algún momento, decides cazar algo más que peces y aves marinas, me encantaría enfrentarme a ti\". - Nilah","Unidad",["DRAGÓN"],["Jonia"],"RARA"],"08IO014":["Heisho, la Concha del mundo","Cada ronda, la primera carta que juegas cuesta 9 menos.","","Para los habitantes de esta aldea jonia, Heisho es su cuidadora y una amiga a partes iguales. Tras haber cargado con sus hogares desde tiempos inmemoriales, pueden confiar en que la portadora de su aldea busque costas pacíficas en tiempos turbulentos.","Unidad",["REPTIL"],["Jonia"],"ÉPICA"],"08IO021":["Danza empírea","Detengo un hechizo veloz, uno lento o una habilidad del enemigo, retiro a un enemigo e invoco 1 El Empíreo.","","\"Esta danza es en su honor\". - Irelia","Hechizo",[],["Jonia"],"RARA"],"08IO019":["Adnere el Confiable","Cuando se me invoca, invoca 1 Avicultores de Adnere.","","\"Esta tierra está llena de lecciones. Nunca lo olvides: debemos celebrar el paso de cada estación, pues un nuevo comienzo solo puede nacer de un final\".","Unidad",[],["Jonia"],"RARA"],"08IO010":["Vuelco","Retira a un enemigo para aumentar en 2 el coste de la siguiente unidad que juegue tu oponente en esta ronda.","","\"Quienes buscan hacernos daño encontrarán descanso en el fondo del mar\". - Moldeador de ríos","Hechizo",["ELEMENTAL"],["Jonia"],"COMÚN"],"08IO023":["Espíritus marinos danzarines","Jugar: Invoca una copia exacta y endeble de mí.","","En determinadas épocas del año, cuando el viento sopla desde el mar, algunos zaunitas juran haber visto a dos enormes criaturas marinas danzando alegres al ritmo de la marea.","Unidad",[],["Jonia"],"COMÚN"],"08BC020":["Pajarillo tempranero","Tu oponente descarta su carta de mayor coste.","","\"Imagina ser un gusano y ver esos ojos justo antes de morir. Ah, ¿que los gusanos son ciegos? Bueno, mejor así, la verdad\". - Elle, viajera esquiva","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"08BC005":["Mochila cargadísima","Por cada Mochila cargadísima que hayas jugado en esta partida, planta 4 Campanas en tu mazo y 4 Boletus venenosos en el mazo del enemigo. Crea 1 Mochila cargadísima en tu mazo.","","\"Regla n.º 207: ¡Una exploradora solo lleva lo indispensable!\". - Ava hazañosa","Hechizo",[],["Ciudad de Bandle"],"RARA"],"08BC021":["Intercambio disimulado","Retira a un aliado para invocar 1 Buhogatito hambriento en su lugar.","","\"¡Brrrrrr!\". - Buhogatito","Hechizo",[],["Ciudad de Bandle"],"RARA"],"08BC002":["Skip, \"Rey del arrecife\"","Jugar: Elige 1 de entre 2 cartas que no sean campeones de la mano del enemigo. La capturo.","","\"Soy bien guapo, rápido y... sereno como un sireno. ¿Cómo te quedas, viejales? Soy el rey de este arrecife eterno, ¡y tú te has colado en mi reino!\"\n\"¡E-Espera! ¡Vuelve de inmediato! ¡Necesito ese espécimen para mi investigación!\". - Conchólogo","Unidad",[],["Ciudad de Bandle"],"ÉPICA"],"08BC006":["Atraviesaportales","Jugar: Elige un hechizo de explorador que crear en la mano.","","\"¡Cada vez me preocupa más Manojito! Ay, conforme pasan los días parece ponerse más nervioso... ¡Hasta el portal más irrelevante lo preocupa! No sé qué le pasa...\". - Registro expedicionario de la División de Confines Lejanos del gremio de exploradores. Destino: Ciudad de Bandle","Unidad",["YORDLE"],["Ciudad de Bandle","Jonia"],"RARA"],"08BC004":["Portia, la Peculiar","Jugar: Manifiesta un adepto titánico; sus estadísticas pasan a ser 1|1 y su coste, 0.","","\"¡Pues claro que conozco a la vieja Portia! Está un poco chiflada, pero puede abrirte un portal a donde quieras cuando lo necesites. ¡Un giro de cola y listo!\". - Atraviesaportales","Unidad",["DRAGÓN"],["Ciudad de Bandle"],"ÉPICA"],"08BC018":["Trampa edulcorada","Coloca un aliado en la parte inferior de tu mazo para invocar al aliado de más arriba del mazo.","","\"Regla n.º 571: Los exploradores nunca deben bajar la guardia. Nunca se sabe qué puede ser una deliciosa sorpresa y qué una trampa\". - Ava hazañosa","Hechizo",[],["Ciudad de Bandle"],"RARA"],"09SI015":["Un bello desastre","I: Asesina a una unidad con un total de 5 o menos de poder y vida.\nII: Drena 2 de vida al nexo enemigo.\nIII: Invoca una copia exacta de un aliado. Tiene Endeble y 1|1.","","Subió al escenario, poema en mano. No había pegado muchos carteles publicitando su actuación, porque ya tenía al público que tanto anhelaba.","Hito",["HISTORIA"],["Islas de la Sombra"],"ÉPICA"],"09SI013":["La conquista de hierro","I-II: Elige un adepto aliado. Crea una copia de él con Endeble y +1|+1 en la mano.\nIII: Revive al adepto aliado más fuerte que haya muerto y le otorga Endeble.","","En el Reino Gris, las formas torturadas forman un ejército espectral. Una vez abiertas las puertas del reino mortal, no habrá quién las pare.","Hito",["HISTORIA"],["Islas de la Sombra"],"RARA"],"09SI012":["Angustia existencial","Otorga Pesimismo a los enemigos.","","\"Nada tiene sentido, paso de todo\". - Vex","Hechizo",[],["Islas de la Sombra"],"RARA"],"09SI017":["Kharox","Cuando otro aliado que no es Tentáculo muere o Último aliento: Engendra 2.","","Se rumorea que Kharox, el solitario remero de un barco espectral que muchos marineros llaman el Navío Espectral, habla con los espíritus de todos los marineros que murieron intentando llegar a las Islas.","Unidad",[],["Islas de la Sombra"],"ÉPICA"],"09SI014":["Grimm","Jugar: Otorga 4 de Pesimismo a una unidad.","","A Grimm, que es un romántico empedernido, poeta torturado y conocedor de todo lo filosófico, no le asusta en absoluto el pesimismo. Es bien sabido que la dueña de su corazón es un tanto cascarrabias, pero eso solo la hace más adorable a sus ojos.","Unidad",["YORDLE"],["Islas de la Sombra"],"COMÚN"],"09DE033":["Espíritus párvulos","","","\"Los espíritus son criaturas maravillosas. Con el tiempo y los ensoñadores adecuados, ¡sus poderes no tienen límites!\". - Madre Espíritu","Unidad",[],["Demacia","Jonia"],"COMÚN"],"09DE039":["La luz de Demacia","I: Otorga Optimismo a un aliado.\nII: Otorga 2 de Optimismo a un aliado.\nII: Acrecienta a todos los aliados.","","Los vítores de la multitud iban en aumento, con el esplendor que ella irradiaba iluminando sus caras. Solo quería animar y apoyar a su pueblo y, a cambio, ellos le devolvían el apoyo, coreando su nombre con adoración: \"¡Luxanna! ¡Luxanna! ¡Luxanna!\".","Hito",["HISTORIA"],["Demacia"],"RARA"],"09DE034":["Lux: Iluminada","Apoyo: Otorga Optimismo al aliado al que apoye y consigo Barrera esta ronda.","Tus aliados han atacado o han obtenido más de 20 palabras clave positivas al atacar.","La luz se arremolinaba y se movía formando arcos alrededor de Luxanna mientras los habitantes de la ciudad la miraban maravillados. Allí, era la Señora de la Luz de Demacia, una honorable joven Crownguard y una maga de lo más diestra. Allí, Demacia era todo lo que siempre había soñado.","Unidad",[],["Demacia"],"Campeón"],"09DE047":["Artefacto olvidado","Invoca 1 Embestidor de las arenas, y luego concede a tus aliados Contendiente esta ronda.","","En las profundidades de una cámara de objetos mágicos confiscados del cazador de magos, se encuentra un extraño artefacto sin etiqueta, cuyo propósito cayó en el olvido hace mucho...","Hechizo",[],["Demacia"],"RARA"],"09DE041":["El Salón de Petricita","I: Un aliado captura una unidad.\nII: Maldice a tu oponente con Supresión.\nIII: Destruye todas las cartas capturadas por parte de aliados.","","Los vítores de la muchedumbre se apagaban a medida que se adentraba en el salón. Las estatuas la observaban en silencio. La oscuridad la aguardaba, pero no podía volver. Si no, ¿quién evitaría que Demacia se convirtiese en una pesadilla hecha realidad?","Hito",["HISTORIA"],["Demacia"],"ÉPICA"],"09DE030":["Incandescencia","Acrecienta a todas las unidades.","","\"¡Desencadenemos nuestro esplendor!\". - Lux: Iluminada","Hechizo",[],["Demacia"],"COMÚN"],"09DE043":["Luz creciente","Acrecienta a todas las unidades 3 veces.","","\"¡Conságrate en la luz!\". - Lux: Iluminada","Hechizo",[],["Demacia"],"RARA"],"09DE031":["Jarro Plumaligera","Jugar: Otorga Optimismo a un aliado de la mano.","","Ante ella se manifestó un joven con una máscara en los ojos, pétalos de rosa y criaturas luminiscentes a su alrededor. \"Me llamo Plumaligera. Jarro Plumaligera\", le dijo. \"Tengo entendido que necesitaría cierta ayuda, ¿no es así, señorita?\".","Unidad",[],["Demacia"],"RARA"],"09DE046":["Sonrisa ardiente","Acrecienta a 2 aliados y luego golpean a un enemigo uno detrás de otro.","","\"Tranquilidad, señoritas. Hay Jarro de sobra para todas\". - Jarro Plumaligera","Hechizo",[],["Demacia"],"COMÚN"],"09DE045":["Alina ensoñadora","Cuando se me invoca, invoca 5 Espíritus párvulos. Por cada uno para el que no haya espacio, otorga al aliado más débil 2 de Optimismo.","","\"Cuando yo tenía tu edad, tenía miedo de esta luz. No había nadie que pudiera decirme que mi magia era una bendición, que se me otorgó con un propósito, pero ahora tú me tienes a mí para decírtelo. Así que no tengas miedo, Alina. Deja que brille\". - Lux: Iluminada","Unidad",[],["Demacia"],"ÉPICA"],"09DE040":["Cazador de magos aberrante","Cuando se me invoca, otorga Optimismo al resto de aliados.","","\"Lady Crownguard\". El cazador de magos apareció de entre las sombras, extendiéndole la mano. Su sonrisa suplicante parecía demasiado amplia para su rostro, cuya mitad permanecía en la oscuridad. \"¿Por qué no me sigues?\".","Unidad",[],["Demacia"],"COMÚN"],"09DE036":["Espíritus del árbol","Jugar: Acrecienta a todas las demás unidades.","","\"Adelante, espíritus. Mostradle el camino a vuestro ensoñador\". - Lillia","Unidad",[],["Demacia","Ciudad de Bandle"],"COMÚN"],"09DE029":["Espíritu luminoso","Apoyo: Concede todas mis palabras claves positivas y sus acumulaciones al aliado al que apoye esta ronda.","","\"Venga, señor Espíritu. ¡Vamos a deshacernos de estas sombras tan horribles!\". - Alina ensoñadora","Unidad",[],["Demacia"],"RARA"],"09SH010":["Reconstructora del imperio","Jugar: Otorga a un hito aliado \"Cuando se me destruye, revivo\".","","El ascenso del emperador ha insuflado esperanza a toda Shurima. Decidida a que la visión de Azir se cumpla, esta maga se considera la \"reconstructora del imperio\" y viaja por el desierto con el propósito de recuperar la antigua gloria de las ruinas enterradas.","Unidad",[],["Shurima"],"COMÚN"],"09SH009":["El ejército del emperador","I: Invoca 2 Soldados de arena.\nII: Predicción.\nIII: Cuando invocas a un aliado esta ronda, consigue +2|+0 esta ronda.","","Azir conoce Shurima por lo que fue, es y será. Cree que su visión de futuro es mucho más que un mero sueño; se trata de una profecía que está destinado a cumplir.","Hito",["HISTORIA"],["Shurima"],"ÉPICA"],"09SH012":["Llamada a los Hijos del Sol","Elige 1 de 3 campeones aleatorios que comenzaron esta partida en tu mazo y róbalo.","","Muchos de los artefactos de los ancestrales guerreros Hijos del Sol desaparecieron tiempo atrás. Aunque no se puede decir lo mismo de los dioses guerreros a los que representan.","Hechizo",[],["Shurima"],"RARA"],"09PZ044":["Plegaria a la luz de las velas","I-II: Arremolina 1 para robar 1.\nIII: Roba 1.","","Este templo a Janna tiene pocos muros férreos, para estar en mayor armonía con los poderes de su diosa. Aun así, siempre hay innumerables velas encendidas, que parecen mantenerse impertérritas ante la enorme tormenta que se cierne sobre el resto de Zaun.","Hito",["HISTORIA"],["Piltover y Zaun"],"ÉPICA"],"09PZ045":["Cartógrafo de las alturas","Jugar: Arremolina 1 para robar otra carta con un coste superior o inferior a la carta que has arremolinado.","","\"No hay nada como alzar el vuelo a una gran altitud y reparar en la intrascendencia de uno mismo\".","Unidad",[],["Piltover y Zaun"],"RARA"],"09PZ046":["Malformación","Elige a un adepto aliado. Invoca 2 Buhogatitos hambrientos y luego transforma a las unidades aliadas en copias exactas del aliado elegido.","","\"Una copia más... y ya estará perfecto\". - Imperfeccionista malvada","Hechizo",[],["Piltover y Zaun"],"ÉPICA"],"09IO055":["Hada del pétalo","Cuando se me invoca, invoca 1 Espíritus párvulos.","","\"¡El cabello de Lillia está hecho un desastre! Anda, ve a arreglarlo. No lo olvides: el primer mechón es el de los deseos; el segundo, el de los sueños; y el último, para todo lo que no es lo que parece\". - Madre Espíritu","Unidad",[],["Jonia"],"RARA"],"09IO056":["Danza de espíritus","Retira a un aliado y otorga todas sus acumulaciones de Optimismo a otro aliado.","","\"¡Los sueños del corazón están a un sopor de la realidad!\". - Lillia","Hechizo",[],["Jonia"],"RARA"],"09IO048":["Madre Espíritu","Cuando se me invoca, otorga Optimismo a Espíritus párvulos y Madres Espíritu aliados estén donde estén.","","Los espíritus son vivaces y fugaces, y no siempre se les da bien escuchar. Para asegurarse de que todos llegan a su ensoñador, Madre Espíritu cuida de ellos con mano firme y un buen puñado de reprimendas.","Unidad",[],["Jonia"],"ÉPICA"],"09IO049":["Cosecha de las gotas de rocío","I: Invoca 1 Espíritus párvulos.\nII: Duerme a un aliado.","","Cada gota de rocío de la madre árbol brinda un pequeño vistazo de un sueño que tiene lugar en alguna parte de Runaterra, y cada gota debe recogerse, nutrirse y protegerse con sumo cuidado.","Hito",["HISTORIA"],["Jonia"],"COMÚN"],"09IO052":["Lillia","Cuando se me invoca o al golpear: Crea 1 Rama de los sueños en la mano o, si tienes una copia, su coste se reduce en 1.","Has invocado a 15 o más aliados o hitos.","En el corazón del Jardín del Olvido, se acerca la cosecha de las gotas de rocío. Aunque Lillia y las demás jardineras recogen estas gotas de rocío con sumo cuidado, se puede apreciar una extraña corrupción en su interior, que convierte los sueños en algo oscuro y horrorífico...","Unidad",[],["Jonia"],"Campeón"],"09IO046":["Jardinera Ophelis","Jugar: Cura por completo a un aliado y luego lo duerme.","","Cuidar del Árbol Onírico y el jardín que le rodea es todo un honor, pero este también conlleva sacrificio. En un ritual de respeto y agradecimiento, los cuidadores del jardín ofrecen sus propios recuerdos como ofrenda, con lo que pierden una parte de sí mismos todas las noches.","Unidad",[],["Jonia"],"COMÚN"],"09IO051":["El camino arraigado","I-II: Roba 1.\nIII: Reduce en 1 el coste de las cartas de tu mano esta ronda.","","El Jardín del Olvido alberga todo tipo de criaturas extrañas, tanto grandes como pequeñas, y algunas con más conciencia de lo que les habría gustado.","Hito",["HISTORIA"],["Jonia"],"RARA"],"09IO053":["Señor Raíz","Cuando se me invoca, roba 1 carta.","","\"Hala, algún día toda esta belleza habrá muerto, al igual que nosotros. Y espero ser el primero de todos. ¡Je, je!\".","Unidad",[],["Jonia"],"COMÚN"],"09IO045":["Capullo floreciente","Duerme a una unidad.","","\"¡Mis sueños florecen!\". - Lillia","Hechizo",[],["Jonia"],"RARA"],"09IO058":["El corazón del árbol","I: Cura 3 de vida a tu nexo e invoca 1 Espíritus párvulos.\nII: Otorga Optimismo a los aliados estén donde estén.\nIII: Manifiesta una carta de coste 8 o superior y reduce el coste a la mitad redondeando hacia arriba.","","Los espíritus oníricos son de los habitantes más comunes del jardín. Los hay de todo tipo de tamaños y formas, cada uno con su propio carácter, y muchos de ellos se sumergen en las gotas de rocío para guiar a sus ensoñadores hasta sus deseos más anhelados.","Hito",["HISTORIA"],["Jonia"],"ÉPICA"],"09IO059":["Vendaval de acero","Aturde a un enemigo y lo vuelve a aturdir en el siguiente comienzo de ronda.","","\"El filo por encima de todo\". - Yone, el Cazavientos","Hechizo",[],["Jonia"],"COMÚN"],"09FR009":["Desfile de poros","I-II: Manifiesta un adepto con un subtipo diferente al de los aliados en juego.\nIII: Concede +1|+1 a un aliado esta ronda por cada aliado con un subtipo.","","Ingvar ha forjado una relación aún más estrecha con los súbditos del Rey Poro desde la visita a su reino. Salir en estampida a través de Freljord en busca de aventuras es una de las mejores formas de potenciar las relaciones diplomáticas.","Hito",["HISTORIA"],["Freljord"],"ÉPICA"],"09FR014":["Brynhir Tónadatormenta","Jugar: Destruye una unidad en la mano para invocar 1 Obelisco a la tormenta con una cuenta atrás equivalente a su coste e invoca una copia idéntica de la unidad (mínimo 1).","","\"¡Me forjé en la tormenta de la montaña y en la canción de mi pueblo!\".","Unidad",[],["Freljord"],"ÉPICA"],"09FR010":["Poro ultrasuave","Jugar: Cura 1 de vida a tu nexo por cada aliado con un subtipo.","","\"Anda, ¡qué pelaje tan mullidito!\". - Pastor de poros","Unidad",["PORO"],["Freljord"],"COMÚN"],"09FR012":["Tala glacial","Otorga a un aliado vida equivalente a su poder y Formidable, luego su poder pasa a 0.","","Solo el poder del gélido invierno puede talar algunos de los árboles de Freljord.","Hechizo",[],["Freljord"],"RARA"],"09BC020":["Mirada asesina","Otorga Pesimismo a una unidad para robar 1.","","\"Enhorabuena. Te odio\". - Vex","Hechizo",[],["Ciudad de Bandle","Islas de la Sombra"],"COMÚN"],"09BC012":["Reunión familiar","I: Otorga Pesimismo a una unidad.\nII: Otorga Impacto a un aliado.\nIII: Acrecienta a 2 unidades.","","La soledad no sirve para ablandar su corazón, pero las cenas familiares son más tranquilas así, ¡tal y como le gustan a Vex!","Hito",["HISTORIA"],["Ciudad de Bandle"],"ÉPICA"],"09BC001":["Vex","Atacar: Otorga Pesimismo al enemigo más fuerte.","Has otorgado Pesimismo 5 o más veces distintas.","\"Uf, es tontísima. Ya le he dicho que odio las fiestas, y si hay tarta, ¡peor me lo pones! Horrible. Despiértame cuando se pire\".","Unidad",["YORDLE"],["Ciudad de Bandle","Islas de la Sombra"],"Campeón"],"09BC002":["Tío Milty","Cuando completas una historia, consigo 2 de Optimismo.","","Aunque se parece como un huevo a una castaña a la pesimista de su sobrina, el tío Milty siempre hace todo lo posible por conectar con ella. Su método preferido es con una historia de miedo a la luz de las velas.","Unidad",["YORDLE"],["Ciudad de Bandle"],"RARA"],"09BC013":["Obrador de alas","I-II: Elige a un aliado y, luego, elige 1 de entre 3 adeptos que cuesten 1 más para transformarlo.\nIII: Elige a un aliado y, luego, elige 1 de entre 3 adeptos que cuesten 2 más para transformarlo.","","El viejo de Trevor Traseroquieto siempre salta de un sueño a otro. Por suerte, este parece bastante tranquilo... Aunque es un poco extraño que toda la gente con la que se cruza quiera tener unas alas como las suyas...","Hito",["HISTORIA"],["Ciudad de Bandle"],"RARA"],"09BC004":["Allay","Jugar: Consigo Optimismo o .Otorga Pesimismo a una unidad.","","\"¡Veeex! ¡Esperaaa! ¡Tengo una cosa para ti! ¡Una invitación a tu fiesta de cumpleaños! Y un regalito por adelantado. ¡Es que no me aguantaba más las ganas! ¡¿No te mueres de la emoción?! Tenemos que hablar de la ropa, la tarta y... ¿Veeex?\".","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"09BC016":["Sorpresa monstruosa","Hace que un aliado pase a tener 5 de poder o de vida esta ronda.","","\"El peor regalo de la historia\". - Vex","Hechizo",[],["Ciudad de Bandle"],"COMÚN"],"09BC003":["Regalo grotesco","Cuando se invoca a un enemigo por primera vez, le otorga Pesimismo.","","\"Meh, al final no ha estado tan mal el regalo\". - Vex","Unidad",[],["Ciudad de Bandle"],"RARA"],"09BC018":["Sombra","Cuando se me invoca, roba a Vex.\nTengo +1|+0 por cada vez que hayas otorgado Pesimismo en esta partida.","","\"¡Eso, así aprenderán, Sombra! Nada de regalos, ni serpentinas, ni gorritos de fiesta\". - Vex","Unidad",[],["Ciudad de Bandle","Islas de la Sombra"],"ÉPICA"],"09BC011":["Espíritu pesimista","Golpear: Consigo Impacto.","","\"Qué curioso, ¡los sueños parecen influir en los espíritus! Estos parecen ser... Anda, ¿eso es una tarta?\". - Lillia","Unidad",[],["Ciudad de Bandle"],"COMÚN"],"09BC006":["Alcalde cachas","Comienzo de ronda: Acreciéntame.","","Parece que el tiempo se detiene conforme el musculoso alcalde sale de una tarta más alta de lo que uno pudiera llegar a imaginar. \"¡Cumpleaaaaños feliz de parte del alcalde elegido más buenazo y cachas de todo Bandle!\", grita el alcalde flexionando el brazo.\n\nDe todos sus sueños, este es el que más odia Vex. ","Unidad",["YORDLE"],["Ciudad de Bandle"],"COMÚN"],"09BW022":["Vencedora del foso","I: Un aliado y un enemigo se golpean el uno al otro. Sus vidas no pueden bajar de 1 con dicho golpe.\nII: Cura por completo a un aliado.\nIII: Crea 3 Monedas en la mano.","","Angel lleva años intentando ganar la batalla que ponga fin a todas las peleas. Todas las noches, sueña con una montaña de monedas tan grande que no cabría en la bahía de Aguas Estancadas. Eso sí que es tener pasta gansa.","Hito",["HISTORIA"],["Aguas Estancadas"],"ÉPICA"],"09BW028":["Plena dedicación","Consigo +1|+0 por cada carta que hayas robado en esta ronda.","","\"¿A qué te refieres con eso de que tengo que entrenar más? ¡Si ya lo he hecho! ¡Mira, mira!\".","Unidad",[],["Aguas Estancadas"],"RARA"],"09BW027":["Etiqueta de mercenario","Roba un adepto enemigo con 3 o menos de vida esta ronda (no se puede jugar si ya tienes 6 aliados o hitos).","","\"Derramar sangre a cambio de oro sí que es empezar el día con buen pie\". - Mercenario a sueldo","Hechizo",[],["Aguas Estancadas"],"COMÚN"],"09MT002":["Huésped de los Humoescama","I-II: Para activarla, descarta 1. Convoca una carta celestial de coste 7 o superior.\nIII: Reduce en 5 el coste de una carta aleatoria de la mano.","","Este Ottrani solitario se dedica a la adoración y la veneración de los dragones. Tal es su dedicación que contempla a estas regias bestias tanto en el mundo real como en el onírico.","Hito",["HISTORIA"],["Targon"],"ÉPICA"],"09MT004":["Bendición enmascarada","Otorga 2 de Optimismo a un aliado.","","\"Yo seré su santuario\". - Morgana","Hechizo",[],["Targon"],"COMÚN"],"09MT005":["Ensoñadora de la melodía dracónica","Cada ronda, la primera vez que convocas, invocas 1 Cría de dragón.","","\"Los dragones están cerca. Puedo sentirlo. Incluso ahora, se mecen en mis sueños\".","Unidad",[],["Targon"],"ÉPICA"],"09NX025":["El mejor de la arena","I-II: Concede +2|+0 a un aliado esta ronda.\nIII: Concede a un enemigo No puede bloquear esta ronda.","","En parte, la popularidad de la arena se debe al hecho de que cualquiera puede labrarse su reputación en ella. Este fan en concreto ha visto todos y cada uno de los combates de Draven que ha podido y está seguro de que, de tener la misma oportunidad que él, también llegaría a lo más alto.","Hito",["HISTORIA"],["Noxus"],"ÉPICA"],"09NX032":["Domador de yetis","Para jugar esta carta, descarta 1.\nCuando se me invoca, invoca 1 Yeti enfurecido.","","En parte, el éxito de la máquina de guerra noxiana se debe a su flexibilidad. A la hora de enfrentarse a terrenos o situaciones difíciles que exigen adaptación, el ejército aprovechará hasta el recurso local más extraño.","Unidad",[],["Noxus"],"RARA"],"09NX033":["Hacha de guerra maldita","Fin de ronda: Si mi portador no ha atacado esta ronda, le otorga Pesimismo.","","La cobardía tiene su precio.","Equipamiento",[],["Noxus"],"RARA"]};
